window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["已废止法规"] = {"caoyuanfanghuotiaoli":[{"i":1,"n":"第一条","txt":"为了加强草原防火工作，积极预防和扑救草原火灾，保护草原，保障人民生命和财产安全，根据《中华人民共和国草原法》，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例适用于中华人民共和国境内草原火灾的预防和扑救。但是，林区和城市市区的除外。"},{"i":3,"n":"第三条","txt":"草原防火工作实行预防为主、防消结合的方针。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当加强草原防火工作的组织领导，将草原防火所需经费纳入本级财政预算，保障草原火灾预防和扑救工作的开展。"},{"i":5,"n":"第五条","txt":"国务院草原行政主管部门主管全国草原防火工作。"},{"i":6,"n":"第六条","txt":"草原的经营使用单位和个人，在其经营使用范围内承担草原防火责任。"},{"i":7,"n":"第七条","txt":"草原防火工作涉及两个以上行政区域或者涉及森林防火、城市消防的，有关地方人民政府及有关部门应当建立联防制度，确定联防区域，制定联防措施，加强信息沟通和监督检查。"},{"i":8,"n":"第八条","txt":"各级人民政府或者有关部门应当加强草原防火宣传教育活动，提高公民的草原防火意识。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持草原火灾预防和扑救的科学技术研究，推广先进的草原火灾预防和扑救技术。"},{"i":10,"n":"第十条","txt":"对在草原火灾预防和扑救工作中有突出贡献或者成绩显著的单位、个人，按照国家有关规定给予表彰和奖励。"},{"i":11,"n":"第十一条","txt":"国务院草原行政主管部门根据草原火灾发生的危险程度和影响范围等，将全国草原划分为极高、高、中、低四个等级的草原火险区。"},{"i":12,"n":"第十二条","txt":"国务院草原行政主管部门根据草原火险区划和草原防火工作的实际需要，编制全国草原防火规划，报国务院或者国务院授权的部门批准后组织实施。"},{"i":13,"n":"第十三条","txt":"草原防火规划应当主要包括下列内容："},{"i":14,"n":"第十四条","txt":"县级以上人民政府应当组织有关部门和单位，按照草原防火规划，加强草原火情瞭望和监测设施、防火隔离带、防火道路、防火物资储备库（站）等基础设施建设，配备草原防火交通工具、灭火器械、观察和通信器材等装备，储存必要的防火物资，建立和完善草原防火指挥信息系统。"},{"i":15,"n":"第十五条","txt":"国务院草原行政主管部门负责制订全国草原火灾应急预案，报国务院批准后组织实施。"},{"i":16,"n":"第十六条","txt":"草原火灾应急预案应当主要包括下列内容："},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府应当根据草原火灾发生规律，确定本行政区域的草原防火期，并向社会公布。"},{"i":18,"n":"第十八条","txt":"在草原防火期内，因生产活动需要在草原上野外用火的，应当经县级人民政府草原防火主管部门批准。用火单位或者个人应当采取防火措施，防止失火。"},{"i":19,"n":"第十九条","txt":"在草原防火期内，禁止在草原上使用枪械狩猎。"},{"i":20,"n":"第二十条","txt":"在草原防火期内，在草原上作业或者行驶的机动车辆，应当安装防火装置，严防漏火、喷火和闸瓦脱落引起火灾。在草原上行驶的公共交通工具上的司机和乘务人员，应当对旅客进行草原防火宣传。司机、乘务人员和旅客不得丢弃火种。"},{"i":21,"n":"第二十一条","txt":"在草原防火期内，经本级人民政府批准，草原防火主管部门应当对进入草原、存在火灾隐患的车辆以及可能引发草原火灾的野外作业活动进行草原防火安全检查。发现存在火灾隐患的，应当告知有关责任人员采取措施消除火灾隐患；拒不采取措施消除火灾隐患的，禁止进入草原或者在草原上从事野外作业活动。"},{"i":22,"n":"第二十二条","txt":"在草原防火期内，出现高温、干旱、大风等高火险天气时，县级以上地方人民政府应当将极高草原火险区、高草原火险区以及一旦发生草原火灾可能造成人身重大伤亡或者财产重大损失的区域划为草原防火管制区，规定管制期限，及时向社会公布，并报上一级人民政府备案。"},{"i":23,"n":"第二十三条","txt":"草原上的农（牧）场、工矿企业和其他生产经营单位，以及驻军单位、自然保护区管理单位和农村集体经济组织等，应当在县级以上地方人民政府的领导和草原防火主管部门的指导下，落实草原防火责任制，加强火源管理，消除火灾隐患，做好本单位的草原防火工作。"},{"i":24,"n":"第二十四条","txt":"省、自治区、直辖市人民政府可以根据本地的实际情况划定重点草原防火区，报国务院草原行政主管部门备案。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府草原防火主管部门和气象主管机构，应当联合建立草原火险预报预警制度。气象主管机构应当根据草原防火的实际需要，做好草原火险气象等级预报和发布工作；新闻媒体应当及时播报草原火险气象等级预报。"},{"i":26,"n":"第二十六条","txt":"从事草原火情监测以及在草原上从事生产经营活动的单位和个人，发现草原火情的，应当采取必要措施，并及时向当地人民政府或者草原防火主管部门报告。其他发现草原火情的单位和个人，也应当及时向当地人民政府或者草原防火主管部门报告。"},{"i":27,"n":"第二十七条","txt":"当地人民政府或者草原防火主管部门应当及时将草原火灾发生时间、地点、估测过火面积、火情发展趋势等情况报上级人民政府及其草原防火主管部门；境外草原火灾威胁到我国草原安全的，还应当报告境外草原火灾距我国边境距离、沿边境蔓延长度以及对我国草原的威胁程度等情况。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府应当根据草原火灾发生情况确定火灾等级，并及时启动草原火灾应急预案。特别重大、重大草原火灾以及境外草原火灾威胁到我国草原安全的，国务院草原行政主管部门应当及时启动草原火灾应急预案。"},{"i":29,"n":"第二十九条","txt":"草原火灾应急预案启动后，有关地方人民政府应当按照草原火灾应急预案的要求，立即组织、指挥草原火灾的扑救工作。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府有关部门应当按照草原火灾应急预案的分工，做好相应的草原火灾应急工作。"},{"i":31,"n":"第三十一条","txt":"扑救草原火灾应当组织和动员专业扑火队和受过专业培训的群众扑火队；接到扑救命令的单位和个人，必须迅速赶赴指定地点，投入扑救工作。"},{"i":32,"n":"第三十二条","txt":"根据扑救草原火灾的需要，有关地方人民政府可以紧急征用物资、交通工具和相关的设施、设备；必要时，可以采取清除障碍物、建设隔离带、应急取水、局部交通管制等应急管理措施。"},{"i":33,"n":"第三十三条","txt":"发生特别重大、重大草原火灾的，国务院草原行政主管部门应当立即派员赶赴火灾现场，组织、协调、督导火灾扑救，并做好跨省、自治区、直辖市草原防火物资的调用工作。"},{"i":34,"n":"第三十四条","txt":"国家实行草原火灾信息统一发布制度。特别重大、重大草原火灾以及威胁到我国草原安全的境外草原火灾信息，由国务院草原行政主管部门发布；其他草原火灾信息，由省、自治区、直辖市人民政府草原防火主管部门发布。"},{"i":35,"n":"第三十五条","txt":"重点草原防火区的县级以上地方人民政府可以根据草原火灾应急预案的规定，成立草原防火指挥部，行使本章规定的本级人民政府在草原火灾扑救中的职责。"},{"i":36,"n":"第三十六条","txt":"草原火灾扑灭后，有关地方人民政府草原防火主管部门或者其指定的单位应当对火灾现场进行全面检查，清除余火，并留有足够的人员看守火场。经草原防火主管部门检查验收合格，看守人员方可撤出。"},{"i":37,"n":"第三十七条","txt":"草原火灾扑灭后，有关地方人民政府应当组织有关部门及时做好灾民安置和救助工作，保障灾民的基本生活条件，做好卫生防疫工作，防止传染病的发生和传播。"},{"i":38,"n":"第三十八条","txt":"草原火灾扑灭后，有关地方人民政府应当组织有关部门及时制定草原恢复计划，组织实施补播草籽和人工种草等技术措施，恢复草场植被，并做好畜禽检疫工作，防止动物疫病的发生。"},{"i":39,"n":"第三十九条","txt":"草原火灾扑灭后，有关地方人民政府草原防火主管部门应当及时会同公安等有关部门，对火灾发生时间、地点、原因以及肇事人等进行调查并提出处理意见。"},{"i":40,"n":"第四十条","txt":"有关地方人民政府草原防火主管部门应当严格按照草原火灾统计报表的要求，进行草原火灾统计，向上一级人民政府草原防火主管部门报告，并抄送同级公安部门、统计机构。草原火灾统计报表由国务院草原行政主管部门会同国务院公安部门制定，报国家统计部门备案。"},{"i":41,"n":"第四十一条","txt":"对因参加草原火灾扑救受伤、致残或者死亡的人员，按照国家有关规定给予医疗、抚恤。"},{"i":42,"n":"第四十二条","txt":"违反本条例规定，县级以上人民政府草原防火主管部门或者其他有关部门及其工作人员，有下列行为之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任："},{"i":43,"n":"第四十三条","txt":"截留、挪用草原防火资金或者侵占、挪用草原防火物资的，依照有关财政违法行为处罚处分的法律、法规进行处理；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"违反本条例规定，有下列行为之一的，由县级以上地方人民政府草原防火主管部门责令停止违法行为，采取防火措施，并限期补办有关手续，对有关责任人员处2000元以上5000元以下罚款，对有关责任单位处5000元以上2万元以下罚款："},{"i":45,"n":"第四十五条","txt":"违反本条例规定，有下列行为之一的，由县级以上地方人民政府草原防火主管部门责令停止违法行为，采取防火措施，消除火灾隐患，并对有关责任人员处200元以上2000元以下罚款，对有关责任单位处2000元以上2万元以下罚款；拒不采取防火措施、消除火灾隐患的，由县级以上地方人民政府草原防火主管部门代为采取防火措施、消除火灾隐患，所需费用由违法单位或者个人承担："},{"i":46,"n":"第四十六条","txt":"违反本条例规定，草原上的生产经营等单位未建立或者未落实草原防火责任制的，由县级以上地方人民政府草原防火主管部门责令改正，对有关责任单位处5000元以上2万元以下罚款。"},{"i":47,"n":"第四十七条","txt":"违反本条例规定，故意或者过失引发草原火灾，构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"草原消防车辆应当按照规定喷涂标志图案，安装警报器、标志灯具。"},{"i":49,"n":"第四十九条","txt":"本条例自2009年1月1日起施行。"}],"chanpinzhiliangjiandushixingbanfa":[{"i":1,"n":"第一条","txt":"为了加强对产品的质量监督，促使企业贯彻执行产品技术标准，提高产品质量和经济效益，以适应社会主义现代化建设和人民生活的需要，制定本办法。"},{"i":2,"n":"第二条","txt":"国家标准局主管全国的产品质量监督工作，省、自治区、直辖市人民政府标准化管理部门负责管理本地区的产品质量监督工作，其主要任务是："},{"i":3,"n":"第三条","txt":"实行产品质量监督的重点是："},{"i":4,"n":"第四条","txt":"计量器具检定、药品检验、食品卫生检验及检疫、动植物及其产品检疫、锅炉及压力容器安全监督检验、进出口商品检验和船舶（包括海上平台）、主要船用设备及材料、集装箱的船舶规范检验，按照国家的有关规定办理。"},{"i":5,"n":"第五条","txt":"国务院主管产品生产的部门，应当督促企业贯彻执行产品技术标准，不断提高产品质量。"},{"i":6,"n":"第六条","txt":"企业必须贯彻执行产品技术标准，对产品质量负责。出厂和销售的产品，必须达到产品技术标准，有质量检验合格证。在产品或其包装上应当标明工厂名称和地址。有关安全的产品，必须附有安全使用说明书。不合格品不得以合格品出厂和销售；危及人身安全和健康的不合格品，严禁出厂和销售。"},{"i":7,"n":"第七条","txt":"标准化管理部门根据工作需要设产品质量监督员，负责分管范围内的产品质量监督工作。产品质量监督员应当从熟悉产品技术标准，具有产品质量检验实践经验，责任心强、办事公正的工程技术人员中考核选任。"},{"i":8,"n":"第八条","txt":"国家标准局根据工作需要，按产品类别设国家级产品质量监督检验测试中心，承担指定产品的质量监督检验任务。国家级产品质量监督检验测试中心，由国家标准局会同有关部门从现有的检验力量较强的检验测试机构或科研单位中审定，并发给证书和印章。其主要职责是："},{"i":9,"n":"第九条","txt":"在工业比较集中的城市，标准化管理部门应当根据工作需要建立健全专职的产品质量监督检验所。"},{"i":10,"n":"第十条","txt":"地方各级标准化管理部门根据工作需要，按产品类别设产品质量监督检验站，承担指定产品的质量监督检验任务。产品质量监督检验站，由标准化管理部门会同有关部门从现有的检验力量较强的检验测试机构或科研单位中审定，并发给证书和印章。"},{"i":11,"n":"第十一条","txt":"产品质量监督检验所、站的主要职责是："},{"i":12,"n":"第十二条","txt":"对于不按产品技术标准生产的产品，标准化管理部门有权制止产品出厂销售，责令企业停发质量检验合格证，追回已售出的可能危及人身安全和健康的不合格品。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，标准化管理部门应当根据情节，分别给予批评、警告、通报，并限期改进；情节严重的，可处以罚款，追究主要责任者的行政或经济责任，提请有关主管部门责令企业停产整顿或吊销其产品生产许可证、营业执照："},{"i":14,"n":"第十四条","txt":"获得国家质量奖或优质产品标志的产品，如质量下降、不符合优质条件，标准化管理部门有权责令该产品生产企业停止使用国家质量奖或优质产品标志，并限期达到原有质量水平；逾期未达到的，提请有关主管部门取消优质荣誉称号，收回国家质量奖或优质产品证书、标志，并予通报。"},{"i":15,"n":"第十五条","txt":"产品质量监督检验人员，必须正确行使职权，坚持原则，秉公办事，不得玩忽职守，徇私舞弊。如有违反，应当根据情节轻重，给予批评教育或行政处分，直至追究法律责任。"},{"i":16,"n":"第十六条","txt":"产品质量监督检验机构对产品进行质量监督检验，得酌收检验费，具体办法由国家标准局和省、自治区、直辖市标准化管理部门制定。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市可根据本办法制定具体规定。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。"}],"chengshigongshuitiaoli-2":[{"i":1,"n":"第一条","txt":"为了加强城市供水管理，发展城市供水事业，保障城市生活、生产用水和其他各项建设用水，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称城市供水，是指城市公共供水和自建设施供水。"},{"i":3,"n":"第三条","txt":"从事城市供水工作和使用城市供水，必须遵守本条例。"},{"i":4,"n":"第四条","txt":"城市供水工作实行开发水源和计划用水、节约用水相结合的原则。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将发展城市供水事业纳入国民经济和社会发展计划。"},{"i":6,"n":"第六条","txt":"国家实行有利于城市供水事业发展的政策，鼓励城市供水科学技术研究，推广先进技术，提高城市供水的现代化水平。"},{"i":7,"n":"第七条","txt":"国务院城市建设行政主管部门主管全国城市供水工作。"},{"i":8,"n":"第八条","txt":"对在城市供水工作中作出显著成绩的单位和个人，给予奖励。"},{"i":9,"n":"第九条","txt":"县级以上城市人民政府应当组织城市规划行政主管部门、水行政主管部门、城市供水行政主管部门和地质矿产行政主管部门等共同编制城市供水水源开发利用规划，作为城市供水发展规划的组成部分，纳入城市总体规划。"},{"i":10,"n":"第十条","txt":"编制城市供水水源开发利用规划，应当从城市发展的需要出发，并与水资源统筹规划和水长期供求计划相协调。"},{"i":11,"n":"第十一条","txt":"编制城市供水水源开发利用规划，应当根据当地情况，合理安排利用地表水和地下水。"},{"i":12,"n":"第十二条","txt":"编制城市供水水源开发利用规划，应当优先保证城市生活用水，统筹兼顾工业用水和其他各项建设用水。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府环境保护部门应当会同城市供水行政主管部门、水行政主管部门和卫生行政主管部门等共同划定饮用水水源保护区，经本级人民政府批准后公布；划定跨省、市、县的饮用水水源保护区，应当由有关人民政府共同商定并经其共同的上级人民政府批准后公布。"},{"i":14,"n":"第十四条","txt":"在饮用水水源保护区内，禁止一切污染水质的活动。"},{"i":15,"n":"第十五条","txt":"城市供水工程的建设，应当按照城市供水发展规划及其年度建设计划进行。"},{"i":16,"n":"第十六条","txt":"城市供水工程的设计、施工，应当委托持有相应资质证书的设计、施工单位承担，并遵守国家有关技术标准和规范。禁止无证或者超越资质证书规定的经营范围承担城市供水工程的设计、施工任务。"},{"i":17,"n":"第十七条","txt":"城市供水工程竣工后，应当按照国家规定组织验收；未经验收或者验收不合格的，不得投入使用。"},{"i":18,"n":"第十八条","txt":"城市新建、扩建、改建工程项目需要增加用水的，其工程项目总概算应当包括供水工程建设投资；需要增加城市公共供水量的，应当将其供水工程建设投资交付城市供水行政主管部门，由其统一组织城市公共供水工程建设。"},{"i":19,"n":"第十九条","txt":"城市自来水供水企业和自建设施对外供水的企业，经工商行政管理机关登记注册后，方可从事经营活动。"},{"i":20,"n":"第二十条","txt":"城市自来水供水企业和自建设施对外供水的企业，应当建立、健全水质检测制度，确保城市供水的水质符合国家规定的饮用水卫生标准。"},{"i":21,"n":"第二十一条","txt":"城市自来水供水企业和自建设施对外供水的企业，应当按照国家有关规定设置管网测压点，做好水压监测工作，确保供水管网的压力符合国家规定的标准。"},{"i":22,"n":"第二十二条","txt":"城市自来水供水企业和自建设施对外供水的企业应当保持不间断供水。由于工程施工、设备维修等原因确需停止供水的，应当经城市供水行政主管部门批准并提前24小时通知用水单位和个人；因发生灾害或者紧急事故，不能提前通知的，应当在抢修的同时通知用水单位和个人，尽快恢复正常供水，并报告城市供水行政主管部门。"},{"i":23,"n":"第二十三条","txt":"城市自来水供水企业和自建设施对外供水的企业应当实行职工持证上岗制度。具体办法由国务院城市建设行政主管部门会同人事部门等制定。"},{"i":24,"n":"第二十四条","txt":"用水单位和个人应当按照规定的计量标准和水价标准按时缴纳水费。"},{"i":25,"n":"第二十五条","txt":"禁止盗用或者转供城市公共供水。"},{"i":26,"n":"第二十六条","txt":"城市供水价格应当按照生活用水保本微利、生产和经营用水合理计价的原则制定。"},{"i":27,"n":"第二十七条","txt":"城市自来水供水企业和自建设施供水的企业对其管理的城市供水的专用水库、引水渠道、取水口、泵站、井群、输（配）水管网、进户总水表、净（配）水厂、公用水站等设施，应当定期检查维修，确保安全运行。"},{"i":28,"n":"第二十八条","txt":"用水单位自行建设的与城市公共供水管道连接的户外管道及其附属设施，必须经城市自来水供水企业验收合格并交其统一管理后，方可使用。"},{"i":29,"n":"第二十九条","txt":"在规定的城市公共供水管道及其附属设施的地面和地下的安全保护范围内，禁止挖坑取土或者修建建筑物、构筑物等危害供水设施安全的活动。"},{"i":30,"n":"第三十条","txt":"因工程建设确需改装、拆除或者迁移城市公共供水设施的，建设单位应当报经县级以上人民政府城市规划行政主管部门和城市供水行政主管部门批准，并采取相应的补救措施。"},{"i":31,"n":"第三十一条","txt":"涉及城市公共供水设施的建设工程开工前，建设单位或者施工单位应当向城市自来水供水企业查明地下供水管网情况。施工影响城市公共供水设施安全的，建设单位或者施工单位应当与城市自来水供水企业商定相应的保护措施，由施工单位负责实施。"},{"i":32,"n":"第三十二条","txt":"禁止擅自将自建设施供水管网系统与城市公共供水管网系统连接；因特殊情况确需连接的，必须经城市自来水供水企业同意，并在管道连接处采取必要的防护措施。"},{"i":33,"n":"第三十三条","txt":"城市自来水供水企业或者自建设施对外供水的企业有下列行为之一的，由城市供水行政主管部门责令改正，可以处以罚款；情节严重的，报经县级以上人民政府批准，可以责令停业整顿；对负有直接责任的主管人员和其他直接责任人员，其所在单位或者上级机关可以给予行政处分："},{"i":34,"n":"第三十四条","txt":"违反本条例规定，有下列行为之一的，由城市供水行政主管部门责令停止违法行为，可以处以罚款；对负有直接责任的主管人员和其他直接责任人员，其所在单位或者上级机关可以给予行政处分："},{"i":35,"n":"第三十五条","txt":"违反本条例规定，有下列行为之一的，由城市供水行政主管部门或者其授权的单位责令限期改正，可以处以罚款："},{"i":36,"n":"第三十六条","txt":"建设工程施工危害城市公共供水设施的，由城市供水行政主管部门责令停止危害活动；造成损失的，由责任方依法赔偿损失；对负有直接责任的主管人员和其他直接责任人员，其所在单位或者上级机关可以给予行政处分。"},{"i":37,"n":"第三十七条","txt":"城市供水行政主管部门的工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"本条例第三十三条、第三十四条、第三十五条规定的罚款数额由省、自治区、直辖市人民政府规定。"},{"i":39,"n":"第三十九条","txt":"本条例自1994年10月1日起施行。"}],"chengshigongshuitiaoli":[{"i":1,"n":"第一条","txt":"为了加强城市供水管理，发展城市供水事业，保障城市生活、生产用水和其他各项建设用水，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称城市供水，是指城市公共供水和自建设施供水。"},{"i":3,"n":"第三条","txt":"从事城市供水工作和使用城市供水，必须遵守本条例。"},{"i":4,"n":"第四条","txt":"城市供水工作实行开发水源和计划用水、节约用水相结合的原则。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将发展城市供水事业纳入国民经济和社会发展计划。"},{"i":6,"n":"第六条","txt":"国家实行有利于城市供水事业发展的政策，鼓励城市供水科学技术研究，推广先进技术，提高城市供水的现代化水平。"},{"i":7,"n":"第七条","txt":"国务院城市建设行政主管部门主管全国城市供水工作。"},{"i":8,"n":"第八条","txt":"对在城市供水工作中作出显著成绩的单位和个人，给予奖励。"},{"i":9,"n":"第九条","txt":"县级以上城市人民政府应当组织城市规划行政主管部门、水行政主管部门、城市供水行政主管部门和地质矿产行政主管部门等共同编制城市供水水源开发利用规划，作为城市供水发展规划的组成部分，纳入城市总体规划。"},{"i":10,"n":"第十条","txt":"编制城市供水水源开发利用规划，应当从城市发展的需要出发，并与水资源统筹规划和水长期供求计划相协调。"},{"i":11,"n":"第十一条","txt":"编制城市供水水源开发利用规划，应当根据当地情况，合理安排利用地表水和地下水。"},{"i":12,"n":"第十二条","txt":"编制城市供水水源开发利用规划，应当优先保证城市生活用水，统筹兼顾工业用水和其他各项建设用水。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府环境保护部门应当会同城市供水行政主管部门、水行政主管部门和卫生行政主管部门等共同划定饮用水水源保护区，经本级人民政府批准后公布；划定跨省、市、县的饮用水水源保护区，应当由有关人民政府共同商定并经其共同的上级人民政府批准后公布。"},{"i":14,"n":"第十四条","txt":"在饮用水水源保护区内，禁止一切污染水质的活动。"},{"i":15,"n":"第十五条","txt":"城市供水工程的建设，应当按照城市供水发展规划及其年度建设计划进行。"},{"i":16,"n":"第十六条","txt":"城市供水工程的设计、施工，应当委托持有相应资质证书的设计、施工单位承担，并遵守国家有关技术标准和规范。禁止无证或者超越资质证书规定的经营范围承担城市供水工程的设计、施工任务。"},{"i":17,"n":"第十七条","txt":"城市供水工程竣工后，应当按照国家规定组织验收；未经验收或者验收不合格的，不得投入使用。"},{"i":18,"n":"第十八条","txt":"城市新建、扩建、改建工程项目需要增加用水的，其工程项目总概算应当包括供水工程建设投资；需要增加城市公共供水量的，应当将其供水工程建设投资交付城市供水行政主管部门，由其统一组织城市公共供水工程建设。"},{"i":19,"n":"第十九条","txt":"城市自来水供水企业和自建设施对外供水的企业，经工商行政管理机关登记注册后，方可从事经营活动。"},{"i":20,"n":"第二十条","txt":"城市自来水供水企业和自建设施对外供水的企业，应当建立、健全水质检测制度，确保城市供水的水质符合国家规定的饮用水卫生标准。"},{"i":21,"n":"第二十一条","txt":"城市自来水供水企业和自建设施对外供水的企业，应当按照国家有关规定设置管网测压点，做好水压监测工作，确保供水管网的压力符合国家规定的标准。"},{"i":22,"n":"第二十二条","txt":"城市自来水供水企业和自建设施对外供水的企业应当保持不间断供水。由于工程施工、设备维修等原因确需停止供水的，应当经城市供水行政主管部门批准并提前24小时通知用水单位和个人；因发生灾害或者紧急事故，不能提前通知的，应当在抢修的同时通知用水单位和个人，尽快恢复正常供水，并报告城市供水行政主管部门。"},{"i":23,"n":"第二十三条","txt":"城市自来水供水企业和自建设施对外供水的企业应当实行职工持证上岗制度。具体办法由国务院城市建设行政主管部门会同人事部门等制定。"},{"i":24,"n":"第二十四条","txt":"用水单位和个人应当按照规定的计量标准和水价标准按时缴纳水费。"},{"i":25,"n":"第二十五条","txt":"禁止盗用或者转供城市公共供水。"},{"i":26,"n":"第二十六条","txt":"城市供水价格应当按照生活用水保本微利、生产和经营用水合理计价的原则制定。"},{"i":27,"n":"第二十七条","txt":"城市自来水供水企业和自建设施供水的企业对其管理的城市供水的专用水库、引水渠道、取水口、泵站、井群、输（配）水管网、进户总水表、净（配）水厂、公用水站等设施，应当定期检查维修，确保安全运行。"},{"i":28,"n":"第二十八条","txt":"用水单位自行建设的与城市公共供水管道连接的户外管道及其附属设施，必须经城市自来水供水企业验收合格并交其统一管理后，方可使用。"},{"i":29,"n":"第二十九条","txt":"在规定的城市公共供水管道及其附属设施的地面和地下的安全保护范围内，禁止挖坑取土或者修建建筑物、构筑物等危害供水设施安全的活动。"},{"i":30,"n":"第三十条","txt":"因工程建设确需改装、拆除或者迁移城市公共供水设施的，建设单位应当报经县级以上人民政府城市规划行政主管部门和城市供水行政主管部门批准，并采取相应的补救措施。"},{"i":31,"n":"第三十一条","txt":"涉及城市公共供水设施的建设工程开工前，建设单位或者施工单位应当向城市自来水供水企业查明地下供水管网情况。施工影响城市公共供水设施安全的，建设单位或者施工单位应当与城市自来水供水企业商定相应的保护措施，由施工单位负责实施。"},{"i":32,"n":"第三十二条","txt":"禁止擅自将自建设施供水管网系统与城市公共供水管网系统连接；因特殊情况确需连接的，必须经城市自来水供水企业同意，并在管道连接处采取必要的防护措施。"},{"i":33,"n":"第三十三条","txt":"城市自来水供水企业或者自建设施对外供水的企业有下列行为之一的，由城市供水行政主管部门责令改正，可以处以罚款；情节严重的，报经县级以上人民政府批准，可以责令停业整顿；对负有直接责任的主管人员和其他直接责任人员，其所在单位或者上级机关可以给予行政处分："},{"i":34,"n":"第三十四条","txt":"违反本条例规定，有下列行为之一的，由城市供水行政主管部门责令停止违法行为，可以处以罚款；对负有直接责任的主管人员和其他直接责任人员，其所在单位或者上级机关可以给予行政处分："},{"i":35,"n":"第三十五条","txt":"违反本条例规定，有下列行为之一的，由城市供水行政主管部门或者其授权的单位责令限期改正，可以处以罚款："},{"i":36,"n":"第三十六条","txt":"建设工程施工危害城市公共供水设施的，由城市供水行政主管部门责令停止危害活动；造成损失的，由责任方依法赔偿损失；对负有直接责任的主管人员和其他直接责任人员，其所在单位或者上级机关可以给予行政处分。"},{"i":37,"n":"第三十七条","txt":"城市供水行政主管部门的工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"本条例第三十三条、第三十四条、第三十五条规定的罚款数额由省、自治区、直辖市人民政府规定。"},{"i":39,"n":"第三十九条","txt":"本条例自1994年10月1日起施行。"}],"chengshiweihujiansheshuizanxingtiaoli":[{"i":1,"n":"第一条","txt":"为了加强城市的维护建设，扩大和稳定城市维护建设资金的来源，特制定本条例。"},{"i":2,"n":"第二条","txt":"凡缴纳消费税、增值税、营业税的单位和个人，都是城市维护建设税的纳税义务人（以下简称纳税人），都应当依照本条例的规定缴纳城市维护建设税。"},{"i":3,"n":"第三条","txt":"城市维护建设税，以纳税人实际缴纳的消费税、增值税、营业税税额为计税依据，分别与消费税、增值税、营业税同时缴纳。"},{"i":4,"n":"第四条","txt":"城市维护建设税税率如下："},{"i":5,"n":"第五条","txt":"城市维护建设税的征收、管理、纳税环节、奖罚等事项，比照消费税、增值税、营业税的有关规定办理。"},{"i":6,"n":"第六条","txt":"城市维护建设税应当保证用于城市的公用事业和公共设施的维护建设，具体安排由地方人民政府确定。"},{"i":7,"n":"第七条","txt":"按照本条例第四条第三项规定缴纳的税款，应当专用于乡镇的维护和建设。"},{"i":8,"n":"第八条","txt":"开征城市维护建设税后，任何地区和部门，都不得再向纳税人摊派资金或物资。遇到摊派情况，纳税人有权拒绝执行。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市人民政府可以根据本条例，制定实施细则，并送财政部备案。"},{"i":10,"n":"第十条","txt":"本条例自1985年度起施行。"}],"danganfashishibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国档案法》（以下简称《档案法》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"《档案法》第二条所称对国家和社会有保存价值的档案，属于国家所有的，由国家档案局会同国家有关部门确定具体范围；属于集体所有、个人所有以及其他不属于国家所有的，由省、自治区、直辖市人民政府档案行政管理部门征得国家档案局同意后确定具体范围。"},{"i":3,"n":"第三条","txt":"各级国家档案馆馆藏的永久保管档案分一、二、三级管理，分级的具体标准和管理办法由国家档案局制定。"},{"i":4,"n":"第四条","txt":"国务院各部门经国家档案局同意，省、自治区、直辖市人民政府各部门经本级人民政府档案行政管理部门同意，可以制定本系统专业档案的具体管理制度和办法。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府应当加强对档案工作的领导，把档案事业建设列入本级国民经济和社会发展计划，建立、健全档案机构，确定必要的人员编制，统筹安排发展档案事业所需经费。"},{"i":6,"n":"第六条","txt":"有下列事迹之一的，由人民政府、档案行政管理部门或者本单位给予奖励："},{"i":7,"n":"第七条","txt":"国家档案局依照《档案法》第六条第一款的规定，履行下列职责："},{"i":8,"n":"第八条","txt":"县级以上地方各级人民政府档案行政管理部门依照《档案法》第六条第二款的规定，履行下列职责："},{"i":9,"n":"第九条","txt":"机关、团体、企业事业单位和其他组织的档案机构依照《档案法》第七条的规定，履行下列职责："},{"i":10,"n":"第十条","txt":"中央和地方各级国家档案馆，是集中保存、管理档案的文化事业机构，依照《档案法》第八条的规定，承担下列工作任务："},{"i":11,"n":"第十一条","txt":"全国档案馆的设置原则和布局方案，由国家档案局制定，报国务院批准后实施。"},{"i":12,"n":"第十二条","txt":"按照国家档案局关于文件材料归档的规定，应当立卷归档的材料由单位的文书或者业务机构收集齐全，并进行整理、立卷，定期交本单位档案机构或者档案工作人员集中管理；任何人都不得据为己有或者拒绝归档。"},{"i":13,"n":"第十三条","txt":"机关、团体、企业事业单位和其他组织，应当按照国家档案局关于档案移交的规定，定期向有关的国家档案馆移交档案。"},{"i":14,"n":"第十四条","txt":"既是文物、图书资料又是档案的，档案馆可以与博物馆、图书馆、纪念馆等单位相互交换重复件、复制件或者目录，联合举办展览，共同编辑出版有关史料或者进行史料研究。"},{"i":15,"n":"第十五条","txt":"各级国家档案馆应当对所保管的档案采取下列管理措施："},{"i":16,"n":"第十六条","txt":"《档案法》第十四条所称保密档案密级的变更和解密，依照《中华人民共和国保守国家秘密法》及其实施办法的规定办理。"},{"i":17,"n":"第十七条","txt":"属于国家所有的档案，任何组织和个人都不得出卖。"},{"i":18,"n":"第十八条","txt":"各级国家档案馆馆藏的一级档案严禁出境。"},{"i":19,"n":"第十九条","txt":"各级国家档案馆保管的档案应当按照《档案法》的有关规定，分期分批地向社会开放，并同时公布开放档案的目录。档案开放的起始时间："},{"i":20,"n":"第二十条","txt":"各级各类档案馆提供社会利用的档案，应当逐步实现以缩微品代替原件。档案缩微品和其他复制形式的档案载有档案收藏单位法定代表人的签名或者印章标记的，具有与档案原件同等的效力。"},{"i":21,"n":"第二十一条","txt":"《档案法》所称档案的利用，是指对档案的阅览、复制和摘录。"},{"i":22,"n":"第二十二条","txt":"《档案法》第二十二条所称档案的公布，是指通过下列形式首次向社会公开档案的全部或者部分原文，或者档案记载的特定内容："},{"i":23,"n":"第二十三条","txt":"公布属于国家所有的档案，按照下列规定办理："},{"i":24,"n":"第二十四条","txt":"各级国家档案馆对寄存档案的公布和利用，应当征得档案所有者同意。"},{"i":25,"n":"第二十五条","txt":"利用、公布档案，不得违反国家有关知识产权保护的法律规定。"},{"i":26,"n":"第二十六条","txt":"有下列行为之一的，由县级以上人民政府档案行政管理部门责令限期改正；情节严重的，对直接负责的主管人员或者其他直接责任人员依法给予行政处分："},{"i":27,"n":"第二十七条","txt":"《档案法》第二十四条第二款、第三款规定的罚款数额，根据有关档案的价值和数量，对单位为1万元以上10万元以下，对个人为500元以上5000元以下。"},{"i":28,"n":"第二十八条","txt":"违反《档案法》和本办法，造成档案损失的，由县级以上人民政府档案行政管理部门、有关主管部门根据损失档案的价值，责令赔偿损失。"},{"i":29,"n":"第二十九条","txt":"中国人民解放军的档案工作，根据《档案法》和本办法确定的原则管理。"},{"i":30,"n":"第三十条","txt":"本办法自发布之日起施行。"}],"daodanjixiangguanwuxianghejishuchukouguanzhitiaoli":[{"i":1,"n":"第一条","txt":"为了加强对导弹及相关物项和技术出口的管制，维护国家安全和社会公共利益，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称导弹及相关物项和技术出口，是指本条例附件《导弹及相关物项和技术出口管制清单》（以下简称《管制清单》）所列的导弹及相关设备、材料、技术的贸易性出口以及对外赠送、展览、科技合作、援助、服务和以其他方式进行的技术转移。"},{"i":3,"n":"第三条","txt":"国家对导弹及相关物项和技术出口实行严格管制，防止《管制清单》所列的可被用于运载大规模杀伤性武器的导弹及其他运载系统的扩散。"},{"i":4,"n":"第四条","txt":"国家对导弹及相关物项和技术出口实行许可证件管理制度。未经许可，任何单位或者个人不得出口导弹及相关物项和技术。"},{"i":5,"n":"第五条","txt":"出口《管制清单》第一部分所列的物项和技术，依照《中华人民共和国军品出口管理条例》及其他有关规定办理。"},{"i":6,"n":"第六条","txt":"导弹相关物项和技术出口的接受方应当保证，未经中国政府允许，不将中国供应的导弹相关物项和技术用于申明的最终用途以外的其他用途，不将中国供应的导弹相关物项和技术向申明的最终用户以外的第三方转让。"},{"i":7,"n":"第七条","txt":"从事导弹相关物项和技术出口的经营者，须经国务院对外经济贸易主管部门（以下简称国务院外经贸主管部门）登记。未经登记，任何单位或者个人不得经营导弹相关物项和技术出口。具体登记办法由国务院外经贸主管部门规定。"},{"i":8,"n":"第八条","txt":"出口导弹相关物项和技术，应当向国务院外经贸主管部门提出申请，填写导弹相关物项和技术出口申请表（以下简称出口申请表），并提交下列文件："},{"i":9,"n":"第九条","txt":"申请人应当如实填写出口申请表。"},{"i":10,"n":"第十条","txt":"国务院外经贸主管部门应当自收到出口申请表和本条例第八条规定的文件之日起进行审查，或者会同国务院有关部门、中央军事委员会有关部门进行审查，并在45个工作日内作出许可或者不许可的决定。"},{"i":11,"n":"第十一条","txt":"对国家安全、社会公共利益有重大影响的导弹相关物项和技术出口，国务院外经贸主管部门应当会同有关部门报国务院、中央军事委员会批准。"},{"i":12,"n":"第十二条","txt":"导弹相关物项和技术出口申请经审查许可的，由国务院外经贸主管部门颁发导弹相关物项和技术出口许可证件（以下简称出口许可证件），并书面通知海关。"},{"i":13,"n":"第十三条","txt":"出口许可证件持有人改变原申请的导弹相关物项和技术出口的，应当交回原出口许可证件，并依照本条例的有关规定，重新申请、领取出口许可证件。"},{"i":14,"n":"第十四条","txt":"导弹相关物项和技术出口时，出口经营者应当向海关出具出口许可证件，依照海关法的规定办理海关手续，并接受海关监管。"},{"i":15,"n":"第十五条","txt":"接受方违反其依照本条例第六条规定作出的保证，或者出现《管制清单》所列的可被用于运载大规模杀伤性武器的导弹及其他运载系统扩散的危险时，国务院外经贸主管部门应当对已经颁发的出口许可证件予以中止或者撤销，并书面通知海关。"},{"i":16,"n":"第十六条","txt":"出口经营者知道或者应当知道所出口的导弹相关物项和技术将被接受方直接用于《管制清单》所列的可被用于运载大规模杀伤性武器的导弹及其他运载系统的发展计划的，即使该物项和技术未列入《管制清单》，也应当依照本条例的规定执行。"},{"i":17,"n":"第十七条","txt":"经国务院、中央军事委员会批准，国务院外经贸主管部门会同有关部门，可以临时决定对《管制清单》以外的特定物项和技术的出口依照本条例实施管制。"},{"i":18,"n":"第十八条","txt":"未经许可擅自出口导弹相关物项和技术的，或者擅自超出许可的范围出口导弹相关物项和技术的，依照刑法关于走私罪、非法经营罪、泄露国家秘密罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，区别不同情况，依照海关法的有关规定处罚，或者由国务院外经贸主管部门给予警告，没收违法所得，处违法所得1倍以上5倍以下的罚款；国务院外经贸主管部门并可以暂停直至撤销其对外贸易经营许可。"},{"i":19,"n":"第十九条","txt":"伪造、变造或者买卖导弹相关物项和技术出口许可证件的，依照刑法关于非法经营罪或者伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任；尚不够刑事处罚的，依照海关法的有关规定处罚；国务院外经贸主管部门并可以撤销其对外贸易经营许可。"},{"i":20,"n":"第二十条","txt":"以欺骗或者其他不正当手段获取导弹相关物项和技术出口许可证件的，由国务院外经贸主管部门收缴其出口许可证件，没收违法所得，处违法所得等值以下的罚款，暂停直至撤销其对外贸易经营许可。"},{"i":21,"n":"第二十一条","txt":"违反本条例第七条规定，未经登记擅自经营导弹相关物项和技术出口的，由国务院外经贸主管部门依法取缔其非法活动，并由国家有关主管部门依照有关法律和行政法规的规定给予处罚。"},{"i":22,"n":"第二十二条","txt":"对导弹相关物项和技术出口实施管制的国家工作人员滥用职权、玩忽职守或者利用职务上的便利索取、收受他人财物的，依照刑法关于滥用职权罪、玩忽职守罪、受贿罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。"},{"i":23,"n":"第二十三条","txt":"国务院外经贸主管部门会同有关部门，可以根据实际情况对《管制清单》进行调整，报国务院、中央军事委员会批准后执行。"},{"i":24,"n":"第二十四条","txt":"本条例自公布之日起施行。"}],"faguiguizhangbeiantiaoli":[{"i":1,"n":"第一条","txt":"为了维护社会主义法制的统一，加强对法规、规章的监督，根据立法法的有关规定，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称法规，是指省、自治区、直辖市和较大的市的人民代表大会及其常务委员会依照法定职权和程序制定的地方性法规，经济特区所在地的省、市的人民代表大会及其常务委员会依照法定职权和程序制定的经济特区法规，以及自治州、自治县的人民代表大会依照法定职权和程序制定的自治条例和单行条例。"},{"i":3,"n":"第三条","txt":"法规、规章公布后，应当自公布之日起30日内，依照下列规定报送备案："},{"i":4,"n":"第四条","txt":"国务院部门，省、自治区、直辖市和较大的市的人民政府应当依法履行规章备案职责，加强对规章备案工作的组织领导。"},{"i":5,"n":"第五条","txt":"国务院法制机构依照本条例的规定负责国务院的法规、规章备案工作，履行备案审查监督职责。"},{"i":6,"n":"第六条","txt":"依照本条例报送国务院备案的法规、规章，径送国务院法制机构。"},{"i":7,"n":"第七条","txt":"报送法规、规章备案，符合本条例第二条和第六条第二款、第三款规定的，国务院法制机构予以备案登记；不符合第二条规定的，不予备案登记；符合第二条规定但不符合第六条第二款、第三款规定的，暂缓办理备案登记。"},{"i":8,"n":"第八条","txt":"经备案登记的法规、规章，由国务院法制机构按月公布目录。"},{"i":9,"n":"第九条","txt":"国家机关、社会团体、企业事业组织、公民认为地方性法规同行政法规相抵触的，或者认为规章以及国务院各部门、省、自治区、直辖市和较大的市的人民政府发布的其他具有普遍约束力的行政决定、命令同法律、行政法规相抵触的，可以向国务院书面提出审查建议，由国务院法制机构研究并提出处理意见，按照规定程序处理。"},{"i":10,"n":"第十条","txt":"国务院法制机构对报送国务院备案的法规、规章，就下列事项进行审查："},{"i":11,"n":"第十一条","txt":"国务院法制机构审查法规、规章时，认为需要有关的国务院部门或者地方人民政府提出意见的，有关的机关应当在规定期限内回复；认为需要法规、规章的制定机关说明有关情况的，有关的制定机关应当在规定期限内予以说明。"},{"i":12,"n":"第十二条","txt":"经审查，地方性法规同行政法规相抵触的，由国务院提请全国人民代表大会常务委员会处理。"},{"i":13,"n":"第十三条","txt":"地方性法规与部门规章之间对同一事项的规定不一致的，由国务院法制机构提出处理意见，报国务院依照立法法第八十六条第一款第（二）项的规定处理。"},{"i":14,"n":"第十四条","txt":"经审查，规章超越权限，违反法律、行政法规的规定，或者其规定不适当的，由国务院法制机构建议制定机关自行纠正；或者由国务院法制机构提出处理意见报国务院决定，并通知制定机关。"},{"i":15,"n":"第十五条","txt":"部门规章之间、部门规章与地方政府规章之间对同一事项的规定不一致的，由国务院法制机构进行协调；经协调不能取得一致意见的，由国务院法制机构提出处理意见报国务院决定，并通知制定机关。"},{"i":16,"n":"第十六条","txt":"对《规章制定程序条例》第二条第二款、第八条第二款规定的无效规章，国务院法制机构不予备案，并通知制定机关。"},{"i":17,"n":"第十七条","txt":"规章的制定机关应当自接到本条例第十四条、第十五条、第十六条规定的通知之日起30日内，将处理情况报国务院法制机构。"},{"i":18,"n":"第十八条","txt":"根据本条例第十五条作出的处理结果，可以作为对最高人民法院依照行政诉讼法第五十三条送请国务院解释或者裁决的答复。"},{"i":19,"n":"第十九条","txt":"法规、规章的制定机关应当于每年1月底前将上一年所制定的法规、规章目录报国务院法制机构。"},{"i":20,"n":"第二十条","txt":"对于不报送规章备案或者不按时报送规章备案的，由国务院法制机构通知制定机关，限期报送；逾期仍不报送的，给予通报，并责令限期改正。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府应当依法加强对下级行政机关发布的规章和其他具有普遍约束力的行政决定、命令的监督，依照本条例的有关规定，建立相关的备案审查制度，维护社会主义法制的统一，保证法律、法规的正确实施。"},{"i":22,"n":"第二十二条","txt":"本条例自2002年1月1日起施行。1990年2月18日国务院发布的《法规、规章备案规定》同时废止。"}],"fangzhibushiganjunbingzanxingbanfa":[{"i":1,"n":"第一条","txt":"为预防和消灭布氏杆菌病（以下简称布病），提高人民健康水平，促进畜牧业发展，特制订本办法。"},{"i":2,"n":"第二条","txt":"卫生、农业（畜牧）、商业、外贸、供销、铁路和交通等部门应当把防治布病作为共同任务，统一规划，分工协作，认真做好。"},{"i":3,"n":"第三条","txt":"防治布病要发动群众，贯彻预防为主的方针，认真落实以畜间免疫为主的综合措施，控制和消灭布病。"},{"i":4,"n":"第四条","txt":"卫生、农业（畜牧）部门要掌握本地区的人畜间疫情，坚持疫情报告制度。"},{"i":5,"n":"第五条","txt":"卫生、农业（畜牧）部门对人畜疫情要及时采取有效措施，认真处理，防止蔓延。"},{"i":6,"n":"第六条","txt":"病畜是人畜布病的主要传染源。农业（畜牧）部门应将畜间免疫做为一项重要工作。认真组织社、队力量，因地制宜，保质保量，按时完成疫区羊、牛等牲畜的免疫工作。免疫后发给证明。"},{"i":7,"n":"第七条","txt":"农业（畜牧）部门要积极开展牲畜检疫工作，对种公畜、奶牛和奶羊要坚持定期检疫，并发检疫证。检出的阳性畜要设专人隔离放牧、饲养，或由商业部门统一收购处理。阳性种公畜必须淘汰。严禁私自买卖和转移病畜。"},{"i":8,"n":"第八条","txt":"牲畜的收购、调运、输入、屠宰要按有关规定进行检疫。已免疫的牲畜须有免疫证明。疫区牲畜迁移放牧要有农业部门出具的免疫或检疫证明。进口牲畜必须进行检疫。凡布病检疫阳性的牲畜要按病畜处理。"},{"i":9,"n":"第九条","txt":"生产队集体畜群要在村外饲养。社员自留畜一定要圈养，做到人畜分居。社员个人不得饲养病畜。工商行政管理部门要加强牲畜交易市场的管理，疫区自留畜及其产品进入集市市场必须有检疫或免疫证明。凡疫区牲畜迁移放牧和进入交易市场无证明者，当地农业（畜牧）部门应给予检疫或免疫并加倍收费。"},{"i":10,"n":"第十条","txt":"卫生部门要组织好重点人群的免疫工作。凡是在疫区从事放牧、配种、饲养等密切接触病畜的人员，屠宰病畜、病畜产品加工人员和从事布病防治、科研人员，都要有计划地进行免疫。"},{"i":11,"n":"第十一条","txt":"外贸、供销、轻工和纺织部门对从疫区收购的生皮、毛类等畜产品，在加工前，要积极创造条件，逐步做到消毒处理。饲养、运输单位对牲畜停留的圈舍、场地、装运的交通工具、产羔场地等都要进行消毒。商业部门对病畜肉必须经过高温处理，鲜牛、羊乳必须严格消毒后方可出售。"},{"i":12,"n":"第十二条","txt":"要广泛宣传、普及布病防治知识。饲养、生产单位和个人应负责管理好牲畜、粪便及水源，严格按卫生要求处理流产物，做好环境卫生和个人卫生。"},{"i":13,"n":"第十三条","txt":"凡直接从事布病防治、科研、检疫、化验和菌苗生产等人员，应发给劳动保护用品，并在工作期间享有保健津贴。有关部门抽调赤脚兽医、赤脚医生参加防治工作时，应给予适当保健和误工补贴。"},{"i":14,"n":"第十四条","txt":"各级医疗和卫生防疫单位都要积极承担布病的诊治任务，对从事人畜布病防治科研人员及重点职业人群都要进行定期检查。发现急性病人要立即给予治疗，同时要有计划地治疗慢性病人。治疗经费可根据情况实行“收、减、免”，经费由卫生防疫事业费开支。"},{"i":15,"n":"第十五条","txt":"卫生、畜牧防疫人员要负责检查、监督有关单位落实防治措施，提出改进意见。受检单位应认真研究落实，如因敷衍塞责而造成布病流行或蔓延时，防疫人员应向上级人民政府、主管部门报告，追究其责任。"},{"i":16,"n":"第十六条","txt":"卫生、农业（畜牧）、防疫、医疗、科研单位和有关高等院校等都要积极承担布病科研任务。重点科研课题要列入本地区、本部门计划，有关单位要加强领导，制定规划，认真解决必需的经费、仪器设备，按时完成研究项目。"},{"i":17,"n":"第十七条","txt":"人畜免疫菌苗必须经过国家有关部门核准生产使用。生物制品和兽药厂要保质保量按时供应菌苗、诊断用品和治疗用品。医药部门应根据防治、科研工作实际需要，安排好药品和器械的生产和供应。"},{"i":18,"n":"第十八条","txt":"各级人民政府和有关部门对认真贯彻执行本办法做出显著成绩的单位和个人，应当给予表扬和物质奖励；对违反本办法的单位和个人，应给予批评教育，情节恶劣，后果严重的，要给予纪律处分或依法惩处。"},{"i":19,"n":"第十九条","txt":"各省、市、自治区和有关部门，应根据本办法，结合具体情况，制订实施细则。"},{"i":20,"n":"第二十条","txt":"本办法自一九八〇年三月一日起施行。"}],"fangzhihaiangongchengjianshexiangmuwuransunhaihaiy61e21e":[{"i":1,"n":"第一条","txt":"为加强海岸工程建设项目的环境保护管理，严格控制新的污染，保护和改善海洋环境，根据《中华人民共和国海洋环境保护法》，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称海岸工程建设项目，是指位于海岸或者与海岸连接，工程主体位于海岸线向陆一侧，对海洋环境产生影响的新建、改建、扩建工程项目。具体包括："},{"i":3,"n":"第三条","txt":"本条例适用于在中华人民共和国境内兴建海岸工程建设项目的一切单位和个人。"},{"i":4,"n":"第四条","txt":"建设海岸工程建设项目，应当符合所在经济区的区域环境保护规划的要求。"},{"i":5,"n":"第五条","txt":"国务院环境保护主管部门，主管全国海岸工程建设项目的环境保护工作。"},{"i":6,"n":"第六条","txt":"新建、改建、扩建海岸工程建设项目，应当遵守国家有关建设项目环境保护管理的规定。"},{"i":7,"n":"第七条","txt":"海岸工程建设项目的建设单位，应当依法编制环境影响报告书（表），报环境保护主管部门审批。"},{"i":8,"n":"第八条","txt":"海岸工程建设项目环境影响报告书的内容，除按有关规定编制外，还应当包括："},{"i":9,"n":"第九条","txt":"禁止兴建向中华人民共和国海域及海岸转嫁污染的中外合资经营企业、中外合作经营企业和外资企业；海岸工程建设项目引进技术和设备，应当有相应的防治污染措施，防止转嫁污染。"},{"i":10,"n":"第十条","txt":"在海洋特别保护区、海上自然保护区、海滨风景游览区、盐场保护区、海水浴场、重要渔业水域和其他需要特殊保护的区域内不得建设污染环境、破坏景观的海岸工程建设项目；在其区域外建设海岸工程建设项目的，不得损害上述区域的环境质量。法律法规另有规定的除外。"},{"i":11,"n":"第十一条","txt":"海岸工程建设项目竣工验收时，建设项目的环境保护设施经验收合格后，该建设项目方可正式投入生产或者使用。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府环境保护主管部门，按照项目管理权限，可以会同有关部门对海岸工程建设项目进行现场检查，被检查者应当如实反映情况、提供资料。检查者有责任为被检查者保守技术秘密和业务秘密。法律法规另有规定的除外。"},{"i":13,"n":"第十三条","txt":"设置向海域排放废水设施的，应当合理利用海水自净能力，选择好排污口的位置。采用暗沟或者管道方式排放的，出水管口位置应当在低潮线以下。"},{"i":14,"n":"第十四条","txt":"建设港口、码头，应当设置与其吞吐能力和货物种类相适应的防污设施。"},{"i":15,"n":"第十五条","txt":"建设岸边造船厂、修船厂，应当设置与其性质、规模相适应的残油、废油接收处理设施，含油废水接收处理设施，拦油、收油、消油设施，工业废水接收处理设施，工业和船舶垃圾接收处理设施等。"},{"i":16,"n":"第十六条","txt":"建设滨海核电站和其他核设施，应当严格遵守国家有关核环境保护和放射防护的规定及标准。"},{"i":17,"n":"第十七条","txt":"建设岸边油库，应当设置含油废水接收处理设施，库场地面冲刷废水的集接、处理设施和事故应急设施；输油管线和储油设施应当符合国家关于防渗漏、防腐蚀的规定。"},{"i":18,"n":"第十八条","txt":"建设滨海矿山，在开采、选矿、运输、贮存、冶炼和尾矿处理等过程中，应当按照有关规定采取防止污染损害海洋环境的措施。"},{"i":19,"n":"第十九条","txt":"建设滨海垃圾场或者工业废渣填埋场，应当建造防护堤坝和场底封闭层，设置渗液收集、导出、处理系统和可燃性气体防爆装置。"},{"i":20,"n":"第二十条","txt":"修筑海岸防护工程，在入海河口处兴建水利设施、航道或者综合整治工程，应当采取措施，不得损害生态环境及水产资源。"},{"i":21,"n":"第二十一条","txt":"兴建海岸工程建设项目，不得改变、破坏国家和地方重点保护的野生动植物的生存环境。不得兴建可能导致重点保护的野生动植物生存环境污染和破坏的海岸工程建设项目；确需兴建的，应当征得野生动植物行政主管部门同意，并由建设单位负责组织采取易地繁育等措施，保证物种延续。"},{"i":22,"n":"第二十二条","txt":"集体所有制单位或者个人在全民所有的水域、海涂，建设构不成基本建设项目的养殖工程的，应当在县级以上地方人民政府规划的区域内进行。"},{"i":23,"n":"第二十三条","txt":"禁止在红树林和珊瑚礁生长的地区，建设毁坏红树林和珊瑚礁生态系统的海岸工程建设项目。"},{"i":24,"n":"第二十四条","txt":"兴建海岸工程建设项目，应当防止导致海岸非正常侵蚀。"},{"i":25,"n":"第二十五条","txt":"未持有经审核和批准的环境影响报告书（表），兴建海岸工程建设项目的，依照《中华人民共和国海洋环境保护法》第七十九条的规定予以处罚。"},{"i":26,"n":"第二十六条","txt":"拒绝、阻挠环境保护主管部门进行现场检查，或者在被检查时弄虚作假的，由县级以上人民政府环境保护主管部门依照《中华人民共和国海洋环境保护法》第七十五条的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"海岸工程建设项目的环境保护设施未建成或者未达到规定要求，该项目即投入生产、使用的，依照《中华人民共和国海洋环境保护法》第八十条的规定予以处罚。"},{"i":28,"n":"第二十八条","txt":"环境保护主管部门工作人员滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本条例自1990年8月1日起施行。"}],"fangzhiluyuanwuranwuwuransunhaihaiyanghuanjingguan02b677":[{"i":1,"n":"第一条","txt":"为加强对陆地污染源的监督管理，防治陆源污染物污染损害海洋环境，根据《中华人民共和国海洋环境保护法》，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称陆地污染源（简称陆源），是指从陆地向海域排放污染物，造成或者可能造成海洋环境污染损害的场所、设施等。"},{"i":3,"n":"第三条","txt":"本条例适用于在中华人民共和国境内向海域排放陆源污染物的一切单位和个人。"},{"i":4,"n":"第四条","txt":"国务院环境保护行政主管部门，主管全国防治陆源污染物污染损害海洋环境工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人向海域排放陆源污染物，必须执行国家和地方发布的污染物排放标准和有关规定。"},{"i":6,"n":"第六条","txt":"任何单位和个人向海域排放陆源污染物，必须向其所在地环境保护行政主管部门申报登记拥有的污染物排放设施、处理设施和在正常作业条件下排放污染物的种类、数量和浓度，提供防治陆源污染物污染损害海洋环境的资料，并将上述事项和资料抄送海洋行政主管部门。"},{"i":7,"n":"第七条","txt":"任何单位和个人向海域排放陆源污染物，超过国家和地方污染物排放标准的，必须缴纳超标准排污费，并负责治理。"},{"i":8,"n":"第八条","txt":"任何单位和个人，不得在海洋特别保护区、海上自然保护区、海滨风景游览区、盐场保护区、海水浴场、重要渔业水域和其他需要特殊保护的区域内兴建排污口。"},{"i":9,"n":"第九条","txt":"对向海域排放陆源污染物造成海洋环境严重污染损害的企业事业单位，限期治理。"},{"i":10,"n":"第十条","txt":"国务院各部门或者省、自治区、直辖市人民政府直接管辖的企业事业单位的限期治理，由省、自治区、直辖市人民政府的环境保护行政主管部门提出意见，报同级人民政府决定。市、县或者市、县以下人民政府管辖的企业事业单位的限期治理，由市、县人民政府环境保护行政主管部门提出意见，报同级人民政府决定。被限期治理的企业事业单位必须如期完成治理任务。"},{"i":11,"n":"第十一条","txt":"禁止在岸滩擅自堆放、弃置和处理固体废弃物。确需临时堆放、处理固体废弃物的，必须按照沿海省、自治区、直辖市人民政府环境保护行政主管部门规定的审批程序，提出书面申请。其主要内容包括："},{"i":12,"n":"第十二条","txt":"被批准设置废弃物堆放场、处理场的单位和个人，必须建造防护堤和防渗漏、防扬尘等设施，经批准设置废弃物堆放场、处理场的环境保护行政主管部门验收合格后方可使用。"},{"i":13,"n":"第十三条","txt":"禁止在岸滩采用不正当的稀释、渗透方式排放有毒、有害废水。"},{"i":14,"n":"第十四条","txt":"禁止向海域排放含高、中放射性物质的废水。"},{"i":15,"n":"第十五条","txt":"禁止向海域排放油类、酸液、碱液和毒液。"},{"i":16,"n":"第十六条","txt":"向海域排放含病原体的废水，必须经过处理，符合国家和地方规定的排放标准和有关规定。"},{"i":17,"n":"第十七条","txt":"向海域排放含热废水的水温应当符合国家有关规定。"},{"i":18,"n":"第十八条","txt":"向自净能力较差的海域排放含有机物和营养物质的工业废水和生活废水，应当控制排放量；排污口应当设置在海水交换良好处，并采用合理的排放方式，防止海水富营养化。"},{"i":19,"n":"第十九条","txt":"禁止将失效或者禁用的药物及药具弃置岸滩。"},{"i":20,"n":"第二十条","txt":"入海河口处发生陆源污染物污染损害海洋环境事故，确有证据证明是由河流携带污染物造成的，由入海河口处所在地的省、自治区、直辖市人民政府环境保护行政主管部门调查处理；河流跨越省、自治区、直辖市的，由入海河口处所在省、自治区、直辖市人民政府环境保护行政主管部门和水利部门会同有关省、自治区、直辖市人民政府环境保护行政主管部门、水利部门和流域管理机构调查处理。"},{"i":21,"n":"第二十一条","txt":"沿海相邻或者相向地区向同一海域排放陆源污染物的，由有关地方人民政府协商制定共同防治陆源污染物污染损害海洋环境的措施。"},{"i":22,"n":"第二十二条","txt":"一切单位和个人造成陆源污染物污染损害海洋环境事故时，必须立即采取措施处理，并在事故发生后四十八小时内，向当地人民政府环境保护行政主管部门作出事故发生的时间、地点、类型和排放污染物的数量、经济损失、人员受害等情况的初步报告，并抄送有关部门。事故查清后，应当向当地人民政府环境保护行政主管部门作出书面报告，并附有关证明文件。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府环境保护行政主管部门，按照项目管理权限，可以会同项目主管部门对排放陆源污染物的单位和个人进行现场检查，被检查者必须如实反映情况、提供资料。检查者有责任为被检查者保守技术秘密和业务秘密。法律法规另有规定的除外。"},{"i":24,"n":"第二十四条","txt":"违反本条例规定，具有下列情形之一的，由县级以上人民政府环境保护行政主管部门责令改正，并可处以三百元以上三千元以下的罚款："},{"i":25,"n":"第二十五条","txt":"废弃物堆放场、处理场的防污染设施未经环境保护行政主管部门验收或者验收不合格而强行使用的，由环境保护行政主管部门责令改正，并可处以五千元以上二万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"违反本条例规定，具有下列情形之一的，由县级以上人民政府环境保护行政主管部门责令改正，并可处以五千元以上十万元以下的罚款："},{"i":27,"n":"第二十七条","txt":"违反本条例规定，具有下列情形之一的，由县级以上人民政府环境保护行政主管部门责令改正，并可处以一千元以上二万元以下的罚款；情节严重的，可处以二万元以上十万元以下的罚款："},{"i":28,"n":"第二十八条","txt":"对逾期未完成限期治理任务的企业事业单位，征收两倍的超标准排污费，并可根据危害和损失后果，处以一万元以上十万元以下的罚款，或者责令停业、关闭。"},{"i":29,"n":"第二十九条","txt":"不按规定缴纳超标准排污费的，除追缴超标准排污费及滞纳金外，并可由县级以上人民政府环境保护行政主管部门处以一千元以上一万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"对造成陆源污染物污染损害海洋环境事故，导致重大经济损失的，由县级以上人民政府环境保护行政主管部门按照直接损失百分之三十计算罚款，但最高不得超过二十万元。"},{"i":31,"n":"第三十一条","txt":"县级人民政府环境保护行政主管部门可处以一万元以下的罚款，超过一万元的罚款，报上级环境保护行政主管部门批准。"},{"i":32,"n":"第三十二条","txt":"缴纳超标准排污费或者被处以罚款的单位、个人，并不免除消除污染、排除危害和赔偿损失的责任。"},{"i":33,"n":"第三十三条","txt":"当事人对行政处罚决定不服的，可以在接到处罚通知之日起十五日内，依法申请复议；对复议决定不服的，可以在接到复议决定之日起十五日内，向人民法院起诉。当事人也可以在接到处罚通知之日起十五日内，直接向人民法院起诉。当事人逾期不申请复议、也不向人民法院起诉、又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":34,"n":"第三十四条","txt":"环境保护行政主管部门工作人员滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"沿海省、自治区、直辖市人民政府，可以根据本条例制定实施办法。"},{"i":36,"n":"第三十六条","txt":"本条例由国务院环境保护行政主管部门负责解释。"},{"i":37,"n":"第三十七条","txt":"本条例自一九九〇年八月一日起施行。"}],"feifajinrongjigouhefeifajinrongyewuhuodongqudibanf29589a":[{"i":1,"n":"第一条","txt":"为了取缔非法金融机构和非法金融业务活动，维护金融秩序，保护社会公众利益，制定本办法。"},{"i":2,"n":"第二条","txt":"任何非法金融机构和非法金融业务活动，必须予以取缔。"},{"i":3,"n":"第三条","txt":"本办法所称非法金融机构，是指未经中国人民银行批准，擅自设立从事或者主要从事吸收存款、发放贷款、办理结算、票据贴现、资金拆借、信托投资、金融租赁、融资担保、外汇买卖等金融业务活动的机构。"},{"i":4,"n":"第四条","txt":"本办法所称非法金融业务活动，是指未经中国人民银行批准，擅自从事的下列活动："},{"i":5,"n":"第五条","txt":"未经中国人民银行依法批准，任何单位和个人不得擅自设立金融机构或者擅自从事金融业务活动。"},{"i":6,"n":"第六条","txt":"非法金融机构和非法金融业务活动由中国人民银行予以取缔。"},{"i":7,"n":"第七条","txt":"中国人民银行依法取缔非法金融机构和非法金融业务活动，任何单位和个人不得干涉，不得拒绝、阻挠。"},{"i":8,"n":"第八条","txt":"中国人民银行工作人员在履行取缔非法金融机构和非法金融业务活动的职责中，应当依法保守秘密。"},{"i":9,"n":"第九条","txt":"对非法金融机构、非法吸收公众存款或者变相吸收公众存款以及非法集资，中国人民银行一经发现，应当立即调查、核实；经初步认定后，应当及时提请公安机关依法立案侦查。"},{"i":10,"n":"第十条","txt":"在调查、侦查非法金融机构和非法金融业务活动的过程中，中国人民银行和公安机关应当互相配合。"},{"i":11,"n":"第十一条","txt":"对非法金融机构和非法金融业务活动的犯罪嫌疑人、涉案资金和财产，由公安机关依法采取强制措施，防止犯罪嫌疑人逃跑和转移资金、财产。"},{"i":12,"n":"第十二条","txt":"对非法金融机构和非法金融业务活动，经中国人民银行调查认定后，作出取缔决定，宣布该金融机构和金融业务活动为非法，责令停止一切业务活动，并予公告。"},{"i":13,"n":"第十三条","txt":"中国人民银行发现金融机构为非法金融机构或者非法金融业务活动开立账户、办理结算和提供贷款的，应当责令该金融机构立即停止有关业务活动。"},{"i":14,"n":"第十四条","txt":"中国人民银行对非法金融机构和非法金融业务活动进行调查时，被调查的单位和个人必须接受中国人民银行依法进行的调查，如实反映情况，提供有关资料，不得拒绝、隐瞒。"},{"i":15,"n":"第十五条","txt":"中国人民银行调查非法金融机构和非法金融业务活动时，对与案件有关的情况和资料，可以采取记录、复制、录音等手段取得证据。"},{"i":16,"n":"第十六条","txt":"因非法金融业务活动形成的债权债务，由从事非法金融业务活动的机构负责清理清退。"},{"i":17,"n":"第十七条","txt":"非法金融机构一经中国人民银行宣布取缔，有批准部门、主管单位或者组建单位的，由批准部门、主管单位或者组建单位负责组织清理清退债权债务；没有批准部门、主管单位或者组建单位的，由所在地的地方人民政府负责组织清理清退债权债务。"},{"i":18,"n":"第十八条","txt":"因参与非法金融业务活动受到的损失，由参与者自行承担。"},{"i":19,"n":"第十九条","txt":"非法金融业务活动所形成的债务和风险，不得转嫁给未参与非法金融业务活动的国有银行和其他金融机构以及其他任何单位。"},{"i":20,"n":"第二十条","txt":"债权债务清理清退后，有剩余非法财物的，予以没收，就地上缴中央金库。"},{"i":21,"n":"第二十一条","txt":"因清理清退发生纠纷的，由当事人协商解决；协商不成的，通过司法程序解决。"},{"i":22,"n":"第二十二条","txt":"设立非法金融机构或者从事非法金融业务活动，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由中国人民银行没收非法所得，并处非法所得1倍以上5倍以下的罚款；没有非法所得的，处10万元以上50万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"擅自批准设立非法金融机构或者擅自批准从事非法金融业务活动的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"金融机构违反规定，为非法金融机构或者非法金融业务活动开立账户、办理结算或者提供贷款的，由中国人民银行责令改正，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得的，处10万元以上50万元以下的罚款；对直接负责的主管人员和其他直接责任人员依法给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"拒绝、阻碍中国人民银行依法执行职务，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关依法给予治安管理处罚。"},{"i":26,"n":"第二十六条","txt":"中国人民银行工作人员在履行取缔非法金融机构和非法金融业务活动的职责中泄露秘密的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"中国人民银行、公安机关和工商行政管理机关工作人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":28,"n":"第二十八条","txt":"取缔非法证券机构和非法证券业务活动参照本办法执行，由中国证券监督管理委员会负责实施，并可以根据本办法的原则制定具体实施办法。"},{"i":29,"n":"第二十九条","txt":"本办法施行前设立的各类基金会、互助会、储金会、资金服务部、股金服务部、结算中心、投资公司等机构，超越国家政策范围，从事非法金融业务活动的，应当按照国务院的规定，限期清理整顿。超过规定期限继续从事非法金融业务活动的，依照本办法予以取缔；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法自发布之日起施行。"}],"getigongshanghutiaoli":[{"i":1,"n":"第一条","txt":"为了保护个体工商户的合法权益，鼓励、支持和引导个体工商户健康发展，加强对个体工商户的监督、管理，发挥其在经济社会发展和扩大就业中的重要作用，制定本条例。"},{"i":2,"n":"第二条","txt":"有经营能力的公民，依照本条例规定经工商行政管理部门登记，从事工商业经营的，为个体工商户。"},{"i":3,"n":"第三条","txt":"县、自治县、不设区的市、市辖区工商行政管理部门为个体工商户的登记机关（以下简称登记机关）。登记机关按照国务院工商行政管理部门的规定，可以委托其下属工商行政管理所办理个体工商户登记。"},{"i":4,"n":"第四条","txt":"国家对个体工商户实行市场平等准入、公平待遇的原则。"},{"i":5,"n":"第五条","txt":"工商行政管理部门和县级以上人民政府其他有关部门应当依法对个体工商户实行监督和管理。"},{"i":6,"n":"第六条","txt":"地方各级人民政府和县级以上人民政府有关部门应当采取措施，在经营场所、创业和职业技能培训、职业技能鉴定、技术创新、参加社会保险等方面，为个体工商户提供支持、便利和信息咨询等服务。"},{"i":7,"n":"第七条","txt":"依法成立的个体劳动者协会在工商行政管理部门指导下，为个体工商户提供服务，维护个体工商户合法权益，引导个体工商户诚信自律。"},{"i":8,"n":"第八条","txt":"申请登记为个体工商户，应当向经营场所所在地登记机关申请注册登记。申请人应当提交登记申请书、身份证明和经营场所证明。"},{"i":9,"n":"第九条","txt":"登记机关对申请材料依法审查后，按照下列规定办理："},{"i":10,"n":"第十条","txt":"个体工商户登记事项变更的，应当向登记机关申请办理变更登记。"},{"i":11,"n":"第十一条","txt":"申请注册登记或者变更登记的登记事项属于依法须取得行政许可的，应当向登记机关提交许可证明。"},{"i":12,"n":"第十二条","txt":"个体工商户不再从事经营活动的，应当到登记机关办理注销登记。"},{"i":13,"n":"第十三条","txt":"个体工商户应当于每年1月1日至6月30日，向登记机关报送年度报告。"},{"i":14,"n":"第十四条","txt":"登记机关将未按照规定履行年度报告义务的个体工商户载入经营异常名录，并在企业信用信息公示系统上向社会公示。"},{"i":15,"n":"第十五条","txt":"登记机关接收个体工商户年度报告和抽查不得收取任何费用。"},{"i":16,"n":"第十六条","txt":"登记机关和有关行政机关应当在其政府网站和办公场所，以便于公众知晓的方式公布个体工商户申请登记和行政许可的条件、程序、期限、需要提交的全部材料目录和收费标准等事项。"},{"i":17,"n":"第十七条","txt":"个体工商户在领取营业执照后，应当依法办理税务登记。"},{"i":18,"n":"第十八条","txt":"任何部门和单位不得向个体工商户集资、摊派，不得强行要求个体工商户提供赞助或者接受有偿服务。"},{"i":19,"n":"第十九条","txt":"地方各级人民政府应当将个体工商户所需生产经营场地纳入城乡建设规划，统筹安排。"},{"i":20,"n":"第二十条","txt":"个体工商户可以凭营业执照及税务登记证明，依法在银行或者其他金融机构开立账户，申请贷款。"},{"i":21,"n":"第二十一条","txt":"个体工商户可以根据经营需要招用从业人员。"},{"i":22,"n":"第二十二条","txt":"个体工商户提交虚假材料骗取注册登记，或者伪造、涂改、出租、出借、转让营业执照的，由登记机关责令改正，处4000元以下的罚款；情节严重的，撤销注册登记或者吊销营业执照。"},{"i":23,"n":"第二十三条","txt":"个体工商户登记事项变更，未办理变更登记的，由登记机关责令改正，处1500元以下的罚款；情节严重的，吊销营业执照。"},{"i":24,"n":"第二十四条","txt":"在个体工商户营业执照有效期内，有关行政机关依法吊销、撤销个体工商户的行政许可，或者行政许可有效期届满的，应当自吊销、撤销行政许可或者行政许可有效期届满之日起5个工作日内通知登记机关，由登记机关撤销注册登记或者吊销营业执照，或者责令当事人依法办理变更登记。"},{"i":25,"n":"第二十五条","txt":"工商行政管理部门以及其他有关部门应当加强个体工商户管理工作的信息交流，逐步建立个体工商户管理信息系统。"},{"i":26,"n":"第二十六条","txt":"工商行政管理部门以及其他有关部门的工作人员，滥用职权、徇私舞弊、收受贿赂或者侵害个体工商户合法权益的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"香港特别行政区、澳门特别行政区永久性居民中的中国公民，台湾地区居民可以按照国家有关规定，申请登记为个体工商户。"},{"i":28,"n":"第二十八条","txt":"个体工商户申请转变为企业组织形式，符合法定条件的，登记机关和有关行政机关应当为其提供便利。"},{"i":29,"n":"第二十九条","txt":"无固定经营场所摊贩的管理办法，由省、自治区、直辖市人民政府根据当地实际情况规定。"},{"i":30,"n":"第三十条","txt":"本条例自2011年11月1日起施行。1987年8月5日国务院发布的《城乡个体工商户管理暂行条例》同时废止。"}],"gongminchujingrujingguanlifashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国公民出境入境管理法》第十九条的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"本实施细则适用于中国公民因私事出境、入境。所称“私事”，是指：定居、探亲、访友、继承财产、留学、就业、旅游和其他非公务活动。"},{"i":3,"n":"第三条","txt":"居住国内的公民因私事出境，须向户口所在地的市、县公安局出入境管理部门提出申请，回答有关的询问并履行下列手续："},{"i":4,"n":"第四条","txt":"本实施细则第三条第四项所称的证明是指："},{"i":5,"n":"第五条","txt":"市、县公安局对出境申请应当在30天内，地处偏僻、交通不便的应当在60天内，作出批准或者不批准的决定，通知申请人。"},{"i":6,"n":"第六条","txt":"居住国内的公民经批准出境的，由公安机关出入境管理部门发给中华人民共和国护照，并附发出境登记卡。"},{"i":7,"n":"第七条","txt":"居住国内的公民办妥前往国家的签证或者入境许可证件后，应当在出境前办理户口手续。出境定居的，须到当地公安派出所或者户籍办公室注销户口。短期出境的，办理临时外出的户口登记，返回后凭护照在原居住地恢复常住户口。"},{"i":8,"n":"第八条","txt":"中国公民回国后再出境，凭有效的中华人民共和国护照或者有效的中华人民共和国旅行证或者其他有效出境入境证件。"},{"i":9,"n":"第九条","txt":"在境外的中国公民短期回国，凭有效的中华人民共和国护照或者有效的中华人民共和国旅行证或者其他有效入境出境证件入境。"},{"i":10,"n":"第十条","txt":"定居国外的中国公民要求回国定居的，应当在入境前向中国驻外国的外交代表机关、领事机关或者外交部授权的其他驻外机关提出申请，也可由本人或者经由国内亲属向拟定居地的市、县公安局提出申请，由省、自治区、直辖市公安厅（局）核发回国定居证明。"},{"i":11,"n":"第十一条","txt":"定居国外的中国公民要求回国工作的，应当向中国劳动、人事部门或者聘请、雇用单位提出申请。"},{"i":12,"n":"第十二条","txt":"定居国外的中国公民回国定居或者回国工作抵达目的地后，应当在30天内凭回国定居证明或者经中国劳动、人事部门核准的聘请、雇用证明到当地公安局办理常住户口登记。"},{"i":13,"n":"第十三条","txt":"定居国外的中国公民短期回国，要按照户口管理规定，办理暂住登记。在宾馆、饭店、旅店、招待所、学校等企业、事业单位或者机关、团体及其他机构内住宿的，应当填写临时住宿登记表；住在亲友家的，由本人或者亲友在24小时内（农村可在72小时内）到住地公安派出所或者户籍办公室办理暂住登记。"},{"i":14,"n":"第十四条","txt":"中国公民应当从对外开放的或者指定的口岸出境、入境，向边防检查站出示中华人民共和国护照或者其他出境入境证件，填交出境、入境登记卡，接受查验。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，边防检查站有权阻止出境、入境："},{"i":16,"n":"第十六条","txt":"中国公民出境入境的主要证件——中华人民共和国护照和中华人民共和国旅行证由持证人保存、使用。除公安机关和原发证机关有权依法吊销、收缴证件以及人民检察院、人民法院有权依法扣留证件外，其他任何机关、团体和企业、事业单位或者个人不得扣留证件。"},{"i":17,"n":"第十七条","txt":"中华人民共和国护照有效期5年，可以延期二次，每次不超过5年。申请延期应在护照有效期满前提出。"},{"i":18,"n":"第十八条","txt":"中华人民共和国旅行证分1年一次有效和2年多次有效两种，由中国驻外国的外交代表机关、领事机关或者外交部授权的其他驻外机关颁发。"},{"i":19,"n":"第十九条","txt":"中华人民共和国入出境通行证，是入出中国国（边）境的通行证件，由省、自治区、直辖市公安厅（局）及其授权的公安机关签发。这种证件在有效期内一次或者多次入出境有效。一次有效的，在出境时由边防检查站收缴。"},{"i":20,"n":"第二十条","txt":"中华人民共和国护照和其他出境入境证件的持有人，如因情况变化，护照、证件上的记载事项需要变更或者加注时，应当分别向市、县公安局出入境管理部门或者中国驻外国的外交代表机关、领事机关或者外交部授权的其他驻外机关提出申请，提交变更、加注事项的证明或者说明材料。"},{"i":21,"n":"第二十一条","txt":"中国公民持有的中华人民共和国护照和其他出境入境证件因即将期满或者签证页用完不能再延长有效期限，或者被损坏不能继续使用的，可以申请换发，同时交回原持有的护照、证件；要求保留原护照的，可以与新护照合订使用。护照、出境入境证件遗失的，应当报告中国主管机关，在登报声明或者挂失声明后申请补发。换发和补发护照、出境入境证件，在国外，由中国驻外国的外交代表机关、领事机关或者外交部授权的其他驻外机关办理；在国内，由省、自治区、直辖市公安厅（局）及其授权的公安机关出入境管理部门办理。"},{"i":22,"n":"第二十二条","txt":"中华人民共和国护照和其他出境入境证件的持有人有下列情形之一的，其护照、出境入境证件应予以吊销或者宣布作废："},{"i":23,"n":"第二十三条","txt":"持用伪造、涂改等无效证件或者冒用他人证件出境、入境的，除收缴证件外，处以警告或者5日以下拘留；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"伪造、涂改、转让、买卖出境入境证件的，处10日以下拘留；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"编造情况，提供假证明，或者以行贿等手段，获取出境入境证件，情节较轻的，处以警告或者5日以下拘留；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"公安机关的工作人员在执行《中华人民共和国公民出境入境管理法》和本实施细则时，如有利用职权索取、收受贿赂或者有其他违法失职行为，情节轻微的，由主管部门酌情予以行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"中国公民因公务出境和中国海员因执行任务出境管理办法，另行制订。"},{"i":28,"n":"第二十八条","txt":"本实施细则自发布之日起施行。"}],"gongsidengjiguanlitiaoli":[{"i":1,"n":"第一条","txt":"为了确认公司的企业法人资格，规范公司登记行为，依据《中华人民共和国公司法》（以下简称《公司法》），制定本条例。"},{"i":2,"n":"第二条","txt":"有限责任公司和股份有限公司（以下统称公司）设立、变更、终止，应当依照本条例办理公司登记。"},{"i":3,"n":"第三条","txt":"公司经公司登记机关依法登记，领取《企业法人营业执照》，方取得企业法人资格。"},{"i":4,"n":"第四条","txt":"工商行政管理机关是公司登记机关。"},{"i":5,"n":"第五条","txt":"国家工商行政管理总局主管全国的公司登记工作。"},{"i":6,"n":"第六条","txt":"国家工商行政管理总局负责下列公司的登记："},{"i":7,"n":"第七条","txt":"省、自治区、直辖市工商行政管理局负责本辖区内下列公司的登记："},{"i":8,"n":"第八条","txt":"设区的市（地区）工商行政管理局、县工商行政管理局，以及直辖市的工商行政管理分局、设区的市工商行政管理局的区分局，负责本辖区内下列公司的登记："},{"i":9,"n":"第九条","txt":"公司的登记事项包括："},{"i":10,"n":"第十条","txt":"公司的登记事项应当符合法律、行政法规的规定。不符合法律、行政法规规定的，公司登记机关不予登记。"},{"i":11,"n":"第十一条","txt":"公司名称应当符合国家有关规定。公司只能使用一个名称。经公司登记机关核准登记的公司名称受法律保护。"},{"i":12,"n":"第十二条","txt":"公司的住所是公司主要办事机构所在地。经公司登记机关登记的公司的住所只能有一个。公司的住所应当在其公司登记机关辖区内。"},{"i":13,"n":"第十三条","txt":"公司的注册资本应当以人民币表示，法律、行政法规另有规定的除外。"},{"i":14,"n":"第十四条","txt":"股东的出资方式应当符合《公司法》第二十七条的规定，但股东不得以劳务、信用、自然人姓名、商誉、特许经营权或者设定担保的财产等作价出资。"},{"i":15,"n":"第十五条","txt":"公司的经营范围由公司章程规定，并依法登记。"},{"i":16,"n":"第十六条","txt":"公司类型包括有限责任公司和股份有限公司。"},{"i":17,"n":"第十七条","txt":"设立公司应当申请名称预先核准。"},{"i":18,"n":"第十八条","txt":"设立有限责任公司，应当由全体股东指定的代表或者共同委托的代理人向公司登记机关申请名称预先核准；设立股份有限公司，应当由全体发起人指定的代表或者共同委托的代理人向公司登记机关申请名称预先核准。"},{"i":19,"n":"第十九条","txt":"预先核准的公司名称保留期为6个月。预先核准的公司名称在保留期内，不得用于从事经营活动，不得转让。"},{"i":20,"n":"第二十条","txt":"设立有限责任公司，应当由全体股东指定的代表或者共同委托的代理人向公司登记机关申请设立登记。设立国有独资公司，应当由国务院或者地方人民政府授权的本级人民政府国有资产监督管理机构作为申请人，申请设立登记。法律、行政法规或者国务院决定规定设立有限责任公司必须报经批准的，应当自批准之日起90日内向公司登记机关申请设立登记；逾期申请设立登记的，申请人应当报批准机关确认原批准文件的效力或者另行报批。"},{"i":21,"n":"第二十一条","txt":"设立股份有限公司，应当由董事会向公司登记机关申请设立登记。以募集方式设立股份有限公司的，应当于创立大会结束后30日内向公司登记机关申请设立登记。"},{"i":22,"n":"第二十二条","txt":"公司申请登记的经营范围中属于法律、行政法规或者国务院决定规定在登记前须经批准的项目的，应当在申请登记前报经国家有关部门批准，并向公司登记机关提交有关批准文件。"},{"i":23,"n":"第二十三条","txt":"公司章程有违反法律、行政法规的内容的，公司登记机关有权要求公司作相应修改。"},{"i":24,"n":"第二十四条","txt":"公司住所证明是指能够证明公司对其住所享有使用权的文件。"},{"i":25,"n":"第二十五条","txt":"依法设立的公司，由公司登记机关发给《企业法人营业执照》。公司营业执照签发日期为公司成立日期。公司凭公司登记机关核发的《企业法人营业执照》刻制印章，开立银行账户，申请纳税登记。"},{"i":26,"n":"第二十六条","txt":"公司变更登记事项，应当向原公司登记机关申请变更登记。"},{"i":27,"n":"第二十七条","txt":"公司申请变更登记，应当向公司登记机关提交下列文件："},{"i":28,"n":"第二十八条","txt":"公司变更名称的，应当自变更决议或者决定作出之日起30日内申请变更登记。"},{"i":29,"n":"第二十九条","txt":"公司变更住所的，应当在迁入新住所前申请变更登记，并提交新住所使用证明。"},{"i":30,"n":"第三十条","txt":"公司变更法定代表人的，应当自变更决议或者决定作出之日起30日内申请变更登记。"},{"i":31,"n":"第三十一条","txt":"公司增加注册资本的，应当自变更决议或者决定作出之日起30日内申请变更登记。"},{"i":32,"n":"第三十二条","txt":"公司变更经营范围的，应当自变更决议或者决定作出之日起30日内申请变更登记；变更经营范围涉及法律、行政法规或者国务院决定规定在登记前须经批准的项目的，应当自国家有关部门批准之日起30日内申请变更登记。"},{"i":33,"n":"第三十三条","txt":"公司变更类型的，应当按照拟变更的公司类型的设立条件，在规定的期限内向公司登记机关申请变更登记，并提交有关文件。"},{"i":34,"n":"第三十四条","txt":"有限责任公司变更股东的，应当自变更之日起30日内申请变更登记，并应当提交新股东的主体资格证明或者自然人身份证明。"},{"i":35,"n":"第三十五条","txt":"公司登记事项变更涉及分公司登记事项变更的，应当自公司变更登记之日起30日内申请分公司变更登记。"},{"i":36,"n":"第三十六条","txt":"公司章程修改未涉及登记事项的，公司应当将修改后的公司章程或者公司章程修正案送原公司登记机关备案。"},{"i":37,"n":"第三十七条","txt":"公司董事、监事、经理发生变动的，应当向原公司登记机关备案。"},{"i":38,"n":"第三十八条","txt":"因合并、分立而存续的公司，其登记事项发生变化的，应当申请变更登记；因合并、分立而解散的公司，应当申请注销登记；因合并、分立而新设立的公司，应当申请设立登记。"},{"i":39,"n":"第三十九条","txt":"变更登记事项涉及《企业法人营业执照》载明事项的，公司登记机关应当换发营业执照。"},{"i":40,"n":"第四十条","txt":"公司依照《公司法》第二十二条规定向公司登记机关申请撤销变更登记的，应当提交下列文件："},{"i":41,"n":"第四十一条","txt":"公司解散，依法应当清算的，清算组应当自成立之日起10日内将清算组成员、清算组负责人名单向公司登记机关备案。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，公司清算组应当自公司清算结束之日起30日内向原公司登记机关申请注销登记："},{"i":43,"n":"第四十三条","txt":"公司申请注销登记，应当提交下列文件："},{"i":44,"n":"第四十四条","txt":"经公司登记机关注销登记，公司终止。"},{"i":45,"n":"第四十五条","txt":"分公司是指公司在其住所以外设立的从事经营活动的机构。分公司不具有企业法人资格。"},{"i":46,"n":"第四十六条","txt":"分公司的登记事项包括：名称、营业场所、负责人、经营范围。"},{"i":47,"n":"第四十七条","txt":"公司设立分公司的，应当自决定作出之日起30日内向分公司所在地的公司登记机关申请登记；法律、行政法规或者国务院决定规定必须报经有关部门批准的，应当自批准之日起30日内向公司登记机关申请登记。"},{"i":48,"n":"第四十八条","txt":"分公司变更登记事项的，应当向公司登记机关申请变更登记。"},{"i":49,"n":"第四十九条","txt":"分公司被公司撤销、依法责令关闭、吊销营业执照的，公司应当自决定作出之日起30日内向该分公司的公司登记机关申请注销登记。申请注销登记应当提交公司法定代表人签署的注销登记申请书和分公司的《营业执照》。公司登记机关准予注销登记后，应当收缴分公司的《营业执照》。"},{"i":50,"n":"第五十条","txt":"申请公司、分公司登记，申请人可以到公司登记机关提交申请，也可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式提出申请。"},{"i":51,"n":"第五十一条","txt":"公司登记机关应当根据下列情况分别作出是否受理的决定："},{"i":52,"n":"第五十二条","txt":"除依照本条例第五十三条第一款第（一）项作出准予登记决定的外，公司登记机关决定予以受理的，应当出具《受理通知书》；决定不予受理的，应当出具《不予受理通知书》，说明不予受理的理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":53,"n":"第五十三条","txt":"公司登记机关对决定予以受理的登记申请，应当分别情况在规定的期限内作出是否准予登记的决定："},{"i":54,"n":"第五十四条","txt":"公司登记机关作出准予公司名称预先核准决定的，应当出具《企业名称预先核准通知书》；作出准予公司设立登记决定的，应当出具《准予设立登记通知书》，告知申请人自决定之日起10日内，领取营业执照；作出准予公司变更登记决定的，应当出具《准予变更登记通知书》，告知申请人自决定之日起10日内，换发营业执照；作出准予公司注销登记决定的，应当出具《准予注销登记通知书》，收缴营业执照。"},{"i":55,"n":"第五十五条","txt":"公司登记机关应当将公司登记、备案信息通过企业信用信息公示系统向社会公示。"},{"i":56,"n":"第五十六条","txt":"吊销《企业法人营业执照》和《营业执照》的公告由公司登记机关发布。"},{"i":57,"n":"第五十七条","txt":"公司应当于每年1月1日至6月30日，通过企业信用信息公示系统向公司登记机关报送上一年度年度报告，并向社会公示。"},{"i":58,"n":"第五十八条","txt":"《企业法人营业执照》、《营业执照》分为正本和副本，正本和副本具有同等法律效力。"},{"i":59,"n":"第五十九条","txt":"任何单位和个人不得伪造、涂改、出租、出借、转让营业执照。"},{"i":60,"n":"第六十条","txt":"公司登记机关对需要认定的营业执照，可以临时扣留，扣留期限不得超过10天。"},{"i":61,"n":"第六十一条","txt":"借阅、抄录、携带、复制公司登记档案资料的，应当按照规定的权限和程序办理。"},{"i":62,"n":"第六十二条","txt":"营业执照正本、副本样式，电子营业执照标准以及公司登记的有关重要文书格式或者表式，由国家工商行政管理总局统一制定。"},{"i":63,"n":"第六十三条","txt":"虚报注册资本，取得公司登记的，由公司登记机关责令改正，处以虚报注册资本金额5%以上15%以下的罚款；情节严重的，撤销公司登记或者吊销营业执照。"},{"i":64,"n":"第六十四条","txt":"提交虚假材料或者采取其他欺诈手段隐瞒重要事实，取得公司登记的，由公司登记机关责令改正，处以5万元以上50万元以下的罚款；情节严重的，撤销公司登记或者吊销营业执照。"},{"i":65,"n":"第六十五条","txt":"公司的发起人、股东虚假出资，未交付或者未按期交付作为出资的货币或者非货币财产的，由公司登记机关责令改正，处以虚假出资金额5%以上15%以下的罚款。"},{"i":66,"n":"第六十六条","txt":"公司的发起人、股东在公司成立后，抽逃出资的，由公司登记机关责令改正，处以所抽逃出资金额5%以上15%以下的罚款。"},{"i":67,"n":"第六十七条","txt":"公司成立后无正当理由超过6个月未开业的，或者开业后自行停业连续6个月以上的，可以由公司登记机关吊销营业执照。"},{"i":68,"n":"第六十八条","txt":"公司登记事项发生变更时，未依照本条例规定办理有关变更登记的，由公司登记机关责令限期登记；逾期不登记的，处以1万元以上10万元以下的罚款。其中，变更经营范围涉及法律、行政法规或者国务院决定规定须经批准的项目而未取得批准，擅自从事相关经营活动，情节严重的，吊销营业执照。"},{"i":69,"n":"第六十九条","txt":"公司在合并、分立、减少注册资本或者进行清算时，不按照规定通知或者公告债权人的，由公司登记机关责令改正，处以1万元以上10万元以下的罚款。"},{"i":70,"n":"第七十条","txt":"清算组不按照规定向公司登记机关报送清算报告，或者报送清算报告隐瞒重要事实或者有重大遗漏的，由公司登记机关责令改正。"},{"i":71,"n":"第七十一条","txt":"伪造、涂改、出租、出借、转让营业执照的，由公司登记机关处以1万元以上10万元以下的罚款；情节严重的，吊销营业执照。"},{"i":72,"n":"第七十二条","txt":"未将营业执照置于住所或者营业场所醒目位置的，由公司登记机关责令改正；拒不改正的，处以1000元以上5000元以下的罚款。"},{"i":73,"n":"第七十三条","txt":"承担资产评估、验资或者验证的机构提供虚假材料的，由公司登记机关没收违法所得，处以违法所得1倍以上5倍以下的罚款，并可以由有关主管部门依法责令该机构停业、吊销直接责任人员的资格证书，吊销营业执照。"},{"i":74,"n":"第七十四条","txt":"未依法登记为有限责任公司或者股份有限公司，而冒用有限责任公司或者股份有限公司名义的，或者未依法登记为有限责任公司或者股份有限公司的分公司，而冒用有限责任公司或者股份有限公司的分公司名义的，由公司登记机关责令改正或者予以取缔，可以并处10万元以下的罚款。"},{"i":75,"n":"第七十五条","txt":"公司登记机关对不符合规定条件的公司登记申请予以登记，或者对符合规定条件的登记申请不予登记的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":76,"n":"第七十六条","txt":"公司登记机关的上级部门强令公司登记机关对不符合规定条件的登记申请予以登记，或者对符合规定条件的登记申请不予登记的，或者对违法登记进行包庇的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":77,"n":"第七十七条","txt":"外国公司违反《公司法》规定，擅自在中国境内设立分支机构的，由公司登记机关责令改正或者关闭，可以并处5万元以上20万元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"利用公司名义从事危害国家安全、社会公共利益的严重违法行为的，吊销营业执照。"},{"i":79,"n":"第七十九条","txt":"分公司有本章规定的违法行为的，适用本章规定。"},{"i":80,"n":"第八十条","txt":"违反本条例规定，构成犯罪的，依法追究刑事责任。"},{"i":81,"n":"第八十一条","txt":"外商投资的公司的登记适用本条例。有关外商投资企业的法律对其登记另有规定的，适用其规定。"},{"i":82,"n":"第八十二条","txt":"法律、行政法规或者国务院决定规定设立公司必须报经批准，或者公司经营范围中属于法律、行政法规或者国务院决定规定在登记前须经批准的项目的，由国家工商行政管理总局依照法律、行政法规或者国务院决定规定编制企业登记前置行政许可目录并公布。"},{"i":83,"n":"第八十三条","txt":"本条例自1994年7月1日起施行。"}],"gongyechanpinzhiliangzerentiaoli":[{"i":1,"n":"第一条","txt":"为了明确工业产品（以下简称产品）质量责任，维护用户和消费者（以下简称用户）的合法权益，保证有计划的商品经济健康发展，促进社会主义现代化建设，特制定本条例。"},{"i":2,"n":"第二条","txt":"产品质量是指国家的有关法规、质量标准以及合同规定的对产品适用、安全和其它特性的要求。"},{"i":3,"n":"第三条","txt":"国家标准化部门负责制定全国统一的国家标准。国家标准应不低于国际标准水平。国家标准可以分级分等。企业主管部门要规定生产企业达到国家标准最高等级的期限。国家物价部门按标准等级，实行按质论价。"},{"i":4,"n":"第四条","txt":"产品的生产、储运、经销企业必须按照本条例的规定，承担产品质量责任。"},{"i":5,"n":"第五条","txt":"质量监督机构、工商行政管理机关必须对产品质量进行监督，维护用户的利益。"},{"i":6,"n":"第六条","txt":"产品的合格证、说明书、优质标志、认证标志等都必须与产品的实际质量水平相一致。"},{"i":7,"n":"第七条","txt":"所有生产、经销企业必须严格执行下列规定："},{"i":8,"n":"第八条","txt":"产品的生产企业必须保证产品质量符合国家的有关法规、质量标准以及合同规定的要求。"},{"i":9,"n":"第九条","txt":"产品出厂，必须符合下列要求："},{"i":10,"n":"第十条","txt":"达不到国家的有关标准规定等级、仍有使用价值的“处理品”，经企业主管机关批准后，方可降价销售，在产品和包装上必须标出显著的“处理品”字样。"},{"i":11,"n":"第十一条","txt":"在产品保证期限内发现质量不符合第二条要求时，根据不同情况，由产品生产企业对用户和经销企业承担质量责任："},{"i":12,"n":"第十二条","txt":"承储、承运、装卸企业必须根据国家有关规定和产品包装上标明的储运要求进行储存、运输和装卸。"},{"i":13,"n":"第十三条","txt":"承储、承运企业在产品入库储存或出库、产品承运或交货时，应按照国家有关规定，严格执行交接验收制度，明确质量责任。确属储存、运输、装卸原因造成产品损伤，承储、承运、装卸企业应分别承担责任，按国家有关规定，赔偿经济损失。"},{"i":14,"n":"第十四条","txt":"经销企业在进货时，应对产品进行验收，明确产品的质量责任。经销企业出售的产品，必须符合本条例第七条、第九条的规定。"},{"i":15,"n":"第十五条","txt":"经销企业售出的产品在保证期限内发现质量不符合第二条的要求时，应由经销企业负责对用户实行包修、包换、包退、承担赔偿实际经济损失的责任。"},{"i":16,"n":"第十六条","txt":"各质量监督机构，按照国家有关规定，单独组织或者会同工商行政管理部门、各行业主管部门、企业主管部门，对产品的生产、储运和经销等各个环节实行经常性的监督抽查，并定期公布抽查产品的质量状况。企业必须如实提供抽查样品，并在检测手段和工作条件方面提供方便。"},{"i":17,"n":"第十七条","txt":"各级行业主管部门和企业主管部门负责本行业产品质量的管理工作，其职责是：在授权范围内，制定或参与制定有关产品质量标准以及有关规章制度，负责产品质量的监督管理，督促企业保证产品质量，完善质量保证系统；组织发放生产许可证。"},{"i":18,"n":"第十八条","txt":"对产品质量实行社会性监督。用户可以向产品生产、储运、经销企业提出质量查询；社团组织可以协助用户参与质量争议的调解、仲裁，支持用户向人民法院起诉。"},{"i":19,"n":"第十九条","txt":"用户按双方协议可以派出代表到生产企业对产品生产过程和产品质量进行现场监督。"},{"i":20,"n":"第二十条","txt":"因产品质量问题发生争议时，有经济合同的，按《经济合同法》的有关规定执行；没有合同的，争议的任何一方都可提请有关的质量监督机构调解处理，也可向人民法院起诉。"},{"i":21,"n":"第二十一条","txt":"对产品质量的技术检验数据有争议时，当事人或调解、仲裁机构可委托法定的质量检验单位进行仲裁检验，质量检验单位应对提供的仲裁检验数据负责。"},{"i":22,"n":"第二十二条","txt":"除国家另有规定外，质量责任的仲裁请求和起诉，应从当事人知悉或应当知悉权益受损害之日起一年内提出。产品质量责任方愿意承担责任时，不受时效限制。"},{"i":23,"n":"第二十三条","txt":"企业产品质量达不到国家规定的标准，企业主管机关应令其限期整顿。经整顿仍无效者，企业主管机关应令其停产或转产，直至建议有关主管机关撤销生产许可证，吊销营业执照。在整顿期间，企业主管机关视不同情况，可扣发企业负责人和职工的奖金、工资。"},{"i":24,"n":"第二十四条","txt":"生产、经销企业违反本条例规定，有下列行为之一者，由企业主管机关对企业负责人和直接责任者给以行政处分，由工商行政管理机关没收其全部非法收入，并视其情节轻重，处以相当于非法收入的15%至20%的罚款，直至由司法机关追究法律责任。"},{"i":25,"n":"第二十五条","txt":"有质量监督抽查中发现生产和经销企业有第二十四条中列举的行为时，由质量监督机构按第二十四条规定处理。对于不符合本条例第九条第七项规定的，由质量监督机构监督就地销毁或作必要的技术处理，并令生产、经销企业在限期内追回已售出的不合格产品。"},{"i":26,"n":"第二十六条","txt":"由于产品的质量责任，造成用户人身伤亡，财产损失，触犯刑律的，由司法机关依法追究当事人的刑事责任。"},{"i":27,"n":"第二十七条","txt":"上述处罚，不免除产品质量责任方对用户承担的产品包修、包换、包退、赔偿实际经济损失的责任。"},{"i":28,"n":"第二十八条","txt":"有关主管部门可根据本条例的规定，制定实施细则；进出口商品、军用产品及有特殊要求的产品的质量责任可由有关主管部门参照本条例的原则，另行规定。"},{"i":29,"n":"第二十九条","txt":"本条例适用于所有全民、集体所有制企业，个体工商业经营者以及在中国境内的中外合资、合作、外资企业。"},{"i":30,"n":"第三十条","txt":"本条例授权国家经济委员会负责解释。"},{"i":31,"n":"第三十一条","txt":"本条例自一九八六年七月一日起施行。"}],"guanyuaiguoweishengyundongweiyuanhuijiqibanshijigo80f73a":[],"guanyuguowuyuanguanliganbudegongsilingdaozhishuden790590":[],"guanyushixingjishipinrenzhidezanxingguiding":[{"i":1,"n":"第一条","txt":"为鼓励工人钻研业务，不断提高技术素质，稳定工人队伍，发挥高级技术工人的作用，以适应经济建设的需要，制定本规定。"},{"i":2,"n":"第二条","txt":"技师是在高级技术工人中设置的技术职务。技师的职务名称由国务院有关部门根据行业特点和历史形成的习惯确定。"},{"i":3,"n":"第三条","txt":"技师任职条件："},{"i":4,"n":"第四条","txt":"实行技师聘任制的工种范围、以技术工人为基数聘任技师的比例限额及技师的技术（业务）考核标准，由国务院有关行业归口部门提出，报劳动人事部核定。"},{"i":5,"n":"第五条","txt":"技师必须经过考核、评审。技师的考核、评审工作，县级以上（不含县级）的行业归口部门已成立工人技术考核委员会的，由该委员会负责；未成立工人技术考核委员会的，可成立技师考评组织，负责技师的考核、评审工作。"},{"i":6,"n":"第六条","txt":"申请技师由本人提出，经所在单位同意后，由工人技术考核委员会或者技师考评组织考核、评审。考核、评审合格的，发给技师考核合格证书。"},{"i":7,"n":"第七条","txt":"技师所在单位应当同被聘任的技师签订聘约，规定聘任期限、双方的权利和义务及辞聘、解聘、违约责任等事宜。"},{"i":8,"n":"第八条","txt":"技师应当在本工种的工作中发挥技术特长，并根据所在单位的需要担任传授技艺或培训技术工人的工作。"},{"i":9,"n":"第九条","txt":"技师聘任期限为三年至五年，根据工作需要可连续聘任。"},{"i":10,"n":"第十条","txt":"被聘任的技师，实行职务津贴。职务津贴一般为每月十五元至二十五元，具体标准以及其他福利待遇，由国务院有关行业归口部门提出，报劳动人事部核定。"},{"i":11,"n":"第十一条","txt":"技师离开本工种工作岗位从事其他工作后，不再享受技师津贴和其他有关福利待遇。"},{"i":12,"n":"第十二条","txt":"本规定适用于全民所有制企业、事业单位以及机关和社会团体。集体所有制企业、事业单位可参照执行。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyugufenyouxiangongsijingwaimujigufenj3d310e":[{"i":1,"n":"第一条","txt":"为适应股份有限公司境外募集股份及境外上市的需要，根据《中华人民共和国公司法》第八十五条、第一百五十五条，制定本规定。"},{"i":2,"n":"第二条","txt":"股份有限公司经国务院证券委员会批准，可以向境外特定的、非特定的投资人募集股份，其股票可以在境外上市。"},{"i":3,"n":"第三条","txt":"股份有限公司向境外投资人募集并在境外上市的股份（以下简称境外上市外资股），采取记名股票形式，以人民币标明面值，以外币认购。"},{"i":4,"n":"第四条","txt":"国务院证券委员会或者其监督管理执行机构中国证券监督管理委员会，可以与境外证券监督管理机构达成谅解、协议，对股份有限公司向境外投资人募集股份并在境外上市及相关活动进行合作监督管理。"},{"i":5,"n":"第五条","txt":"股份有限公司向境外投资人募集股份并在境外上市，应当按照国务院证券委员会的要求提出书面申请并附有关材料，报经国务院证券委员会批准。"},{"i":6,"n":"第六条","txt":"国有企业或者国有资产占主导地位的企业按照国家有关规定改建为向境外投资人募集股份并在境外上市的股份有限公司，以发起方式设立的，发起人可以少于5人；该股份有限公司一经成立，即可以发行新股。"},{"i":7,"n":"第七条","txt":"向境外投资人募集股份并在境外上市的股份有限公司（以下简称公司）向境内投资人发行的股份（以下简称内资股），采取记名股票形式。"},{"i":8,"n":"第八条","txt":"经国务院证券委员会批准的公司发行境外上市外资股和内资股的计划，公司董事会可以作出分别发行的实施安排。"},{"i":9,"n":"第九条","txt":"公司在发行计划确定的股份总数内，分别发行境外上市外资股和内资股的，应当分别一次募足；有特殊情况不能一次募足的，经国务院证券委员会批准，也可以分次发行。"},{"i":10,"n":"第十条","txt":"公司发行计划确定的股份未募足的，不得在该发行计划外发行新股。公司需要调整发行计划的，由股东大会作出决议，经国务院授权的公司审批部门核准后，报国务院证券委员会审批。"},{"i":11,"n":"第十一条","txt":"公司在发行计划确定的股份总数内发行境外上市外资股，经国务院证券委员会批准，可以与包销商在包销协议中约定，在包销数额之外预留不超过该次拟募集境外上市外资股数额15%的股份。预留股份的发行，视为该次发行的一部分。"},{"i":12,"n":"第十二条","txt":"公司分别发行境外上市外资股和内资股的计划，应当在公司各次募集股份的招股说明材料中全面、详尽披露。对已经批准并披露的发行计划进行调整的，必须重新披露。"},{"i":13,"n":"第十三条","txt":"国务院证券委员会会同国务院授权的公司审批部门，可以对公司章程必备条款作出规定。"},{"i":14,"n":"第十四条","txt":"公司应当在公司章程中载明公司的营业期限。公司的营业期限，可以为永久存续。"},{"i":15,"n":"第十五条","txt":"公司章程对公司及其股东、董事、监事、经理和其他高级管理人员具有约束力。"},{"i":16,"n":"第十六条","txt":"依法持有境外上市外资股、其姓名或者名称登记在公司的股东名册上的境外投资人，为公司的境外上市外资股股东。"},{"i":17,"n":"第十七条","txt":"依据本规定第四条所指的谅解、协议，公司可以将境外上市外资股股东名册正本存放在境外，委托境外代理机构管理；公司应当将境外代理机构制作的境外上市外资股股东名册的副本备置于公司的住所。受委托的境外代理机构应当随时保证境外上市外资股股东名册正本、副本的一致性。"},{"i":18,"n":"第十八条","txt":"境外上市外资股股东名册正本的更正需要依据司法裁定作出的，可以由名册正本存放地有管辖权的法院裁定。"},{"i":19,"n":"第十九条","txt":"境外上市外资股股东遗失股票，申请补发的，可以依照境外上市外资股股东名册正本存放地的法律、证券交易场所规则或者其他有关规定处理。"},{"i":20,"n":"第二十条","txt":"公司召开股东大会，应当于会议召开45日前发出书面通知，将会议拟审议的事项以及会议日期和地点告知所有在册股东。"},{"i":21,"n":"第二十一条","txt":"公司召开股东大会年会，持有公司有表决权的股份5%以上的股东有权以书面形式向公司提出新的提案，公司应当将提案中属于股东大会职责范围内的事项，列入该次会议的议程。"},{"i":22,"n":"第二十二条","txt":"公司根据股东大会召开前20日时收到的书面回复，计算拟出席会议的股东所代表的有表决权的股份数。拟出席会议的股东所代表的有表决权的股份数达到公司有表决权的股份总数二分之一的，公司可以召开股东大会；达不到的，公司应当于5日内将会议拟审议的事项、会议日期和地点以公告形式再次通知股东，经公告通知，公司可以召开股东大会。"},{"i":23,"n":"第二十三条","txt":"公司的董事、监事、经理和其他高级管理人员对公司负有诚信和勤勉的义务。"},{"i":24,"n":"第二十四条","txt":"公司应当聘用符合国家有关规定的、独立的会计师事务所，审计公司的年度报告，并复核公司的其他财务报告。"},{"i":25,"n":"第二十五条","txt":"公司解聘或者不再续聘会计师事务所，应当事先通知会计师事务所，会计师事务所有权向股东大会陈述意见。"},{"i":26,"n":"第二十六条","txt":"公司聘用、解聘或者不再续聘会计师事务所由股东大会作出决定，并报中国证券监督管理委员会备案。"},{"i":27,"n":"第二十七条","txt":"公司向境外上市外资股股东支付股利以及其他款项，以人民币计价和宣布，以外币支付。公司所筹集的外币资本金的结汇和公司向股东支付股利以及其他款项所需的外币，按照国家有关外汇管理的规定办理。"},{"i":28,"n":"第二十八条","txt":"公司所编制的向境内和境外公布的信息披露文件，内容不得相互矛盾。"},{"i":29,"n":"第二十九条","txt":"境外上市外资股股东与公司之间，境外上市外资股股东与公司董事、监事和经理之间，境外上市外资股股东与内资股股东之间发生的与公司章程规定的内容以及公司其他事务有关的争议，依照公司章程规定的解决方式处理。"},{"i":30,"n":"第三十条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyutongyonghangkongguanlidezanxingguida10492":[{"i":1,"n":"第一条","txt":"为了促进通用航空事业的健康发展，维护公共利益，保障飞行安全，以适应社会主义现代化建设的需要，特制定本规定。"},{"i":2,"n":"第二条","txt":"凡使用民用航空器从事为工业、农业、林业、牧业、渔业生产和国家建设服务的作业飞行，以及从事医疗卫生、抢险救灾、海洋及环境监测、科学实验、教育训练、文化体育及游览等项飞行活动（以下统称通用航空），都应当遵守本规定。"},{"i":3,"n":"第三条","txt":"通用航空由中国民用航空局（以下简称民航局）归口管理。"},{"i":4,"n":"第四条","txt":"从事通用航空飞行的单位或个人，经营通用航空业务的企业，都应当按照下列规定，履行申请审批手续："},{"i":5,"n":"第五条","txt":"申请通用航空许可证，应当具备与通用航空要求相适应的下列条件："},{"i":6,"n":"第六条","txt":"经营通用航空业务的企业，应当持通用航空许可证，按照《工商企业登记管理条例》的规定，办理登记手续，领取营业执照，方可经营业务。"},{"i":7,"n":"第七条","txt":"从事通用航空飞行的单位或个人，经营通用航空业务的企业，都应当向中国人民保险公司投保机身险和第三者责任险。"},{"i":8,"n":"第八条","txt":"经营通用航空业务的企业，可以承担中国境外通用航空业务，但是应当按照国家有关规定办理相关手续。"},{"i":9,"n":"第九条","txt":"企业、单位或个人实施通用航空作业飞行时，应当采取有效措施保护环境；噪声或排放有害物质，都必须符合国家规定的标准。"},{"i":10,"n":"第十条","txt":"从事或经营通用航空飞行或业务的单位、个人、企业，都应当遵守国家法律、行政法规的规定，接受有关部门的监督检查。"},{"i":11,"n":"第十一条","txt":"从事或经营通用航空飞行或业务的单位、个人、企业，都应当遵守有关民用航空的规章、条令，接受民航局对飞行事故的调查处理。"},{"i":12,"n":"第十二条","txt":"从事或经营通用航空飞行或业务的单位、个人、企业，都应当按照民航局的规定，定期报送通用航空统计资料和其他材料。"},{"i":13,"n":"第十三条","txt":"从事民用航空教育、训练的学校或机构，应当接受民航局的监督检查。"},{"i":14,"n":"第十四条","txt":"航空体育主管部门应当根据本规定制定航空体育管理办法，并报民航局备案。"},{"i":15,"n":"第十五条","txt":"从事或经营通用航空飞行或业务的单位、个人、企业违法、违章，民航局或地区民用航空管理机构可以分别给予警告、罚款、暂停业务、吊销通用航空许可证等处分。"},{"i":16,"n":"第十六条","txt":"本规定由民航局负责解释。"},{"i":17,"n":"第十七条","txt":"本规定自发布之日起施行。在本规定发布前已经从事或经营通用航空飞行或业务的单位、个人、企业，应当在3个月内按照本规定补办申请、批准手续；逾期不办的，不得从事或经营通用航空飞行或业务。"}],"guowuyuanguanyuyufangmeikuangshengchananquanshigudf2d48b":[{"i":1,"n":"第一条","txt":"为了及时发现并排除煤矿安全生产隐患，落实煤矿安全生产责任，预防煤矿生产安全事故发生，保障职工的生命安全和煤矿安全生产，制定本规定。"},{"i":2,"n":"第二条","txt":"煤矿企业是预防煤矿生产安全事故的责任主体。煤矿企业负责人（包括一些煤矿企业的实际控制人，下同）对预防煤矿生产安全事故负主要责任。"},{"i":3,"n":"第三条","txt":"国务院有关部门和地方各级人民政府应当建立并落实预防煤矿生产安全事故的责任制，监督检查煤矿企业预防煤矿生产安全事故的情况，及时解决煤矿生产安全事故预防工作中的重大问题。"},{"i":4,"n":"第四条","txt":"县级以上地方人民政府负责煤矿安全生产监督管理的部门、国家煤矿安全监察机构设在省、自治区、直辖市的煤矿安全监察机构（以下简称煤矿安全监察机构），对所辖区域的煤矿重大安全生产隐患和违法行为负有检查和依法查处的职责。"},{"i":5,"n":"第五条","txt":"煤矿未依法取得采矿许可证、安全生产许可证、营业执照和矿长未依法取得矿长资格证、矿长安全资格证的，煤矿不得从事生产。擅自从事生产的，属非法煤矿。"},{"i":6,"n":"第六条","txt":"负责颁发采矿许可证、安全生产许可证、营业执照和矿长资格证、矿长安全资格证的部门，向不符合法定条件的煤矿或者矿长颁发有关证照的，对直接责任人，根据情节轻重，给予降级、撤职或者开除的行政处分；对主要负责人，根据情节轻重，给予记大过、降级、撤职或者开除的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":7,"n":"第七条","txt":"在乡、镇人民政府所辖区域内发现有非法煤矿并且没有采取有效制止措施的，对乡、镇人民政府的主要负责人以及负有责任的相关负责人，根据情节轻重，给予降级、撤职或者开除的行政处分；在县级人民政府所辖区域内1个月内发现有2处或者2处以上非法煤矿并且没有采取有效制止措施的，对县级人民政府的主要负责人以及负有责任的相关负责人，根据情节轻重，给予降级、撤职或者开除的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":8,"n":"第八条","txt":"煤矿的通风、防瓦斯、防水、防火、防煤尘、防冒顶等安全设备、设施和条件应当符合国家标准、行业标准，并有防范生产安全事故发生的措施和完善的应急处理预案。"},{"i":9,"n":"第九条","txt":"煤矿企业应当建立健全安全生产隐患排查、治理和报告制度。煤矿企业应当对本规定第八条第二款所列情形定期组织排查，并将排查情况每季度向县级以上地方人民政府负责煤矿安全生产监督管理的部门、煤矿安全监察机构写出书面报告。报告应当经煤矿企业负责人签字。"},{"i":10,"n":"第十条","txt":"煤矿有本规定第八条第二款所列情形之一，仍然进行生产的，由县级以上地方人民政府负责煤矿安全生产监督管理的部门或者煤矿安全监察机构责令停产整顿，提出整顿的内容、时间等具体要求，处50万元以上200万元以下的罚款；对煤矿企业负责人处3万元以上15万元以下的罚款。"},{"i":11,"n":"第十一条","txt":"对被责令停产整顿的煤矿，颁发证照的部门应当暂扣采矿许可证、安全生产许可证、营业执照和矿长资格证、矿长安全资格证。"},{"i":12,"n":"第十二条","txt":"对被责令停产整顿的煤矿，在停产整顿期间，由有关地方人民政府采取有效措施进行监督检查。因监督检查不力，煤矿在停产整顿期间继续生产的，对直接责任人，根据情节轻重，给予降级、撤职或者开除的行政处分；对有关负责人，根据情节轻重，给予记大过、降级、撤职或者开除的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"对提请关闭的煤矿，县级以上地方人民政府负责煤矿安全生产监督管理的部门或者煤矿安全监察机构应当责令立即停止生产；有关地方人民政府应当在7日内作出关闭或者不予关闭的决定，并由其主要负责人签字存档。对决定关闭的，有关地方人民政府应当立即组织实施。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府负责煤矿安全生产监督管理的部门或者煤矿安全监察机构，发现煤矿有本规定第八条第二款所列情形之一的，应当将情况报送有关地方人民政府。"},{"i":15,"n":"第十五条","txt":"煤矿存在瓦斯突出、自然发火、冲击地压、水害威胁等重大安全生产隐患，该煤矿在现有技术条件下难以有效防治的，县级以上地方人民政府负责煤矿安全生产监督管理的部门、煤矿安全监察机构应当责令其立即停止生产，并提请有关地方人民政府组织专家进行论证。专家论证应当客观、公正、科学。有关地方人民政府应当根据论证结论，作出是否关闭煤矿的决定，并组织实施。"},{"i":16,"n":"第十六条","txt":"煤矿企业应当依照国家有关规定对井下作业人员进行安全生产教育和培训，保证井下作业人员具有必要的安全生产知识，熟悉有关安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能，并建立培训档案。未进行安全生产教育和培训或者经教育和培训不合格的人员不得下井作业。"},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府负责煤矿安全生产监督管理的部门、煤矿安全监察机构在监督检查中，1个月内3次或者3次以上发现煤矿企业未依照国家有关规定对井下作业人员进行安全生产教育和培训或者特种作业人员无证上岗的，应当提请有关地方人民政府对该煤矿予以关闭。"},{"i":18,"n":"第十八条","txt":"煤矿拒不执行县级以上地方人民政府负责煤矿安全生产监督管理的部门或者煤矿安全监察机构依法下达的执法指令的，由颁发证照的部门吊销矿长资格证和矿长安全资格证；构成违反治安管理行为的，由公安机关依照治安管理的法律、行政法规的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府负责煤矿安全生产监督管理的部门、煤矿安全监察机构对被责令停产整顿或者关闭的煤矿，应当自煤矿被责令停产整顿或者关闭之日起3日内在当地主要媒体公告。"},{"i":20,"n":"第二十条","txt":"国家机关工作人员和国有企业负责人不得违反国家规定投资入股煤矿（依法取得上市公司股票的除外），不得对煤矿的违法行为予以纵容、包庇。"},{"i":21,"n":"第二十一条","txt":"煤矿企业负责人和生产经营管理人员应当按照国家规定轮流带班下井，并建立下井登记档案。"},{"i":22,"n":"第二十二条","txt":"煤矿企业应当免费为每位职工发放煤矿职工安全手册。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人发现煤矿有本规定第五条第一款和第八条第二款所列情形之一的，都有权向县级以上地方人民政府负责煤矿安全生产监督管理的部门或者煤矿安全监察机构举报。"},{"i":24,"n":"第二十四条","txt":"煤矿有违反本规定的违法行为，法律规定由有关部门查处的，有关部门应当依法进行查处。但是，对同一违法行为不得给予两次以上罚款的行政处罚。"},{"i":25,"n":"第二十五条","txt":"国家行政机关工作人员、国有企业负责人有违反本规定的行为，依照本规定应当给予处分的，由监察机关或者任免机关依法作出处分决定。"},{"i":26,"n":"第二十六条","txt":"当事人对行政处罚决定不服的，可以依法申请行政复议，或者依法直接向人民法院提起行政诉讼。"},{"i":27,"n":"第二十七条","txt":"省、自治区、直辖市人民政府可以依据本规定制定具体实施办法。"},{"i":28,"n":"第二十八条","txt":"本规定自公布之日起施行。"}],"guoyouqiyejianshihuizanxingtiaoli":[{"i":1,"n":"第一条","txt":"为了健全国有企业监督机制，加强对国有企业的监督，制定本条例。"},{"i":2,"n":"第二条","txt":"国有重点大型企业监事会（以下简称监事会）由国务院派出，对国务院负责，代表国家对国有重点大型企业（以下简称企业）的国有资产保值增值状况实施监督。"},{"i":3,"n":"第三条","txt":"监事会以财务监督为核心，根据有关法律、行政法规和财政部的有关规定，对企业的财务活动及企业负责人的经营管理行为进行监督，确保国有资产及其权益不受侵犯。"},{"i":4,"n":"第四条","txt":"监事会管理机构负责监事会的日常管理工作，协调监事会与国务院有关部门和有关地方的联系，承办国务院交办的事项。"},{"i":5,"n":"第五条","txt":"监事会履行下列职责："},{"i":6,"n":"第六条","txt":"监事会一般每年对企业定期检查1至2次，并可以根据实际需要不定期地对企业进行专项检查。"},{"i":7,"n":"第七条","txt":"监事会开展监督检查，可以采取下列方式："},{"i":8,"n":"第八条","txt":"国务院有关部门和地方人民政府有关部门应当支持、配合监事会的工作，向监事会提供有关情况和资料。"},{"i":9,"n":"第九条","txt":"监事会每次对企业进行检查结束后，应当及时作出检查报告。"},{"i":10,"n":"第十条","txt":"检查报告经监事会成员讨论，由监事会主席签署，经监事会管理机构报国务院；检查报告经国务院批复后，抄送国家经济贸易委员会、财政部等有关部门。"},{"i":11,"n":"第十一条","txt":"监事会在监督检查中发现企业经营行为有可能危及国有资产安全、造成国有资产流失或者侵害国有资产所有者权益以及监事会认为应当立即报告的其他紧急情况，应当及时向监事会管理机构提出专项报告，也可以直接向国务院报告。"},{"i":12,"n":"第十二条","txt":"企业应当定期、如实向监事会报送财务会计报告，并及时报告重大经营管理活动情况，不得拒绝、隐匿、伪报。"},{"i":13,"n":"第十三条","txt":"监事会根据对企业实施监督检查的需要，必要时，经监事会管理机构同意，可以聘请注册会计师事务所对企业进行审计。"},{"i":14,"n":"第十四条","txt":"监事会由主席1人、监事若干人组成。监事会成员不少于3人。"},{"i":15,"n":"第十五条","txt":"监事会主席人选按照规定程序确定，由国务院任命。监事会主席由副部级国家工作人员担任，为专职，年龄一般在60周岁以下。"},{"i":16,"n":"第十六条","txt":"监事会成员每届任期3年，其中监事会主席和专职监事、派出监事不得在同一企业连任。"},{"i":17,"n":"第十七条","txt":"监事会主席应当具有较高的政策水平，坚持原则，廉洁自持，熟悉经济工作。"},{"i":18,"n":"第十八条","txt":"监事应当具备下列条件："},{"i":19,"n":"第十九条","txt":"监事会主席和专职监事、派出监事实行回避原则，不得在其曾经管辖的行业、曾经工作过的企业或者其近亲属担任高级管理职务的企业的监事会中任职。"},{"i":20,"n":"第二十条","txt":"监事会开展监督检查工作所需费用由国家财政拨付，由监事会管理机构统一列支。"},{"i":21,"n":"第二十一条","txt":"监事会成员不得接受企业的任何馈赠，不得参加由企业安排、组织或者支付费用的宴请、娱乐、旅游、出访等活动，不得在企业中为自己、亲友或者其他人谋取私利。"},{"i":22,"n":"第二十二条","txt":"监事会成员必须对检查报告内容保密，并不得泄露企业的商业秘密。"},{"i":23,"n":"第二十三条","txt":"监事会成员在监督检查中成绩突出，为维护国家利益做出重要贡献的，给予奖励。"},{"i":24,"n":"第二十四条","txt":"监事会成员有下列行为之一的，依法给予行政处分或者纪律处分，直至撤销监事职务；构成犯罪的，依法追究刑事责任："},{"i":25,"n":"第二十五条","txt":"企业有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予纪律处分，直至撤销职务；构成犯罪的，依法追究刑事责任："},{"i":26,"n":"第二十六条","txt":"企业发现监事会成员有违反本条例第二十一条、第二十二条所列行为时，有权向监事会管理机构报告，也可以直接向国务院报告。"},{"i":27,"n":"第二十七条","txt":"对国务院不派出监事会的国有企业，由省、自治区、直辖市人民政府参照本条例的规定，决定派出监事会。"},{"i":28,"n":"第二十八条","txt":"国务院向国有重点金融机构派出的监事会，依照《国有重点金融机构监事会暂行条例》执行。"},{"i":29,"n":"第二十九条","txt":"本条例自发布之日起施行。1994年7月24日国务院发布的《国有企业财产监督管理条例》同时废止。"}],"hehuoqiyedengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了确认合伙企业的经营资格，规范合伙企业登记行为，依据《中华人民共和国合伙企业法》（以下简称合伙企业法），制定本办法。"},{"i":2,"n":"第二条","txt":"合伙企业的设立、变更、注销，应当依照合伙企业法和本办法的规定办理企业登记。"},{"i":3,"n":"第三条","txt":"合伙企业经依法登记，领取合伙企业营业执照后，方可从事经营活动。"},{"i":4,"n":"第四条","txt":"工商行政管理部门是合伙企业登记机关（以下简称企业登记机关）。"},{"i":5,"n":"第五条","txt":"设立合伙企业，应当具备合伙企业法规定的条件。"},{"i":6,"n":"第六条","txt":"合伙企业的登记事项应当包括："},{"i":7,"n":"第七条","txt":"合伙企业名称中的组织形式后应当标明“普通合伙”、“特殊普通合伙”或者“有限合伙”字样，并符合国家有关企业名称登记管理的规定。"},{"i":8,"n":"第八条","txt":"经企业登记机关登记的合伙企业主要经营场所只能有一个，并且应当在其企业登记机关登记管辖区域内。"},{"i":9,"n":"第九条","txt":"合伙协议未约定或者全体合伙人未决定委托执行事务合伙人的，全体合伙人均为执行事务合伙人。"},{"i":10,"n":"第十条","txt":"合伙企业类型包括普通合伙企业（含特殊的普通合伙企业）和有限合伙企业。"},{"i":11,"n":"第十一条","txt":"设立合伙企业，应当由全体合伙人指定的代表或者共同委托的代理人向企业登记机关申请设立登记。"},{"i":12,"n":"第十二条","txt":"合伙企业的经营范围中有属于法律、行政法规或者国务院规定在登记前须经批准的项目的，应当向企业登记机关提交批准文件。"},{"i":13,"n":"第十三条","txt":"全体合伙人决定委托执行事务合伙人的，应当向企业登记机关提交全体合伙人的委托书。执行事务合伙人是法人或者其他组织的，还应当提交其委派代表的委托书和身份证明。"},{"i":14,"n":"第十四条","txt":"以实物、知识产权、土地使用权或者其他财产权利出资，由全体合伙人协商作价的，应当向企业登记机关提交全体合伙人签署的协商作价确认书；由全体合伙人委托法定评估机构评估作价的，应当向企业登记机关提交法定评估机构出具的评估作价证明。"},{"i":15,"n":"第十五条","txt":"法律、行政法规规定设立特殊的普通合伙企业，需要提交合伙人的职业资格证明的，应当向企业登记机关提交有关证明。"},{"i":16,"n":"第十六条","txt":"申请人提交的登记申请材料齐全、符合法定形式，企业登记机关能够当场登记的，应予当场登记，发给合伙企业营业执照。"},{"i":17,"n":"第十七条","txt":"合伙企业营业执照的签发之日，为合伙企业的成立日期。"},{"i":18,"n":"第十八条","txt":"合伙企业登记事项发生变更的，执行合伙事务的合伙人应当自作出变更决定或者发生变更事由之日起15日内，向原企业登记机关申请变更登记。"},{"i":19,"n":"第十九条","txt":"合伙企业申请变更登记，应当向原企业登记机关提交下列文件："},{"i":20,"n":"第二十条","txt":"申请人提交的申请材料齐全、符合法定形式，企业登记机关能够当场变更登记的，应予当场变更登记。"},{"i":21,"n":"第二十一条","txt":"合伙企业解散，依法由清算人进行清算。清算人应当自被确定之日起10日内，将清算人成员名单向企业登记机关备案。"},{"i":22,"n":"第二十二条","txt":"合伙企业依照合伙企业法的规定解散的，清算人应当自清算结束之日起15日内，向原企业登记机关办理注销登记。"},{"i":23,"n":"第二十三条","txt":"合伙企业办理注销登记，应当提交下列文件："},{"i":24,"n":"第二十四条","txt":"经企业登记机关注销登记，合伙企业终止。"},{"i":25,"n":"第二十五条","txt":"合伙企业设立分支机构，应当向分支机构所在地的企业登记机关申请设立登记。"},{"i":26,"n":"第二十六条","txt":"分支机构的登记事项包括：分支机构的名称、经营场所、经营范围、分支机构负责人的姓名及住所。"},{"i":27,"n":"第二十七条","txt":"合伙企业设立分支机构，应当向分支机构所在地的企业登记机关提交下列文件："},{"i":28,"n":"第二十八条","txt":"分支机构的经营范围中有属于法律、行政法规或者国务院规定在登记前须经批准的项目的，应当向分支机构所在地的企业登记机关提交批准文件。"},{"i":29,"n":"第二十九条","txt":"申请人提交的登记申请材料齐全、符合法定形式，企业登记机关能够当场登记的，应予当场登记，发给营业执照。"},{"i":30,"n":"第三十条","txt":"合伙企业申请分支机构变更登记或者注销登记，比照本办法关于合伙企业变更登记、注销登记的规定办理。"},{"i":31,"n":"第三十一条","txt":"企业登记机关应当将合伙企业登记、备案信息通过企业信用信息公示系统向社会公示。"},{"i":32,"n":"第三十二条","txt":"合伙企业应当于每年1月1日至6月30日，通过企业信用信息公示系统向企业登记机关报送上一年度年度报告，并向社会公示。"},{"i":33,"n":"第三十三条","txt":"合伙企业的营业执照分为正本和副本，正本和副本具有同等法律效力。"},{"i":34,"n":"第三十四条","txt":"任何单位和个人不得伪造、涂改、出售、出租、出借或者以其他方式转让营业执照。"},{"i":35,"n":"第三十五条","txt":"合伙企业及其分支机构营业执照的正本和副本样式，由国务院工商行政管理部门制定。"},{"i":36,"n":"第三十六条","txt":"企业登记机关吊销合伙企业营业执照的，应当发布公告，并不得收取任何费用。"},{"i":37,"n":"第三十七条","txt":"未领取营业执照，而以合伙企业或者合伙企业分支机构名义从事合伙业务的，由企业登记机关责令停止，处5000元以上5万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"提交虚假文件或者采取其他欺骗手段，取得合伙企业登记的，由企业登记机关责令改正，处5000元以上5万元以下的罚款；情节严重的，撤销企业登记，并处5万元以上20万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"合伙企业登记事项发生变更，未依照本办法规定办理变更登记的，由企业登记机关责令限期登记；逾期不登记的，处2000元以上2万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"合伙企业未依照本办法规定在其名称中标明“普通合伙”、“特殊普通合伙”或者“有限合伙”字样的，由企业登记机关责令限期改正，处2000元以上1万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"合伙企业未依照本办法规定办理清算人成员名单备案的，由企业登记机关责令限期办理；逾期未办理的，处2000元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"合伙企业的清算人未向企业登记机关报送清算报告，或者报送的清算报告隐瞒重要事实，或者有重大遗漏的，由企业登记机关责令改正。由此产生的费用和损失，由清算人承担和赔偿。"},{"i":43,"n":"第四十三条","txt":"合伙企业未将其营业执照正本置放在经营场所醒目位置的，由企业登记机关责令改正；拒不改正的，处1000元以上5000元以下的罚款。"},{"i":44,"n":"第四十四条","txt":"合伙企业涂改、出售、出租、出借或者以其他方式转让营业执照的，由企业登记机关责令改正，处2000元以上1万元以下的罚款；情节严重的，吊销营业执照。"},{"i":45,"n":"第四十五条","txt":"企业登记机关的工作人员滥用职权、徇私舞弊、收受贿赂、侵害合伙企业合法权益的，依法给予处分。"},{"i":46,"n":"第四十六条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"合伙企业登记收费项目按照国务院财政部门、价格主管部门的有关规定执行，合伙企业登记收费标准按照国务院价格主管部门、财政部门的有关规定执行。"},{"i":48,"n":"第四十八条","txt":"本办法自发布之日起施行。"}],"heliangyongpinjixiangguanjishuchukouguanzhitiaoli":[{"i":1,"n":"第一条","txt":"为了加强对核两用品及相关技术出口的管制，防止核武器扩散，防范核恐怖主义行为，促进和平利用核能的国际合作，维护国家安全和社会公共利益，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称核两用品及相关技术出口，是指《核两用品及相关技术出口管制清单》（以下简称《管制清单》）所列的设备、材料、软件和相关技术的贸易性出口及对外赠送、展览、科技合作、援助、服务和以其他方式进行的转移。"},{"i":3,"n":"第三条","txt":"国家对核两用品及相关技术出口实行严格管制，严格履行所承担的不扩散核武器的国际义务，防止核两用品及相关技术用于核爆炸目的或者核恐怖主义行为。"},{"i":4,"n":"第四条","txt":"核两用品及相关技术出口，应当遵守国家有关法律、行政法规和本条例的规定，不得损害国家安全和社会公共利益。"},{"i":5,"n":"第五条","txt":"国家对核两用品及相关技术出口实行许可证管理制度。"},{"i":6,"n":"第六条","txt":"核两用品及相关技术出口的许可，应当基于接受方的如下保证："},{"i":7,"n":"第七条","txt":"从事核两用品及相关技术出口的经营者，须经商务部登记。未经登记，任何单位或者个人不得经营核两用品及相关技术出口。登记的具体办法由商务部规定。"},{"i":8,"n":"第八条","txt":"出口《管制清单》所列的核两用品及相关技术，应当向商务部提出申请，填写核两用品及相关技术出口申请表（以下简称出口申请表），并提交下列文件："},{"i":9,"n":"第九条","txt":"核两用品及相关技术出口，属于参加境外展览、中方在境外自用、境外检修，并在规定期限内复运进境的，或者属于境内检修复运出境以及商务部规定的其他情形的，在申请时经商务部审查同意，可以免予提交本条例第八条规定的有关文件。"},{"i":10,"n":"第十条","txt":"申请人应当如实填写出口申请表。"},{"i":11,"n":"第十一条","txt":"商务部应当自收到出口申请表和本条例第八条规定的文件之日起，会同国家原子能机构或者会同国家原子能机构商有关部门，涉及外交政策的，并商外交部，进行审查并在45个工作日内作出许可或者不许可的决定。"},{"i":12,"n":"第十二条","txt":"对国家安全、社会公共利益或者外交政策有重大影响的核两用品及相关技术出口，商务部会同有关部门报国务院批准。"},{"i":13,"n":"第十三条","txt":"核两用品及相关技术出口申请经审查许可的，由商务部颁发核两用品及相关技术出口许可证件（以下简称出口许可证件）。"},{"i":14,"n":"第十四条","txt":"出口许可证件持有人改变原申请的核两用品及相关技术出口的，应当交回原出口许可证件，并依照本条例的有关规定，重新申请、领取出口许可证件。"},{"i":15,"n":"第十五条","txt":"核两用品及相关技术出口时，出口经营者应当向海关出具出口许可证件，依照海关法的规定办理海关手续，并接受海关监管。"},{"i":16,"n":"第十六条","txt":"海关可以对出口经营者出口的设备、材料、软件和相关技术是否需要办理核两用品及相关技术出口许可证件提出质疑，并可以要求其向商务部申请办理是否属于核两用品及相关技术出口管制范围的证明文件；属于核两用品及相关技术出口管制范围的，出口经营者应当依照本条例的规定申请取得核两用品及相关技术出口许可证件。具体办法由海关总署会同商务部制定。"},{"i":17,"n":"第十七条","txt":"接受方违反其依照本条例第六条规定作出的保证，或者出现核扩散、核恐怖主义行为危险时，商务部应当对已经颁发的出口许可证件予以中止或者撤销，并书面通知有关部门。"},{"i":18,"n":"第十八条","txt":"出口经营者应当建立、健全核两用品及相关技术出口的内部控制机制，并妥善保存有关合同、发票、单据、业务函电等资料，保存期限不少于5年。商务部可以查阅、复制相关资料。"},{"i":19,"n":"第十九条","txt":"出口经营者知道或者应当知道，或者得到商务部通知，其所出口的设备、材料、软件和相关技术存在核扩散风险或者可能被用于核恐怖主义目的的，即使该设备、材料、软件和相关技术未列入《管制清单》，也应当依照本条例的规定执行。"},{"i":20,"n":"第二十条","txt":"经国务院批准，商务部会同有关部门，可以临时决定对《管制清单》以外的特定核两用品及相关技术的出口依照本条例实施管制。"},{"i":21,"n":"第二十一条","txt":"商务部组织有关方面的专家组成核两用品及相关技术出口管制咨询委员会，承担核两用品及相关技术出口管制的咨询、评估、论证等工作。"},{"i":22,"n":"第二十二条","txt":"商务部或者商务部会同有关部门可以对涉嫌违反本条例规定的行为进行调查、制止。必要时，商务部可以将拟出境的设备、材料、软件和相关技术的有关情况通报海关，对其中属于海关监管货物的，海关可以查验和扣留。对海关监管区域外不属于海关监管货物的，商务部可以查封或者扣留。有关单位和个人应当予以配合、协助。"},{"i":23,"n":"第二十三条","txt":"违反本条例的规定，出口核两用品的，依照海关法的规定处罚。"},{"i":24,"n":"第二十四条","txt":"伪造、变造或者买卖出口许可证件的，依照有关法律、行政法规的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"对核两用品及相关技术出口实施管制的国家工作人员玩忽职守、徇私舞弊或者滥用职权，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":26,"n":"第二十六条","txt":"商务部会同国家原子能机构和有关部门，可以根据实际情况对《管制清单》进行调整，并予以公布。"},{"i":27,"n":"第二十七条","txt":"中华人民共和国缔结或者参加的国际条约同本条例有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":28,"n":"第二十八条","txt":"核两用品及相关技术从保税区、出口加工区等海关特殊监管区域和出口监管仓库、保税物流中心等保税监管场所出口，适用本条例的规定。"},{"i":29,"n":"第二十九条","txt":"本条例自发布之日起施行。"}],"helihuajianyihejishugaijinjianglitiaoli":[{"i":1,"n":"第一条","txt":"为了鼓励职工积极提合理化建议，推动技术进步，改善经营管理，增强企业内部活力，促进国民经济发展，特制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称合理化建议，是指有关改进和完善企业、事业单位生产技术和经营管理方面的办法和措施；所称技术改进，是指对机械设备、工具、工艺技术等方面所做的改进和革新。"},{"i":3,"n":"第三条","txt":"对提合理化建议和技术改进者的奖励，实行精神鼓励与物质奖励相结合的原则。"},{"i":4,"n":"第四条","txt":"本条例适用于全民所有制企业、事业单位。非全民所有制单位可以参照本条例执行。"},{"i":5,"n":"第五条","txt":"职工（集体或者个人）提出的合理化建议或者进行的技术改进，必须经过试验研究和实际应用，并在企业、事业单位的生产或者工作中取得成效，方能获得奖励。"},{"i":6,"n":"第六条","txt":"对被采用的、可以直接计算经济效益的合理化建议和技术改进项目，奖励分为五个等级："},{"i":7,"n":"第七条","txt":"对被采用的、不能直接计算经济效益的合理化建议和技术改进项目，根据其作用大小、技术复杂程度和推广范围，参照本条例第六条的规定，评定相应的奖励等级。"},{"i":8,"n":"第八条","txt":"被采纳的合理化建议和技术改进项目，经评审确定作为技术储备的，采纳项目的单位应当按照本条例第六条的规定，在第五等级的限额内酌情给予奖励；如作为技术储备的项目以后投入实际应用，应当按照应用后的经济效益大小，评定相应的奖励等级。实际应用后增发奖金时，应当剔除已发放的奖金额。"},{"i":9,"n":"第九条","txt":"被采用的合理化建议和技术改进项目年节约或者创造的价值，自采用之日起，按十二个月为计算单位，并经采用单位财务部门审核。"},{"i":10,"n":"第十条","txt":"工程技术人员、管理干部在完成本职工作前提下提出的，与本身职责虽有直接关联，但有创新的项目，采用见效后可以按照本条例奖励。厂职干部的奖励，报上级主管部门审批。"},{"i":11,"n":"第十一条","txt":"获奖项目不得重复得奖。一个合理化建议或者技术改进项目符合两个以上奖励条例时，应当按照奖金额较高的条例奖励；一个合理化建议或者技术改进项目经再次评审提高了奖励等级，再次发放奖金时只补发差额部分。"},{"i":12,"n":"第十二条","txt":"集体取得的合理化建议和技术改进项目的奖金，按各人贡献大小合理分配。"},{"i":13,"n":"第十三条","txt":"企业、事业单位应当建立合理化建议和技术改进项目评审委员会或者评审小组，由行政负责，吸收工会等有关部门的人员参加，负责合理化建议和技术改进项目的评议审定工作。"},{"i":14,"n":"第十四条","txt":"各企业、事业单位的有关科室或者管理人员，应当及时对合理化建议和技术改进项目做出采纳或者不采纳的结论，并连同做结论的说明以书面形式送给主管建议工作的机构或者人员，提交评审委员会或者评审小组审批。"},{"i":15,"n":"第十五条","txt":"对合理化建议和技术改进项目奖励等级的确定，由采用单位审查批准，其中：一、二等奖励项目，采用单位批准后报上级主管部门备案。"},{"i":16,"n":"第十六条","txt":"奖金由采用单位支付。企业单位支付的奖金，计入生产成本；事业单位支付的奖金，在事业费或者收入提成中列支。"},{"i":17,"n":"第十七条","txt":"对经济效益较高而本单位无法实施的合理化建议和技术改进项目，应当报上级主管部门或者省、自治区、直辖市经济委员会（计划经济委员会）处理；对经济效益显著的合理化建议和技术改进项目，也可以通过技术市场进行有偿转让。"},{"i":18,"n":"第十八条","txt":"对提高工效和降低物质消耗的合理化建议和技术改进项目，对原定额可以给予六个月至一年的保留期。"},{"i":19,"n":"第十九条","txt":"企业、事业单位的工会和职工代表大会有权监督本条例的执行情况，可以对项目的处理、实施、奖励等问题向有关部门提出质询。"},{"i":20,"n":"第二十条","txt":"上级主管部门应当对所属单位的合理化建议和技术改进工作进行监督、检查，并负责协调解决所属企业、事业单位在项目评审工作中发生的争议。"},{"i":21,"n":"第二十一条","txt":"对弄虚作假骗取荣誉者，应当由授奖单位撤销其荣誉称号，扣回其所得奖金；情节严重的，由其所在单位给予行政处分，并追究其经济责任。"},{"i":22,"n":"第二十二条","txt":"本条例由国家经济委员会负责解释。"},{"i":23,"n":"第二十三条","txt":"国家经济委员会根据本条例制订实施细则。各企业、事业单位根据本条例和实施细则，制订具体实施办法，并报上级主管部门备案。"},{"i":24,"n":"第二十四条","txt":"本条例自修订发布之日起施行。"}],"huaiheliuyushuiwuranfangzhizanxingtiaoli":[{"i":1,"n":"第一条","txt":"为了加强淮河流域水污染防治，保护和改善水质，保障人体健康和人民生活、生产用水，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例适用于淮河流域的河流、湖泊、水库、渠道等地表水体的污染防治。"},{"i":3,"n":"第三条","txt":"淮河流域水污染防治的目标：1997年实现全流域工业污染源达标排放；2000年淮河流域各主要河段、湖泊、水库的水质达到淮河流域水污染防治规划的要求，实现淮河水体变清。"},{"i":4,"n":"第四条","txt":"淮河流域水资源保护领导小组（以下简称领导小组），负责协调、解决有关淮河流域水资源保护和水污染防治的重大问题，监督、检查淮河流域水污染防治工作，并行使国务院授予的其他职权。"},{"i":5,"n":"第五条","txt":"河南、安徽、江苏、山东四省（以下简称四省）人民政府各对本省淮河流域水环境质量负责，必须采取措施确保本省淮河流域水污染防治目标的实现。"},{"i":6,"n":"第六条","txt":"淮河流域县级以上地方人民政府，应当定期向本级人民代表大会常务委员会报告本行政区域内淮河流域水污染防治工作进展情况。"},{"i":7,"n":"第七条","txt":"国家对淮河流域水污染防治实行优惠、扶持政策。"},{"i":8,"n":"第八条","txt":"四省人民政府应当妥善做好淮河流域关、停企业的职工安置工作。"},{"i":9,"n":"第九条","txt":"国家对淮河流域实行水污染物排放总量（以下简称排污总量）控制制度。"},{"i":10,"n":"第十条","txt":"国务院环境保护行政主管部门会同国务院计划部门、水行政主管部门商四省人民政府，根据淮河流域水污染防治目标，拟订淮河流域水污染防治规划和排污总量控制计划，经由领导小组报国务院批准后执行。"},{"i":11,"n":"第十一条","txt":"淮河流域县级以上地方人民政府，根据上级人民政府制定的淮河流域水污染防治规划和排污总量控制计划，组织制定本行政区域内淮河流域水污染防治规划和排污总量控制计划，并纳入本行政区域的国民经济和社会发展中长期规划和年度计划。"},{"i":12,"n":"第十二条","txt":"淮河流域排污总量控制计划，应当包括确定的排污总量控制区域、排污总量、排污削减量和削减时限要求，以及应当实行重点排污控制的区域和重点排污控制区域外的重点排污单位名单等内容。"},{"i":13,"n":"第十三条","txt":"向淮河流域水体排污的企业事业单位和个体工商户（以下简称排污单位），凡纳入排污总量控制的，由环境保护行政主管部门商同级有关行业主管部门，根据排污总量控制计划、建设项目环境影响报告书和排污申报量，确定其排污总量控制指标。"},{"i":14,"n":"第十四条","txt":"在淮河流域排污总量控制计划确定的重点排污控制区域内的排污单位和重点排污控制区域外的重点排污单位，必须按照国家有关规定申请领取排污许可证，并在排污口安装污水排放计量器具。"},{"i":15,"n":"第十五条","txt":"国务院环境保护行政主管部门商国务院水行政主管部门，根据淮河流域排污总量控制计划以及四省的经济技术条件，制定淮河流域省界水质标准，报国务院批准后施行。"},{"i":16,"n":"第十六条","txt":"淮河流域水资源保护局负责监测四省省界水质，并将监测结果及时报领导小组。"},{"i":17,"n":"第十七条","txt":"淮河流域重点排污单位超标排放水污染物的，责令限期治理。"},{"i":18,"n":"第十八条","txt":"自1998年1月1日起，禁止一切工业企业向淮河流域水体超标排放水污染物。"},{"i":19,"n":"第十九条","txt":"淮河流域排污单位必须采取措施按期完成污染治理任务，保证水污染物的排放符合国家制定的和地方制定的排放标准；持有排污许可证的单位应当保证其排污总量不超过排污许可证规定的排污总量控制指标。"},{"i":20,"n":"第二十条","txt":"淮河流域县级以上地方人民政府环境保护行政主管部门征收的排污费，必须按照国家有关规定，全部用于污染治理，不得挪作他用。"},{"i":21,"n":"第二十一条","txt":"在淮河流域河流、湖泊、水库、渠道等管理范围内设置或者扩大排污口的，必须依法报经水行政主管部门同意。"},{"i":22,"n":"第二十二条","txt":"禁止在淮河流域新建化学制浆造纸企业。"},{"i":23,"n":"第二十三条","txt":"淮河流域县级以上地方人民政府环境保护行政主管部门审批向水体排放污染物的建设项目的环境影响报告书时，不得突破本行政区域排污总量控制指标。"},{"i":24,"n":"第二十四条","txt":"淮河流域县级以上地方人民政府应当按照淮河流域水污染防治规划的要求，建设城镇污水集中处理设施。"},{"i":25,"n":"第二十五条","txt":"淮河流域水闸应当在保证防汛、抗旱的前提下，兼顾上游下游水质，制定防污调控方案，避免闸控河道蓄积的污水集中下泄。"},{"i":26,"n":"第二十六条","txt":"领导小组办公室应当组织四省人民政府环境保护行政主管部门、水行政主管部门等采取下列措施，开展枯水期水污染联合防治工作："},{"i":27,"n":"第二十七条","txt":"淮河流域发生水污染事故时，必须及时向环境保护行政主管部门报告。环境保护行政主管部门应当在接到事故报告时起24小时内，向本级人民政府、上级环境保护行政主管部门和领导小组办公室报告，并向相邻上游和下游的环境保护行政主管部门、水行政主管部门通报。当地人民政府应当采取应急措施，消除或者减轻污染危害。"},{"i":28,"n":"第二十八条","txt":"淮河流域省际水污染纠纷，由领导小组办公室进行调查、监测，提出解决方案，报领导小组协调处理。"},{"i":29,"n":"第二十九条","txt":"领导小组办公室根据领导小组的授权，可以组织四省人民政府环境保护行政主管部门、水行政主管部门等检查淮河流域水污染防治工作。被检查单位必须如实反映情况，提供必要的资料。"},{"i":30,"n":"第三十条","txt":"排污单位有下列情形之一的，由有关县级以上人民政府责令关闭或者停业："},{"i":31,"n":"第三十一条","txt":"在限期治理期限内，未完成治理任务的，由县级以上地方人民政府环境保护行政主管部门责令限量排污，可以处10万元以下的罚款；情节严重的，由有关县级以上人民政府责令关闭或者停业。"},{"i":32,"n":"第三十二条","txt":"擅自在河流、湖泊、水库、渠道管理范围内设置或者扩大排污口的，由有关县级以上地方人民政府环境保护行政主管部门或者水行政主管部门责令纠正，可以处5万元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"自本条例施行之日起，新建化学制浆造纸企业和制革、化工、印染、电镀、酿造等污染严重的小型企业或者未经批准建设属于严格限制的项目的，由有关县级人民政府责令停止建设或者关闭，环境保护行政主管部门可以处20万元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"环境保护行政主管部门超过本行政区域的排污总量控制指标，批准建设项目环境影响报告书的，对负有直接责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"违反枯水期污染源限排方案超量排污的，由有关县级以上地方人民政府环境保护行政主管部门责令纠正，可以处10万元以下的罚款；情节严重的，由有关县级以上人民政府责令关闭或者停业；对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":36,"n":"第三十六条","txt":"本条例规定的责令企业事业单位停止建设或者停业、关闭，由作出限期治理决定的人民政府决定；责令中央管辖的企业事业单位停止建设或者停业、关闭，须报国务院批准。"},{"i":37,"n":"第三十七条","txt":"县级人民政府环境保护行政主管部门或者水行政主管部门决定的罚款额，以不超过1万元为限；超过1万元的，应当报上一级环境保护行政主管部门或者水行政主管部门批准。"},{"i":38,"n":"第三十八条","txt":"违反水闸防污调控方案调度水闸的，由县级以上人民政府水行政主管部门责令纠正；对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":39,"n":"第三十九条","txt":"因发生水污染事故，造成重大经济损失或者人员伤亡，负有直接责任的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"拒绝、阻碍承担本条例规定职责的国家工作人员依法执行职务，违反治安管理的，依照《中华人民共和国治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"承担本条例规定职责的国家工作人员滥用职权、徇私舞弊、玩忽职守，或者拒不履行义务，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":42,"n":"第四十二条","txt":"四省人民政府可以根据本条例分别制定实施办法。"},{"i":43,"n":"第四十三条","txt":"本条例自1995年8月8日起施行。"}],"huazhuangpinweishengjiandutiaoli":[{"i":1,"n":"第一条","txt":"为加强化妆品的卫生监督，保证化妆品的卫生质量和使用安全，保障消费者健康，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称的化妆品，是指以涂擦、喷洒或者其他类似的方法，散布于人体表面任何部位（皮肤、毛发、指甲、口唇等），以达到清洁、消除不良气味、护肤、美容和修饰目的的日用化学工业产品。"},{"i":3,"n":"第三条","txt":"国家实行化妆品卫生监督制度。国务院化妆品监督管理部门主管全国化妆品的卫生监督工作，县以上地方各级人民政府的化妆品监督管理部门主管本辖区内化妆品的卫生监督工作。"},{"i":4,"n":"第四条","txt":"凡从事化妆品生产、经营的单位和个人都必须遵守本条例。"},{"i":5,"n":"第五条","txt":"对化妆品生产企业实行化妆品生产许可证制度。"},{"i":6,"n":"第六条","txt":"化妆品生产企业必须符合下列卫生要求："},{"i":7,"n":"第七条","txt":"直接从事化妆品生产的人员，必须每年进行健康检查，取得健康证后方可从事化妆品的生产活动。"},{"i":8,"n":"第八条","txt":"生产化妆品所需的原料、辅料以及直接接触化妆品的容器和包装材料必须符合国家卫生标准。"},{"i":9,"n":"第九条","txt":"使用化妆品新原料生产化妆品，必须经国务院化妆品监督管理部门批准。"},{"i":10,"n":"第十条","txt":"生产特殊用途的化妆品，必须经国务院化妆品监督管理部门批准，取得批准文号后方可生产。"},{"i":11,"n":"第十一条","txt":"生产企业在化妆品投放市场前，必须按照国家《化妆品卫生标准》对产品进行卫生质量检验，对质量合格的产品应当附有合格标记。未经检验或者不符合卫生标准的产品不得出厂。"},{"i":12,"n":"第十二条","txt":"化妆品标签上应当注明产品名称、厂名，并注明生产企业化妆品生产许可证编号；小包装或者说明书上应当注明生产日期和有效使用期限。特殊用途的化妆品，还应当注明批准文号。对可能引起不良反应的化妆品，说明书上应当注明使用方法、注意事项。"},{"i":13,"n":"第十三条","txt":"化妆品经营单位和个人不得销售下列化妆品："},{"i":14,"n":"第十四条","txt":"化妆品的广告宣传不得有下列内容："},{"i":15,"n":"第十五条","txt":"首次进口的特殊用途化妆品，进口单位必须提供该化妆品的说明书、质量标准、检验方法等有关资料和样品以及出口国（地区）批准生产的证明文件，经国务院化妆品监督管理部门批准，方可签订进口合同。首次进口的其他化妆品，应当按照规定备案。"},{"i":16,"n":"第十六条","txt":"进口的化妆品，必须经国家商检部门检验；检验合格的，方准进口。"},{"i":17,"n":"第十七条","txt":"各级化妆品监督管理部门行使化妆品卫生监督职责。"},{"i":18,"n":"第十八条","txt":"国务院化妆品监督管理部门聘请科研、医疗、生产、卫生管理等有关专家组成化妆品安全性评审组，对特殊用途的化妆品和化妆品新原料进行安全性评审，对化妆品引起的重大事故进行技术鉴定。"},{"i":19,"n":"第十九条","txt":"各级化妆品监督管理部门设化妆品卫生监督员，对化妆品实施卫生监督。"},{"i":20,"n":"第二十条","txt":"化妆品卫生监督员在实施化妆品卫生监督时，应当佩戴证章，出示证件。"},{"i":21,"n":"第二十一条","txt":"化妆品卫生监督员有权按照国家规定向生产企业和经营单位抽检样品，索取与卫生监督有关的安全性资料，任何单位不得拒绝、隐瞒和提供假材料。"},{"i":22,"n":"第二十二条","txt":"各级化妆品监督管理部门和化妆品卫生监督员不得以技术咨询、技术服务等方式参与生产、销售化妆品，不得监制化妆品。"},{"i":23,"n":"第二十三条","txt":"对因使用化妆品引起不良反应的病例，各医疗单位应当向当地化妆品监督管理部门报告。"},{"i":24,"n":"第二十四条","txt":"未取得化妆品生产许可证的企业擅自生产化妆品的，责令该企业停产，没收产品及违法所得，并且可以处违法所得三到五倍的罚款。"},{"i":25,"n":"第二十五条","txt":"生产未取得批准文号的特殊用途的化妆品，或者使用化妆品禁用原料和未经批准的化妆品新原料的，没收产品及违法所得，处违法所得三到五倍的罚款，并且可以责令该企业停产或者吊销化妆品生产许可证。"},{"i":26,"n":"第二十六条","txt":"违反本条例规定，进口或者销售未经批准或者检验的进口化妆品的，没收产品及违法所得，并且可以处违法所得三到五倍的罚款。"},{"i":27,"n":"第二十七条","txt":"生产或者销售不符合国家《化妆品卫生标准》的化妆品的，没收产品及违法所得，并且可以处违法所得三到五倍的罚款。"},{"i":28,"n":"第二十八条","txt":"对违反本条例其他有关规定的，处以警告，责令限期改进；情节严重的，对生产企业，可以责令该企业停产或者吊销化妆品生产许可证，对经营单位，可以责令其停止经营，没收违法所得，并且可以处违法所得二到三倍的罚款。"},{"i":29,"n":"第二十九条","txt":"本条例规定的行政处罚，由县级以上化妆品监督管理部门决定。违反本条例第十四条有关广告管理的行政处罚，由市场监督管理部门决定。"},{"i":30,"n":"第三十条","txt":"当事人对化妆品监督管理部门的行政处罚决定不服的，可以在收到通知书次日起十五日内向上一级化妆品监督管理部门申请复议。上一级化妆品监督管理部门应当在三十日内给予答复。当事人对上一级化妆品监督管理部门复议决定不服的，可以在收到复议通知书次日起十五日内向人民法院起诉。但对化妆品监督管理部门所作出的没收产品及责令停产的处罚决定必须立即执行。当事人对处罚决定不执行，逾期又不起诉的，化妆品监督管理部门可以申请人民法院强制执行。"},{"i":31,"n":"第三十一条","txt":"对违反本条例造成人体损伤或者发生中毒事故的，有直接责任的生产企业和经营单位或者个人应负损害赔偿责任。"},{"i":32,"n":"第三十二条","txt":"化妆品卫生监督员滥用职权，营私舞弊以及泄露企业提供的技术资料的，由化妆品监督管理部门给予行政处分，造成严重后果，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"中国人民解放军所属单位生产的投放市场的化妆品的卫生监督，依照本条例执行。"},{"i":34,"n":"第三十四条","txt":"本条例的实施细则由国务院化妆品监督管理部门制定。"},{"i":35,"n":"第三十五条","txt":"本条例自1990年1月1日起施行。"}],"jihuashengyujishufuwuguanlitiaoli":[{"i":1,"n":"第一条","txt":"为了加强对计划生育技术服务工作的管理，控制人口数量，提高人口素质，保障公民的生殖健康权利，制定本条例。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事计划生育技术服务活动的机构及其人员应当遵守本条例。"},{"i":3,"n":"第三条","txt":"计划生育技术服务实行国家指导和个人自愿相结合的原则。"},{"i":4,"n":"第四条","txt":"国务院计划生育行政部门负责管理全国计划生育技术服务工作。国务院卫生行政等有关部门在各自的职责范围内，配合计划生育行政部门做好计划生育技术服务工作。"},{"i":5,"n":"第五条","txt":"计划生育技术服务网络由计划生育技术服务机构和从事计划生育技术服务的医疗、保健机构组成，并纳入区域卫生规划。"},{"i":6,"n":"第六条","txt":"计划生育技术服务包括计划生育技术指导、咨询以及与计划生育有关的临床医疗服务。"},{"i":7,"n":"第七条","txt":"计划生育技术指导、咨询包括下列内容："},{"i":8,"n":"第八条","txt":"县级以上城市从事计划生育技术服务的机构可以在批准的范围内开展下列与计划生育有关的临床医疗服务："},{"i":9,"n":"第九条","txt":"乡级计划生育技术服务机构可以在批准的范围内开展下列计划生育技术服务项目："},{"i":10,"n":"第十条","txt":"乡级计划生育技术服务机构申请开展本条例第九条规定的项目，应当具备下列条件："},{"i":11,"n":"第十一条","txt":"各级计划生育行政部门和卫生行政部门应当定期互相通报开展与计划生育有关的临床医疗服务的审批情况。"},{"i":12,"n":"第十二条","txt":"因生育病残儿要求再生育的，应当向县级人民政府计划生育行政部门申请医学鉴定，经县级人民政府计划生育行政部门初审同意后，由设区的市级人民政府计划生育行政部门组织医学专家进行医学鉴定；当事人对医学鉴定有异议的，可以向省、自治区、直辖市人民政府计划生育行政部门申请再鉴定。省、自治区、直辖市人民政府计划生育行政部门组织的医学鉴定为终局鉴定。具体办法由国务院计划生育行政部门会同国务院卫生行政部门制定。"},{"i":13,"n":"第十三条","txt":"向公民提供的计划生育技术服务和药具应当安全、有效，符合国家规定的质量技术标准。"},{"i":14,"n":"第十四条","txt":"国务院计划生育行政部门定期编制并发布计划生育技术、药具目录，指导列入目录的计划生育技术、药具的推广和应用。"},{"i":15,"n":"第十五条","txt":"开展计划生育科技项目和计划生育国际合作项目，应当经国务院计划生育行政部门审核批准，并接受项目实施地县级以上地方人民政府计划生育行政部门的监督管理。"},{"i":16,"n":"第十六条","txt":"涉及计划生育技术的广告，其内容应当经省、自治区、直辖市人民政府计划生育行政部门审查同意。"},{"i":17,"n":"第十七条","txt":"从事计划生育技术服务的机构施行避孕、节育手术、特殊检查或者特殊治疗时，应当征得受术者本人同意，并保证受术者的安全。"},{"i":18,"n":"第十八条","txt":"任何机构和个人不得进行非医学需要的胎儿性别鉴定或者选择性别的人工终止妊娠。"},{"i":19,"n":"第十九条","txt":"从事计划生育技术服务的机构包括计划生育技术服务机构和从事计划生育技术服务的医疗、保健机构。"},{"i":20,"n":"第二十条","txt":"从事计划生育技术服务的机构，必须符合国务院计划生育行政部门规定的设置标准。"},{"i":21,"n":"第二十一条","txt":"设立计划生育技术服务机构，由设区的市级以上地方人民政府计划生育行政部门批准，发给《计划生育技术服务机构执业许可证》，并在《计划生育技术服务机构执业许可证》上注明获准开展的计划生育技术服务项目。"},{"i":22,"n":"第二十二条","txt":"从事计划生育技术服务的医疗、保健机构，由县级以上地方人民政府卫生行政部门审查批准，在其《医疗机构执业许可证》上注明获准开展的计划生育技术服务项目，并向同级计划生育行政部门通报。"},{"i":23,"n":"第二十三条","txt":"乡、镇已有医疗机构的，不再新设立计划生育技术服务机构；但是，医疗机构内必须设有计划生育技术服务科（室），专门从事计划生育技术服务工作。乡、镇既有医疗机构，又有计划生育技术服务机构的，各自在批准的范围内开展计划生育技术服务工作。乡、镇没有医疗机构，需要设立计划生育技术服务机构的，应当依照本条例第二十一条的规定从严审批。"},{"i":24,"n":"第二十四条","txt":"计划生育技术服务机构从事产前诊断的，应当经省、自治区、直辖市人民政府计划生育行政部门同意后，由同级卫生行政部门审查批准，并报国务院计划生育行政部门和国务院卫生行政部门备案。"},{"i":25,"n":"第二十五条","txt":"从事计划生育技术服务的机构的执业许可证明文件每三年由原批准机关校验一次。"},{"i":26,"n":"第二十六条","txt":"从事计划生育技术服务的机构应当按照批准的业务范围和服务项目执业，并遵守有关法律、行政法规和国务院卫生行政部门制定的医疗技术常规和抢救与转诊制度。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府计划生育行政部门应当对本行政区域内的计划生育技术服务工作进行定期检查。"},{"i":28,"n":"第二十八条","txt":"国家建立避孕药具流通管理制度。具体办法由国务院药品监督管理部门会同国务院计划生育行政部门及其他有关主管部门制定。"},{"i":29,"n":"第二十九条","txt":"计划生育技术服务人员中依据本条例的规定从事与计划生育有关的临床服务人员，应当依照执业医师法和国家有关护士管理的规定，分别取得执业医师、执业助理医师、乡村医生或者护士的资格，并在依照本条例设立的机构中执业。在计划生育技术服务机构执业的执业医师和执业助理医师应当依照执业医师法的规定向所在地县级以上地方人民政府卫生行政部门申请注册。具体办法由国务院计划生育行政部门、卫生行政部门共同制定。"},{"i":30,"n":"第三十条","txt":"计划生育技术服务人员必须按照批准的服务范围、服务项目、手术术种从事计划生育技术服务，遵守与执业有关的法律、法规、规章、技术常规、职业道德规范和管理制度。"},{"i":31,"n":"第三十一条","txt":"国务院计划生育行政部门负责全国计划生育技术服务的监督管理工作。县级以上地方人民政府计划生育行政部门负责本行政区域内计划生育技术服务的监督管理工作。"},{"i":32,"n":"第三十二条","txt":"国家建立计划生育技术服务统计制度和计划生育技术服务事故、计划生育手术并发症和计划生育药具不良反应的鉴定制度和报告制度。"},{"i":33,"n":"第三十三条","txt":"国务院计划生育行政部门会同国务院卫生行政部门汇总、分析计划生育技术服务事故、计划生育手术并发症和计划生育药具不良反应的数据，并应当及时向有关部门通报。国务院计划生育行政部门应当按照国家有关规定及时公布计划生育技术服务重大事故、计划生育手术严重的并发症和计划生育药具严重的或者新出现的不良反应，并可以授权省、自治区、直辖市计划生育行政部门及时公布和通报本行政区域内计划生育技术服务事故、计划生育手术并发症和计划生育药具不良反应。"},{"i":34,"n":"第三十四条","txt":"计划生育技术服务机构或者医疗、保健机构以外的机构或者人员违反本条例的规定，擅自从事计划生育技术服务的，由县级以上地方人民政府计划生育行政部门依据职权，责令改正，给予警告，没收违法所得和有关药品、医疗器械；违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款；造成严重后果，构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"计划生育技术服务机构违反本条例的规定，未经批准擅自从事产前诊断和使用辅助生育技术治疗不育症的，由县级以上地方人民政府卫生行政部门会同计划生育行政部门依据职权，责令改正，给予警告，没收违法所得和有关药品、医疗器械；违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款；情节严重的，并由原发证部门吊销计划生育技术服务的执业资格。"},{"i":36,"n":"第三十六条","txt":"违反本条例的规定，逾期不校验计划生育技术服务执业许可证明文件，继续从事计划生育技术服务的，由原发证部门责令限期补办校验手续；拒不校验的，由原发证部门吊销计划生育技术服务的执业资格。"},{"i":37,"n":"第三十七条","txt":"违反本条例的规定，买卖、出借、出租或者涂改、伪造计划生育技术服务执业许可证明文件的，由原发证部门责令改正，没收违法所得；违法所得3000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足3000元的，并处3000元以上5000元以下的罚款；情节严重的，并由原发证部门吊销相关的执业资格。"},{"i":38,"n":"第三十八条","txt":"从事计划生育技术服务的机构违反本条例第三条第三款的规定，向农村实行计划生育的育龄夫妻提供避孕、节育技术服务，收取费用的，由县级地方人民政府计划生育行政部门责令退还所收费用，给予警告，并处所收费用2倍以上5倍以下的罚款；情节严重的，并对该机构的正职负责人、直接负责的主管人员和其他直接责任人员给予降级或者撤职的行政处分。"},{"i":39,"n":"第三十九条","txt":"从事计划生育技术服务的机构违反本条例的规定，未经批准擅自扩大计划生育技术服务项目的，由原发证部门责令改正，给予警告，没收违法所得；违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款；情节严重的，并由原发证部门吊销计划生育技术服务的执业资格。"},{"i":40,"n":"第四十条","txt":"从事计划生育技术服务的机构违反本条例的规定，使用没有依法取得相应的医师资格的人员从事与计划生育技术服务有关的临床医疗服务的，由县级以上人民政府卫生行政部门依据职权，责令改正，没收违法所得；违法所得3000元以上的，并处违法所得1倍以上3倍以下的罚款；没有违法所得或者违法所得不足3000元的，并处3000元以上5000元以下的罚款；情节严重的，并由原发证部门吊销计划生育技术服务的执业资格。"},{"i":41,"n":"第四十一条","txt":"从事计划生育技术服务的机构出具虚假证明文件，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由原发证部门责令改正，给予警告，没收违法所得；违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款；情节严重的，并由原发证部门吊销计划生育技术服务的执业资格。"},{"i":42,"n":"第四十二条","txt":"计划生育行政部门、卫生行政部门违反规定，批准不具备规定条件的计划生育技术服务机构或者医疗、保健机构开展与计划生育有关的临床医疗服务项目，或者不履行监督职责，或者发现违法行为不予查处，导致计划生育技术服务重大事故发生的，对该部门的正职负责人、直接负责的主管人员和其他直接责任人员给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"依照本条例的规定，乡级计划生育技术服务机构开展本条例第九条规定的项目发生计划生育技术服务事故的，由计划生育行政部门行使依照《医疗事故处理条例》有关规定由卫生行政部门承担的受理、交由负责医疗事故技术鉴定工作的医学会组织鉴定和赔偿调解的职能；对发生计划生育技术服务事故的该机构及其有关责任人员，依法进行处理。"},{"i":44,"n":"第四十四条","txt":"设区的市级以上地方人民政府计划生育行政部门应当自《国务院关于修改〈计划生育技术服务管理条例〉的决定》施行之日起6个月内，对本行政区域内已经获得批准开展本条例第九条规定的项目的乡级计划生育技术服务机构，依照本条例第十条规定的条件重新进行检查；对不符合条件的，应当责令其立即停止开展相应的项目，并收回原批准文件。"},{"i":45,"n":"第四十五条","txt":"在乡村计划生育技术服务机构或者乡村医疗、保健机构中从事计划生育技术服务的人员，符合本条例规定的，可以经认定取得执业资格；不具备本条例规定条件的，按照国务院的有关规定执行。"},{"i":46,"n":"第四十六条","txt":"本条例自2001年10月1日起施行。"}],"jinchukouguanshuitiaoli":[{"i":1,"n":"第一条","txt":"为了贯彻对外开放政策，促进对外经济贸易和国民经济的发展，根据《中华人民共和国海关法》（以下简称《海关法》）的有关规定，制定本条例。"},{"i":2,"n":"第二条","txt":"中华人民共和国准许进出口的货物、进境物品，除法律、行政法规另有规定外，海关依照本条例规定征收进出口关税。"},{"i":3,"n":"第三条","txt":"国务院制定《中华人民共和国进出口税则》（以下简称《税则》）、《中华人民共和国进境物品进口税税率表》（以下简称《进境物品进口税税率表》），规定关税的税目、税则号列和税率，作为本条例的组成部分。"},{"i":4,"n":"第四条","txt":"国务院设立关税税则委员会，负责《税则》和《进境物品进口税税率表》的税目、税则号列和税率的调整和解释，报国务院批准后执行；决定实行暂定税率的货物、税率和期限；决定关税配额税率；决定征收反倾销税、反补贴税、保障措施关税、报复性关税以及决定实施其他关税措施；决定特殊情况下税率的适用，以及履行国务院规定的其他职责。"},{"i":5,"n":"第五条","txt":"进口货物的收货人、出口货物的发货人、进境物品的所有人，是关税的纳税义务人。"},{"i":6,"n":"第六条","txt":"海关及其工作人员应当依照法定职权和法定程序履行关税征管职责，维护国家利益，保护纳税人合法权益，依法接受监督。"},{"i":7,"n":"第七条","txt":"纳税义务人有权要求海关对其商业秘密予以保密，海关应当依法为纳税义务人保密。"},{"i":8,"n":"第八条","txt":"海关对检举或者协助查获违反本条例行为的单位和个人，应当按照规定给予奖励，并负责保密。"},{"i":9,"n":"第九条","txt":"进口关税设置最惠国税率、协定税率、特惠税率、普通税率、关税配额税率等税率。对进口货物在一定期限内可以实行暂定税率。"},{"i":10,"n":"第十条","txt":"原产于共同适用最惠国待遇条款的世界贸易组织成员的进口货物，原产于与中华人民共和国签订含有相互给予最惠国待遇条款的双边贸易协定的国家或者地区的进口货物，以及原产于中华人民共和国境内的进口货物，适用最惠国税率。"},{"i":11,"n":"第十一条","txt":"适用最惠国税率的进口货物有暂定税率的，应当适用暂定税率；适用协定税率、特惠税率的进口货物有暂定税率的，应当从低适用税率；适用普通税率的进口货物，不适用暂定税率。"},{"i":12,"n":"第十二条","txt":"按照国家规定实行关税配额管理的进口货物，关税配额内的，适用关税配额税率；关税配额外的，其税率的适用按照本条例第十条、第十一条的规定执行。"},{"i":13,"n":"第十三条","txt":"按照有关法律、行政法规的规定对进口货物采取反倾销、反补贴、保障措施的，其税率的适用按照《中华人民共和国反倾销条例》、《中华人民共和国反补贴条例》和《中华人民共和国保障措施条例》的有关规定执行。"},{"i":14,"n":"第十四条","txt":"任何国家或者地区违反与中华人民共和国签订或者共同参加的贸易协定及相关协定，对中华人民共和国在贸易方面采取禁止、限制、加征关税或者其他影响正常贸易的措施的，对原产于该国家或者地区的进口货物可以征收报复性关税，适用报复性关税税率。"},{"i":15,"n":"第十五条","txt":"进出口货物，应当适用海关接受该货物申报进口或者出口之日实施的税率。"},{"i":16,"n":"第十六条","txt":"有下列情形之一，需缴纳税款的，应当适用海关接受申报办理纳税手续之日实施的税率："},{"i":17,"n":"第十七条","txt":"补征和退还进出口货物关税，应当按照本条例第十五条或者第十六条的规定确定适用的税率。"},{"i":18,"n":"第十八条","txt":"进口货物的完税价格由海关以符合本条第三款所列条件的成交价格以及该货物运抵中华人民共和国境内输入地点起卸前的运输及其相关费用、保险费为基础审查确定。"},{"i":19,"n":"第十九条","txt":"进口货物的下列费用应当计入完税价格："},{"i":20,"n":"第二十条","txt":"进口时在货物的价款中列明的下列税收、费用，不计入该货物的完税价格："},{"i":21,"n":"第二十一条","txt":"进口货物的成交价格不符合本条例第十八条第三款规定条件的，或者成交价格不能确定的，海关经了解有关情况，并与纳税义务人进行价格磋商后，依次以下列价格估定该货物的完税价格："},{"i":22,"n":"第二十二条","txt":"按照本条例第二十一条第一款第（三）项规定估定完税价格，应当扣除的项目是指："},{"i":23,"n":"第二十三条","txt":"以租赁方式进口的货物，以海关审查确定的该货物的租金作为完税价格。"},{"i":24,"n":"第二十四条","txt":"运往境外加工的货物，出境时已向海关报明并在海关规定的期限内复运进境的，应当以境外加工费和料件费以及复运进境的运输及其相关费用和保险费审查确定完税价格。"},{"i":25,"n":"第二十五条","txt":"运往境外修理的机械器具、运输工具或者其他货物，出境时已向海关报明并在海关规定的期限内复运进境的，应当以境外修理费和料件费审查确定完税价格。"},{"i":26,"n":"第二十六条","txt":"出口货物的完税价格由海关以该货物的成交价格以及该货物运至中华人民共和国境内输出地点装载前的运输及其相关费用、保险费为基础审查确定。"},{"i":27,"n":"第二十七条","txt":"出口货物的成交价格不能确定的，海关经了解有关情况，并与纳税义务人进行价格磋商后，依次以下列价格估定该货物的完税价格："},{"i":28,"n":"第二十八条","txt":"按照本条例规定计入或者不计入完税价格的成本、费用、税收，应当以客观、可量化的数据为依据。"},{"i":29,"n":"第二十九条","txt":"进口货物的纳税义务人应当自运输工具申报进境之日起14日内，出口货物的纳税义务人除海关特准的外，应当在货物运抵海关监管区后、装货的24小时以前，向货物的进出境地海关申报。进出口货物转关运输的，按照海关总署的规定执行。"},{"i":30,"n":"第三十条","txt":"纳税义务人应当依法如实向海关申报，并按照海关的规定提供有关确定完税价格、进行商品归类、确定原产地以及采取反倾销、反补贴或者保障措施等所需的资料；必要时，海关可以要求纳税义务人补充申报。"},{"i":31,"n":"第三十一条","txt":"纳税义务人应当按照《税则》规定的目录条文和归类总规则、类注、章注、子目注释以及其他归类注释，对其申报的进出口货物进行商品归类，并归入相应的税则号列；海关应当依法审核确定该货物的商品归类。"},{"i":32,"n":"第三十二条","txt":"海关可以要求纳税义务人提供确定商品归类所需的有关资料；必要时，海关可以组织化验、检验，并将海关认定的化验、检验结果作为商品归类的依据。"},{"i":33,"n":"第三十三条","txt":"海关为审查申报价格的真实性和准确性，可以查阅、复制与进出口货物有关的合同、发票、账册、结付汇凭证、单据、业务函电、录音录像制品和其他反映买卖双方关系及交易活动的资料。"},{"i":34,"n":"第三十四条","txt":"海关对纳税义务人申报的价格有怀疑的，应当将怀疑的理由书面告知纳税义务人，要求其在规定的期限内书面作出说明、提供有关资料。"},{"i":35,"n":"第三十五条","txt":"海关审查确定进出口货物的完税价格后，纳税义务人可以以书面形式要求海关就如何确定其进出口货物的完税价格作出书面说明，海关应当向纳税义务人作出书面说明。"},{"i":36,"n":"第三十六条","txt":"进出口货物关税，以从价计征、从量计征或者国家规定的其他方式征收。"},{"i":37,"n":"第三十七条","txt":"纳税义务人应当自海关填发税款缴款书之日起15日内向指定银行缴纳税款。纳税义务人未按期缴纳税款的，从滞纳税款之日起，按日加收滞纳税款万分之五的滞纳金。"},{"i":38,"n":"第三十八条","txt":"海关征收关税、滞纳金等，应当按人民币计征。"},{"i":39,"n":"第三十九条","txt":"纳税义务人因不可抗力或者在国家税收政策调整的情形下，不能按期缴纳税款的，经依法提供税款担保后，可以延期缴纳税款，但是最长不得超过6个月。"},{"i":40,"n":"第四十条","txt":"进出口货物的纳税义务人在规定的纳税期限内有明显的转移、藏匿其应税货物以及其他财产迹象的，海关可以责令纳税义务人提供担保；纳税义务人不能提供担保的，海关可以按照《海关法》第六十一条的规定采取税收保全措施。"},{"i":41,"n":"第四十一条","txt":"加工贸易的进口料件按照国家规定保税进口的，其制成品或者进口料件未在规定的期限内出口的，海关按照规定征收进口关税。"},{"i":42,"n":"第四十二条","txt":"暂时进境或者暂时出境的下列货物，在进境或者出境时纳税义务人向海关缴纳相当于应纳税款的保证金或者提供其他担保的，可以暂不缴纳关税，并应当自进境或者出境之日起6个月内复运出境或者复运进境；需要延长复运出境或者复运进境期限的，纳税义务人应当根据海关总署的规定向海关办理延期手续："},{"i":43,"n":"第四十三条","txt":"因品质或者规格原因，出口货物自出口之日起1年内原状复运进境的，不征收进口关税。"},{"i":44,"n":"第四十四条","txt":"因残损、短少、品质不良或者规格不符原因，由进出口货物的发货人、承运人或者保险公司免费补偿或者更换的相同货物，进出口时不征收关税。被免费更换的原进口货物不退运出境或者原出口货物不退运进境的，海关应当对原进出口货物重新按照规定征收关税。"},{"i":45,"n":"第四十五条","txt":"下列进出口货物，免征关税："},{"i":46,"n":"第四十六条","txt":"特定地区、特定企业或者有特定用途的进出口货物减征或者免征关税，以及临时减征或者免征关税，按照国务院的有关规定执行。"},{"i":47,"n":"第四十七条","txt":"进口货物减征或者免征进口环节海关代征税，按照有关法律、行政法规的规定执行。"},{"i":48,"n":"第四十八条","txt":"纳税义务人进出口减免税货物的，除另有规定外，应当在进出口该货物之前，按照规定持有关文件向海关办理减免税审批手续。经海关审查符合规定的，予以减征或者免征关税。"},{"i":49,"n":"第四十九条","txt":"需由海关监管使用的减免税进口货物，在监管年限内转让或者移作他用需要补税的，海关应当根据该货物进口时间折旧估价，补征进口关税。"},{"i":50,"n":"第五十条","txt":"有下列情形之一的，纳税义务人自缴纳税款之日起1年内，可以申请退还关税，并应当以书面形式向海关说明理由，提供原缴款凭证及相关资料："},{"i":51,"n":"第五十一条","txt":"进出口货物放行后，海关发现少征或者漏征税款的，应当自缴纳税款或者货物放行之日起1年内，向纳税义务人补征税款。但因纳税义务人违反规定造成少征或者漏征税款的，海关可以自缴纳税款或者货物放行之日起3年内追征税款，并从缴纳税款或者货物放行之日起按日加收少征或者漏征税款万分之五的滞纳金。"},{"i":52,"n":"第五十二条","txt":"海关发现多征税款的，应当立即通知纳税义务人办理退还手续。"},{"i":53,"n":"第五十三条","txt":"按照本条例第五十条、第五十二条的规定退还税款、利息涉及从国库中退库的，按照法律、行政法规有关国库管理的规定执行。"},{"i":54,"n":"第五十四条","txt":"报关企业接受纳税义务人的委托，以纳税义务人的名义办理报关纳税手续，因报关企业违反规定而造成海关少征、漏征税款的，报关企业对少征或者漏征的税款、滞纳金与纳税义务人承担纳税的连带责任。"},{"i":55,"n":"第五十五条","txt":"欠税的纳税义务人，有合并、分立情形的，在合并、分立前，应当向海关报告，依法缴清税款。纳税义务人合并时未缴清税款的，由合并后的法人或者其他组织继续履行未履行的纳税义务；纳税义务人分立时未缴清税款的，分立后的法人或者其他组织对未履行的纳税义务承担连带责任。"},{"i":56,"n":"第五十六条","txt":"进境物品的关税以及进口环节海关代征税合并为进口税，由海关依法征收。"},{"i":57,"n":"第五十七条","txt":"海关总署规定数额以内的个人自用进境物品，免征进口税。"},{"i":58,"n":"第五十八条","txt":"进境物品的纳税义务人是指，携带物品进境的入境人员、进境邮递物品的收件人以及以其他方式进口物品的收件人。"},{"i":59,"n":"第五十九条","txt":"进境物品的纳税义务人可以自行办理纳税手续，也可以委托他人办理纳税手续。接受委托的人应当遵守本章对纳税义务人的各项规定。"},{"i":60,"n":"第六十条","txt":"进口税从价计征。"},{"i":61,"n":"第六十一条","txt":"海关应当按照《进境物品进口税税率表》及海关总署制定的《中华人民共和国进境物品归类表》、《中华人民共和国进境物品完税价格表》对进境物品进行归类、确定完税价格和确定适用税率。"},{"i":62,"n":"第六十二条","txt":"进境物品，适用海关填发税款缴款书之日实施的税率和完税价格。"},{"i":63,"n":"第六十三条","txt":"进口税的减征、免征、补征、追征、退还以及对暂准进境物品征收进口税参照本条例对货物征收进口关税的有关规定执行。"},{"i":64,"n":"第六十四条","txt":"纳税义务人、担保人对海关确定纳税义务人、确定完税价格、商品归类、确定原产地、适用税率或者汇率、减征或者免征税款、补税、退税、征收滞纳金、确定计征方式以及确定纳税地点有异议的，应当缴纳税款，并可以依法向上一级海关申请复议。对复议决定不服的，可以依法向人民法院提起诉讼。"},{"i":65,"n":"第六十五条","txt":"进口环节海关代征税的征收管理，适用关税征收管理的规定。"},{"i":66,"n":"第六十六条","txt":"有违反本条例规定行为的，按照《海关法》、《中华人民共和国海关行政处罚实施条例》和其他有关法律、行政法规的规定处罚。"},{"i":67,"n":"第六十七条","txt":"本条例自2004年1月1日起施行。1992年3月18日国务院修订发布的《中华人民共和国进出口关税条例》同时废止。"}],"jizhunqihouzhanguancehuanjingbaohuguiding":[{"i":1,"n":"第一条","txt":"为了保护基准气候站的观测环境，以利于观测和积累气候资料，准确反映我国气候资源状况，更好地为经济建设服务，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称基准气候站，是指获取标准气候资料的气候站，是全国气候站网中的骨干和基准点。"},{"i":3,"n":"第三条","txt":"对基准气候站观测环境的要求："},{"i":4,"n":"第四条","txt":"基准气候站站址应当长期保持稳定。确因国家重点工程建设或军事上特殊需要必须搬迁的，应经国家气象局审查同意，并按下列程序办理："},{"i":5,"n":"第五条","txt":"对违反本规定、破坏基准气候站观测环境的，由所在地人民政府规定期限，令其拆除违法建筑、排除妨碍或恢复原状，对拒不执行的，提请人民法院强制执行；对直接责任人员，应当视其情节轻重，由其所在单位或主管部门给予批评教育或行政处分。"},{"i":6,"n":"第六条","txt":"本规定由国家气象局负责解释。"},{"i":7,"n":"第七条","txt":"本规定自发布之日起施行。"}],"kaifajianshejinshanmengjierangdiqushuitubaochiguid5f11ef":[{"i":1,"n":"第一条","txt":"为加强山西、陕西、内蒙古（以下简称晋陕蒙）接壤地区开发建设中的水土保持工作，促进该地区经济建设的发展，保护生态环境，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称晋陕蒙接壤地区，指山西省河曲县、保德县、偏关县，陕西省神木县、府谷县、榆林县，内蒙古自治区准格尔旗、伊金霍洛旗、达拉特旗和东胜市。"},{"i":3,"n":"第三条","txt":"资源开发和生产建设必须兼顾国土整治和水土保持，执行“防治并重，治管结合，因地制宜，全面规划，综合治理，除害兴利”的水土保持工作方针。"},{"i":4,"n":"第四条","txt":"防治水土流失，实行“谁开发谁保护”、“谁造成水土流失谁治理”的原则。"},{"i":5,"n":"第五条","txt":"加强晋陕蒙接壤地区的国土规划和水土保持规划工作。国土规划，应当将防治水土流失作为重要内容。水土保持规划，应当以市、县、旗和流域为单位编制，具体规定规划区内水土流失的综合治理措施，确定各个阶段的防治目标和实施步骤，并对各工矿企业（含交通、建设企业，下同）提出防治水土流失的要求。"},{"i":6,"n":"第六条","txt":"工矿企业进行基本建设，必须重视水土保持，防治水土流失。建设项目涉及水土保持的，其可行性研究报告、设计任务书、初步设计等文件，应当有水土保持的内容和要求，并附有当地水土保持部门的书面意见。评审上述文件时，应当有水土保持部门参加。凡可行性研究报告中没有水土流失预测、评价的，或者设计任务书、初步设计等文件中没有具体水土流失防治措施的，有关审批部门不得批准。"},{"i":7,"n":"第七条","txt":"工矿企业生产建设总体规划和设计文件确定的各项水土保持工程和措施，必须纳入工矿企业的生产建设计划，并保证实施。因情况发生变化，水土保持的工程和设施确需改变时，必须事先征得水土保持部门的同意。"},{"i":8,"n":"第八条","txt":"工矿企业在生产建设活动中，应当按照水土保持技术规范的要求，因地制宜，因害设防，采取有效的工程措施和生物措施，防治水土流失。"},{"i":9,"n":"第九条","txt":"为防治水土流失兴建各类工程，由开发建设的单位和个人按照“谁开发谁保护”、“谁造成水土流失谁治理”的原则承担防治费用。有条件的，有关各方可以集资联合兴建，并由联合的各方按照协议合理分担费用。上述工程建成后，投资者享有经营管理权和收益权。"},{"i":10,"n":"第十条","txt":"基本建设过程中造成的水土流失，其防治费用由建设单位从基本建设投资中列支。生产过程中造成的水土流失，其防治费用由企业从更新改造资金或者生产发展基金中列支。"},{"i":11,"n":"第十一条","txt":"各类小型矿山企业和个体户采矿应当提高技术水平，提高矿产资源回收率。禁止乱挖滥采、破坏矿产资源和水土保持。有关机关颁发采矿许可证，应当征求当地水土保持部门的意见。"},{"i":12,"n":"第十二条","txt":"水土保持部门应当加强对工矿企业水土保持工作的监督检查和技术服务工作。水土保持工作人员可持专门证件进入工矿企业和各采矿点进行现场检查，被检查单位必须如实报告情况，提供必要的工作条件。"},{"i":13,"n":"第十三条","txt":"晋陕蒙三省（区）根据实际需要可以成立水土保持协调机构。协调机构由三省（区）人民政府委派有关部门负责人员组成，定期召开会议，研究、协调晋陕蒙接壤地区水土保持工作中的重大问题。"},{"i":14,"n":"第十四条","txt":"违反本规定，有下列行为之一的，县级以上地方人民政府的水土保持部门除责令其限期纠正、采取补救措施外，可以并处警告、罚款；对有关责任人员，可以由其所在单位或者上级主管机关给予行政处分："},{"i":15,"n":"第十五条","txt":"罚款的幅度，由晋陕蒙接壤地区水土保持协调机构拟订，报三省（区）人民政府批准。"},{"i":16,"n":"第十六条","txt":"对违反本规定，造成严重的水土流失后果，并在水土保持部门给予本规定第十四条所列的行政处罚后仍拒绝承担治理义务的，由水土保持部门报请该工矿企业主管部门所在的人民政府批准，责令其停业治理。"},{"i":17,"n":"第十七条","txt":"有下列行为之一，尚不够刑事处罚，应当给予治安管理处罚的，依照《治安管理处罚法》有关规定处罚；构成犯罪的，依照《刑法》有关规定追究刑事责任："},{"i":18,"n":"第十八条","txt":"当事人对行政处罚决定不服的，可以在接到处罚通知之日起15日内，向作出处罚决定的机关的上一级机关申请复议；对复议决定不服的，可以在接到复议决定之日起15日内向人民法院起诉。当事人在规定的期限内不申请复议或者不向人民法院起诉又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。对治安管理处罚不服的，按照《治安管理处罚法》的规定办理。"},{"i":19,"n":"第十九条","txt":"违反本规定，造成严重水土流失后果的单位和个人，有责任对直接遭受损失者赔偿损失。"},{"i":20,"n":"第二十条","txt":"本规定自发布之日起施行。"}],"kuangchanziyuanbuchangfeizhengshouguanliguiding":[{"i":1,"n":"第一条","txt":"为了保障和促进矿产资源的勘查、保护与合理开发，维护国家对矿产资源的财产权益，根据《中华人民共和国矿产资源法》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和其他管辖海域开采矿产资源，应当依照本规定缴纳矿产资源补偿费；法律、行政法规另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"矿产资源补偿费按照矿产品销售收入的一定比例计征。企业缴纳的矿产资源补偿费列入管理费用。"},{"i":4,"n":"第四条","txt":"矿产资源补偿费由采矿权人缴纳。"},{"i":5,"n":"第五条","txt":"矿产资源补偿费按照下列方式计算："},{"i":6,"n":"第六条","txt":"矿产资源补偿费依照本规定附录所规定的费率征收。"},{"i":7,"n":"第七条","txt":"矿产资源补偿费由地质矿产主管部门会同财政部门征收。"},{"i":8,"n":"第八条","txt":"采矿权人应当于每年的7月31日前缴纳上半年的矿产资源补偿费；于下一年度1月31日前缴纳上一年度下半年的矿产资源补偿费。"},{"i":9,"n":"第九条","txt":"采矿权人在缴纳矿产资源补偿费时，应当同时提交已采出的矿产品的矿种、产量、销售数量、销售价格和实际开采回采率等资料。"},{"i":10,"n":"第十条","txt":"征收的矿产资源补偿费，应当及时全额上缴，并按照下款规定的中央与省、自治区、直辖市的分成比例分别入库，年终不再结算。"},{"i":11,"n":"第十一条","txt":"矿产资源补偿费纳入国家预算，实行专项管理，主要用于矿产资源勘查。"},{"i":12,"n":"第十二条","txt":"采矿权人有下列情形之一的，经省级人民政府地质矿产主管部门会同同级财政部门批准，可以免缴矿产资源补偿费："},{"i":13,"n":"第十三条","txt":"采矿权人有下列情况之一的，经省级人民政府地质矿产主管部门会同同级财政部门批准，可以减缴矿产资源补偿费："},{"i":14,"n":"第十四条","txt":"采矿权人在规定期限内未足额缴纳矿产资源补偿费的，由征收机关责令限期缴纳，并从滞纳之日起按日加收滞纳补偿费2‰的滞纳金。"},{"i":15,"n":"第十五条","txt":"采矿权人采取伪报矿种，隐匿产量、销售数量，或者伪报销售价格、实际开采回采率等手段，不缴或者少缴矿产资源补偿费的，由征收机关追缴应当缴纳的矿产资源补偿费，并处以应当缴纳的矿产资源补偿费5倍以下的罚款；情节严重的，由采矿许可证颁发机关吊销其采矿许可证。"},{"i":16,"n":"第十六条","txt":"采矿权人未按照本规定第九条的规定报送有关资料的，由征收机关责令限期报送；逾期不报送的，处以5,000元以下罚款；仍不报送的，采矿许可证颁发机关可以吊销其采矿许可证。"},{"i":17,"n":"第十七条","txt":"依照本规定对采矿权人处以的罚款、加收的滞纳金应当上缴国库。"},{"i":18,"n":"第十八条","txt":"当事人对行政处罚决定不服的，可以自接到处罚决定通知之日起15日内向作出处罚决定的机关的上一级机关申请复议；当事人也可以自接到处罚决定通知之日起15日内直接向人民法院起诉。"},{"i":19,"n":"第十九条","txt":"本规定发布前的地方性法规和地方人民政府发布的规章及行政性文件的内容，与本规定相抵触的，以本规定为准。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市人民政府可以根据本规定制定实施办法。"},{"i":21,"n":"第二十一条","txt":"本规定由地质矿产部负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自1994年4月1日起施行。"}],"kuangchanziyuanfashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国矿产资源法》，制定本细则。"},{"i":2,"n":"第二条","txt":"矿产资源是指由地质作用形成的，具有利用价值的，呈固态、液态、气态的自然资源。"},{"i":3,"n":"第三条","txt":"矿产资源属于国家所有，地表或者地下的矿产资源的国家所有权，不因其所依附的土地的所有权或者使用权的不同而改变。"},{"i":4,"n":"第四条","txt":"在中华人民共和国领域及管辖的其他海域勘查、开采矿产资源，必须遵守《中华人民共和国矿产资源法》（以下简称《矿产资源法》）和本细则。"},{"i":5,"n":"第五条","txt":"国家对矿产资源的勘查、开采实行许可证制度。勘查矿产资源，必须依法申请登记，领取勘查许可证，取得探矿权；开采矿产资源，必须依法申请登记，领取采矿许可证，取得采矿权。"},{"i":6,"n":"第六条","txt":"《矿产资源法》及本细则中下列用语的含义："},{"i":7,"n":"第七条","txt":"国家允许外国的公司、企业和其他经济组织以及个人依照中华人民共和国有关法律、行政法规的规定，在中华人民共和国领域及管辖的其他海域投资勘查、开采矿产资源。"},{"i":8,"n":"第八条","txt":"国务院地质矿产主管部门主管全国矿产资源勘查、开采的监督管理工作。国务院有关主管部门按照国务院规定的职责分工，协助国务院地质矿产主管部门进行矿产资源勘查、开采的监督管理工作。"},{"i":9,"n":"第九条","txt":"勘查矿产资源，应当按照国务院关于矿产资源勘查登记管理的规定，办理申请、审批和勘查登记。"},{"i":10,"n":"第十条","txt":"国有矿山企业开采矿产资源，应当按照国务院关于采矿登记管理的规定，办理申请、审批和采矿登记。开采国家规划矿区、对国民经济具有重要价值矿区的矿产和国家规定实行保护性开采的特定矿种，办理申请、审批和采矿登记时，应当持有国务院有关主管部门批准的文件。"},{"i":11,"n":"第十一条","txt":"开办国有矿山企业，除应当具备有关法律、法规规定的条件外，并应当具备下列条件："},{"i":12,"n":"第十二条","txt":"申请开办集体所有制矿山企业、私营矿山企业及个体采矿的审查批准、采矿登记，按照省、自治区、直辖市的有关规定办理。"},{"i":13,"n":"第十三条","txt":"申请开办集体所有制矿山企业或者私营矿山企业，除应当具备有关法律、法规规定的条件外，并应当具备下列条件："},{"i":14,"n":"第十四条","txt":"申请个体采矿应当具备下列条件："},{"i":15,"n":"第十五条","txt":"国家对矿产资源勘查实行统一规划。全国矿产资源中、长期勘查规划，在国务院计划行政主管部门指导下，由国务院地质矿产主管部门根据国民经济和社会发展中、长期规划，在国务院有关主管部门勘查规划的基础上组织编制。"},{"i":16,"n":"第十六条","txt":"探矿权人享有下列权利："},{"i":17,"n":"第十七条","txt":"探矿权人应当履行下列义务："},{"i":18,"n":"第十八条","txt":"探矿权人可以对符合国家边探边采规定要求的复杂类型矿床进行开采；但是，应当向原颁发勘查许可证的机关、矿产储量审批机构和勘查项目主管部门提交论证材料，经审核同意后，按照国务院关于采矿登记管理法规的规定，办理采矿登记。"},{"i":19,"n":"第十九条","txt":"矿产资源勘查报告按照下列规定审批："},{"i":20,"n":"第二十条","txt":"矿产资源勘查报告及其他有价值的勘查资料，按照国务院有关规定实行有偿使用。"},{"i":21,"n":"第二十一条","txt":"探矿权人取得临时使用土地权后，在勘查过程中给他人造成财产损害的，按照下列规定给以补偿："},{"i":22,"n":"第二十二条","txt":"探矿权人在没有农作物和其他附着物的荒岭、荒坡、荒地、荒漠、沙滩、河滩、湖滩、海滩上进行勘查的，不予补偿；但是，勘查作业不得阻碍或者损害航运、灌溉、防洪等活动或者设施，勘查作业结束后应当采取措施，防止水土流失，保护生态环境。"},{"i":23,"n":"第二十三条","txt":"探矿权人之间对勘查范围发生争议时，由当事人协商解决；协商不成的，由勘查作业区所在地的省、自治区、直辖市人民政府地质矿产主管部门裁决；跨省、自治区、直辖市的勘查范围争议，当事人协商不成的，由有关省、自治区、直辖市人民政府协商解决；协商不成的，由国务院地质矿产主管部门裁决。特定矿种的勘查范围争议，当事人协商不成的，由国务院授权的有关主管部门裁决。"},{"i":24,"n":"第二十四条","txt":"全国矿产资源的分配和开发利用，应当兼顾当前和长远、中央和地方的利益，实行统一规划、有效保护、合理开采、综合利用。"},{"i":25,"n":"第二十五条","txt":"全国矿产资源规划，在国务院计划行政主管部门指导下，由国务院地质矿产主管部门根据国民经济和社会发展中、长期规划，组织国务院有关主管部门和省、自治区、直辖市人民政府编制，报国务院批准后施行。"},{"i":26,"n":"第二十六条","txt":"矿产资源开发规划是对矿区的开发建设布局进行统筹安排的规划。"},{"i":27,"n":"第二十七条","txt":"设立、变更或者撤销国家规划矿区、对国民经济具有重要价值的矿区，由国务院有关主管部门提出，并附具矿产资源详查报告及论证材料，经国务院计划行政主管部门和地质矿产主管部门审定，并联合书面通知有关县级人民政府。县级人民政府应当自收到通知之日起一个月内予以公告，并报国务院计划行政主管部门、地质矿产主管部门备案。"},{"i":28,"n":"第二十八条","txt":"确定或者撤销国家规定实行保护性开采的特定矿种，由国务院有关主管部门提出，并附具论证材料，经国务院计划行政主管部门和地质矿产主管部门审核同意后，报国务院批准。"},{"i":29,"n":"第二十九条","txt":"单位或者个人开采矿产资源前，应当委托持有相应矿山设计证书的单位进行可行性研究和设计。开采零星分散矿产资源和用作建筑材料的砂、石、粘土的，可以不进行可行性研究和设计，但是应当有开采方案和环境保护措施。"},{"i":30,"n":"第三十条","txt":"采矿权人享有下列权利："},{"i":31,"n":"第三十一条","txt":"采矿权人应当履行下列义务："},{"i":32,"n":"第三十二条","txt":"采矿权人在采矿许可证有效期满或者在有效期内，停办矿山而矿产资源尚未采完的，必须采取措施将资源保持在能够继续开采的状态，并事先完成下列工作："},{"i":33,"n":"第三十三条","txt":"矿山企业关闭矿山，应当按照下列程序办理审批手续："},{"i":34,"n":"第三十四条","txt":"关闭矿山报告批准后，矿山企业应当完成下列工作："},{"i":35,"n":"第三十五条","txt":"建设单位在建设铁路、公路、工厂、水库、输油管道、输电线路和各种大型建筑物前，必须向所在地的省、自治区、直辖市人民政府地质矿产主管部门了解拟建工程所在地区的矿产资源分布情况，并在建设项目设计任务书报请审批时附具地质矿产主管部门的证明。在上述建设项目与重要矿床的开采发生矛盾时，由国务院有关主管部门或者省、自治区、直辖市人民政府提出方案，经国务院地质矿产主管部门提出意见后，报国务院计划行政主管部门决定。"},{"i":36,"n":"第三十六条","txt":"采矿权人之间对矿区范围发生争议时，由当事人协商解决；协商不成的，由矿产资源所在地的县级以上地方人民政府根据依法核定的矿区范围处理；跨省、自治区、直辖市的矿区范围争议，当事人协商不成的，由有关省、自治区、直辖市人民政府协商解决；协商不成的，由国务院地质矿产主管部门提出处理意见，报国务院决定。"},{"i":37,"n":"第三十七条","txt":"国家依法保护集体所有制矿山企业、私营矿山企业和个体采矿者的合法权益，依法对集体所有制矿山企业、私营矿山企业和个体采矿者进行监督管理。"},{"i":38,"n":"第三十八条","txt":"集体所有制矿山企业可以开采下列矿产资源："},{"i":39,"n":"第三十九条","txt":"私营矿山企业开采矿产资源的范围参照本细则第三十八条的规定执行。"},{"i":40,"n":"第四十条","txt":"个体采矿者可以采挖下列矿产资源："},{"i":41,"n":"第四十一条","txt":"国家设立国家规划矿区、对国民经济具有重要价值的矿区时，对应当撤出的原采矿权人，国家按照有关规定给予合理补偿。"},{"i":42,"n":"第四十二条","txt":"依照《矿产资源法》第三十九条、第四十条、第四十二条、第四十三条、第四十四条规定处以罚款的，分别按照下列规定执行："},{"i":43,"n":"第四十三条","txt":"违反本细则规定，有下列行为之一的，对主管人员和直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":44,"n":"第四十四条","txt":"地下水资源具有水资源和矿产资源的双重属性。地下水资源的勘查，适用《矿产资源法》和本细则；地下水资源的开发、利用、保护和管理，适用《水法》和有关的行政法规。"},{"i":45,"n":"第四十五条","txt":"本细则由地质矿产部负责解释。"},{"i":46,"n":"第四十六条","txt":"本细则自发布之日起施行。"}],"kuangchanziyuanjianduguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强对矿山企业的矿产资源开发利用和保护工作的监督管理，根据《中华人民共和国矿产资源法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国领域及管辖海域内从事采矿生产的矿山企业（包括有矿山的单位，下同），但本办法另有规定的除外。"},{"i":3,"n":"第三条","txt":"国务院地质矿产主管部门对执行本办法负有下列职责："},{"i":4,"n":"第四条","txt":"省、自治区、直辖市人民政府地质矿产主管部门对执行本办法负有下列职责："},{"i":5,"n":"第五条","txt":"国务院和各省、自治区、直辖市人民政府的有关主管部门对贯彻执行本办法负有下列职责："},{"i":6,"n":"第六条","txt":"矿山企业的地质测量机构是本企业矿产资源开发利用与保护工作的监督管理机构，对执行本办法负有以下职责："},{"i":7,"n":"第七条","txt":"矿山企业开发利用矿产资源，应当加强开采管理，选择合理的采矿方法和选矿方法，推广先进工艺技术，提高矿产资源利用水平。"},{"i":8,"n":"第八条","txt":"矿山企业在基建施工至矿山关闭的生产全过程中，都应当加强矿产资源的保护工作。"},{"i":9,"n":"第九条","txt":"矿山企业应当按照国家有关法规及其主管部门的有关规章、规定，建立、健全本企业开发利用和保护矿产资源的各项制度，并切实加以贯彻落实。"},{"i":10,"n":"第十条","txt":"矿山开采设计要求的回采率、采矿贫化率和选矿回收率，应当列为考核矿山企业的重要年度计划指标。"},{"i":11,"n":"第十一条","txt":"矿山企业应当加强生产勘探，提高矿床勘探程度，为开采设计提供可靠依据；对具有工业价值的共生、伴生矿产应当系统查定和评价。"},{"i":12,"n":"第十二条","txt":"矿山企业的开采设计应当在可靠地质资料基础上进行。中段（或阶段）开采应当有总体设计，块段开采应当有采矿设计。"},{"i":13,"n":"第十三条","txt":"矿山的开拓、采准及采矿工程，必须按照开采设计进行施工。应当建立严格的施工验收制度，防止资源丢失。"},{"i":14,"n":"第十四条","txt":"矿山企业必须按照设计进行开采，不准任意丢掉矿体。对开采应当加强监督检查，严防不应有的开采损失。"},{"i":15,"n":"第十五条","txt":"矿山企业在开采中必须加强对矿石损失、贫化的管理，建立定期检查制度，分析造成非正常损失、贫化的原因，制定措施，提高资源的回采率，降低贫化率。"},{"i":16,"n":"第十六条","txt":"选矿（煤）厂应当根据设计要求定期进行选矿流程考察；对选矿回收率和精矿（洗精煤）质量没有达到设计指标的，应当查明原因，提出改进措施。"},{"i":17,"n":"第十七条","txt":"在采、选主要矿产的同时，对具有工业价值的共生、伴生矿产，在技术可行、经济合理的条件下，必须综合回收；对暂时不能综合回收利用的矿产，应当采取有效的保护措施。"},{"i":18,"n":"第十八条","txt":"矿山企业应当加强对滞销矿石、粉矿、中矿、尾矿、废石和煤矸石的管理，积极研究其利用途径；暂时不能利用的，应当在节约土地的原则下，妥善堆放保存，防止其流失及污染环境。"},{"i":19,"n":"第十九条","txt":"矿山企业对矿产储量的圈定、计算及开采，必须以批准的计算矿产储量的工业指标为依据，不得随意变动。需要变动的，应当上报实际资料，经主管部门审核同意后，报原审批单位批准。"},{"i":20,"n":"第二十条","txt":"报销矿产储量，应当经矿山企业地质测量机构检查鉴定后，向矿山企业的主管部门提出申请。"},{"i":21,"n":"第二十一条","txt":"地下开采的中段（水平）或露天采矿场内尚有未采完的保有矿产储量，未经地质测量机构检查验收和报销申请尚未批准之前，不准擅自废除坑道和其他工程。"},{"i":22,"n":"第二十二条","txt":"矿山企业应当向其上级主管部门和地质矿产主管部门上报矿产资源开发利用情况报表。"},{"i":23,"n":"第二十三条","txt":"矿山企业有下列情形之一的，应当追究有关人员的责任，或者由地质矿产主管部门责令其限期改正，并可处以相当于矿石损失50%以下的罚款，情节严重的，应当责令停产整顿或者吊销采矿许可证："},{"i":24,"n":"第二十四条","txt":"当事人对行政处罚决定不服的，可以在收到处罚通知之日起15日内，向人民法院起诉。对罚款的行政处罚决定期满不起诉又不履行的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":25,"n":"第二十五条","txt":"矿山企业上报的矿产资源开发利用资料数据必须准确可靠。虚报瞒报的，依照《中华人民共和国统计法》的有关规定追究责任。对保密资料，应当按照国家有关保密规定执行。"},{"i":26,"n":"第二十六条","txt":"对乡镇集体矿山企业和个体采矿的矿产资源开发利用与保护工作的监督管理办法，由省、自治区、直辖市人民政府参照本办法制定。"},{"i":27,"n":"第二十七条","txt":"本办法由国务院地质矿产主管部门负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自发布之日起施行。"}],"kuangchanziyuankaicaidengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对矿产资源开采的管理，保护采矿权人的合法权益，维护矿产资源开采秩序，促进矿业发展，根据《中华人民共和国矿产资源法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域开采矿产资源，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"开采下列矿产资源，由国务院地质矿产主管部门审批登记，颁发采矿许可证："},{"i":4,"n":"第四条","txt":"采矿权申请人在提出采矿权申请前，应当根据经批准的地质勘查储量报告，向登记管理机关申请划定矿区范围。"},{"i":5,"n":"第五条","txt":"采矿权申请人申请办理采矿许可证时，应当向登记管理机关提交下列资料："},{"i":6,"n":"第六条","txt":"登记管理机关应当自收到申请之日起40日内，作出准予登记或者不予登记的决定，并通知采矿权申请人。"},{"i":7,"n":"第七条","txt":"采矿许可证有效期，按照矿山建设规模确定：大型以上的，采矿许可证有效期最长为30年；中型的，采矿许可证有效期最长为20年；小型的，采矿许可证有效期最长为10年。采矿许可证有效期满，需要继续采矿的，采矿权人应当在采矿许可证有效期届满的30日前，到登记管理机关办理延续登记手续。"},{"i":8,"n":"第八条","txt":"登记管理机关在颁发采矿许可证后，应当通知矿区范围所在地的有关县级人民政府。有关县级人民政府应当自收到通知之日起90日内，对矿区范围予以公告，并可以根据采矿权人的申请，组织埋设界桩或者设置地面标志。"},{"i":9,"n":"第九条","txt":"国家实行采矿权有偿取得的制度。采矿权使用费，按照矿区范围的面积逐年缴纳，标准为每平方公里每年1000元。"},{"i":10,"n":"第十条","txt":"申请国家出资勘查并已经探明矿产地的采矿权的，采矿权申请人除依照本办法第九条的规定缴纳采矿权使用费外，还应当缴纳国家出资勘查形成的采矿权价款；采矿权价款按照国家有关规定，可以一次缴纳，也可以分期缴纳。"},{"i":11,"n":"第十一条","txt":"采矿权使用费和国家出资勘查形成的采矿权价款由登记管理机关收取，全部纳入国家预算管理。具体管理、使用办法，由国务院地质矿产主管部门会同国务院财政部门、计划主管部门制定。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，由采矿权人提出申请，经省级以上人民政府登记管理机关按照国务院地质矿产主管部门会同国务院财政部门制定的采矿权使用费和采矿权价款的减免办法审查批准，可以减缴、免缴采矿权使用费和采矿权价款："},{"i":13,"n":"第十三条","txt":"采矿权可以通过招标投标的方式有偿取得。"},{"i":14,"n":"第十四条","txt":"登记管理机关应当对本行政区域内的采矿权人合理开发利用矿产资源、保护环境及其他应当履行的法定义务等情况依法进行监督检查。采矿权人应当如实报告有关情况，并提交年度报告。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，采矿权人应当在采矿许可证有效期内，向登记管理机关申请变更登记："},{"i":16,"n":"第十六条","txt":"采矿权人在采矿许可证有效期内或者有效期届满，停办、关闭矿山的，应当自决定停办或者关闭矿山之日起30日内，向原发证机关申请办理采矿许可证注销登记手续。"},{"i":17,"n":"第十七条","txt":"任何单位和个人未领取采矿许可证擅自采矿的，擅自进入国家规划矿区和对国民经济具有重要价值的矿区范围采矿的，擅自开采国家规定实行保护性开采的特定矿种的，超越批准的矿区范围采矿的，由登记管理机关依照有关法律、行政法规的规定予以处罚。"},{"i":18,"n":"第十八条","txt":"不依照本办法规定提交年度报告、拒绝接受监督检查或者弄虚作假的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令停止违法行为，予以警告，可以并处5万元以下的罚款；情节严重的，由原发证机关吊销采矿许可证。"},{"i":19,"n":"第十九条","txt":"破坏或者擅自移动矿区范围界桩或者地面标志的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令限期恢复；情节严重的，处3万元以下的罚款。"},{"i":20,"n":"第二十条","txt":"擅自印制或者伪造、冒用采矿许可证的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，没收违法所得，可以并处10万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，不按期缴纳本办法规定应当缴纳的费用的，由登记管理机关责令限期缴纳，并从滞纳之日起每日加收2‰的滞纳金；逾期仍不缴纳的，由原发证机关吊销采矿许可证。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定，不办理采矿许可证变更登记或者注销登记手续的，由登记管理机关责令限期改正；逾期不改正的，由原发证机关吊销采矿许可证。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定开采石油、天然气矿产的，由国务院地质矿产主管部门按照本办法的有关规定给予行政处罚。"},{"i":24,"n":"第二十四条","txt":"采矿权人被吊销采矿许可证的，自采矿许可证被吊销之日起2年内不得再申请采矿权。"},{"i":25,"n":"第二十五条","txt":"登记管理机关工作人员徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":26,"n":"第二十六条","txt":"采矿许可证由国务院地质矿产主管部门统一印制。申请登记书、变更申请登记书和注销申请登记书的格式，由国务院地质矿产主管部门统一制定。"},{"i":27,"n":"第二十七条","txt":"办理采矿登记手续，应当按照规定缴纳登记费。收费标准和管理、使用办法，由国务院物价主管部门会同国务院地质矿产主管部门、财政部门规定。"},{"i":28,"n":"第二十八条","txt":"外商投资开采矿产资源，依照本办法的规定办理；法律、行政法规另有特别规定的，从其规定。"},{"i":29,"n":"第二十九条","txt":"中外合作开采矿产资源的，中方合作者应当在签订合同后，将合同向原发证机关备案。"},{"i":30,"n":"第三十条","txt":"本办法施行前已经取得采矿许可证的，由国务院地质矿产主管部门统一组织换领新采矿许可证。"},{"i":31,"n":"第三十一条","txt":"登记管理机关应当对颁发的采矿许可证和吊销的采矿许可证予以公告。"},{"i":32,"n":"第三十二条","txt":"本办法所称矿区范围，是指经登记管理机关依法划定的可供开采矿产资源的范围、井巷工程设施分布范围或者露天剥离范围的立体空间区域。"},{"i":33,"n":"第三十三条","txt":"本办法附录的修改，由国务院地质矿产主管部门报国务院批准后公布。"},{"i":34,"n":"第三十四条","txt":"本办法自发布之日起施行。1987年4月29日国务院发布的《全民所有制矿山企业采矿登记管理暂行办法》和1990年11月22日《国务院关于修改〈全民所有制矿山企业采矿登记管理暂行办法〉的决定》同时废止。"}],"kuangchanziyuankanchaqukuaidengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对矿产资源勘查的管理，保护探矿权人的合法权益，维护矿产资源勘查秩序，促进矿业发展，根据《中华人民共和国矿产资源法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域勘查矿产资源，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"国家对矿产资源勘查实行统一的区块登记管理制度。矿产资源勘查工作区范围以经纬度1′×1′划分的区块为基本单位区块。每个勘查项目允许登记的最大范围："},{"i":4,"n":"第四条","txt":"勘查下列矿产资源，由国务院地质矿产主管部门审批登记，颁发勘查许可证："},{"i":5,"n":"第五条","txt":"勘查出资人为探矿权申请人；但是，国家出资勘查的，国家委托勘查的单位为探矿权申请人。"},{"i":6,"n":"第六条","txt":"探矿权申请人申请探矿权时，应当向登记管理机关提交下列资料："},{"i":7,"n":"第七条","txt":"申请石油、天然气滚动勘探开发的，应当向登记管理机关提交下列资料，经批准，办理登记手续，领取滚动勘探开发的采矿许可证："},{"i":8,"n":"第八条","txt":"登记管理机关应当自收到申请之日起40日内，按照申请在先的原则作出准予登记或者不予登记的决定，并通知探矿权申请人。对申请勘查石油、天然气的，登记管理机关还应当在收到申请后及时予以公告或者提供查询。"},{"i":9,"n":"第九条","txt":"禁止任何单位和个人进入他人依法取得探矿权的勘查作业区内进行勘查或者采矿活动。"},{"i":10,"n":"第十条","txt":"勘查许可证有效期最长为3年；但是，石油、天然气勘查许可证有效期最长为7年。需要延长勘查工作时间的，探矿权人应当在勘查许可证有效期届满的30日前，到登记管理机关办理延续登记手续，每次延续时间不得超过2年。"},{"i":11,"n":"第十一条","txt":"登记管理机关应当自颁发勘查许可证之日起10日内，将登记发证项目的名称、探矿权人、区块范围和勘查许可证期限等事项，通知勘查项目所在地的县级人民政府负责地质矿产管理工作的部门。"},{"i":12,"n":"第十二条","txt":"国家实行探矿权有偿取得的制度。探矿权使用费以勘查年度计算，逐年缴纳。"},{"i":13,"n":"第十三条","txt":"申请国家出资勘查并已经探明矿产地的区块的探矿权的，探矿权申请人除依照本办法第十二条的规定缴纳探矿权使用费外，还应当缴纳国家出资勘查形成的探矿权价款；探矿权价款按照国家有关规定，可以一次缴纳，也可以分期缴纳。"},{"i":14,"n":"第十四条","txt":"探矿权使用费和国家出资勘查形成的探矿权价款，由登记管理机关收取，全部纳入国家预算管理。具体管理、使用办法，由国务院地质矿产主管部门会同国务院财政部门、计划主管部门制定。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，由探矿权人提出申请，经登记管理机关按照国务院地质矿产主管部门会同国务院财政部门制定的探矿权使用费和探矿权价款的减免办法审查批准，可以减缴、免缴探矿权使用费和探矿权价款："},{"i":16,"n":"第十六条","txt":"探矿权可以通过招标投标的方式有偿取得。"},{"i":17,"n":"第十七条","txt":"探矿权人应当自领取勘查许可证之日起，按照下列规定完成最低勘查投入："},{"i":18,"n":"第十八条","txt":"探矿权人应当自领取勘查许可证之日起6个月内开始施工；在开始勘查工作时，应当向勘查项目所在地的县级人民政府负责地质矿产管理工作的部门报告，并向登记管理机关报告开工情况。"},{"i":19,"n":"第十九条","txt":"探矿权人在勘查许可证有效期内进行勘查时，发现符合国家边探边采规定要求的复杂类型矿床的，可以申请开采，经登记管理机关批准，办理采矿登记手续。"},{"i":20,"n":"第二十条","txt":"探矿权人在勘查石油、天然气等流体矿产期间，需要试采的，应当向登记管理机关提交试采申请，经批准后可以试采1年；需要延长试采时间的，必须办理登记手续。"},{"i":21,"n":"第二十一条","txt":"探矿权人在勘查许可证有效期内探明可供开采的矿体后，经登记管理机关批准，可以停止相应区块的最低勘查投入，并可以在勘查许可证有效期届满的30日前，申请保留探矿权。但是，国家为了公共利益或者因技术条件暂时难以利用等情况，需要延期开采的除外。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，探矿权人应当在勘查许可证有效期内，向登记管理机关申请变更登记："},{"i":23,"n":"第二十三条","txt":"探矿权延续登记和变更登记，其勘查年度、探矿权使用费和最低勘查投入连续计算。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，探矿权人应当在勘查许可证有效期内，向登记管理机关递交勘查项目完成报告或者勘查项目终止报告，报送资金投入情况报表和有关证明文件，由登记管理机关核定其实际勘查投入后，办理勘查许可证注销登记手续："},{"i":25,"n":"第二十五条","txt":"登记管理机关需要调查勘查投入、勘查工作进展情况，探矿权人应当如实报告并提供有关资料，不得虚报、瞒报，不得拒绝检查。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，未取得勘查许可证擅自进行勘查工作的，超越批准的勘查区块范围进行勘查工作的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令停止违法行为，予以警告，可以并处10万元以下的罚款。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，未经批准，擅自进行滚动勘探开发、边探边采或者试采的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令停止违法行为，予以警告，没收违法所得，可以并处10万元以下的罚款。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，擅自印制或者伪造、冒用勘查许可证的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，没收违法所得，可以并处10万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，有下列行为之一的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令限期改正；逾期不改正的，处5万元以下的罚款；情节严重的，原发证机关可以吊销勘查许可证："},{"i":30,"n":"第三十条","txt":"违反本办法规定，不办理勘查许可证变更登记或者注销登记手续的，由登记管理机关责令限期改正；逾期不改正的，由原发证机关吊销勘查许可证。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，不按期缴纳本办法规定应当缴纳的费用的，由登记管理机关责令限期缴纳，并从滞纳之日起每日加收2‰的滞纳金；逾期仍不缴纳的，由原发证机关吊销勘查许可证。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定勘查石油、天然气矿产的，由国务院地质矿产主管部门按照本办法的有关规定给予行政处罚。"},{"i":33,"n":"第三十三条","txt":"探矿权人被吊销勘查许可证的，自勘查许可证被吊销之日起6个月内，不得再申请探矿权。"},{"i":34,"n":"第三十四条","txt":"登记管理机关工作人员徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":35,"n":"第三十五条","txt":"勘查许可证由国务院地质矿产主管部门统一印制。申请登记书、变更申请登记书、探矿权保留申请登记书和注销申请登记书的格式，由国务院地质矿产主管部门统一制定。"},{"i":36,"n":"第三十六条","txt":"办理勘查登记手续，应当按照规定缴纳登记费。收费标准和管理、使用办法，由国务院物价主管部门会同国务院地质矿产主管部门、财政部门规定。"},{"i":37,"n":"第三十七条","txt":"外商投资勘查矿产资源的，依照本办法的规定办理；法律、行政法规另有特别规定的，从其规定。"},{"i":38,"n":"第三十八条","txt":"中外合作勘查矿产资源的，中方合作者应当在签订合同后，将合同向原发证机关备案。"},{"i":39,"n":"第三十九条","txt":"本办法施行前已经取得勘查许可证的，由国务院地质矿产主管部门统一组织换领新的勘查许可证。探矿权使用费、最低勘查投入按照重新登记后的第一个勘查年度计算，并可以依照本办法的规定申请减缴、免缴。"},{"i":40,"n":"第四十条","txt":"本办法附录的修改，由国务院地质矿产主管部门报国务院批准后公布。"},{"i":41,"n":"第四十一条","txt":"本办法自发布之日起施行。1987年4月29日国务院发布的《矿产资源勘查登记管理暂行办法》和1987年12月16日国务院批准、石油工业部发布的《石油及天然气勘查、开采登记管理暂行办法》同时废止。"}],"laodongbaoxiantiaoli":[{"i":1,"n":"第一条","txt":"为了保护工人职员的健康，减轻其生活中的困难，特依据目前经济条件，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例的实施，采取逐步推广办法，目前的实施范围暂定如下："},{"i":3,"n":"第三条","txt":"不实行本条例的企业及季节性的企业，其有关劳动保险事项，得由各该企业或其所属产业或行业的行政方面或资方与工会组织，根据本条例的原则及本企业、本产业或本行业的实际情况协商，订立集体合同规定之。"},{"i":4,"n":"第四条","txt":"凡在实行劳动保险的企业内工作的工人与职员（包括学徒），不分民族、年龄、性别和国籍，均适用本条例，但被剥夺政治权利者除外。"},{"i":5,"n":"第五条","txt":"凡在实行劳动保险的企业内工作的临时工、季节工与试用人员，其劳动保险待遇在本条例实施细则中另行规定之。"},{"i":6,"n":"第六条","txt":"本条例适用范围内的企业，因经济特殊困难不易维持，或尚未正式开工营业者，经企业行政方面或资方与工会基层委员会双方协商同意，并报请当地人民政府劳动行政机关批准后，可暂缓实行本条例。"},{"i":7,"n":"第七条","txt":"本条例所规定之劳动保险的各项费用，全部由实行劳动保险的企业行政方面或资方负担，其中一部分由企业行政方面或资方直接支付，另一部分由企业行政方面或资方缴纳劳动保险金，交工会组织办理。"},{"i":8,"n":"第八条","txt":"凡根据本条例实行劳动保险的企业，其行政方面或资方须按月缴纳相当于各该企业全部工人与职员工资总额的百分之三，作为劳动保险金。此项劳动保险金，不得在工人与职员工资内扣除，并不得向工人与职员另行征收。"},{"i":9,"n":"第九条","txt":"劳动保险金的征集与保管方法如下："},{"i":10,"n":"第十条","txt":"企业行政方面或资方逾期未缴或欠缴劳动保险金时，须每日增交滞纳金，其数额为未缴部分百分之一。如逾期二十日尚未缴纳，对于国营、地方国营、公私合营或合作社经营的企业，由工会基层委员会通知当地国家银行从其经费中扣缴；对于私营企业，由工会基层委员会报告当地人民政府劳动行政机关，对该企业资方追究责任。"},{"i":11,"n":"第十一条","txt":"劳动保险金的保管，由中华全国总工会委托中国人民银行代理之。"},{"i":12,"n":"第十二条","txt":"因工负伤、残废待遇的规定："},{"i":13,"n":"第十三条","txt":"疾病、非因工负伤、残废待遇的规定："},{"i":14,"n":"第十四条","txt":"工人与职员及其供养的直系亲属死亡时待遇的规定："},{"i":15,"n":"第十五条","txt":"养老待遇的规定："},{"i":16,"n":"第十六条","txt":"生育待遇的规定："},{"i":17,"n":"第十七条","txt":"集体劳动保险事业的规定："},{"i":18,"n":"第十八条","txt":"凡在实行劳动保险的企业内工作的工人与职员，未加入工会者，除因工负伤、残废、死亡待遇，生育待遇，因病或非因工负伤治疗待遇，供养直系亲属疾病治疗待遇，均得按本条例的规定享受外，其他各项，如疾病或非因工负伤医疗期间的工资与救济费，非因工残废救济费，供养直系亲属救济费，养老补助费，丧葬补助费，只能领取规定额的半数。"},{"i":19,"n":"第十九条","txt":"凡对本企业有特殊贡献的劳动模范及转入本企业工作的战斗英雄，经工会基层委员会提出，并经各省、市工会组织或产业工会全国委员会的批准，得享受下列较优异的劳动保险待遇："},{"i":20,"n":"第二十条","txt":"残废军人转入本企业工作者，疾病或非因工负伤停止工作医疗期间，不计本企业工龄长短，前六个月工资照发；六个月以后，仍按第十三条乙款规定办理。"},{"i":21,"n":"第二十一条","txt":"劳动保险金的支配办法如下："},{"i":22,"n":"第二十二条","txt":"劳动保险金，除用于劳动保险事业外，不得移作其他用途。"},{"i":23,"n":"第二十三条","txt":"各企业的会计部门，均须设立劳动保险基金的独立会计，负责办理劳动保险基金的收支事宜。劳动保险基金会计制度，由中央人民政府劳动部会同中华全国总工会制定之。"},{"i":24,"n":"第二十四条","txt":"劳动保险调剂金的收支事宜，由各级工会组织的财务部门根据中华全国总工会的规定办理之。"},{"i":25,"n":"第二十五条","txt":"各工会基层委员会，为执行劳动保险业务的基层单位，其主要工作为：督促劳动保险金的缴纳；决定劳动保险基金的支付；监督本条例所规定由企业行政方面或资方直接支付的各项费用的开支；推动该企业改进集体劳动保险事业及医疗卫生工作；执行一切有关劳动保险的实际业务；每月编造劳动保险基金月报表，每年编造预算、决算、业务计划书及业务报告书，报告省、市工会组织和产业工会全国委员会及当地人民政府劳动行政机关；并向工会全体会员大会或代表大会报告工作。"},{"i":26,"n":"第二十六条","txt":"各工会基层委员会的经费审查委员会，应按月审核劳动保险基金收支帐目及本条例所规定的由企业行政方面或资方直接支付的各项费用，并公布之。"},{"i":27,"n":"第二十七条","txt":"各省、市工会组织，各产业工会全国委员会或地区委员会对所属各工会基层委员会的劳动保险业务，负指导督促之责，审核劳动保险基金的收支月报表、预算、决算及劳动保险基金的收支有无错误，接受工人与职员有关劳动保险事件的申诉，每月编造劳动保险基金及调剂金的收支月报表，每年编造预算、决算、业务计划书及业务报告书，并依下列程序报告："},{"i":28,"n":"第二十八条","txt":"各大行政区工会组织对所属各省、市工会组织及其区域内产业工会组织的劳动保险工作，负指导督促之责，审核省、市工会组织劳动保险基金及调剂金的收支月报表、预算、决算、业务计划书及业务报告书，并每三个月编造劳动保险基金收支报告，每年编造预算、决算、业务计划书及业务报告书，报告所在地大行政区人民政府劳动部、中央人民政府劳动部及中华全国总工会。"},{"i":29,"n":"第二十九条","txt":"中华全国总工会为全国劳动保险事业的最高领导机关，统筹全国劳动保险事业的进行，督导所属各地方工会组织、各产业工会组织有关劳动保险事业的执行；审核并汇编劳动保险基金及总基金的收支报告表，每年编造劳动保险金的预算、决算、业务计划书及业务报告书，并送中央人民政府劳动部、财政部备查。"},{"i":30,"n":"第三十条","txt":"各级人民政府劳动行政机关应监督劳动保险金的缴纳，检查劳动保险业务的执行，并处理有关劳动保险事件的申诉。"},{"i":31,"n":"第三十一条","txt":"中央人民政府劳动部为全国劳动保险业务的最高监督机关，负责贯彻劳动保险条例的实施，检查全国劳动保险业务的执行，其检查制度另订之。"},{"i":32,"n":"第三十二条","txt":"本条例由中央人民政府政务院通过后公布施行，修改时同。"}],"liudongrenkoujihuashengyugongzuotiaoli":[{"i":1,"n":"第一条","txt":"为了加强流动人口计划生育工作，寓管理于服务之中，维护流动人口的合法权益，稳定低生育水平，根据《中华人民共和国人口与计划生育法》，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称流动人口，是指离开户籍所在地的县、市或者市辖区，以工作、生活为目的异地居住的成年育龄人员。但是，下列人员除外："},{"i":3,"n":"第三条","txt":"县级以上地方人民政府领导本行政区域内流动人口计划生育工作，将流动人口计划生育工作纳入本地经济社会发展规划，并提供必要的保障；建立健全流动人口计划生育工作协调机制，组织协调有关部门对流动人口计划生育工作实行综合管理；实行目标管理责任制，对有关部门承担的流动人口计划生育工作进行考核、监督。"},{"i":4,"n":"第四条","txt":"流动人口计划生育工作由流动人口户籍所在地和现居住地的人民政府共同负责，以现居住地人民政府为主，户籍所在地人民政府予以配合。"},{"i":5,"n":"第五条","txt":"国务院人口和计划生育部门主管全国流动人口计划生育工作，制定流动人口计划生育工作规划并组织实施；建立流动人口计划生育信息管理系统，实现流动人口户籍所在地和现居住地计划生育信息共享，并与相关部门有关人口的信息管理系统实现信息共享。"},{"i":6,"n":"第六条","txt":"乡（镇）人民政府、街道办事处负责本管辖区域内流动人口计划生育工作，对流动人口实施计划生育管理，开展计划生育宣传教育；组织从事计划生育技术服务的机构指导流动人口中的育龄夫妻（以下称育龄夫妻）选择安全、有效、适宜的避孕节育措施，依法向育龄夫妻免费提供国家规定的基本项目的计划生育技术服务。"},{"i":7,"n":"第七条","txt":"流动人口中的成年育龄妇女（以下称成年育龄妇女）在离开户籍所在地前，应当凭本人居民身份证到户籍所在地的乡（镇）人民政府或者街道办事处办理婚育证明；已婚的，办理婚育证明还应当出示结婚证。婚育证明应当载明成年育龄妇女的姓名、年龄、公民身份号码、婚姻状况、配偶信息、生育状况、避孕节育情况等内容。"},{"i":8,"n":"第八条","txt":"成年育龄妇女应当自到达现居住地之日起30日内提交婚育证明。成年育龄妇女可以向现居住地的乡（镇）人民政府或者街道办事处提交婚育证明，也可以通过村民委员会、居民委员会向现居住地的乡（镇）人民政府或者街道办事处提交婚育证明。"},{"i":9,"n":"第九条","txt":"流动人口现居住地的县级人民政府公安、民政、人力资源社会保障、卫生等部门和县级工商行政管理部门应当结合部门职责，将流动人口计划生育工作纳入相关管理制度；及时向所在地同级人口和计划生育部门通报在办理有关登记和证照等工作中了解的流动人口婚育证明办理情况等计划生育信息。"},{"i":10,"n":"第十条","txt":"流动人口在现居住地享受下列计划生育服务和奖励、优待："},{"i":11,"n":"第十一条","txt":"流动人口现居住地的地方各级人民政府和县级以上地方人民政府有关部门应当采取措施，落实本条例第十条规定的流动人口计划生育服务和奖励、优待。"},{"i":12,"n":"第十二条","txt":"育龄夫妻应当自觉落实计划生育避孕节育措施，接受户籍所在地和现居住地人民政府的计划生育管理。"},{"i":13,"n":"第十三条","txt":"流动人口现居住地从事计划生育技术服务的机构应当按照所在地省、自治区、直辖市或者较大的市的规定，为已婚育龄妇女出具避孕节育情况证明。"},{"i":14,"n":"第十四条","txt":"流动人口现居住地的村民委员会、居民委员会应当协助所在地的乡（镇）人民政府或者街道办事处了解本村或者本居住地区流动人口计划生育情况，及时向乡（镇）人民政府或者街道办事处通报相关信息。"},{"i":15,"n":"第十五条","txt":"用人单位应当做好本单位流动人口计划生育工作，依法落实法律、法规和规章规定的流动人口计划生育奖励、优待，接受所在地的乡（镇）人民政府或者街道办事处和县级以上地方人民政府人口和计划生育部门的监督、检查。"},{"i":16,"n":"第十六条","txt":"育龄夫妻生育第一个子女的，可以在现居住地的乡（镇）人民政府或者街道办事处办理生育服务登记。办理生育服务登记，应当提供下列证明材料："},{"i":17,"n":"第十七条","txt":"出具婚育证明或者其他计划生育证明材料，不得收取任何费用。"},{"i":18,"n":"第十八条","txt":"地方各级人民政府和政府有关部门以及协助查验婚育证明的村民委员会、居民委员会及其工作人员，应当对涉及公民隐私的流动人口信息予以保密。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府人口和计划生育部门未依照本条例的规定履行流动人口计划生育工作职责的，由本级人民政府或者上级人民政府人口和计划生育部门责令改正，通报批评；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":20,"n":"第二十条","txt":"流动人口户籍所在地的乡（镇）人民政府或者街道办事处在流动人口计划生育工作中有下列情形之一的，分别由乡（镇）人民政府的上级人民政府或者设立街道办事处的人民政府责令改正，通报批评；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":21,"n":"第二十一条","txt":"流动人口现居住地的乡（镇）人民政府或者街道办事处在流动人口计划生育工作中有下列情形之一的，分别由乡（镇）人民政府的上级人民政府或者设立街道办事处的人民政府责令改正，通报批评；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":22,"n":"第二十二条","txt":"流动人口现居住地的县级人民政府公安、民政、人力资源社会保障、卫生等部门和县级工商行政管理部门违反本条例第九条规定的，由本级人民政府或者上级人民政府主管部门责令改正，通报批评。"},{"i":23,"n":"第二十三条","txt":"流动人口未依照本条例规定办理婚育证明的，现居住地的乡（镇）人民政府或者街道办事处应当通知其在3个月内补办；逾期仍不补办或者拒不提交婚育证明的，由流动人口现居住地的乡（镇）人民政府或者街道办事处予以批评教育。"},{"i":24,"n":"第二十四条","txt":"用人单位违反本条例第十五条规定的，由所在地县级人民政府人口和计划生育部门责令改正，通报批评。"},{"i":25,"n":"第二十五条","txt":"本条例自2009年10月1日起施行。1998年8月6日国务院批准、1998年9月22日原国家计划生育委员会发布的《流动人口计划生育工作管理办法》同时废止。"}],"maiyinpiaochangrenyuanshourongjiaoyubanfa":[{"i":1,"n":"第一条","txt":"为了教育、挽救卖淫、嫖娼人员，制止性病蔓延，根据《全国人民代表大会常务委员会关于严禁卖淫嫖娼的决定》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称收容教育，是指对卖淫、嫖娼人员集中进行法律教育和道德教育、组织参加生产劳动以及进行性病检查、治疗的行政强制教育措施。"},{"i":3,"n":"第三条","txt":"收容教育工作由公安部主管。"},{"i":4,"n":"第四条","txt":"收容教育所的设立，由省、自治区、直辖市或者自治州、设区的市的公安机关根据收容教育工作的需要提出方案，报同级人民政府批准。"},{"i":5,"n":"第五条","txt":"收容教育所根据工作需要，配备辅导、医务、财会等工作人员。"},{"i":6,"n":"第六条","txt":"收容教育所应当设置收容室以及教育、劳动、医疗、文体活动等场所。"},{"i":7,"n":"第七条","txt":"对卖淫、嫖娼人员，除依照《中华人民共和国治安管理处罚法》第六十六条的规定处罚外，对尚不够实行劳动教养的，可以由公安机关决定收容教育。"},{"i":8,"n":"第八条","txt":"对卖淫、嫖娼人员实行收容教育，由县级公安机关决定。决定实行收容教育的，有关县级公安机关应当填写收容教育决定书。收容教育决定书副本应当交给被收容教育人员本人，并自决定之日起15日内通知其家属、所在单位和户口所在地的公安派出所。"},{"i":9,"n":"第九条","txt":"收容教育期限为6个月至2年。"},{"i":10,"n":"第十条","txt":"收容教育所对入所的被收容教育人员，应当进行性病检查和治疗。检查和治疗性病的费用一般由本人或者家属负担。"},{"i":11,"n":"第十一条","txt":"收容教育所对被收容教育人员，应当按照性别和有无性病实行分别管理。"},{"i":12,"n":"第十二条","txt":"收容教育所应当依法管理，建立、健全各项管理制度，严禁打骂、体罚或者以其他方式侮辱被收容教育人员。"},{"i":13,"n":"第十三条","txt":"对被收容教育人员应当进行法律教育和道德教育，并组织他们参加生产劳动，学习生产技能，增强劳动观念。"},{"i":14,"n":"第十四条","txt":"被收容教育人员在收容教育期间的生活费用一般由本人或者家属负担。"},{"i":15,"n":"第十五条","txt":"被收容教育人员入所时携带的物品需要由收容教育所保管的，收容教育所应当造册登记，妥善保管，在被收容教育人员离所时将原物交还本人。"},{"i":16,"n":"第十六条","txt":"收容教育所应当允许被收容教育人员的家属探访。"},{"i":17,"n":"第十七条","txt":"被收容教育人员在收容教育期间确有悔改表现或者有立功表现以及其他特殊情况的，可以给予表扬或者提前解除收容教育。需要提前解除收容教育的，由收容教育所提出意见，报原决定对其实行收容教育的公安机关批准。但是，提前解除收容教育的，实际执行的收容教育期限不得少于原决定收容教育期限的1/2。"},{"i":18,"n":"第十八条","txt":"对拒绝接受教育或者不服从管理的被收容教育人员，可以给予警告或者延长收容教育期限。需要延长收容教育期限的，由收容教育所提出意见，报原决定对其实行收容教育的公安机关批准。但是，延长收容教育期限的，实际执行的收容教育期限最长不得超过2年。"},{"i":19,"n":"第十九条","txt":"对收容教育期满的人员，应当按期解除收容教育，发给解除收容教育证明书，并通知其家属或者所在单位领回。"},{"i":20,"n":"第二十条","txt":"被收容教育人员对收容教育决定不服的，可以依法申请行政复议；对行政复议决定不服的，可以依照《中华人民共和国行政诉讼法》的规定向人民法院提起诉讼。"},{"i":21,"n":"第二十一条","txt":"被收容教育人员在收容教育期间死亡的，应当由公安机关组织法医或者指定医生作出死亡鉴定，经同级人民检察院检验，报上一级公安机关和人民检察院备案，并填写死亡通知书，通知被收容教育人员家属、所在单位和户口所在地公安派出所；家属不予认领的，由公安机关拍照后处理。"},{"i":22,"n":"第二十二条","txt":"本办法由公安部负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自发布之日起施行。"}],"meikuanganquanjianchatiaoli":[{"i":1,"n":"第一条","txt":"为了保障煤矿安全，规范煤矿安全监察工作，保护煤矿职工人身安全和身体健康，根据煤炭法、矿山安全法、第九届全国人民代表大会第一次会议通过的国务院机构改革方案和国务院关于煤矿安全监察体制的决定，制定本条例。"},{"i":2,"n":"第二条","txt":"国家对煤矿安全实行监察制度。国务院决定设立的煤矿安全监察机构按照国务院规定的职责，依照本条例的规定对煤矿实施安全监察。"},{"i":3,"n":"第三条","txt":"煤矿安全监察机构依法行使职权，不受任何组织和个人的非法干涉。"},{"i":4,"n":"第四条","txt":"地方各级人民政府应当加强煤矿安全管理工作，支持和协助煤矿安全监察机构依法对煤矿实施安全监察。"},{"i":5,"n":"第五条","txt":"煤矿安全监察应当以预防为主，及时发现和消除事故隐患，有效纠正影响煤矿安全的违法行为，实行安全监察与促进安全管理相结合、教育与惩处相结合。"},{"i":6,"n":"第六条","txt":"煤矿安全监察应当依靠煤矿职工和工会组织。"},{"i":7,"n":"第七条","txt":"煤矿安全监察机构及其煤矿安全监察人员应当依法履行安全监察职责。任何单位和个人对煤矿安全监察机构及其煤矿安全监察人员的违法违纪行为，有权向上级煤矿安全监察机构或者有关机关检举和控告。"},{"i":8,"n":"第八条","txt":"本条例所称煤矿安全监察机构，是指国家煤矿安全监察机构和在省、自治区、直辖市设立的煤矿安全监察机构（以下简称地区煤矿安全监察机构）及其在大中型矿区设立的煤矿安全监察办事处。"},{"i":9,"n":"第九条","txt":"地区煤矿安全监察机构及其煤矿安全监察办事处负责对划定区域内的煤矿实施安全监察；煤矿安全监察办事处在国家煤矿安全监察机构规定的权限范围内，可以对违法行为实施行政处罚。"},{"i":10,"n":"第十条","txt":"煤矿安全监察机构设煤矿安全监察员。煤矿安全监察员应当公道、正派，熟悉煤矿安全法律、法规和规章，具有相应的专业知识和相关的工作经验，并经考试录用。"},{"i":11,"n":"第十一条","txt":"地区煤矿安全监察机构、煤矿安全监察办事处应当对煤矿实施经常性安全检查；对事故多发地区的煤矿，应当实施重点安全检查。国家煤矿安全监察机构根据煤矿安全工作的实际情况，组织对全国煤矿的全面安全检查或者重点安全抽查。"},{"i":12,"n":"第十二条","txt":"地区煤矿安全监察机构、煤矿安全监察办事处应当对每个煤矿建立煤矿安全监察档案。煤矿安全监察人员对每次安全检查的内容、发现的问题及其处理情况，应当作详细记录，并由参加检查的煤矿安全监察人员签名后归档。"},{"i":13,"n":"第十三条","txt":"地区煤矿安全监察机构、煤矿安全监察办事处应当每15日分别向国家煤矿安全监察机构、地区煤矿安全监察机构报告一次煤矿安全监察情况；有重大煤矿安全问题的，应当及时采取措施并随时报告。"},{"i":14,"n":"第十四条","txt":"煤矿安全监察人员履行安全监察职责，有权随时进入煤矿作业场所进行检查，调阅有关资料，参加煤矿安全生产会议，向有关单位或者人员了解情况。"},{"i":15,"n":"第十五条","txt":"煤矿安全监察人员在检查中发现影响煤矿安全的违法行为，有权当场予以纠正或者要求限期改正；对依法应当给予行政处罚的行为，由煤矿安全监察机构依照行政处罚法和本条例规定的程序作出决定。"},{"i":16,"n":"第十六条","txt":"煤矿安全监察人员进行现场检查时，发现存在事故隐患的，有权要求煤矿立即消除或者限期解决；发现威胁职工生命安全的紧急情况时，有权要求立即停止作业，下达立即从危险区内撤出作业人员的命令，并立即将紧急情况和处理措施报告煤矿安全监察机构。"},{"i":17,"n":"第十七条","txt":"煤矿安全监察机构在实施安全监察过程中，发现煤矿存在的安全问题涉及有关地方人民政府或其有关部门的，应当向有关地方人民政府或其有关部门提出建议，并向上级人民政府或其有关部门报告。"},{"i":18,"n":"第十八条","txt":"煤矿发生伤亡事故的，由煤矿安全监察机构负责组织调查处理。"},{"i":19,"n":"第十九条","txt":"煤矿安全监察机构及其煤矿安全监察人员不得接受煤矿的任何馈赠、报酬、福利待遇，不得在煤矿报销任何费用，不得参加煤矿安排、组织或者支付费用的宴请、娱乐、旅游、出访等活动，不得借煤矿安全监察工作在煤矿为自己、亲友或者他人谋取利益。"},{"i":20,"n":"第二十条","txt":"煤矿安全监察机构对煤矿执行煤炭法、矿山安全法和其他有关煤矿安全的法律、法规以及国家安全标准、行业安全标准、煤矿安全规程和行业技术规范的情况实施监察。"},{"i":21,"n":"第二十一条","txt":"煤矿建设工程设计必须符合煤矿安全规程和行业技术规范的要求。煤矿建设工程安全设施设计必须经煤矿安全监察机构审查同意；未经审查同意的，不得施工。"},{"i":22,"n":"第二十二条","txt":"煤矿建设工程竣工后或者投产前，应当经煤矿安全监察机构对其安全设施和条件进行验收；未经验收或者验收不合格的，不得投入生产。"},{"i":23,"n":"第二十三条","txt":"煤矿安全监察机构应当监督煤矿制定事故预防和应急计划，并检查煤矿制定的发现和消除事故隐患的措施及其落实情况。"},{"i":24,"n":"第二十四条","txt":"煤矿安全监察机构发现煤矿矿井通风、防火、防水、防瓦斯、防毒、防尘等安全设施和条件不符合国家安全标准、行业安全标准、煤矿安全规程和行业技术规范要求的，应当责令立即停止作业或者责令限期达到要求。"},{"i":25,"n":"第二十五条","txt":"煤矿安全监察机构发现煤矿进行独眼井开采的，应当责令关闭。"},{"i":26,"n":"第二十六条","txt":"煤矿安全监察机构发现煤矿作业场所有下列情形之一的，应当责令立即停止作业，限期改正；有关煤矿或其作业场所经复查合格的，方可恢复作业："},{"i":27,"n":"第二十七条","txt":"煤矿安全监察机构对煤矿安全技术措施专项费用的提取和使用情况进行监督，对未依法提取或者使用的，应当责令限期改正。"},{"i":28,"n":"第二十八条","txt":"煤矿安全监察机构发现煤矿矿井使用的设备、器材、仪器、仪表、防护用品不符合国家安全标准或者行业安全标准的，应当责令立即停止使用。"},{"i":29,"n":"第二十九条","txt":"煤矿安全监察机构发现煤矿有下列情形之一的，应当责令限期改正："},{"i":30,"n":"第三十条","txt":"煤矿安全监察人员发现煤矿作业场所的瓦斯、粉尘或者其他有毒有害气体的浓度超过国家安全标准或者行业安全标准的，煤矿擅自开采保安煤柱的，或者采用危及相邻煤矿生产安全的决水、爆破、贯通巷道等危险方法进行采矿作业的，应当责令立即停止作业，并将有关情况报告煤矿安全监察机构。"},{"i":31,"n":"第三十一条","txt":"煤矿安全监察人员发现煤矿矿长或者其他主管人员违章指挥工人或者强令工人违章、冒险作业，或者发现工人违章作业的，应当立即纠正或者责令立即停止作业。"},{"i":32,"n":"第三十二条","txt":"煤矿安全监察机构及其煤矿安全监察人员履行安全监察职责，向煤矿有关人员了解情况时，有关人员应当如实反映情况，不得提供虚假情况，不得隐瞒本煤矿存在的事故隐患以及其他安全问题。"},{"i":33,"n":"第三十三条","txt":"煤矿安全监察机构依照本条例的规定责令煤矿限期解决事故隐患、限期改正影响煤矿安全的违法行为或者限期使安全设施和条件达到要求的，应当在限期届满时及时对煤矿的执行情况进行复查并签署复查意见；经有关煤矿申请，也可以在限期内进行复查并签署复查意见。"},{"i":34,"n":"第三十四条","txt":"煤矿安全监察机构及其煤矿安全监察人员履行安全监察职责，应当出示安全监察证件。发出安全监察指令，应当采用书面通知形式；紧急情况下需要采取紧急处置措施，来不及书面通知的，应当随后补充书面通知。"},{"i":35,"n":"第三十五条","txt":"煤矿建设工程安全设施设计未经煤矿安全监察机构审查同意，擅自施工的，由煤矿安全监察机构责令停止施工；拒不执行的，由煤矿安全监察机构移送地质矿产主管部门依法吊销采矿许可证。"},{"i":36,"n":"第三十六条","txt":"煤矿建设工程安全设施和条件未经验收或者验收不合格，擅自投入生产的，由煤矿安全监察机构责令停止生产，处5万元以上10万元以下的罚款；拒不停止生产的，由煤矿安全监察机构移送地质矿产主管部门依法吊销采矿许可证。"},{"i":37,"n":"第三十七条","txt":"煤矿矿井通风、防火、防水、防瓦斯、防毒、防尘等安全设施和条件不符合国家安全标准、行业安全标准、煤矿安全规程和行业技术规范的要求，经煤矿安全监察机构责令限期达到要求，逾期仍达不到要求的，由煤矿安全监察机构责令停产整顿；经停产整顿仍不具备安全生产条件的，由煤矿安全监察机构决定吊销安全生产许可证，并移送地质矿产主管部门依法吊销采矿许可证。"},{"i":38,"n":"第三十八条","txt":"煤矿作业场所未使用专用防爆电器设备、专用放炮器、人员专用升降容器或者使用明火明电照明，经煤矿安全监察机构责令限期改正，逾期不改正的，由煤矿安全监察机构责令停产整顿，可以处3万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"未依法提取或者使用煤矿安全技术措施专项费用，或者使用不符合国家安全标准或者行业安全标准的设备、器材、仪器、仪表、防护用品，经煤矿安全监察机构责令限期改正或者责令立即停止使用，逾期不改正或者不立即停止使用的，由煤矿安全监察机构处5万元以下的罚款；情节严重的，由煤矿安全监察机构责令停产整顿；对直接负责的主管人员和其他直接责任人员，依法给予纪律处分。"},{"i":40,"n":"第四十条","txt":"煤矿矿长不具备安全专业知识，或者特种作业人员未取得操作资格证书上岗作业，经煤矿安全监察机构责令限期改正，逾期不改正的，责令停产整顿；调整配备合格人员并经复查合格后，方可恢复生产。"},{"i":41,"n":"第四十一条","txt":"分配职工上岗作业前未进行安全教育、培训，经煤矿安全监察机构责令限期改正，逾期不改正的，由煤矿安全监察机构处4万元以下的罚款；情节严重的，由煤矿安全监察机构责令停产整顿；对直接负责的主管人员和其他直接责任人员，依法给予纪律处分。"},{"i":42,"n":"第四十二条","txt":"煤矿作业场所的瓦斯、粉尘或者其他有毒有害气体的浓度超过国家安全标准或者行业安全标准，经煤矿安全监察人员责令立即停止作业，拒不停止作业的，由煤矿安全监察机构责令停产整顿，可以处10万元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"擅自开采保安煤柱，或者采用危及相邻煤矿生产安全的决水、爆破、贯通巷道等危险方法进行采矿作业，经煤矿安全监察人员责令立即停止作业，拒不停止作业的，由煤矿安全监察机构决定吊销安全生产许可证，并移送地质矿产主管部门依法吊销采矿许可证；构成犯罪的，依法追究刑事责任；造成损失的，依法承担赔偿责任。"},{"i":44,"n":"第四十四条","txt":"煤矿矿长或者其他主管人员有下列行为之一的，由煤矿安全监察机构给予警告；造成严重后果，构成犯罪的，依法追究刑事责任："},{"i":45,"n":"第四十五条","txt":"煤矿有关人员拒绝、阻碍煤矿安全监察机构及其煤矿安全监察人员现场检查，或者提供虚假情况，或者隐瞒存在的事故隐患以及其他安全问题的，由煤矿安全监察机构给予警告，可以并处5万元以上10万元以下的罚款；情节严重的，由煤矿安全监察机构责令停产整顿；对直接负责的主管人员和其他直接责任人员，依法给予撤职直至开除的纪律处分。"},{"i":46,"n":"第四十六条","txt":"煤矿发生事故，有下列情形之一的，由煤矿安全监察机构给予警告，可以并处3万元以上15万元以下的罚款；情节严重的，由煤矿安全监察机构责令停产整顿；对直接负责的主管人员和其他直接责任人员，依法给予降级直至开除的纪律处分；构成犯罪的，依法追究刑事责任："},{"i":47,"n":"第四十七条","txt":"依照本条例规定被吊销采矿许可证的，由工商行政管理部门依法相应吊销营业执照。"},{"i":48,"n":"第四十八条","txt":"煤矿安全监察人员滥用职权、玩忽职守、徇私舞弊，应当发现而没有发现煤矿事故隐患或者影响煤矿安全的违法行为，或者发现事故隐患或者影响煤矿安全的违法行为不及时处理或者报告，或者有违反本条例第十九条规定行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":49,"n":"第四十九条","txt":"未设立地区煤矿安全监察机构的省、自治区、直辖市，省、自治区、直辖市人民政府可以指定有关部门依照本条例的规定对本行政区域内的煤矿实施安全监察。"},{"i":50,"n":"第五十条","txt":"本条例自2000年12月1日起施行。"}],"meitansonghuobanfa":[{"i":1,"n":"第一条","txt":"煤矿和铁路、交通部门，必须加强协作，密切配合，千方百计地采取措施，保证用煤单位按时收到煤炭。"},{"i":2,"n":"第二条","txt":"煤矿应当根据订货合同，编制煤炭月度运输计划，并办理托运手续。"},{"i":3,"n":"第三条","txt":"用煤单位遇有特殊情况，提出推迟或者提前发运煤炭的时候，煤矿和铁路、交通部门，应当共同设法，尽量满足这种要求。"},{"i":4,"n":"第四条","txt":"煤矿必须认真贯彻“质量第一”的方针，努力提高煤炭的质量，不断降低煤炭中的灰分、全水分、含矸率和块煤限下率，保证按照订货合同中规定的品种、规格、质量标准发运煤炭。"},{"i":5,"n":"第五条","txt":"煤矿发运的煤炭的质量，应当批批合格。但是，灰分和全水分，按批检查的时候，分别允许有百分之零点五和百分之一（绝对值）的波动系数，全月平均都不准有波动系数。"},{"i":6,"n":"第六条","txt":"煤矿在发煤以前，必须按照国家规定的办法严格进行质量检查，发现不符合第五条规定的，不准装车外运；已经运出的，必须主动赔偿用煤单位的损失。灰分低于规定标准的，征得用煤单位同意后，可以增收价款。全水分、含矸率和块煤限下率低于规定标准的，不增收价款。"},{"i":7,"n":"第七条","txt":"煤矿应当根据用煤单位的要求，提交煤炭质量化验单。"},{"i":8,"n":"第八条","txt":"煤矿和铁路、交通部门，必须切实负责，积极采取措施，保证发运的煤炭，重量准确，在运输和换装过程中不抛撒丢失。"},{"i":9,"n":"第九条","txt":"铁路部门和有专用铁道的企业，对于送到煤矿的车皮，应当保证车体完整，技术状态良好，清扫干净，关牢车门；对于装载出口煤炭需要原车过轨的车皮，还必须保证符合过轨的条件。煤矿发现车皮不符合上述要求的时候，应当通知铁路部门或有专用铁道的企业及时改进，或者在力所能及的情况下主动帮助处理。"},{"i":10,"n":"第十条","txt":"煤矿装车，应当按照车皮标记载重装足；如果装到车帮高度仍然达不到标记载重，可以超出车帮起脊装载，但是必须确保车辆运行时不溜失煤炭。起脊高度由路矿双方商定。煤炭的价款和运费，都按实际装载量计算。"},{"i":11,"n":"第十一条","txt":"煤矿发运煤炭的重量，应当用轨道衡衡量；没有轨道衡的煤矿，用检尺测量方法计算，但是应当有计划地安装轨道衡。"},{"i":12,"n":"第十二条","txt":"用轨道衡衡量重量的，车皮自重以标记自重为准；装煤重量，除按规定可以少装或多装的以外，应当与标记载重符合，不够的必须添足，超过的必须卸下。装好以后，在煤车的顶面上洒石灰浆作为标记；或者进行平车，以煤车顶面的平整状态作为标记。在货物运单内，煤矿必须填明煤炭的矿别、品种、级别、并加盖“衡”字章。"},{"i":13,"n":"第十三条","txt":"煤矿装车，必须做到四个一样：黑夜和白天装的一样；坏天气和好天气装的一样；领导不在场和领导在场装的一样；没人检查和有人检查装的一样。"},{"i":14,"n":"第十四条","txt":"车站对于煤矿装好的煤车，必须逐车检查。合格的，与煤矿办理交接手续；不合格的，应当提出要求，经煤矿改善后再办交接手续。"},{"i":15,"n":"第十五条","txt":"煤车到站后，用煤单位可以采取抽查的办法对煤炭的重量和质量进行验收。通过验收，发现问题，找出原因，分清责任，改进工作。"},{"i":16,"n":"第十六条","txt":"到站的煤车，标记状态发生变化的，车站应当会同用煤单位进行复查。短少的重量，由铁路部门赔偿。"},{"i":17,"n":"第十七条","txt":"煤炭的质量，以煤矿的化验和测定结果为准。但是，用煤单位认为必要的时候，可以派员到煤矿进行检查，也可以在到站进行抽查。抽查的时候，灰分按照国家规定的办法，采样、制样、化验；含矸率整车拣选；块煤限下率整车筛选，但是为了避免筛选造成破碎损失，应当尽量协商处理。抽查结果，质量不合格的，煤矿应当负责赔偿。"},{"i":18,"n":"第十八条","txt":"煤矿对于水陆联运煤炭的质量和重量，负责到第一个换装港口的车站；对于出口煤炭的质量和重量，负责到国境车站。"},{"i":19,"n":"第十九条","txt":"用煤单位对于品种不符合合同规定的煤炭，应当领取卸车，妥为保管，并及时通知煤矿设法处理。"},{"i":20,"n":"第二十条","txt":"用煤单位要求煤矿赔偿重量短少和质量不合格的损失，都以实际抽查的部分为限，不得以抽查结果推算全部。"},{"i":21,"n":"第二十一条","txt":"用煤单位必须按期付款。但遇有下列情形之一的时候，可以拒付价款和运费的一部或全部："},{"i":22,"n":"第二十二条","txt":"煤炭的价款和运费（包括煤矿垫付运费的利息和未计入煤价的铁路专用线费、调车费），按照银行的规定办理结算。"},{"i":23,"n":"第二十三条","txt":"煤矿实行送货，应当经过批准。煤炭工业部所属煤矿，由主管的煤炭工业管理局（公司）商得有关铁路局同意后，报请煤炭工业部和铁道部批准；地方煤矿，由所在省、自治区、直辖市主管厅（局）商得有关铁路局同意后，报请省、自治区、直辖市人民委员会批准。"},{"i":24,"n":"第二十四条","txt":"本办法的实施细则，由煤炭工业部、铁道部、交通部另行制定。"}],"nongminzhuanyehezuoshedengjiguanlitiaoli":[{"i":1,"n":"第一条","txt":"为了确认农民专业合作社的法人资格，规范农民专业合作社登记行为，依据《中华人民共和国农民专业合作社法》，制定本条例。"},{"i":2,"n":"第二条","txt":"农民专业合作社的设立、变更和注销，应当依照《中华人民共和国农民专业合作社法》和本条例的规定办理登记。"},{"i":3,"n":"第三条","txt":"农民专业合作社经登记机关依法登记，领取农民专业合作社法人营业执照（以下简称营业执照），取得法人资格。未经依法登记，不得以农民专业合作社名义从事经营活动。"},{"i":4,"n":"第四条","txt":"工商行政管理部门是农民专业合作社登记机关。国务院工商行政管理部门负责全国的农民专业合作社登记管理工作。"},{"i":5,"n":"第五条","txt":"农民专业合作社的登记事项包括："},{"i":6,"n":"第六条","txt":"农民专业合作社的名称应当含有“专业合作社”字样，并符合国家有关企业名称登记管理的规定。"},{"i":7,"n":"第七条","txt":"农民专业合作社的住所是其主要办事机构所在地。"},{"i":8,"n":"第八条","txt":"农民专业合作社成员可以用货币出资，也可以用实物、知识产权等能够用货币估价并可以依法转让的非货币财产作价出资。成员以非货币财产出资的，由全体成员评估作价。成员不得以劳务、信用、自然人姓名、商誉、特许经营权或者设定担保的财产等作价出资。"},{"i":9,"n":"第九条","txt":"农民专业合作社以其成员为主要服务对象，业务范围可以有农业生产资料购买，农产品销售、加工、运输、贮藏以及与农业生产经营有关的技术、信息等服务。"},{"i":10,"n":"第十条","txt":"农民专业合作社理事长为农民专业合作社的法定代表人。"},{"i":11,"n":"第十一条","txt":"申请设立农民专业合作社，应当由全体设立人指定的代表或者委托的代理人向登记机关提交下列文件："},{"i":12,"n":"第十二条","txt":"农民专业合作社章程含有违反《中华人民共和国农民专业合作社法》以及有关法律、行政法规规定的内容的，登记机关应当要求农民专业合作社做相应修改。"},{"i":13,"n":"第十三条","txt":"具有民事行为能力的公民，以及从事与农民专业合作社业务直接有关的生产经营活动的企业、事业单位或者社会团体，能够利用农民专业合作社提供的服务，承认并遵守农民专业合作社章程，履行章程规定的入社手续的，可以成为农民专业合作社的成员。但是，具有管理公共事务职能的单位不得加入农民专业合作社。"},{"i":14,"n":"第十四条","txt":"农民专业合作社应当有5名以上的成员，其中农民至少应当占成员总数的80%。"},{"i":15,"n":"第十五条","txt":"农民专业合作社的成员为农民的，成员身份证明为农业人口户口簿；无农业人口户口簿的，成员身份证明为居民身份证和土地承包经营权证或者村民委员会（居民委员会）出具的身份证明。"},{"i":16,"n":"第十六条","txt":"申请人提交的登记申请材料齐全、符合法定形式，登记机关能够当场登记的，应予当场登记，发给营业执照。"},{"i":17,"n":"第十七条","txt":"营业执照分为正本和副本，正本和副本具有同等法律效力。"},{"i":18,"n":"第十八条","txt":"营业执照遗失或者毁坏的，农民专业合作社应当申请补领。"},{"i":19,"n":"第十九条","txt":"农民专业合作社的登记文书格式，营业执照的正本、副本样式以及电子营业执照标准，由国务院工商行政管理部门制定。"},{"i":20,"n":"第二十条","txt":"农民专业合作社的名称、住所、成员出资总额、业务范围、法定代表人姓名发生变更的，应当自做出变更决定之日起30日内向原登记机关申请变更登记，并提交下列文件："},{"i":21,"n":"第二十一条","txt":"农民专业合作社变更业务范围涉及法律、行政法规或者国务院规定须经批准的项目的，应当自批准之日起30日内申请变更登记，并提交有关批准文件。"},{"i":22,"n":"第二十二条","txt":"农民专业合作社成员发生变更的，应当自本财务年度终了之日起30日内，将法定代表人签署的修改后的成员名册报送登记机关备案。其中，新成员入社的还应当提交新成员的身份证明。"},{"i":23,"n":"第二十三条","txt":"农民专业合作社修改章程未涉及登记事项的，应当自做出修改决定之日起30日内，将法定代表人签署的修改后的章程或者章程修正案报送登记机关备案。"},{"i":24,"n":"第二十四条","txt":"变更登记事项涉及营业执照变更的，登记机关应当换发营业执照。"},{"i":25,"n":"第二十五条","txt":"成立清算组的农民专业合作社应当自清算结束之日起30日内，由清算组全体成员指定的代表或者委托的代理人向原登记机关申请注销登记，并提交下列文件："},{"i":26,"n":"第二十六条","txt":"提交虚假材料或者采取其他欺诈手段取得农民专业合作社登记的，由登记机关责令改正；情节严重的，撤销农民专业合作社登记。"},{"i":27,"n":"第二十七条","txt":"农民专业合作社有下列行为之一的，由登记机关责令改正；情节严重的，吊销营业执照："},{"i":28,"n":"第二十八条","txt":"农民专业合作社有下列行为之一的，由登记机关责令改正："},{"i":29,"n":"第二十九条","txt":"登记机关对不符合规定条件的农民专业合作社登记申请予以登记，或者对符合规定条件的登记申请不予登记的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":30,"n":"第三十条","txt":"农民专业合作社可以设立分支机构，并比照本条例有关农民专业合作社登记的规定，向分支机构所在地登记机关申请办理登记。农民专业合作社分支机构不具有法人资格。"},{"i":31,"n":"第三十一条","txt":"登记机关办理农民专业合作社登记不得收费。"},{"i":32,"n":"第三十二条","txt":"建立农民专业合作社年度报告制度。农民专业合作社年度报告办法由国务院工商行政管理部门制定。"},{"i":33,"n":"第三十三条","txt":"本条例施行前设立的农民专业合作社，应当自本条例施行之日起1年内依法办理登记。"},{"i":34,"n":"第三十四条","txt":"本条例自2007年7月1日起施行。"}],"qishuizanxingtiaoli":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内转移土地、房屋权属，承受的单位和个人为契税的纳税人，应当依照本条例的规定缴纳契税。"},{"i":2,"n":"第二条","txt":"本条例所称转移土地、房屋权属是指下列行为："},{"i":3,"n":"第三条","txt":"契税税率为3—5%。"},{"i":4,"n":"第四条","txt":"契税的计税依据："},{"i":5,"n":"第五条","txt":"契税应纳税额，依照本条例第三条规定的税率和第四条规定的计税依据计算征收。应纳税额计算公式："},{"i":6,"n":"第六条","txt":"有下列情形之一的，减征或者免征契税："},{"i":7,"n":"第七条","txt":"经批准减征、免征契税的纳税人改变有关土地、房屋的用途，不再属于本条例第六条规定的减征、免征契税范围的，应当补缴已经减征、免征的税款。"},{"i":8,"n":"第八条","txt":"契税的纳税义务发生时间，为纳税人签订土地、房屋权属转移合同的当天，或者纳税人取得其他具有土地、房屋权属转移合同性质凭证的当天。"},{"i":9,"n":"第九条","txt":"纳税人应当自纳税义务发生之日起10日内，向土地、房屋所在地的契税征收机关办理纳税申报，并在契税征收机关核定的期限内缴纳税款。"},{"i":10,"n":"第十条","txt":"纳税人办理纳税事宜后，契税征收机关应当向纳税人开具契税完税凭证。"},{"i":11,"n":"第十一条","txt":"纳税人应当持契税完税凭证和其他规定的文件材料，依法向土地管理部门、房产管理部门办理有关土地、房屋的权属变更登记手续。"},{"i":12,"n":"第十二条","txt":"契税征收机关为土地、房屋所在地的税务机关。"},{"i":13,"n":"第十三条","txt":"契税的征收管理，依照本条例和有关法律、行政法规的规定执行。"},{"i":14,"n":"第十四条","txt":"财政部根据本条例制定细则。"},{"i":15,"n":"第十五条","txt":"本条例自1997年10月1日起施行。1950年4月3日中央人民政府政务院发布的《契税暂行条例》同时废止。"}],"qiyefarendengjiguanlitiaoli":[{"i":1,"n":"第一条","txt":"为建立企业法人登记管理制度，确认企业法人资格，保障企业合法权益，取缔非法经营，维护社会经济秩序，根据《中华人民共和国民法通则》的有关规定，制定本条例。"},{"i":2,"n":"第二条","txt":"具备法人条件的下列企业，应当依照本条例的规定办理企业法人登记："},{"i":3,"n":"第三条","txt":"申请企业法人登记，经企业法人登记主管机关审核，准予登记注册的，领取《企业法人营业执照》，取得法人资格，其合法权益受国家法律保护。"},{"i":4,"n":"第四条","txt":"企业法人登记主管机关（以下简称登记主管机关）是国家市场监督管理总局和地方各级市场监督管理部门。各级登记主管机关在上级登记主管机关的领导下，依法履行职责，不受非法干预。"},{"i":5,"n":"第五条","txt":"经国务院或者国务院授权部门批准的全国性公司、经营进出口业务的公司，由国家市场监督管理总局核准登记注册。中外合资经营企业、中外合作经营企业、外资企业由国家市场监督管理总局或者国家市场监督管理总局授权的地方市场监督管理部门核准登记注册。"},{"i":6,"n":"第六条","txt":"各级登记主管机关，应当建立企业法人登记档案和登记统计制度，掌握企业法人登记有关的基础信息，为发展有计划的商品经济服务。"},{"i":7,"n":"第七条","txt":"申请企业法人登记的单位应当具备下列条件："},{"i":8,"n":"第八条","txt":"企业办理企业法人登记，由该企业的组建负责人申请。"},{"i":9,"n":"第九条","txt":"企业法人登记注册的主要事项：企业法人名称、住所、经营场所、法定代表人、经济性质、经营范围、经营方式、注册资金、从业人数、经营期限、分支机构。"},{"i":10,"n":"第十条","txt":"企业法人只准使用一个名称。企业法人申请登记注册的名称由登记主管机关核定，经核准登记注册后在规定的范围内享有专用权。"},{"i":11,"n":"第十一条","txt":"登记主管机关核准登记注册的企业法人的法定代表人是代表企业行使职权的签字人。法定代表人的签字应当向登记主管机关备案。"},{"i":12,"n":"第十二条","txt":"注册资金是国家授予企业法人经营管理的财产或者企业法人自有财产的数额体现。"},{"i":13,"n":"第十三条","txt":"企业法人的经营范围应当与其资金、场地、设备、从业人员以及技术力量相适应；按照国家有关规定，可以一业为主，兼营他业。企业法人应当在核准登记注册的经营范围内从事经营活动。"},{"i":14,"n":"第十四条","txt":"企业法人办理开业登记，应当在主管部门或者审批机关批准后30日内，向登记主管机关提出申请；没有主管部门、审批机关的企业申请开业登记，由登记主管机关进行审查。登记主管机关应当在受理申请后30日内，做出核准登记或者不予核准登记的决定。"},{"i":15,"n":"第十五条","txt":"申请企业法人开业登记，应当提交下列文件、证件："},{"i":16,"n":"第十六条","txt":"申请企业法人开业登记的单位，经登记主管机关核准登记注册，领取《企业法人营业执照》后，企业即告成立。企业法人凭据《企业法人营业执照》可以刻制公章、开立银行账户、签订合同，进行经营活动。"},{"i":17,"n":"第十七条","txt":"企业法人改变名称、住所、经营场所、法定代表人、经济性质、经营范围、经营方式、注册资金、经营期限，以及增设或者撤销分支机构，应当申请办理变更登记。"},{"i":18,"n":"第十八条","txt":"企业法人申请变更登记，应当在主管部门或者审批机关批准后30日内，向登记主管机关申请办理变更登记。"},{"i":19,"n":"第十九条","txt":"企业法人分立、合并、迁移，应当在主管部门或者审批机关批准后30日内，向登记主管机关申请办理变更登记、开业登记或者注销登记。"},{"i":20,"n":"第二十条","txt":"企业法人歇业、被撤销、宣告破产或者因其他原因终止营业，应当向登记主管机关办理注销登记。"},{"i":21,"n":"第二十一条","txt":"企业法人办理注销登记，应当提交法定代表人签署的申请注销登记报告、主管部门或者审批机关的批准文件、清理债务完结的证明或者清算组织负责清理债权债务的文件。经登记主管机关核准后，收缴《企业法人营业执照》、《企业法人营业执照》副本，收缴公章，并将注销登记情况告知其开户银行。"},{"i":22,"n":"第二十二条","txt":"企业法人领取《企业法人营业执照》后，满6个月尚未开展经营活动或者停止经营活动满1年的，视同歇业，登记主管机关应当收缴《企业法人营业执照》、《企业法人营业执照》副本，收缴公章，并将注销登记情况告知其开户银行。"},{"i":23,"n":"第二十三条","txt":"登记主管机关应当将企业法人登记、备案信息通过企业信用信息公示系统向社会公示。"},{"i":24,"n":"第二十四条","txt":"企业法人应当于每年1月1日至6月30日，通过企业信用信息公示系统向登记主管机关报送上一年度年度报告，并向社会公示。"},{"i":25,"n":"第二十五条","txt":"登记主管机关核发的《企业法人营业执照》是企业法人凭证，除登记主管机关依照法定程序可以扣缴或者吊销外，其他任何单位和个人不得收缴、扣押、毁坏。"},{"i":26,"n":"第二十六条","txt":"事业单位、科技性的社会团体根据国家有关规定，设立具备法人条件的企业，由该企业申请登记，经登记主管机关核准，领取《企业法人营业执照》，方可从事经营活动。"},{"i":27,"n":"第二十七条","txt":"根据国家有关规定，实行企业化经营，国家不再核拨经费的事业单位和从事经营活动的科技性的社会团体，具备企业法人登记条件的，由该单位申请登记，经登记主管机关核准，领取《企业法人营业执照》，方可从事经营活动。"},{"i":28,"n":"第二十八条","txt":"登记主管机关对企业法人依法履行下列监督管理职责："},{"i":29,"n":"第二十九条","txt":"企业法人有下列情形之一的，登记主管机关可以根据情况分别给予警告、罚款、没收非法所得、停业整顿、扣缴、吊销《企业法人营业执照》的处罚："},{"i":30,"n":"第三十条","txt":"登记主管机关处理企业法人违法活动，必须查明事实，依法处理，并将处理决定书面通知当事人。"},{"i":31,"n":"第三十一条","txt":"企业法人对登记主管机关的处罚不服时，可以在收到处罚通知后15日内向上一级登记主管机关申请复议。上级登记主管机关应当在收到复议申请之日起30日内作出复议决定。申请人对复议决定不服的，可以在收到复议通知之日起30日内向人民法院起诉。逾期不提出申诉又不缴纳罚没款的，登记主管机关可以按照规定程序申请人民法院强制执行。"},{"i":32,"n":"第三十二条","txt":"企业法人被吊销《企业法人营业执照》，登记主管机关应当收缴其公章，并将注销登记情况告知其开户银行，其债权债务由主管部门或者清算组织负责清理。"},{"i":33,"n":"第三十三条","txt":"主管部门、审批机关、登记主管机关的工作人员违反本条例规定，严重失职、滥用职权、营私舞弊、索贿受贿或者侵害企业法人合法权益的，应当根据情节给予行政处分和经济处罚；触犯刑律的，由司法机关依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"企业法人设立不能独立承担民事责任的分支机构，由该企业法人申请登记，经登记主管机关核准，领取《营业执照》，在核准登记的经营范围内从事经营活动。"},{"i":35,"n":"第三十五条","txt":"经国务院有关部门或者各级计划部门批准的新建企业，其筹建期满1年的，应当按照专项规定办理筹建登记。"},{"i":36,"n":"第三十六条","txt":"本条例施行前，具备法人条件的企业，已经登记主管机关核准登记注册的，不再另行办理企业法人登记。"},{"i":37,"n":"第三十七条","txt":"本条例施行细则由国家市场监督管理总局制定。"},{"i":38,"n":"第三十八条","txt":"本条例自1988年7月1日起施行。1980年7月26日国务院发布的《中外合资经营企业登记管理办法》，1982年8月9日国务院发布的《工商企业登记管理条例》，1985年8月14日国务院批准、1985年8月25日原国家工商行政管理局发布的《公司登记管理暂行规定》同时废止。"}],"qiyefarenfadingdaibiaorendengjiguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范企业法人法定代表人的登记管理，制定本规定。"},{"i":2,"n":"第二条","txt":"企业法人登记（包括公司登记，下同）中法定代表人的登记管理，适用本规定。"},{"i":3,"n":"第三条","txt":"企业法人的法定代表人（以下简称法定代表人）经企业登记机关核准登记，取得法定代表人资格。"},{"i":4,"n":"第四条","txt":"有下列情形之一的，不得担任法定代表人，企业登记机关不予核准登记："},{"i":5,"n":"第五条","txt":"企业法定代表人的产生、免职程序，应当符合法律、行政法规和企业法人组织章程的规定。"},{"i":6,"n":"第六条","txt":"企业法人申请办理法定代表人变更登记，应当向原企业登记机关提交下列文件："},{"i":7,"n":"第七条","txt":"有限责任公司或者股份有限公司更换法定代表人需要由股东会、股东大会或者董事会召开会议作出决议，而原法定代表人不能或者不履行职责，致使股东会、股东大会或者董事会不能依照法定程序召开的，可以由半数以上的董事推选1名董事或者由出资最多或者持有最大股份表决权的股东或其委派的代表召集和主持会议，依法作出决议。"},{"i":8,"n":"第八条","txt":"法定代表人任职期间出现本规定第四条所列情形之一的，该企业法人应当申请办理法定代表人变更登记。"},{"i":9,"n":"第九条","txt":"法定代表人应当在法律、行政法规和企业法人组织章程规定的职权范围内行使职权。"},{"i":10,"n":"第十条","txt":"法定代表人的签字应当向企业登记机关备案。"},{"i":11,"n":"第十一条","txt":"违反本规定，隐瞒真实情况，采用欺骗手段取得法定代表人资格的，由企业登记机关责令改正，处1万元以上10万元以下的罚款；情节严重的，撤销企业登记，吊销企业法人营业执照。"},{"i":12,"n":"第十二条","txt":"违反本规定，应当申请办理法定代表人变更登记而未办理的，由企业登记机关责令限期办理；逾期未办理的，处1万元以上10万元以下的罚款；情节严重的，撤销企业登记，吊销企业法人营业执照。"},{"i":13,"n":"第十三条","txt":"任何单位和个人发现法定代表人有本规定第四条所列情形之一的，有权向企业登记机关检举。"},{"i":14,"n":"第十四条","txt":"本规定自发布之日起施行。"}],"quanminsuoyouzhigongyejiaotongqiyeshebeiguanlitiao398edb":[{"i":1,"n":"第一条","txt":"为加强设备管理，提高生产技术装备水平和经济效益，保证安全生产和设备正常运行，特制定本条例。"},{"i":2,"n":"第二条","txt":"本条例适用于全民所有制工业交通企业（以下简称企业）的全部生产设备的管理。"},{"i":3,"n":"第三条","txt":"企业的设备管理应当依靠技术进步、促进生产发展和预防为主，坚持设计、制造与使用相结合，维护与计划检修相结合，修理、改造与更新相结合，专业管理与群众管理相结合，技术管理与经济管理相结合的原则。"},{"i":4,"n":"第四条","txt":"企业设备管理的主要任务，是对设备进行综合管理，保持设备完好，不断改善和提高企业技术装备素质，充分发挥设备的效能，取得良好的投资效益。"},{"i":5,"n":"第五条","txt":"各级企业管理部门应当按照分级管理的原则，负责对企业设备管理工作进行业务指导和监督检查。"},{"i":6,"n":"第六条","txt":"国家鼓励设备管理和检修工作的社会化、专业化协作，支持对设备管理和维修技术的科学研究工作。"},{"i":7,"n":"第七条","txt":"企业应当积极采用先进的设备管理方法和维修技术，采用以设备状态监测为基础的设备维修方法，不断提高设备管理和维修技术现代化水平。"},{"i":8,"n":"第八条","txt":"企业设备管理的主要经济、技术考核指标，应当列入厂长任期责任目标。"},{"i":9,"n":"第九条","txt":"国家经济委员会在设备管理工作中的主要职责是："},{"i":10,"n":"第十条","txt":"国务院工业交通各部门在设备管理工作中的主要职责是："},{"i":11,"n":"第十一条","txt":"各省、自治区、直辖市人民政府经济委员会（或计划经济委员会）在设备管理工作中的主要职责是："},{"i":12,"n":"第十二条","txt":"企业必须做好设备的规划、选型、购置（或设计、制造）及安装调试等管理工作。企业购置重要生产设备，应当进行技术经济论证，并按照有关规定上报审批。企业购置设备，应当由企业设备管理机构或设备管理人员提出有关设备的可靠性和有利于设备维修等要求。"},{"i":13,"n":"第十三条","txt":"企业自制设备，应当组织设备管理、维修、使用方面的人员参加设计方案的研究和审查工作，并严格按照设计方案做好设备的制造工作。设备制成后，应当有完整的技术资料。"},{"i":14,"n":"第十四条","txt":"设备制造部门应当与用户建立设备使用信息反馈制度，提供设备售后服务。"},{"i":15,"n":"第十五条","txt":"企业选购的进口设备应当备有设备维修技术资料和必要的维修配件。"},{"i":16,"n":"第十六条","txt":"企业应当建立健全设备的操作、使用、维护规程和岗位责任制。"},{"i":17,"n":"第十七条","txt":"企业应当按照国家有关规定，加强对动力、起重、运输、仪器仪表、压力容器等设备的维护、检查监测和预防性试验。"},{"i":18,"n":"第十八条","txt":"企业的设备检修工作应当严格遵守检修规程，执行检修技术标准，以保证检修质量，缩短检修时间，降低检修成本。"},{"i":19,"n":"第十九条","txt":"企业应当根据设备的实际技术状况，结合生产安排，编制设备检修计划，并纳入企业年度计划。企业必须严格执行设备检修计划。"},{"i":20,"n":"第二十条","txt":"企业必须遵守财经制度，接受审计监督。企业提取和使用设备的大修理基金，必须遵守国家有关规定。"},{"i":21,"n":"第二十一条","txt":"企业应当合理储备备品配件，并做好保管维护工作。"},{"i":22,"n":"第二十二条","txt":"企业应当在保证设备检修质量的前提下，做好设备旧件的修复利用，节约检修资金。"},{"i":23,"n":"第二十三条","txt":"企业应当编制设备改造和更新的中长期计划和年度计划，并组织实施。"},{"i":24,"n":"第二十四条","txt":"企业对重要设备进行改造和更新，必须事先进行技术经济论证，并按照有关规定上报审批。"},{"i":25,"n":"第二十五条","txt":"企业设备的固定资产折旧基金，应当按国家规定主要用于设备的改造和更新。"},{"i":26,"n":"第二十六条","txt":"企业对设备改造验收后新增的价值，应当办理固定资产增值手续。"},{"i":27,"n":"第二十七条","txt":"企业对属于下列情况之一的设备，应当报废更新："},{"i":28,"n":"第二十八条","txt":"企业出租、转让或者报废设备，必须遵守国家有关规定。"},{"i":29,"n":"第二十九条","txt":"企业应当建立健全设备的验收交接、档案、管理和考核制度。"},{"i":30,"n":"第三十条","txt":"企业应当制定设备检修的工时、资金、消耗及储备定额。"},{"i":31,"n":"第三十一条","txt":"企业应当向有关部门报送设备管理的统计报表。设备管理的统计指标，由国务院工业交通各部门制定。"},{"i":32,"n":"第三十二条","txt":"企业发生设备事故必须如实上报。"},{"i":33,"n":"第三十三条","txt":"国务院工业交通各部门，各省、自治区、直辖市人民政府，应当创造条件，有计划地培养设备管理与维修方面的专业人员。"},{"i":34,"n":"第三十四条","txt":"企业设备管理工作的负责人，一般应当由具有中专以上文化水平（包括经过自学、职业培训，达到同等水平的），并有一定实践经验的人员担任。"},{"i":35,"n":"第三十五条","txt":"国家经济委员会、国务院工业交通各部门及各省、自治区、直辖市经济委员会（或计划经济委员会）可根据需要组织开展设备管理评优活动，对设备管理工作成绩显著的企业，给予表彰或奖励。"},{"i":36,"n":"第三十六条","txt":"企业根据设备管理工作的需要，可以定期开展评比竞赛活动。"},{"i":37,"n":"第三十七条","txt":"企业主管部门对于因设备管理混乱、设备严重失修而影响生产的企业，应当令其限期整顿并根据情节轻重追究企业领导人员或者有关责任人员的行政责任。"},{"i":38,"n":"第三十八条","txt":"对玩忽职守，违章指挥，违反设备操作、使用、维护、检修规程，造成设备事故和经济损失的职工，由其所在单位根据情节轻重，分别追究经济责任和行政责任；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"本条例原则上亦适用于全民所有制邮电、地质、建筑施工、农林、水利等企业。事业单位、集体所有制工业交通企业可参照执行。"},{"i":40,"n":"第四十条","txt":"国务院工业交通各部门和各省、自治区、直辖市经济委员会（或计划经济委员会）可根据本条例制定实施办法。"},{"i":41,"n":"第四十一条","txt":"本条例由国家经济委员会负责解释。"},{"i":42,"n":"第四十二条","txt":"本条例自发布之日起施行。"}],"quanminsuoyouzhigongyeqiyechangzhanggongzuotiaoli":[{"i":1,"n":"第一条","txt":"为改革全民所有制工业企业的领导体制，确定厂长的责任和权限，实行厂长负责制，特制定本条例。"},{"i":2,"n":"第二条","txt":"全民所有制工业企业（以下简称企业）依照国家法律规定，取得企业法人资格。企业的法定代表人为厂长，负责代表法人行使职权。厂长依据本条例规定，对本企业的生产指挥和经营管理工作统一领导，全面负责。"},{"i":3,"n":"第三条","txt":"厂长在组织企业生产经营活动中，必须坚持企业的社会主义经营方向，执行党和国家的方针、政策，遵守国家的法律、法规，执行企业主管机关的决定。"},{"i":4,"n":"第四条","txt":"厂长必须维护国家利益，保护国家财产，正确处理国家、企业、职工三者利益关系。"},{"i":5,"n":"第五条","txt":"厂长在企业缴纳税金、上交利润和提取、使用利润留成以及转让固定资产和进行重大经济活动等方面，必须接受审计、财政、税务、工商行政管理等部门和国家银行的监督。"},{"i":6,"n":"第六条","txt":"厂长应当定期向企业党的基层委员会（含不设基层委员会的党总支部委员会、支部委员会，以下简称党委）报告工作，接受监督。"},{"i":7,"n":"第七条","txt":"厂长应当定期向职工代表大会（或职工大会，下同）报告工作，听取意见，组织实施职工代表大会在其职权范围内作出的有关决定，负责处理职工代表大会提出应由行政方面处理的提案，接受职工代表大会的监督。"},{"i":8,"n":"第八条","txt":"厂长应当具备以下条件："},{"i":9,"n":"第九条","txt":"厂长的产生，应当根据企业的不同情况，分别采取下列方式："},{"i":10,"n":"第十条","txt":"厂长实行任期制，每届任期3至5年，可以连任。"},{"i":11,"n":"第十一条","txt":"企业设立管理委员会，就企业经营管理中的重大问题协助厂长决策。"},{"i":12,"n":"第十二条","txt":"本条例第十一条所称重大问题是指："},{"i":13,"n":"第十三条","txt":"管理委员会讨论本条例第十二条规定事项中需经企业主管机关审批的，由厂长负责上报。"},{"i":14,"n":"第十四条","txt":"管理委员会讨论本条例第十二条规定的事项中需经职工代表大会审议的，由厂长负责提出。"},{"i":15,"n":"第十五条","txt":"企业建立以厂长为首的生产经营管理系统，实行统一领导，分级负责。"},{"i":16,"n":"第十六条","txt":"企业根据规模大小和生产经营的需要，可设总工程师、总经济师、总会计师等厂级经济技术负责人。企业是否设副厂长以及副厂长的名额，由厂长提出方案，报企业主管机关决定。"},{"i":17,"n":"第十七条","txt":"企业应当根据生产经营工作的需要设立必要的、精干的管理机构。"},{"i":18,"n":"第十八条","txt":"厂长应当根据国家计划和市场需求，结合任期责任目标，提出企业的年度经营目标和发展方向，经管理委员会讨论和职工代表大会审议后组织实施。"},{"i":19,"n":"第十九条","txt":"厂长应当组织企业各方面的力量，保证完成国家计划，组织实施国家下达给企业的各项任务，严格履行经济合同。"},{"i":20,"n":"第二十条","txt":"厂长应当注重市场信息，不断开发新产品，降低成本和费用，增强企业的应变、竞争能力。"},{"i":21,"n":"第二十一条","txt":"厂长应当通过严格的质量管理，保证产品质量达到国家规定的标准或合同的要求。"},{"i":22,"n":"第二十二条","txt":"厂长应当采取切实措施，推进企业的技术进步和企业的现代化管理，提高经济效益，增强企业自我改造和自我发展能力。"},{"i":23,"n":"第二十三条","txt":"厂长应当不断改善企业的劳动条件，高度重视安全生产，认真搞好环境保护。"},{"i":24,"n":"第二十四条","txt":"厂长应当采取切实措施，进行智力投资和人才开发，加强对职工的思想、文化、业务教育，组织职工进行技术革新，支持合理化建议，做好思想政治工作，充分发挥职工参加社会主义建设的主动性、积极性和创造性。"},{"i":25,"n":"第二十五条","txt":"厂长应当按照法律、法规规定，保障企业职工代表大会和工会行使其职权；在决定同广大职工切身利益有关的问题时，应当征求企业工会的意见。"},{"i":26,"n":"第二十六条","txt":"厂长有企业经营管理工作的决策权和生产指挥权。"},{"i":27,"n":"第二十七条","txt":"本条例第十六条所列副厂长和厂级经济技术负责人，以及中层行政干部的人选方案由厂长负责提出，并征求企业党委意见。中层行政干部由厂长决定任免；厂级行政副职按干部管理权限上报审批。"},{"i":28,"n":"第二十八条","txt":"厂长有权按国家规定对职工进行奖惩。"},{"i":29,"n":"第二十九条","txt":"厂长有权拒绝企业外部任何组织和个人抽调、借用企业的人员，无偿占用企业的资金和物资，对企业摊派劳务、费用。"},{"i":30,"n":"第三十条","txt":"厂长对职工代表大会在其职权范围内决定的事项如有不同意见，可以提请复议。复议后仍有不同意见，厂长应当按决定执行，同时报告上级主管机关。"},{"i":31,"n":"第三十一条","txt":"厂长有国家规定的企业生产指挥和经营管理工作方面的其他权限。"},{"i":32,"n":"第三十二条","txt":"厂长按照本条例规定行使职权时，受国家法律保护，任何组织和个人不得威胁、压制、阻挠和打击报复。"},{"i":33,"n":"第三十三条","txt":"厂长在工作中成绩显著，具有下列情形之一者，给予荣誉奖励、一次性物质奖励或晋级奖励："},{"i":34,"n":"第三十四条","txt":"由于厂长工作上的过错，发生下列情形，应当区别情节轻重，给予处分："},{"i":35,"n":"第三十五条","txt":"厂长以权谋私，违法乱纪，弄虚作假，骗取荣誉或经济利益，应当区别情况，给予处分；触犯刑律的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"对厂长的奖惩和调资、晋级，由企业主管机关决定；或由企业主管机关提出，按照干部管理权限报上级机关决定。"},{"i":37,"n":"第三十七条","txt":"实行承包、租赁的企业，厂长的产生、任期、任免、奖惩，企业经营管理中重大问题的决策，都按照根据国家有关规定签订的协议或合同执行。"},{"i":38,"n":"第三十八条","txt":"本条例原则上适用于全民所有制交通运输、邮电、地质、建筑施工、农林、水利等企业。"},{"i":39,"n":"第三十九条","txt":"本条例由国家经济委员会负责解释。"},{"i":40,"n":"第四十条","txt":"本条例自1986年10月1日起施行。"}],"quanminsuoyouzhigongyeqiyechengbaojingyingzerenzhi2bab16":[{"i":1,"n":"第一条","txt":"为发展和完善全民所有制工业企业（以下简称企业）承包经营责任制，转变企业经营机制，增强企业活力，提高经济效益，制定本条例。"},{"i":2,"n":"第二条","txt":"承包经营责任制，是在坚持企业的社会主义全民所有制的基础上，按照所有权与经营权分离的原则，以承包经营合同形式，确定国家与企业的责权利关系，使企业做到自主经营、自负盈亏的经营管理制度。"},{"i":3,"n":"第三条","txt":"实行承包经营责任制，必须兼顾国家、企业、经营者和生产者利益，调动企业经营者和生产者积极性，挖掘企业内部潜力，确保上交国家利润，增强企业自我发展能力，逐步改善职工生活。"},{"i":4,"n":"第四条","txt":"实行承包经营责任制，应当按照责权利相结合的原则，切实落实企业的经营管理自主权，保护企业的合法权益。"},{"i":5,"n":"第五条","txt":"实行承包经营责任制，按照包死基数、确保上交、超收多留、欠收自补的原则，确定国家与企业的分配关系。"},{"i":6,"n":"第六条","txt":"实行承包经营责任制，合同双方必须遵守国家法律、法规和政策，接受人民政府有关部门的监督。"},{"i":7,"n":"第七条","txt":"实行承包经营责任制，由国家审计机关及其委托的其他审计组织对合同双方及企业经营者进行审计。"},{"i":8,"n":"第八条","txt":"承包经营责任制的主要内容是：包上交国家利润，包完成技术改造任务，实行工资总额与经济效益挂钩。"},{"i":9,"n":"第九条","txt":"承包上交国家利润的形式有："},{"i":10,"n":"第十条","txt":"上交利润基数一般以上年上交的利润额（实行第二步利改税的企业，是指依法缴纳的所得税、调节税部分，下同）为准。"},{"i":11,"n":"第十一条","txt":"上交利润的方式为：企业按照税法纳税，纳税额中超过承包经营合同规定的上交利润额多上交的部分，由财政部门每季返还80%给企业，年终结算，多退少补，保证兑现。"},{"i":12,"n":"第十二条","txt":"技术改造任务，应当根据国家的产业政策、市场需求、技术改造规划和企业的经济技术状况确定。"},{"i":13,"n":"第十三条","txt":"实行工资总额与经济效益挂钩，其具体形式，可根据国家的规定和企业的实际情况确定。"},{"i":14,"n":"第十四条","txt":"实行承包经营责任制，必须由企业经营者代表承包方同发包方订立承包经营合同。"},{"i":15,"n":"第十五条","txt":"订立承包经营合同，合同双方必须坚持平等、自愿和协商的原则。"},{"i":16,"n":"第十六条","txt":"承包经营合同一般应当包括下列主要条款："},{"i":17,"n":"第十七条","txt":"承包期限，一般不得少于3年。"},{"i":18,"n":"第十八条","txt":"承包经营合同依法成立，即具有法律效力，任何一方均不得随意变更或解除。"},{"i":19,"n":"第十九条","txt":"国务院对税种、税率进行重大调整，合同双方可按国务院规定协商变更承包经营合同。"},{"i":20,"n":"第二十条","txt":"由于承包方经营管理不善完不成承包经营合同任务时，发包方有权提出解除承包经营合同。"},{"i":21,"n":"第二十一条","txt":"合同双方发生纠纷，应当协商解决。协商不成的，合同双方可以根据承包经营合同规定向国家工商行政管理机关申请仲裁；也可以根据承包经营合同规定直接向人民法院起诉。"},{"i":22,"n":"第二十二条","txt":"发包方有权按承包经营合同规定，对承包方的生产经营活动进行检查、监督。"},{"i":23,"n":"第二十三条","txt":"承包方享有国家法律、法规、政策和承包经营合同规定的经营管理自主权。"},{"i":24,"n":"第二十四条","txt":"由于发包方没有履行合同，影响承包经营合同完成时，发包方应当承担违约责任，并视情节轻重追究发包方直接责任者的行政责任和经济责任。"},{"i":25,"n":"第二十五条","txt":"承包方完不成承包经营合同任务时，应当承担违约责任，并视情节轻重追究企业经营者的行政责任和经济责任。"},{"i":26,"n":"第二十六条","txt":"实行承包经营责任制，一般应当采取公开招标办法通过竞争确定企业经营者或经营集团。也可以按国家规定的其他方式确定企业经营者。"},{"i":27,"n":"第二十七条","txt":"地方各级人民政府应当积极创造条件，逐步建立承包市场，为企业承包经营提供招标投标信息，为企业经营人才提供平等的竞争机会。"},{"i":28,"n":"第二十八条","txt":"由发包方组织有承包企业职工代表参加的招标委员会（或小组），对投标者进行全面评审，公开答辩，择优选定。"},{"i":29,"n":"第二十九条","txt":"企业经营者必须具备下列条件："},{"i":30,"n":"第三十条","txt":"企业经营者是企业的厂长（经理），企业的法定代表人，对企业全面负责。"},{"i":31,"n":"第三十一条","txt":"企业经营者可根据需要，按国家有关规定聘任一定数量的人员，组成企业领导班子。承包期满后，原企业领导班子即告解散。"},{"i":32,"n":"第三十二条","txt":"企业经营者必须履行承包经营合同规定的有关义务；在承包期间，按年度向发包方和企业职工代表大会提交承包经营合同执行情况的报告。"},{"i":33,"n":"第三十三条","txt":"企业经营者的年收入，视完成承包经营合同情况，可高于本企业职工年平均收入的1至3倍，贡献突出的，还可适当高一些。企业领导班子其他成员的收入要低于企业经营者。"},{"i":34,"n":"第三十四条","txt":"实行承包经营责任制的企业，试行资金分账制度，划分国家资金和企业资金，分别列账。"},{"i":35,"n":"第三十五条","txt":"企业资金作为承包经营企业负亏的风险基金。承包期满后转入下期承包的企业资金。"},{"i":36,"n":"第三十六条","txt":"承包经营企业必须合理核定留利中的生产发展基金、福利基金和奖励基金分配比例，并提取一定比例的福利基金和奖励基金用于住房制度改革。承包后新增的留利应当主要作为生产发展基金。"},{"i":37,"n":"第三十七条","txt":"实行承包前的贷款，由国家承担的部分，要在承包经营合同中规定还款额度和期限，分年还清，然后按规定调整承包基数。实行承包后的贷款，原则上要用企业资金偿还。"},{"i":38,"n":"第三十八条","txt":"承包经营企业必须严格遵守国家物价政策，不得擅自涨价或变相涨价。企业发生价格违法行为时，按国家有关规定追究企业和企业经营者的责任。"},{"i":39,"n":"第三十九条","txt":"承包经营企业应当搞好企业内部领导制度改革，实行厂长（经理）负责制。"},{"i":40,"n":"第四十条","txt":"承包经营企业应当加强民主管理，健全职工代表大会制度，充分发挥工会的作用，切实保障职工的民主权利。"},{"i":41,"n":"第四十一条","txt":"承包经营企业应当按照责权利相结合的原则，建立和健全企业内部经济责任制，搞好企业内部承包。"},{"i":42,"n":"第四十二条","txt":"承包经营企业应当贯彻按劳分配原则，确定适合本企业的工资形式和分配办法，积极推行计件工资制和定额工资制，使职工的劳动所得同劳动成果紧密挂钩。"},{"i":43,"n":"第四十三条","txt":"交通、建筑、农林、物资、商业、外贸行业的全民所有制企业实行承包经营责任制的，可参照本条例执行。"},{"i":44,"n":"第四十四条","txt":"各省、自治区、直辖市人民政府可根据本条例制定实施办法。"},{"i":45,"n":"第四十五条","txt":"本条例自1988年3月1日起施行。"}],"quanminsuoyouzhigongyeqiyezhuanhuanjingyingjizhiti1784e4":[{"i":1,"n":"第一条","txt":"为了推动全民所有制工业企业（以下简称企业）进入市场，增强企业活力，提高企业经济效益，根据《中华人民共和国全民所有制工业企业法》（以下简称《企业法》），制定本条例。"},{"i":2,"n":"第二条","txt":"企业转换经营机制的目标是：使企业适应市场的要求，成为依法自主经营、自负盈亏、自我发展、自我约束的商品生产和经营单位，成为独立享有民事权利和承担民事义务的企业法人。"},{"i":3,"n":"第三条","txt":"转换企业经营机制必须遵循下列原则："},{"i":4,"n":"第四条","txt":"围绕转换企业经营机制，按照宏观要管好，微观要放开的要求，政府必须转变职能，改革管理企业的方式，培育和发展市场体系，建立和完善社会保障制度，协调配套地进行计划、投资、财政、税收、金融、价格、物资、商业、外贸、人事和劳动工资等方面的改革。"},{"i":5,"n":"第五条","txt":"企业中的党组织和工会、共青团等组织以及全体职工都应当为实现企业转换经营机制的目标和《企业法》规定的企业根本任务开展工作。社会各有关方面都应当为企业转换经营机制创造条件。"},{"i":6,"n":"第六条","txt":"企业经营权是指企业对国家授予其经营管理的财产（以下简称企业财产）享有占有、使用和依法处分的权利。"},{"i":7,"n":"第七条","txt":"企业按照国家规定的资产经营形式，依法行使经营权。企业资产经营形式是指规范国家与企业的责、权、利关系，企业经营管理国有资产的责任制形式。"},{"i":8,"n":"第八条","txt":"企业享有生产经营决策权。"},{"i":9,"n":"第九条","txt":"企业享有产品、劳务定价权。"},{"i":10,"n":"第十条","txt":"企业享有产品销售权。"},{"i":11,"n":"第十一条","txt":"企业享有物资采购权。"},{"i":12,"n":"第十二条","txt":"企业享有进出口权。"},{"i":13,"n":"第十三条","txt":"企业享有投资决策权。"},{"i":14,"n":"第十四条","txt":"企业享有留用资金支配权。"},{"i":15,"n":"第十五条","txt":"企业享有资产处置权。"},{"i":16,"n":"第十六条","txt":"企业享有联营、兼并权。"},{"i":17,"n":"第十七条","txt":"企业享有劳动用工权。"},{"i":18,"n":"第十八条","txt":"企业享有人事管理权。"},{"i":19,"n":"第十九条","txt":"企业享有工资、奖金分配权。"},{"i":20,"n":"第二十条","txt":"企业享有内部机构设置权。"},{"i":21,"n":"第二十一条","txt":"企业享有拒绝摊派权。"},{"i":22,"n":"第二十二条","txt":"企业经营权受法律保护，任何部门、单位和个人不得干预和侵犯。"},{"i":23,"n":"第二十三条","txt":"企业以国家授予其经营管理的财产，承担民事责任。"},{"i":24,"n":"第二十四条","txt":"企业必须建立分配约束机制和监督机制。"},{"i":25,"n":"第二十五条","txt":"企业应当每年从工资总额的新增部分中提取不少于10%的数额，作为企业工资储备基金，由企业自主使用。工资储备基金累计达到本企业1年工资总额的，不再提取。"},{"i":26,"n":"第二十六条","txt":"企业连续3年全面完成上交任务，并实现企业财产增殖的，政府主管部门对厂长或者厂级领导给予相应奖励，奖金由决定奖励的部门拨付。"},{"i":27,"n":"第二十七条","txt":"实行承包经营责任制的企业，未完成上交利润任务的，应当以企业风险抵押金、工资储备基金、留利补交。"},{"i":28,"n":"第二十八条","txt":"企业为实现政府规定的社会公益目标，由于定价原因而形成的政策性亏损，物价部门应当依法调整或者放开产品价格，予以解决。不能调整或者放开产品价格的，经财政部门审查核准，给予相应的补贴或者其他方式补偿。采取上述措施后，企业仍然亏损的，作为经营性亏损处理。"},{"i":29,"n":"第二十九条","txt":"企业由于经营管理不善造成经营性亏损的，厂长、其他厂级领导和职工应当根据责任大小，承担相应的责任。"},{"i":30,"n":"第三十条","txt":"企业必须严格执行国家财政、税收和国有资产管理的法律、法规，定期进行财产盘点和审计，做到账实相符，如实反映企业经营成果，不得造成利润虚增或者虚盈实亏，确保企业财产的保值、增殖。"},{"i":31,"n":"第三十一条","txt":"企业可以通过转产、停产整顿、合并、分立、解散、破产等方式，进行产品结构和组织结构调整，实现资源合理配置和企业的优胜劣汰。"},{"i":32,"n":"第三十二条","txt":"企业主导产品不符合国家产业政策，或者没有市场销路、造成严重积压的，应当实行转产。企业为获取更大的经济效益，根据市场预测和自身条件，可以主动实行转产。"},{"i":33,"n":"第三十三条","txt":"企业经营性亏损严重的，可以自行申请停产整顿；政府主管部门也可以责令其停产整顿。停产整顿的期限一般不超过1年。"},{"i":34,"n":"第三十四条","txt":"政府可以决定或者批准企业的合并。政府决定或者批准的合并，在全民所有制企业的范围内，可以采取资产无偿划转方式进行。合并方案由政府主管部门或者企业提出。在政府主管部门主持下，合并各方经充分协商后，订立合并协议。原企业的债权债务，由合并后的企业承担。"},{"i":35,"n":"第三十五条","txt":"经政府批准，企业可以分立。企业分立时，应当由分立各方签订分立协议，明确划分分立各方的财产和债权债务等。"},{"i":36,"n":"第三十六条","txt":"企业经停产整顿仍然达不到扭亏目标，并且无法实行合并的，以及因其他原因应当终止的，在保证清偿债务的前提下，由政府主管部门提出，经省级政府或者国务院主管部门批准，可以依法予以解散。企业解散，由政府主管部门指定成立的清算组进行清算。"},{"i":37,"n":"第三十七条","txt":"企业所欠债务，应当以留用资金清偿。留用资金不足以偿还债务的，可以依法用抵押企业财产的方式，保证债务的履行。"},{"i":38,"n":"第三十八条","txt":"企业的变更和终止，应当依照法律、法规的规定，经工商行政管理部门核准登记，并向国有资产管理部门办理产权变更或者注销登记。"},{"i":39,"n":"第三十九条","txt":"政府决定解散的企业，职工由政府主管部门负责安置。"},{"i":40,"n":"第四十条","txt":"按照政企职责分开的原则，政府依法对企业进行协调、监督和管理，为企业提供服务。"},{"i":41,"n":"第四十一条","txt":"企业财产属于全民所有，即国家所有，国务院代表国家行使企业财产的所有权。"},{"i":42,"n":"第四十二条","txt":"为确保企业财产所有权，政府及其有关部门分别行使下列职责："},{"i":43,"n":"第四十三条","txt":"政府应当采取下列措施，加强宏观调控和行业管理，建立既有利于增强企业活力，又有利于经济有序运行的宏观调控体系："},{"i":44,"n":"第四十四条","txt":"政府应当采取下列措施，培育和完善市场体系，发挥市场调节作用："},{"i":45,"n":"第四十五条","txt":"政府应当采取下列措施建立和完善社会保障体系："},{"i":46,"n":"第四十六条","txt":"政府应当采取下列措施为企业提供社会服务："},{"i":47,"n":"第四十七条","txt":"政府有关部门违反本条例，有下列行为之一的，上级机关应当责令其改正；情节严重的，由同级机关或者有关上级机关对主管人员和直接责任人员，给予行政处分，构成犯罪的，由司法机关依法追究刑事责任："},{"i":48,"n":"第四十八条","txt":"企业违反本条例规定，有下列行为之一的，政府或者政府有关部门应当责令其改正；情节严重的，对厂长、其他厂级领导和直接责任人员，分别追究行政责任、给予经济处罚，并依照有关法律、法规，对企业给予相应的行政处罚；构成犯罪的，由司法机关依法追究刑事责任："},{"i":49,"n":"第四十九条","txt":"阻碍厂长和各级管理人员依法行使职权的，或者扰乱企业秩序，致使生产、营业、工作不能正常进行的，由企业所在地公安机关给予治安管理处罚；情节严重，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"本条例的原则适用于全民所有制交通运输、邮电、地质勘探、建筑安装、商业、外贸、物资、农林、水利、科技等企业。"},{"i":51,"n":"第五十一条","txt":"本条例发布前的行政法规、地方性法规、规章和其他行政性文件的内容，与本条例相抵触的，以本条例为准。"},{"i":52,"n":"第五十二条","txt":"本条例由国家经济体制改革委员会负责解释，国务院经济贸易办公室会同国务院有关部门组织实施。"},{"i":53,"n":"第五十三条","txt":"国务院有关部门和省、自治区、直辖市人民政府可以根据本条例制定实施办法。"},{"i":54,"n":"第五十四条","txt":"本条例自发布之日起施行。"}],"quanminsuoyouzhixiaoxinggongyeqiyezulinjingyingzan0451c6":[{"i":1,"n":"第一条","txt":"为完善企业租赁经营，增强企业活力，提高经济效益，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例适用于全民所有制小型工业企业（以下简称企业）。"},{"i":3,"n":"第三条","txt":"本条例所称租赁经营，是指在不改变企业的全民所有制性质的条件下，实行所有权与经营权的分离，国家授权单位为出租方将企业有期限地交给承租方经营，承租方向出租方交付租金并依照合同规定对企业实行自主经营的方式。"},{"i":4,"n":"第四条","txt":"实行租赁经营必须兼顾国家、企业、职工和承租方的利益。"},{"i":5,"n":"第五条","txt":"出租方和承租方必须执行国家的方针政策、法律法规，接受人民政府有关部门的监督。"},{"i":6,"n":"第六条","txt":"国家授权企业所在地方人民政府委托的部门为出租方，代表国家行使企业的出租权。"},{"i":7,"n":"第七条","txt":"按照本条例规定承租经营企业的为承租方。"},{"i":8,"n":"第八条","txt":"租赁期限每届为三至五年。承租方不得将企业转租。"},{"i":9,"n":"第九条","txt":"承租经营者是指承租经营企业的个人，或者合伙承租、全员承租确定的厂长，或者承租企业派出的厂长。承租经营者是企业租赁期间的法定代表人，行使厂长职权，对企业全面负责。"},{"i":10,"n":"第十条","txt":"承租经营者必须具备国家规定的厂长条件。"},{"i":11,"n":"第十一条","txt":"承租方必须提供下列担保："},{"i":12,"n":"第十二条","txt":"出租方在企业出租前必须会同有关部门对企业进行清产核资、清理债权债务、评估资产（包括有形资产和无形资产），根据行业和本企业资金利润率确定标底。"},{"i":13,"n":"第十三条","txt":"出租方选择承租方的步骤："},{"i":14,"n":"第十四条","txt":"企业、事业单位的干部或者职工按照国家有关规定参加租赁企业投标的，其所在单位应当允许，并支持中标者到租赁企业任职。"},{"i":15,"n":"第十五条","txt":"出租方选定承租方后，出租方与承租方必须订立租赁经营合同，按照国家有关规定办理法人变更登记手续。"},{"i":16,"n":"第十六条","txt":"租赁期满，出租方同意承租方继续承租的，必须重新订立合同并按照国家有关规定办理法人变更登记手续。"},{"i":17,"n":"第十七条","txt":"租赁经营合同应当采用书面形式。订立租赁经营合同的双方必须坚持自愿、平等、协商的原则。"},{"i":18,"n":"第十八条","txt":"租赁经营合同应当具备下列条款："},{"i":19,"n":"第十九条","txt":"未经协商同意，任何一方不得擅自变更、解除租赁经营合同。"},{"i":20,"n":"第二十条","txt":"有下列情况之一，使租赁经营合同无法履行时，允许变更或者解除合同："},{"i":21,"n":"第二十一条","txt":"租赁经营合同一方要求变更或者解除合同时，应当及时以书面形式通知对方，双方未达成书面协议以前，原合同仍然有效。"},{"i":22,"n":"第二十二条","txt":"租赁经营合同双方发生纠纷，应当协商解决。协商不成的，可以根据合同规定向工商行政管理机关申请调解或者仲裁。租赁经营合同任何一方对仲裁机关的仲裁决定不服的，可以在接到仲裁决定书之日起10日内向上一级仲裁机关申请复议。上一级仲裁机关作出的决定，即为终局裁决。逾期未申请复议，发生法律效力的仲裁决定，即为终局裁决。"},{"i":23,"n":"第二十三条","txt":"出租方的权利："},{"i":24,"n":"第二十四条","txt":"出租方的义务："},{"i":25,"n":"第二十五条","txt":"承租方的权利："},{"i":26,"n":"第二十六条","txt":"承租方的义务："},{"i":27,"n":"第二十七条","txt":"承租经营者作为承租方的代表享有和履行本条例第二十五条、第二十六条规定的权利和义务。"},{"i":28,"n":"第二十八条","txt":"出租方可视企业技术改造任务情况，将承租方交付租金的全部或者一部交给企业，用于生产发展和技术改造，或者清偿企业租赁前的债务及遗留亏损。"},{"i":29,"n":"第二十九条","txt":"租赁经营企业实现的利润依法纳税后，分为承租方的收入（含租金）、企业生产发展基金、职工集体福利基金、职工奖励基金四部分，按照合同规定的比例进行分配。"},{"i":30,"n":"第三十条","txt":"租赁经营企业可以在规定的工资总额（包括奖励基金）范围内，自主确定企业内部分配的制度、形式和方法，并依法纳税。"},{"i":31,"n":"第三十一条","txt":"企业租赁经营前的债权债务及遗留亏损的处理办法，按照租赁经营合同规定办理。"},{"i":32,"n":"第三十二条","txt":"自租赁经营合同生效之日起，停发承租经营者及合伙承租成员的工资、奖金，预支生活费。承租经营者及合伙承租成员的收入可以按照本条例第三十三条的规定分年度结算或者租赁期满一次结算。"},{"i":33,"n":"第三十三条","txt":"承租经营者的收入，原则上不超过本企业职工平均工资（含奖金）的五倍。其他承租成员的收入应当低于承租经营者的收入。"},{"i":34,"n":"第三十四条","txt":"承租方按照租赁经营合同规定的比例取得的收入，在交付租金和实际支付给承租成员以后仍有余额的，应当作为企业的风险保证金留存。"},{"i":35,"n":"第三十五条","txt":"租赁经营合同解除时，出租方应当会同有关部门对承租方经营成果进行审查。凡达到租赁经营合同规定的经营总目标并按照租赁经营合同规定交付租金的，出租方应当根据企业的经营情况，商得职工代表大会（职工大会）的同意，从企业的风险保证金中按照承租方担保现金数额的一至五倍支付给承租方。承租方在租赁期内达不到租赁经营合同规定的经营总目标或者欠交租金时，应当以企业的风险保证金、预支的生活费（或承租成员的年度收入）抵补，不足部分，由承租方、保证人提供的担保财产抵补。保证人以其保证财产抵补后，有权向承租方追偿。"},{"i":36,"n":"第三十六条","txt":"个人承租的承租经营者对保证人的风险补偿，应当从个人收入中支付并订立书面协议。"},{"i":37,"n":"第三十七条","txt":"租赁经营企业的劳动、财政管理办法，由国务院有关部门根据本条例制定。"},{"i":38,"n":"第三十八条","txt":"集体所有制工业企业实行租赁经营的，可参照本条例执行。"},{"i":39,"n":"第三十九条","txt":"各省、自治区、直辖市人民政府可以根据本条例制定实施细则。"},{"i":40,"n":"第四十条","txt":"本条例自1988年7月1日起施行。"}],"rentiqiguanyizhitiaoli":[{"i":1,"n":"第一条","txt":"为了规范人体器官移植，保证医疗质量，保障人体健康，维护公民的合法权益，制定本条例。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事人体器官移植，适用本条例；从事人体细胞和角膜、骨髓等人体组织移植，不适用本条例。"},{"i":3,"n":"第三条","txt":"任何组织或者个人不得以任何形式买卖人体器官，不得从事与买卖人体器官有关的活动。"},{"i":4,"n":"第四条","txt":"国务院卫生主管部门负责全国人体器官移植的监督管理工作。县级以上地方人民政府卫生主管部门负责本行政区域人体器官移植的监督管理工作。"},{"i":5,"n":"第五条","txt":"任何组织或者个人对违反本条例规定的行为，有权向卫生主管部门和其他有关部门举报；对卫生主管部门和其他有关部门未依法履行监督管理职责的行为，有权向本级人民政府、上级人民政府有关部门举报。接到举报的人民政府、卫生主管部门和其他有关部门对举报应当及时核实、处理，并将处理结果向举报人通报。"},{"i":6,"n":"第六条","txt":"国家通过建立人体器官移植工作体系，开展人体器官捐献的宣传、推动工作，确定人体器官移植预约者名单，组织协调人体器官的使用。"},{"i":7,"n":"第七条","txt":"人体器官捐献应当遵循自愿、无偿的原则。"},{"i":8,"n":"第八条","txt":"捐献人体器官的公民应当具有完全民事行为能力。公民捐献其人体器官应当有书面形式的捐献意愿，对已经表示捐献其人体器官的意愿，有权予以撤销。"},{"i":9,"n":"第九条","txt":"任何组织或者个人不得摘取未满18周岁公民的活体器官用于移植。"},{"i":10,"n":"第十条","txt":"活体器官的接受人限于活体器官捐献人的配偶、直系血亲或者三代以内旁系血亲，或者有证据证明与活体器官捐献人存在因帮扶等形成亲情关系的人员。"},{"i":11,"n":"第十一条","txt":"医疗机构从事人体器官移植，应当依照《医疗机构管理条例》的规定，向所在地省、自治区、直辖市人民政府卫生主管部门申请办理人体器官移植诊疗科目登记。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市人民政府卫生主管部门进行人体器官移植诊疗科目登记，除依据本条例第十一条规定的条件外，还应当考虑本行政区域人体器官移植的医疗需求和合法的人体器官来源情况。"},{"i":13,"n":"第十三条","txt":"已经办理人体器官移植诊疗科目登记的医疗机构不再具备本条例第十一条规定条件的，应当停止从事人体器官移植，并向原登记部门报告。原登记部门应当自收到报告之日起2日内注销该医疗机构的人体器官移植诊疗科目登记，并予以公布。"},{"i":14,"n":"第十四条","txt":"省级以上人民政府卫生主管部门应当定期组织专家根据人体器官移植手术成功率、植入的人体器官和术后患者的长期存活率，对医疗机构的人体器官移植临床应用能力进行评估，并及时公布评估结果；对评估不合格的，由原登记部门撤销人体器官移植诊疗科目登记。具体办法由国务院卫生主管部门制订。"},{"i":15,"n":"第十五条","txt":"医疗机构及其医务人员从事人体器官移植，应当遵守伦理原则和人体器官移植技术管理规范。"},{"i":16,"n":"第十六条","txt":"实施人体器官移植手术的医疗机构及其医务人员应当对人体器官捐献人进行医学检查，对接受人因人体器官移植感染疾病的风险进行评估，并采取措施，降低风险。"},{"i":17,"n":"第十七条","txt":"在摘取活体器官前或者尸体器官捐献人死亡前，负责人体器官移植的执业医师应当向所在医疗机构的人体器官移植技术临床应用与伦理委员会提出摘取人体器官审查申请。"},{"i":18,"n":"第十八条","txt":"人体器官移植技术临床应用与伦理委员会收到摘取人体器官审查申请后，应当对下列事项进行审查，并出具同意或者不同意的书面意见："},{"i":19,"n":"第十九条","txt":"从事人体器官移植的医疗机构及其医务人员摘取活体器官前，应当履行下列义务："},{"i":20,"n":"第二十条","txt":"摘取尸体器官，应当在依法判定尸体器官捐献人死亡后进行。从事人体器官移植的医务人员不得参与捐献人的死亡判定。"},{"i":21,"n":"第二十一条","txt":"从事人体器官移植的医疗机构实施人体器官移植手术，除向接受人收取下列费用外，不得收取或者变相收取所移植人体器官的费用："},{"i":22,"n":"第二十二条","txt":"申请人体器官移植手术患者的排序，应当符合医疗需要，遵循公平、公正和公开的原则。具体办法由国务院卫生主管部门制订。"},{"i":23,"n":"第二十三条","txt":"从事人体器官移植的医务人员应当对人体器官捐献人、接受人和申请人体器官移植手术的患者的个人资料保密。"},{"i":24,"n":"第二十四条","txt":"从事人体器官移植的医疗机构应当定期将实施人体器官移植的情况向所在地省、自治区、直辖市人民政府卫生主管部门报告。具体办法由国务院卫生主管部门制订。"},{"i":25,"n":"第二十五条","txt":"违反本条例规定，有下列情形之一，构成犯罪的，依法追究刑事责任："},{"i":26,"n":"第二十六条","txt":"违反本条例规定，买卖人体器官或者从事与买卖人体器官有关活动的，由设区的市级以上地方人民政府卫生主管部门依照职责分工没收违法所得，并处交易额8倍以上10倍以下的罚款；医疗机构参与上述活动的，还应当对负有责任的主管人员和其他直接责任人员依法给予处分，并由原登记部门撤销该医疗机构人体器官移植诊疗科目登记，该医疗机构3年内不得再申请人体器官移植诊疗科目登记；医务人员参与上述活动的，由原发证部门吊销其执业证书。"},{"i":27,"n":"第二十七条","txt":"医疗机构未办理人体器官移植诊疗科目登记，擅自从事人体器官移植的，依照《医疗机构管理条例》的规定予以处罚。"},{"i":28,"n":"第二十八条","txt":"医务人员有下列情形之一的，依法给予处分；情节严重的，由县级以上地方人民政府卫生主管部门依照职责分工暂停其6个月以上1年以下执业活动；情节特别严重的，由原发证部门吊销其执业证书："},{"i":29,"n":"第二十九条","txt":"医疗机构有下列情形之一的，对负有责任的主管人员和其他直接责任人员依法给予处分；情节严重的，由原登记部门撤销该医疗机构人体器官移植诊疗科目登记，该医疗机构3年内不得再申请人体器官移植诊疗科目登记："},{"i":30,"n":"第三十条","txt":"从事人体器官移植的医务人员参与尸体器官捐献人的死亡判定的，由县级以上地方人民政府卫生主管部门依照职责分工暂停其6个月以上1年以下执业活动；情节严重的，由原发证部门吊销其执业证书。"},{"i":31,"n":"第三十一条","txt":"国家机关工作人员在人体器官移植监督管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":32,"n":"第三十二条","txt":"本条例自2007年5月1日起施行。"}],"senlinfanghuotiaoli":[{"i":1,"n":"第一条","txt":"为了有效预防和扑救森林火灾，保障人民生命财产安全，保护森林资源，维护生态安全，根据《中华人民共和国森林法》，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例适用于中华人民共和国境内森林火灾的预防和扑救。但是，城市市区的除外。"},{"i":3,"n":"第三条","txt":"森林防火工作实行预防为主、积极消灭的方针。"},{"i":4,"n":"第四条","txt":"国家森林防火指挥机构负责组织、协调和指导全国的森林防火工作。"},{"i":5,"n":"第五条","txt":"森林防火工作实行地方各级人民政府行政首长负责制。"},{"i":6,"n":"第六条","txt":"森林、林木、林地的经营单位和个人，在其经营范围内承担森林防火责任。"},{"i":7,"n":"第七条","txt":"森林防火工作涉及两个以上行政区域的，有关地方人民政府应当建立森林防火联防机制，确定联防区域，建立联防制度，实行信息共享，并加强监督检查。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当将森林防火基础设施建设纳入国民经济和社会发展规划，将森林防火经费纳入本级财政预算。"},{"i":9,"n":"第九条","txt":"国家支持森林防火科学研究，推广和应用先进的科学技术，提高森林防火科技水平。"},{"i":10,"n":"第十条","txt":"各级人民政府、有关部门应当组织经常性的森林防火宣传活动，普及森林防火知识，做好森林火灾预防工作。"},{"i":11,"n":"第十一条","txt":"国家鼓励通过保险形式转移森林火灾风险，提高林业防灾减灾能力和灾后自我救助能力。"},{"i":12,"n":"第十二条","txt":"对在森林防火工作中作出突出成绩的单位和个人，按照国家有关规定，给予表彰和奖励。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府林业主管部门应当按照国务院林业主管部门制定的森林火险区划等级标准，以县为单位确定本行政区域的森林火险区划等级，向社会公布，并报国务院林业主管部门备案。"},{"i":14,"n":"第十四条","txt":"国务院林业主管部门应当根据全国森林火险区划等级和实际工作需要，编制全国森林防火规划，报国务院或者国务院授权的部门批准后组织实施。"},{"i":15,"n":"第十五条","txt":"国务院有关部门和县级以上地方人民政府应当按照森林防火规划，加强森林防火基础设施建设，储备必要的森林防火物资，根据实际需要整合、完善森林防火指挥信息系统。"},{"i":16,"n":"第十六条","txt":"国务院林业主管部门应当按照有关规定编制国家重大、特别重大森林火灾应急预案，报国务院批准。"},{"i":17,"n":"第十七条","txt":"森林火灾应急预案应当包括下列内容："},{"i":18,"n":"第十八条","txt":"在林区依法开办工矿企业、设立旅游区或者新建开发区的，其森林防火设施应当与该建设项目同步规划、同步设计、同步施工、同步验收；在林区成片造林的，应当同时配套建设森林防火设施。"},{"i":19,"n":"第十九条","txt":"铁路的经营单位应当负责本单位所属林地的防火工作，并配合县级以上地方人民政府做好铁路沿线森林火灾危险地段的防火工作。"},{"i":20,"n":"第二十条","txt":"森林、林木、林地的经营单位和个人应当按照林业主管部门的规定，建立森林防火责任制，划定森林防火责任区，确定森林防火责任人，并配备森林防火设施和设备。"},{"i":21,"n":"第二十一条","txt":"地方各级人民政府和国有林业企业、事业单位应当根据实际需要，成立森林火灾专业扑救队伍；县级以上地方人民政府应当指导森林经营单位和林区的居民委员会、村民委员会、企业、事业单位建立森林火灾群众扑救队伍。专业的和群众的火灾扑救队伍应当定期进行培训和演练。"},{"i":22,"n":"第二十二条","txt":"森林、林木、林地的经营单位配备的兼职或者专职护林员负责巡护森林，管理野外用火，及时报告火情，协助有关机关调查森林火灾案件。"},{"i":23,"n":"第二十三条","txt":"县级以上地方人民政府应当根据本行政区域内森林资源分布状况和森林火灾发生规律，划定森林防火区，规定森林防火期，并向社会公布。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府森林防火指挥机构，应当组织有关部门对森林防火区内有关单位的森林防火组织建设、森林防火责任制落实、森林防火设施建设等情况进行检查；对检查中发现的森林火灾隐患，县级以上地方人民政府林业主管部门应当及时向有关单位下达森林火灾隐患整改通知书，责令限期整改，消除隐患。"},{"i":25,"n":"第二十五条","txt":"森林防火期内，禁止在森林防火区野外用火。因防治病虫鼠害、冻害等特殊情况确需野外用火的，应当经县级人民政府批准，并按照要求采取防火措施，严防失火；需要进入森林防火区进行实弹演习、爆破等活动的，应当经省、自治区、直辖市人民政府林业主管部门批准，并采取必要的防火措施；中国人民解放军和中国人民武装警察部队因处置突发事件和执行其他紧急任务需要进入森林防火区的，应当经其上级主管部门批准，并采取必要的防火措施。"},{"i":26,"n":"第二十六条","txt":"森林防火期内，森林、林木、林地的经营单位应当设置森林防火警示宣传标志，并对进入其经营范围的人员进行森林防火安全宣传。"},{"i":27,"n":"第二十七条","txt":"森林防火期内，经省、自治区、直辖市人民政府批准，林业主管部门、国务院确定的重点国有林区的管理机构可以设立临时性的森林防火检查站，对进入森林防火区的车辆和人员进行森林防火检查。"},{"i":28,"n":"第二十八条","txt":"森林防火期内，预报有高温、干旱、大风等高火险天气的，县级以上地方人民政府应当划定森林高火险区，规定森林高火险期。必要时，县级以上地方人民政府可以根据需要发布命令，严禁一切野外用火；对可能引起森林火灾的居民生活用火应当严格管理。"},{"i":29,"n":"第二十九条","txt":"森林高火险期内，进入森林高火险区的，应当经县级以上地方人民政府批准，严格按照批准的时间、地点、范围活动，并接受县级以上地方人民政府林业主管部门的监督管理。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府林业主管部门和气象主管机构应当根据森林防火需要，建设森林火险监测和预报台站，建立联合会商机制，及时制作发布森林火险预警预报信息。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府应当公布森林火警电话，建立森林防火值班制度。"},{"i":32,"n":"第三十二条","txt":"发生下列森林火灾，省、自治区、直辖市人民政府森林防火指挥机构应当立即报告国家森林防火指挥机构，由国家森林防火指挥机构按照规定报告国务院，并及时通报国务院有关部门："},{"i":33,"n":"第三十三条","txt":"发生森林火灾，县级以上地方人民政府森林防火指挥机构应当按照规定立即启动森林火灾应急预案；发生重大、特别重大森林火灾，国家森林防火指挥机构应当立即启动重大、特别重大森林火灾应急预案。"},{"i":34,"n":"第三十四条","txt":"森林防火指挥机构应当按照森林火灾应急预案，统一组织和指挥森林火灾的扑救。"},{"i":35,"n":"第三十五条","txt":"扑救森林火灾应当以专业火灾扑救队伍为主要力量；组织群众扑救队伍扑救森林火灾的，不得动员残疾人、孕妇和未成年人以及其他不适宜参加森林火灾扑救的人员参加。"},{"i":36,"n":"第三十六条","txt":"武装警察森林部队负责执行国家赋予的森林防火任务。武装警察森林部队执行森林火灾扑救任务，应当接受火灾发生地县级以上地方人民政府森林防火指挥机构的统一指挥；执行跨省、自治区、直辖市森林火灾扑救任务的，应当接受国家森林防火指挥机构的统一指挥。"},{"i":37,"n":"第三十七条","txt":"发生森林火灾，有关部门应当按照森林火灾应急预案和森林防火指挥机构的统一指挥，做好扑救森林火灾的有关工作。"},{"i":38,"n":"第三十八条","txt":"因扑救森林火灾的需要，县级以上人民政府森林防火指挥机构可以决定采取开设防火隔离带、清除障碍物、应急取水、局部交通管制等应急措施。"},{"i":39,"n":"第三十九条","txt":"森林火灾扑灭后，火灾扑救队伍应当对火灾现场进行全面检查，清理余火，并留有足够人员看守火场，经当地人民政府森林防火指挥机构检查验收合格，方可撤出看守人员。"},{"i":40,"n":"第四十条","txt":"按照受害森林面积和伤亡人数，森林火灾分为一般森林火灾、较大森林火灾、重大森林火灾和特别重大森林火灾："},{"i":41,"n":"第四十一条","txt":"县级以上人民政府林业主管部门应当会同有关部门及时对森林火灾发生原因、肇事者、受害森林面积和蓄积、人员伤亡、其他经济损失等情况进行调查和评估，向当地人民政府提出调查报告；当地人民政府应当根据调查报告，确定森林火灾责任单位和责任人，并依法处理。"},{"i":42,"n":"第四十二条","txt":"县级以上地方人民政府林业主管部门应当按照有关要求对森林火灾情况进行统计，报上级人民政府林业主管部门和本级人民政府统计机构，并及时通报本级人民政府有关部门。"},{"i":43,"n":"第四十三条","txt":"森林火灾信息由县级以上人民政府森林防火指挥机构或者林业主管部门向社会发布。重大、特别重大森林火灾信息由国务院林业主管部门发布。"},{"i":44,"n":"第四十四条","txt":"对因扑救森林火灾负伤、致残或者死亡的人员，按照国家有关规定给予医疗、抚恤。"},{"i":45,"n":"第四十五条","txt":"参加森林火灾扑救的人员的误工补贴和生活补助以及扑救森林火灾所发生的其他费用，按照省、自治区、直辖市人民政府规定的标准，由火灾肇事单位或者个人支付；起火原因不清的，由起火单位支付；火灾肇事单位、个人或者起火单位确实无力支付的部分，由当地人民政府支付。误工补贴和生活补助以及扑救森林火灾所发生的其他费用，可以由当地人民政府先行支付。"},{"i":46,"n":"第四十六条","txt":"森林火灾发生后，森林、林木、林地的经营单位和个人应当及时采取更新造林措施，恢复火烧迹地森林植被。"},{"i":47,"n":"第四十七条","txt":"违反本条例规定，县级以上地方人民政府及其森林防火指挥机构、县级以上人民政府林业主管部门或者其他有关部门及其工作人员，有下列行为之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任："},{"i":48,"n":"第四十八条","txt":"违反本条例规定，森林、林木、林地的经营单位或者个人未履行森林防火责任的，由县级以上地方人民政府林业主管部门责令改正，对个人处500元以上5000元以下罚款，对单位处1万元以上5万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"违反本条例规定，森林防火区内的有关单位或者个人拒绝接受森林防火检查或者接到森林火灾隐患整改通知书逾期不消除火灾隐患的，由县级以上地方人民政府林业主管部门责令改正，给予警告，对个人并处200元以上2000元以下罚款，对单位并处5000元以上1万元以下罚款。"},{"i":50,"n":"第五十条","txt":"违反本条例规定，森林防火期内未经批准擅自在森林防火区内野外用火的，由县级以上地方人民政府林业主管部门责令停止违法行为，给予警告，对个人并处200元以上3000元以下罚款，对单位并处1万元以上5万元以下罚款。"},{"i":51,"n":"第五十一条","txt":"违反本条例规定，森林防火期内未经批准在森林防火区内进行实弹演习、爆破等活动的，由县级以上地方人民政府林业主管部门责令停止违法行为，给予警告，并处5万元以上10万元以下罚款。"},{"i":52,"n":"第五十二条","txt":"违反本条例规定，有下列行为之一的，由县级以上地方人民政府林业主管部门责令改正，给予警告，对个人并处200元以上2000元以下罚款，对单位并处2000元以上5000元以下罚款："},{"i":53,"n":"第五十三条","txt":"违反本条例规定，造成森林火灾，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，除依照本条例第四十八条、第四十九条、第五十条、第五十一条、第五十二条的规定追究法律责任外，县级以上地方人民政府林业主管部门可以责令责任人补种树木。"},{"i":54,"n":"第五十四条","txt":"森林消防专用车辆应当按照规定喷涂标志图案，安装警报器、标志灯具。"},{"i":55,"n":"第五十五条","txt":"在中华人民共和国边境地区发生的森林火灾，按照中华人民共和国政府与有关国家政府签订的有关协定开展扑救工作；没有协定的，由中华人民共和国政府和有关国家政府协商办理。"},{"i":56,"n":"第五十六条","txt":"本条例自2009年1月1日起施行。"}],"shehuifuyangfeizhengshouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范社会抚养费的征收管理，维护计划生育基本国策，保护公民的合法权益，实现人口与经济、社会、资源、环境的协调发展，根据《中华人民共和国人口与计划生育法》（以下简称人口与计划生育法），制定本办法。"},{"i":2,"n":"第二条","txt":"公民享有依法生育的权利，同时应当依法履行计划生育的义务，其生育行为应当符合人口与计划生育法的规定。"},{"i":3,"n":"第三条","txt":"不符合人口与计划生育法第十八条的规定生育子女的公民，应当依照本办法的规定缴纳社会抚养费。"},{"i":4,"n":"第四条","txt":"社会抚养费的征收，由县级人民政府计划生育行政部门作出书面征收决定；县级人民政府计划生育行政部门可以委托乡（镇）人民政府或者街道办事处作出书面征收决定。"},{"i":5,"n":"第五条","txt":"不符合人口与计划生育法第十八条规定生育子女的流动人口的社会抚养费的征收，按照下列规定办理："},{"i":6,"n":"第六条","txt":"社会抚养费的征收决定，自送达当事人之日起生效。当事人应当自收到征收决定之日起30日内一次性缴纳社会抚养费。"},{"i":7,"n":"第七条","txt":"社会抚养费的具体征收、缴纳方式，由省、自治区、直辖市根据当地实际情况规定。"},{"i":8,"n":"第八条","txt":"当事人未在规定的期限内缴纳社会抚养费的，自欠缴之日起每月加收欠缴社会抚养费的千分之二的滞纳金；仍不缴纳的，由作出征收决定的计划生育行政部门依法申请人民法院强制执行。"},{"i":9,"n":"第九条","txt":"当事人对征收决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":10,"n":"第十条","txt":"社会抚养费及滞纳金应当全部上缴国库，按照国务院财政部门的规定纳入地方财政预算管理；任何单位和个人不得截留、挪用、贪污、私分。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府计划生育、财政、计划（物价）、审计、监察等部门，应当加强对社会抚养费征收管理工作的监督、检查。"},{"i":12,"n":"第十二条","txt":"当事人所在单位或者村民委员会、城市居民委员会，应当依法配合做好社会抚养费的征收工作。"},{"i":13,"n":"第十三条","txt":"违反法律、法规的规定，擅自增设与计划生育有关的收费项目或者擅自提高社会抚养费征收标准的，依照《违反行政事业性收费和罚没收入收支两条线管理规定行政处分暂行规定》处理。"},{"i":14,"n":"第十四条","txt":"截留、挪用、贪污、私分社会抚养费的，依照刑法关于贪污罪、挪用公款罪、私分国有资产罪的规定，依法追究刑事责任；尚不够刑事处罚的，对直接负责的主管人员和其他直接责任人员依法给予降级、撤职或者开除的行政处分。"},{"i":15,"n":"第十五条","txt":"本办法自2002年9月1日起施行。"}],"shengwuliangyongpinjixiangguanshebeihejishuchukoug412b46":[{"i":1,"n":"第一条","txt":"为了加强对生物两用品及相关设备和技术出口的管制，维护国家安全和社会公共利益，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称生物两用品及相关设备和技术出口，是指本条例附件《生物两用品及相关设备和技术出口管制清单》（以下简称《管制清单》）所列的生物两用品及相关设备和技术的贸易性出口以及对外交流、交换、赠送、展览、援助、服务和以其他方式进行的技术转移。"},{"i":3,"n":"第三条","txt":"生物两用品及相关设备和技术出口应当遵守国家有关法律、行政法规和本条例规定，不得损害国家安全和社会公共利益。"},{"i":4,"n":"第四条","txt":"国家对生物两用品及相关设备和技术出口实行严格管制，防止《管制清单》所列的生物两用品及相关设备和技术用于生物武器目的。"},{"i":5,"n":"第五条","txt":"国家对《管制清单》所列的生物两用品及相关设备和技术出口实行许可制度。未经许可，任何单位或者个人不得出口《管制清单》所列的生物两用品及相关设备和技术。"},{"i":6,"n":"第六条","txt":"从事生物两用品及相关设备和技术出口的经营者，须经国务院对外经济贸易主管部门（以下简称国务院外经贸主管部门）登记。未经登记，任何单位或者个人不得经营生物两用品及相关设备和技术出口。具体登记办法由国务院外经贸主管部门规定。"},{"i":7,"n":"第七条","txt":"生物两用品及相关设备和技术出口的接受方应当保证："},{"i":8,"n":"第八条","txt":"出口《管制清单》所列的生物两用品及相关设备和技术，应当向国务院外经贸主管部门提出申请，填写生物两用品及相关设备和技术出口申请表（以下简称出口申请表），并提交下列文件："},{"i":9,"n":"第九条","txt":"申请人应当如实填写出口申请表。"},{"i":10,"n":"第十条","txt":"国务院外经贸主管部门应当自收到出口申请表和本条例第八条规定的文件之日起进行审查，或者会同有关部门进行审查。"},{"i":11,"n":"第十一条","txt":"对国家安全、社会公共利益有重大影响的生物两用品及相关设备和技术出口，国务院外经贸主管部门应当会同有关部门报国务院批准。"},{"i":12,"n":"第十二条","txt":"生物两用品及相关设备和技术出口申请经审查许可的，由国务院外经贸主管部门向申请人颁发生物两用品及相关设备和技术出口许可证件（以下简称出口许可证件），并书面通知海关。"},{"i":13,"n":"第十三条","txt":"出口许可证件持有人改变原申请的生物两用品及相关设备和技术出口的，应当交回原出口许可证件，并依照本条例的有关规定，重新申请出口许可。"},{"i":14,"n":"第十四条","txt":"生物两用品及相关设备和技术出口时，出口单位或者个人应当向海关出具出口许可证件，依照海关法的规定办理海关手续，并接受海关监管。"},{"i":15,"n":"第十五条","txt":"接受方违反其依照本条例第七条规定作出的保证，或者出现《管制清单》所列的可用于生物武器目的的生物两用品及相关设备和技术扩散的危险时，国务院外经贸主管部门应当对已经颁发的出口许可证件予以中止或者撤销，并书面通知海关。"},{"i":16,"n":"第十六条","txt":"任何单位或者个人知道或者应当知道所出口的生物两用品及相关设备和技术将被接受方直接用于生物武器目的的，无论该生物两用品及相关设备和技术是否列入《管制清单》，都不应当出口。"},{"i":17,"n":"第十七条","txt":"经国务院批准，国务院外经贸主管部门会同有关部门，可以临时决定对《管制清单》以外的特定生物两用品及相关设备和技术的出口依照本条例实施管制。"},{"i":18,"n":"第十八条","txt":"未经许可擅自出口生物两用品及相关设备和技术的，或者擅自超出许可的范围出口生物两用品及相关设备和技术的，依照刑法关于走私罪、非法经营罪、泄露国家秘密罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，区别不同情况，依照海关法的有关规定处罚，或者由国务院外经贸主管部门给予警告，没收违法所得，处5万元以上25万元以下的罚款；国务院外经贸主管部门并可以暂停直至撤销其对外贸易经营许可。"},{"i":19,"n":"第十九条","txt":"伪造、变造或者买卖生物两用品及相关设备和技术出口许可证件的，依照刑法关于非法经营罪或者伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任；尚不够刑事处罚的，依照海关法的有关规定处罚；国务院外经贸主管部门并可以撤销其对外贸易经营许可。"},{"i":20,"n":"第二十条","txt":"以欺骗或者其他不正当手段获取生物两用品及相关设备和技术出口许可证件的，由国务院外经贸主管部门收缴其出口许可证件，没收违法所得，处2万元以上10万元以下的罚款，暂停直至撤销其对外贸易经营许可。"},{"i":21,"n":"第二十一条","txt":"违反本条例第六条规定，未经登记擅自经营生物两用品及相关设备和技术出口的，由国务院外经贸主管部门依法取缔其非法活动，并由国家有关主管部门依照有关法律和行政法规的规定给予处罚。"},{"i":22,"n":"第二十二条","txt":"对生物两用品及相关设备和技术出口实施管制的国家工作人员滥用职权、玩忽职守或者利用职务上的便利索取、收受他人财物的，依照刑法关于滥用职权罪、玩忽职守罪、受贿罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。"},{"i":23,"n":"第二十三条","txt":"国务院外经贸主管部门会同有关部门，可以根据实际情况对《管制清单》进行调整，报国务院批准后执行。"},{"i":24,"n":"第二十四条","txt":"《管制清单》所列生物两用品及相关设备和技术进口后再出口的，适用本条例的规定。"},{"i":25,"n":"第二十五条","txt":"本条例自2002年12月1日起施行。"}],"shuilidianlibumendianceregongjiliangyibiaohezhuang874813":[],"shuiluhuowuyunshuhetongshishixize":[{"i":1,"n":"第一条","txt":"为了规范水路货物运输合同，根据有关法律，制定本细则。"},{"i":2,"n":"第二条","txt":"本细则所称水路运输是指中华人民共和国沿海、江河、湖泊以及其他通航水域中一切营业性的货物运输。"},{"i":3,"n":"第三条","txt":"水路货物运输合同，应贯彻优先运输国家指令性计划产品和急需物资，适当兼顾指导性计划产品和其他物资的原则，根据国家下达的产品调拨或购销计划和船舶运输、港口通过能力签订。"},{"i":4,"n":"第四条","txt":"水路货物运输合同，除短途驳运、摆渡零星货物，双方当事人可以即时清结者外，应当采用书面的形式。大宗物资运输，可按月签订货物运输合同。对其他按规定必须提送月度托运计划的货物，经托运人和承运人协商同意，可以按月签订货物运输合同或以货物运单作为运输合同。零星货物运输和计划外的整批货物运输，以货物运单作为运输合同。"},{"i":5,"n":"第五条","txt":"按月度签订的货物运输合同，经双方在合同上签认后，合同即告成立。如承、托运双方当事人无需商定特约事项的，可以用月度托运计划表代替运输合同，经双方在计划表上签认后，合同即告成立。在实际办理货物承托运手续时，托运人还应向承运人按批提出货物运单，作为运输合同的组成部分。"},{"i":6,"n":"第六条","txt":"按月度签订的货物运输合同，应具备下列基本内容："},{"i":7,"n":"第七条","txt":"货物运单应具备下列内容："},{"i":8,"n":"第八条","txt":"托运人应当承担下列义务："},{"i":9,"n":"第九条","txt":"承运人应当承担下列义务："},{"i":10,"n":"第十条","txt":"收货人应当承担下列义务："},{"i":11,"n":"第十一条","txt":"散装液体货物，只限于整船、整舱运输。装船前应由托运人验舱，合格后才能装运。托运人要求在两个以上地点装船或卸船，或在同一卸船地点由几个收货人接收货物时，其计量分劈工作及发生重量差数，由托运人和收货人自行处理。"},{"i":12,"n":"第十二条","txt":"拖带运输的货物，托运人应按规定提供被拖物的技术资料。承运人应当根据被拖物的技术资料和航道、气象等条件，调配适当的拖轮。在航行中，被拖物上的人员应听从拖轮船长的指挥，配合拖轮保证航行安全。"},{"i":13,"n":"第十三条","txt":"易腐货物和有生动植物，承、托运双方应预先商定容许的运到期限；采用冷藏设备船舶装运的，应商定冷藏温度。有生动植物在运输途中需要照料、饲养的，由托运人自行负责；随带的饲料免收运费，需用的淡水由承运人按规定提供。"},{"i":14,"n":"第十四条","txt":"遇有下列情况之一，应采取包船、包舱或租船运输："},{"i":15,"n":"第十五条","txt":"在已经开办集装箱运输的水运航线和海江河联运线路上，凡精密、易碎、价高及其他适于集装箱运输的物品，承、托运双方应采用集装箱运输。"},{"i":16,"n":"第十六条","txt":"承运人向收货人交付货物时应认真进行验收交接。按件承运的货物如发现货物有异状或与货物运单记载不符，按舱、按箱施封的货物如发现舱封、箱封有异状，收货人应即向承运人提出异议。收货人在验收交接时没有提出异议，并在提货单上签章后，运输合同即终止。"},{"i":17,"n":"第十七条","txt":"凡发生下列情况之一者，允许变更或解除月度货物运输合同："},{"i":18,"n":"第十八条","txt":"以货物运单作为运输合同的，允许按下列规定变更或解除运输合同："},{"i":19,"n":"第十九条","txt":"按月度签订的货物运输合同，承运人在履行时未配备足够的运力，应按落空的运量每吨偿付违约金1元；托运人在履行时未提供足够的货源，应按落空的货源每吨偿付违约金1元；运量与货源均有落空时，应按对等数量相互抵销违约金，偿付差额。"},{"i":20,"n":"第二十条","txt":"从承运货物时起，至货物交付收货人或依照规定处理完毕时止，货物发生灭失、短少、变质、污染、损坏，按下列规定赔偿："},{"i":21,"n":"第二十一条","txt":"由于下列原因造成货物灭失、短少、变质、污染、损坏的，承运人不承担赔偿责任："},{"i":22,"n":"第二十二条","txt":"如果托运人或收货人证明损失的发生确属承运人的故意行为，则承运人除按规定赔偿实际损失外，由合同管理机关处其造成损失部分10%到50%的罚款。"},{"i":23,"n":"第二十三条","txt":"由于承运人责任发生货物错运、错交，应无偿运回合同规定的到达港，交给指定的收货人。如由此发生逾期运到，应按本细则第二十四条规定偿付逾期违约金。"},{"i":24,"n":"第二十四条","txt":"承运人未按规定或约定的时间将货物运抵到达港，应按规定向收货人偿付违约金，但由于下列原因之一引起的滞延时间应从实际运到期限中扣除："},{"i":25,"n":"第二十五条","txt":"由于托运人责任发生下列事故，以致船舶、港口设备或波及其他货物的损坏、污染、腐蚀，或造成人身伤亡的，应由托运人负责赔偿："},{"i":26,"n":"第二十六条","txt":"由于托运人责任发生下列情况之一，应由托运人负责处理："},{"i":27,"n":"第二十七条","txt":"由于托运人或收货人责任发生下列情况之一，应由托运人或收货人承担有关的费用或违约金："},{"i":28,"n":"第二十八条","txt":"由于货物本身原因或应托运人要求，需要对货物、船舱、库场进行检疫、薰蒸、消毒的，应由托运人或收货人负责办理检疫、薰蒸、消毒并承担有关费用。"},{"i":29,"n":"第二十九条","txt":"承、托运双方对拖带运输的责任划分如下："},{"i":30,"n":"第三十条","txt":"由托运人自理装船或收货人自理卸船的货物，可以由承运人与托运人或收货人签订装卸合同，商定装卸时间和条件，实行船舶速遣和滞期奖罚办法。"},{"i":31,"n":"第三十一条","txt":"承运人与托运人或收货人彼此之间要求赔偿的时效，从货运记录交给托运人或收货人的次日起算不超过180日。赔偿要求应以书面形式提出，对方应在收到书面赔偿要求的次日起60日内处理。"},{"i":32,"n":"第三十二条","txt":"承运人和托运人或收货人在履行货物运输合同中发生纠纷，应协商解决。协商不成时，可向合同管理机关申请调解、仲裁，也可以直接向人民法院起诉。"},{"i":33,"n":"第三十三条","txt":"对行驶国际航线，香港、澳门航线的船舶及所载货物，在我国港口作业中发生的船体、船具或货物的灭失、损坏事故，不适用于本细则。"},{"i":34,"n":"第三十四条","txt":"本细则由交通部负责解释。"},{"i":35,"n":"第三十五条","txt":"本细则自1987年7月1日起施行。"}],"shuitubaochifashishitiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国水土保持法》（以下简称《水土保持法》）的规定，制定本条例。"},{"i":2,"n":"第二条","txt":"一切单位和个人都有权对有下列破坏水土资源、造成水土流失的行为之一的单位和个人，向县级以上人民政府水行政主管部门或者其他有关部门进行检举："},{"i":3,"n":"第三条","txt":"水土流失防治区的地方人民政府应当实行水土流失防治目标责任制。"},{"i":4,"n":"第四条","txt":"地方人民政府根据当地实际情况设立的水土保持机构，可以行使《水土保持法》和本条例规定的水行政主管部门对水土保持工作的职权。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将批准的水土保持规划确定的任务，纳入国民经济和社会发展计划，安排专项资金，组织实施，并可以按照有关规定，安排水土流失地区的部分扶贫资金、以工代赈资金和农业发展基金等资金，用于水土保持。"},{"i":6,"n":"第六条","txt":"水土流失重点防治区按国家、省、县三级划分，具体范围由县级以上人民政府水行政主管部门提出，报同级人民政府批准并公告。"},{"i":7,"n":"第七条","txt":"水土流失严重的省、自治区、直辖市，可以根据需要，设置水土保持中等专业学校或者在有关院校开设水土保持专业。中小学的有关课程，应当包含水土保持方面的内容。"},{"i":8,"n":"第八条","txt":"山区、丘陵区、风沙区的地方人民政府，对从事挖药材、养柞蚕、烧木炭、烧砖瓦等副业生产的单位和个人，必须根据水土保持的要求，加强管理，采取水土保持措施，防止水土流失和生态环境恶化。"},{"i":9,"n":"第九条","txt":"在水土流失严重、草场少的地区，地方人民政府及其有关主管部门应当采取措施，推行舍饲，改变野外放牧习惯。"},{"i":10,"n":"第十条","txt":"地方人民政府及其有关主管部门应当因地制宜，组织营造薪炭林，发展小水电、风力发电，发展沼气，利用太阳能，推广节能灶。"},{"i":11,"n":"第十一条","txt":"《水土保持法》施行前已在禁止开垦的陡坡地上开垦种植农作物的，应当在平地或者缓坡地建设基本农田，提高单位面积产量，将已开垦的陡坡耕地逐步退耕，植树种草；退耕确有困难的，由县级人民政府限期修成梯田，或者采取其他水土保持措施。"},{"i":12,"n":"第十二条","txt":"依法申请开垦荒坡地的，必须同时提出防止水土流失的措施，报县级人民政府水行政主管部门或者其所属的水土保持监督管理机构批准。"},{"i":13,"n":"第十三条","txt":"在林区采伐林木的，采伐方案中必须有采伐区水土保持措施。林业行政主管部门批准采伐方案后，应当将采伐方案抄送水行政主管部门，共同监督实施采伐区水土保持措施。"},{"i":14,"n":"第十四条","txt":"在山区、丘陵区、风沙区修建铁路、公路、水工程，开办矿山企业、电力企业和其他大中型工业企业，其环境影响报告书中的水土保持方案，必须先经水行政主管部门审查同意。"},{"i":15,"n":"第十五条","txt":"《水土保持法》施行前已建或者在建并造成水土流失的生产建设项目，生产建设单位必须向县级以上地方人民政府水行政主管部门提出水土流失防治措施。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府应当组织国有农场、林场、牧场和农业集体经济组织及农民，在禁止开垦坡度以下的坡耕地，按照水土保持规划，修筑水平梯田和蓄水保土工程，整治排水系统，治理水土流失。"},{"i":17,"n":"第十七条","txt":"水土流失地区的集体所有的土地承包给个人使用的，应当将治理水土流失的责任列入承包合同。当地乡、民族乡、镇的人民政府和农业集体经济组织应当监督承包合同的履行。"},{"i":18,"n":"第十八条","txt":"荒山、荒沟、荒丘、荒滩的水土流失，可以由农民个人、联户或者专业队承包治理，也可以由企业事业单位或者个人投资投劳入股治理。"},{"i":19,"n":"第十九条","txt":"企业事业单位在建设和生产过程中造成水土流失的，应当负责治理。因技术等原因无力自行治理的，可以交纳防治费，由水行政主管部门组织治理。防治费的收取标准和使用管理办法由省级以上人民政府财政部门、主管物价的部门会同水行政主管部门制定。"},{"i":20,"n":"第二十条","txt":"对水行政主管部门投资营造的水土保持林、水源涵养林和防风固沙林进行抚育和更新性质的采伐时，所提取的育林基金应当用于营造水土保持林、水源涵养林和防风固沙林。"},{"i":21,"n":"第二十一条","txt":"建成的水土保持设施和种植的林草，应当按照国家技术标准进行检查验收；验收合格的，应当建立档案，设立标志，落实管护责任制。"},{"i":22,"n":"第二十二条","txt":"《水土保持法》第二十九条所称水土保持监测网络，是指全国水土保持监测中心，大江大河流域水土保持中心站，省、自治区、直辖市水土保持监测站以及省、自治区、直辖市重点防治区水土保持监测分站。"},{"i":23,"n":"第二十三条","txt":"国务院水行政主管部门和省、自治区、直辖市人民政府水行政主管部门应当定期分别公告水土保持监测情况。公告应当包括下列事项："},{"i":24,"n":"第二十四条","txt":"有水土流失防治任务的企业事业单位，应当定期向县级以上地方人民政府水行政主管部门通报本单位水土流失防治工作的情况。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府水行政主管部门及其所属的水土保持监督管理机构，应当对《水土保持法》和本条例的执行情况实施监督检查。水土保持监督人员依法执行公务时，应当持有县级以上人民政府颁发的水土保持监督检查证件。"},{"i":26,"n":"第二十六条","txt":"依照《水土保持法》第三十二条的规定处以罚款的，罚款幅度为非法开垦的陡坡地每平方米1元至2元。"},{"i":27,"n":"第二十七条","txt":"依照《水土保持法》第三十三条的规定处以罚款的，罚款幅度为擅自开垦的荒坡地每平方米0.5元至1元。"},{"i":28,"n":"第二十八条","txt":"依照《水土保持法》第三十四条的规定处以罚款的，罚款幅度为500元以上、5000元以下。"},{"i":29,"n":"第二十九条","txt":"依照《水土保持法》第三十五条的规定处以罚款的，罚款幅度为造成的水土流失面积每平方米2元至5元。"},{"i":30,"n":"第三十条","txt":"依照《水土保持法》第三十六条的规定处以罚款的，罚款幅度为1000元以上、1万元以下。"},{"i":31,"n":"第三十一条","txt":"破坏水土保持设施，尚不够刑事处罚的，由公安机关依照《中华人民共和国治安管理处罚法》的有关规定予以处罚。"},{"i":32,"n":"第三十二条","txt":"依照《水土保持法》第三十九条第二款的规定，请求水行政主管部门处理赔偿责任和赔偿金额纠纷的，应当提出申请报告。申请报告应当包括下列事项："},{"i":33,"n":"第三十三条","txt":"由于发生不可抗拒的自然灾害而造成水土流失时，有关单位和个人应当向水行政主管部门报告不可抗拒的自然灾害的种类、程度、时间和已采取的措施等情况，经水行政主管部门查实并作出“不能避免造成水土流失危害”认定的，免予承担责任。"},{"i":34,"n":"第三十四条","txt":"本条例由国务院水行政主管部门负责解释。"},{"i":35,"n":"第三十五条","txt":"本条例自发布之日起施行。"}],"tankuangquancaikuangquanzhuanrangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对探矿权、采矿权转让的管理，保护探矿权人、采矿权人的合法权益，促进矿业发展，根据《中华人民共和国矿产资源法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域转让依法取得的探矿权、采矿权的，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"除按照下列规定可以转让外，探矿权、采矿权不得转让："},{"i":4,"n":"第四条","txt":"国务院地质矿产主管部门和省、自治区、直辖市人民政府地质矿产主管部门是探矿权、采矿权转让的审批管理机关。"},{"i":5,"n":"第五条","txt":"转让探矿权，应当具备下列条件："},{"i":6,"n":"第六条","txt":"转让采矿权，应当具备下列条件："},{"i":7,"n":"第七条","txt":"探矿权或者采矿权转让的受让人，应当符合《矿产资源勘查区块登记管理办法》或者《矿产资源开采登记管理办法》规定的有关探矿权申请人或者采矿权申请人的条件。"},{"i":8,"n":"第八条","txt":"探矿权人或者采矿权人在申请转让探矿权或者采矿权时，应当向审批管理机关提交下列资料："},{"i":9,"n":"第九条","txt":"转让国家出资勘查所形成的探矿权、采矿权的，必须进行评估。"},{"i":10,"n":"第十条","txt":"申请转让探矿权、采矿权的，审批管理机关应当自收到转让申请之日起40日内，作出准予转让或者不准转让的决定，并通知转让人和受让人。"},{"i":11,"n":"第十一条","txt":"审批管理机关批准转让探矿权、采矿权后，应当及时通知原发证机关。"},{"i":12,"n":"第十二条","txt":"探矿权、采矿权转让后，探矿权人、采矿权人的权利、义务随之转移。"},{"i":13,"n":"第十三条","txt":"探矿权、采矿权转让后，勘查许可证、采矿许可证的有效期限，为原勘查许可证、采矿许可证的有效期减去已经进行勘查、采矿的年限的剩余期限。"},{"i":14,"n":"第十四条","txt":"未经审批管理机关批准，擅自转让探矿权、采矿权的，由登记管理机关责令改正，没收违法所得，处10万元以下的罚款；情节严重的，由原发证机关吊销勘查许可证、采矿许可证。"},{"i":15,"n":"第十五条","txt":"违反本办法第三条第（二）项的规定，以承包等方式擅自将采矿权转给他人进行采矿的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令改正，没收违法所得，处10万元以下的罚款；情节严重的，由原发证机关吊销采矿许可证。"},{"i":16,"n":"第十六条","txt":"审批管理机关工作人员徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":17,"n":"第十七条","txt":"探矿权转让申请书、采矿权转让申请书的格式，由国务院地质矿产主管部门统一制定。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。"}],"tieluhuowuyunshuhetongshishixize":[{"i":1,"n":"第一条","txt":"为了规范铁路货物运输合同，根据有关法律，制定本细则。"},{"i":2,"n":"第二条","txt":"本细则所指铁路货物运输是中华人民共和国铁道部公布的营业铁路货物运输。"},{"i":3,"n":"第三条","txt":"托运人利用铁路运输货物，应与承运人签订货物运输合同。"},{"i":4,"n":"第四条","txt":"大宗物资的运输，有条件的可按年度、半年度或季度签订货物运输合同，也可以签订更长期限的运输合同；其他整车货物运输，应按月签订运输合同。按月度签订的运输合同，可以用月度要车计划表代替。"},{"i":5,"n":"第五条","txt":"按年度、半年度、季度或月度签订的货物运输合同，经双方在合同上签认后，合同即告成立。托运人在交运货物时，还应向承运人按批提出货物运单，作为运输合同的组成部分。"},{"i":6,"n":"第六条","txt":"按年度、半年度、季度或月度签订的货物运输合同，应载明下列基本内容："},{"i":7,"n":"第七条","txt":"货物运单应载明下列内容："},{"i":8,"n":"第八条","txt":"托运人应当承担下列义务："},{"i":9,"n":"第九条","txt":"承运人应当承担下列义务："},{"i":10,"n":"第十条","txt":"收货人应当承担下列义务："},{"i":11,"n":"第十一条","txt":"托运人托运个人搬家货物、行李每10千克价值在30元以上者，可声明价格，要求保价运输。承运人按保价运输办理时，按规定核收货物保价费。"},{"i":12,"n":"第十二条","txt":"托运人向承运人托运货物和承运人向收货人交付货物的时候，都应进行交接验收。如果发现货物（托运人组织装车的为封印、货物装载状态、篷布苫盖状态或规定标记）有异状或与货物运单记载不符，在承运时，应由托运人改善后接收；在交付时，收货人应即向承运人提出异议。收货人在验收货物的时候，没有提出异议，即认为运输合同履行完毕。"},{"i":13,"n":"第十三条","txt":"承运人在查找不到收货人或收货人拒绝领取货物时，除不宜于长期保管的货物外，从发出催领通知次日起30日内或从收货人拒绝领取货物时起3日内通知托运人。托运人自接到通知次日起，5日内提出处理办法答复承运人。超过期限，运输合同仍无法履行时，承运人有权按照有关规定处理。"},{"i":14,"n":"第十四条","txt":"因自然灾害，货物运输发生阻碍，承运人应当采取绕路运输或卸下再装措施。因货物性质特殊，绕路运输或卸下再装会造成货物损失时，承运人应联系托运人或收货人在要求的时间内提出处理办法。超过期限未答复时，承运人可比照本细则第十三条规定处理。"},{"i":15,"n":"第十五条","txt":"货物运输合同必须经双方同意，并在规定的变更范围内办理变更。"},{"i":16,"n":"第十六条","txt":"托运人或收货人由于特殊原因，经承运人同意，对承运后的货物可以按批在货物所在的途中站或到站办理变更到站、变更收货人，但属于下列情况，不得办理变更："},{"i":17,"n":"第十七条","txt":"货物运输合同在货物发送前，经双方同意，可以解除。"},{"i":18,"n":"第十八条","txt":"承运人的责任"},{"i":19,"n":"第十九条","txt":"托运人的责任"},{"i":20,"n":"第二十条","txt":"由于收货人原因招致运输工具、设备或第三者的货物损坏，由收货人按实际损失赔偿。"},{"i":21,"n":"第二十一条","txt":"货物运输合同遇有下列情况，承运人或托运人免除责任："},{"i":22,"n":"第二十二条","txt":"承运人同托运人或收货人相互间要求赔偿或退补费用的时效期限为180日（要求铁路支付运到期限违约金为60日）。"},{"i":23,"n":"第二十三条","txt":"承运人与托运人或收货人相互提出的赔偿要求，应自收到书面赔偿要求的次日起30日内（跨及两个铁路局以上运输的货物为60日内）进行处理，答复赔偿要求人。"},{"i":24,"n":"第二十四条","txt":"对货物运输合同的纠纷，承运人和托运人或收货人应协商解决。协商不一致时，任何一方均可向合同管理机关申请调解或仲裁，也可以直接向人民法院起诉。"},{"i":25,"n":"第二十五条","txt":"本细则由铁道部负责解释。"},{"i":26,"n":"第二十六条","txt":"本细则自1987年7月1日起施行。"}],"tuiyishibinganzhitiaoli":[{"i":1,"n":"第一条","txt":"为了规范退役士兵安置工作，保障退役士兵的合法权益，根据《中华人民共和国兵役法》，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称退役士兵，是指依照《中国人民解放军现役士兵服役条例》的规定退出现役的义务兵和士官。"},{"i":3,"n":"第三条","txt":"国家建立以扶持就业为主，自主就业、安排工作、退休、供养等多种方式相结合的退役士兵安置制度，妥善安置退役士兵。"},{"i":4,"n":"第四条","txt":"全社会应当尊重、优待退役士兵，支持退役士兵安置工作。"},{"i":5,"n":"第五条","txt":"国务院退役士兵安置工作主管部门负责全国的退役士兵安置工作。"},{"i":6,"n":"第六条","txt":"退役士兵应当遵守有关退役士兵安置的法律法规，服从人民政府的安置。"},{"i":7,"n":"第七条","txt":"对在退役士兵安置工作中作出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":8,"n":"第八条","txt":"国务院退役士兵安置工作主管部门和中国人民解放军总参谋部应当制定全国退役士兵的年度移交、接收计划。"},{"i":9,"n":"第九条","txt":"退役士兵所在部队应当依照本条例的规定，将退役士兵移交安置地县级以上人民政府退役士兵安置工作主管部门。安置地县级以上人民政府退役士兵安置工作主管部门负责接收退役士兵。"},{"i":10,"n":"第十条","txt":"退役士兵安置地为退役士兵入伍时的户口所在地。但是，入伍时是普通高等学校在校学生的退役士兵，退出现役后不复学的，其安置地为入学前的户口所在地。"},{"i":11,"n":"第十一条","txt":"退役士兵有下列情形之一的，可以易地安置："},{"i":12,"n":"第十二条","txt":"退役士兵有下列情形之一的，根据本人申请，可以由省级以上人民政府退役士兵安置工作主管部门按照有利于退役士兵生活的原则确定其安置地："},{"i":13,"n":"第十三条","txt":"自主就业的退役士兵应当自被批准退出现役之日起30日内，持退出现役证件、介绍信到安置地县级人民政府退役士兵安置工作主管部门报到。"},{"i":14,"n":"第十四条","txt":"退役士兵所在部队应当按照国家档案管理的有关规定，在士兵退役时将其档案及时移交安置地县级以上人民政府退役士兵安置工作主管部门。"},{"i":15,"n":"第十五条","txt":"自主就业和安排工作的退役士兵的档案，由安置地退役士兵安置工作主管部门按照国家档案管理有关规定办理。"},{"i":16,"n":"第十六条","txt":"退役士兵发生与服役有关的问题，由其原部队负责处理；发生与安置有关的问题，由安置地人民政府负责处理。"},{"i":17,"n":"第十七条","txt":"退役士兵无正当理由不按照规定时间报到超过30天的，视为放弃安置待遇。"},{"i":18,"n":"第十八条","txt":"义务兵和服现役不满12年的士官退出现役的，由人民政府扶持自主就业。"},{"i":19,"n":"第十九条","txt":"对自主就业的退役士兵，由部队发给一次性退役金，一次性退役金由中央财政专项安排；地方人民政府可以根据当地实际情况给予经济补助，经济补助标准及发放办法由省、自治区、直辖市人民政府规定。"},{"i":20,"n":"第二十条","txt":"国家根据国民经济发展水平、全国职工年平均工资收入和军人职业特殊性等因素确定退役金标准，并适时调整。国务院退役士兵安置工作主管部门、军队有关部门会同国务院财政部门负责确定和调整退役金标准的具体工作。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府退役士兵安置工作主管部门应当组织自主就业的退役士兵参加职业教育和技能培训，经考试考核合格的，发给相应的学历证书、职业资格证书并推荐就业。退役士兵退役1年内参加职业教育和技能培训的，费用由县级以上人民政府承担；退役士兵退役1年以上参加职业教育和技能培训的，按照国家相关政策执行。"},{"i":22,"n":"第二十二条","txt":"各级人民政府举办的公共就业人才服务机构，应当免费为退役士兵提供档案管理、职业介绍和职业指导服务。"},{"i":23,"n":"第二十三条","txt":"对从事个体经营的退役士兵，按照国家规定给予税收优惠，给予小额担保贷款扶持，从事微利项目的给予财政贴息。除国家限制行业外，自其在工商行政管理部门首次注册登记之日起3年内，免收管理类、登记类和证照类的行政事业性收费。"},{"i":24,"n":"第二十四条","txt":"国家鼓励用人单位招收录用或者聘用自主就业的退役士兵，用人单位招收录用或者聘用自主就业退役士兵符合规定条件的，依法享受税收等优惠。"},{"i":25,"n":"第二十五条","txt":"自主就业的退役士兵入伍前是国家机关、社会团体、企业事业单位工作人员或者职工的，退出现役后可以选择复职复工，其工资、福利和其他待遇不得低于本单位同等条件人员的平均水平。"},{"i":26,"n":"第二十六条","txt":"自主就业的退役士兵入伍前通过家庭承包方式承包的农村土地，承包期内不得违法收回或者强制流转；通过招标、拍卖、公开协商等非家庭承包方式承包的农村土地，承包期内其家庭成员可以继续承包；承包的农村土地被依法征收、征用或者占用的，与其他农村集体经济组织成员享有同等权利。"},{"i":27,"n":"第二十七条","txt":"有劳动能力的残疾退役士兵，优先享受国家规定的残疾人就业优惠政策。"},{"i":28,"n":"第二十八条","txt":"自主就业的退役士兵进入中等职业学校学习、报考成人高等学校或者普通高等学校的，按照国家有关规定享受优待。"},{"i":29,"n":"第二十九条","txt":"退役士兵符合下列条件之一的，由人民政府安排工作："},{"i":30,"n":"第三十条","txt":"国务院退役士兵安置工作主管部门和中国人民解放军总参谋部应当制定下达全国需由人民政府安排工作退役士兵的年度安置计划。"},{"i":31,"n":"第三十一条","txt":"中央国家机关及其管理的在京企业事业单位接收安排退役士兵工作任务，由国务院退役士兵安置工作主管部门下达。中央国家机关京外直属机构、中央国家机关管理的京外企业事业单位接收安排退役士兵工作任务，由所在地县级以上地方人民政府按照属地管理的原则下达。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府，应当根据符合安排工作条件的退役士兵人数和用人单位的实际情况，下达安排退役士兵工作的任务，并依法向社会公开。"},{"i":33,"n":"第三十三条","txt":"安置地县级以上地方人民政府应当按照属地管理的原则，对符合安排工作条件的退役士兵进行安置，保障其第一次就业。"},{"i":34,"n":"第三十四条","txt":"国家机关、事业单位、国有以及国有控股和国有资本占主导地位的企业招收录用或者聘用人员的，应当在同等条件下优先招收录用或者聘用退役士兵。"},{"i":35,"n":"第三十五条","txt":"安置地人民政府应当在接收退役士兵的6个月内，完成本年度安排退役士兵工作的任务。"},{"i":36,"n":"第三十六条","txt":"承担安排退役士兵工作任务的单位应当按时完成所在地人民政府下达的安排退役士兵工作任务，在退役士兵安置工作主管部门开出介绍信1个月内安排退役士兵上岗，并与退役士兵依法签订期限不少于3年的劳动合同或者聘用合同。"},{"i":37,"n":"第三十七条","txt":"由人民政府安排工作的退役士兵，服现役年限和符合本条例规定的待安排工作时间计算为工龄，享受所在单位同等条件人员的工资、福利待遇。"},{"i":38,"n":"第三十八条","txt":"非因退役士兵本人原因，接收单位未按照规定安排退役士兵上岗的，应当从所在地人民政府退役士兵安置工作主管部门开出介绍信的当月起，按照不低于本单位同等条件人员平均工资80%的标准逐月发给退役士兵生活费至其上岗为止。"},{"i":39,"n":"第三十九条","txt":"对安排工作的残疾退役士兵，所在单位不得因其残疾与其解除劳动关系或者人事关系。"},{"i":40,"n":"第四十条","txt":"符合安排工作条件的退役士兵无正当理由拒不服从安置地人民政府安排工作的，视为放弃安排工作待遇；在待安排工作期间被依法追究刑事责任的，取消其安排工作待遇。"},{"i":41,"n":"第四十一条","txt":"中级以上士官符合下列条件之一的，作退休安置："},{"i":42,"n":"第四十二条","txt":"被评定为1级至4级残疾等级的义务兵和初级士官退出现役的，由国家供养终身。"},{"i":43,"n":"第四十三条","txt":"因战、因公致残被评定为1级至4级残疾等级的中级以上士官，本人自愿放弃退休安置的，可以选择由国家供养。"},{"i":44,"n":"第四十四条","txt":"退役士兵服现役年限计算为工龄，与所在单位工作年限累计计算，享受国家和所在单位规定的与工龄有关的相应待遇。"},{"i":45,"n":"第四十五条","txt":"军队的军人保险管理部门与地方的社会保险经办机构，应当按照国家有关规定为退役士兵办理保险关系转移接续手续。"},{"i":46,"n":"第四十六条","txt":"退役士兵到城镇企业就业或者在城镇从事个体经营、以灵活方式就业的，按照国家有关规定参加职工基本养老保险，服现役年限视同职工基本养老保险缴费年限，并与实际缴费年限合并计算。退役士兵回农村的，按照国家有关规定参加新型农村社会养老保险。"},{"i":47,"n":"第四十七条","txt":"退役士兵到各类用人单位工作的，应当随所在单位参加职工基本医疗保险；以灵活方式就业或者暂未实现就业的，可以参加职工基本医疗保险、城镇居民基本医疗保险或者新型农村合作医疗。退役士兵参加基本医疗保险的，其军人退役医疗保险金，按照国家有关规定转入退役士兵安置地的社会保险经办机构。实行工龄视同参加基本医疗保险缴费年限规定的地区，退役士兵的服现役年限视同参保缴费年限。"},{"i":48,"n":"第四十八条","txt":"退役士兵就业应当随所在单位参加失业保险，其服现役年限视同失业保险缴费年限，并与实际缴费年限合并计算。参加失业保险的退役士兵失业，并符合《失业保险条例》规定条件的，按照规定享受失业保险待遇和相应的促进再就业服务。"},{"i":49,"n":"第四十九条","txt":"退役士兵安置工作主管部门及其工作人员、参与退役士兵安置工作的单位及其工作人员有下列行为之一的，由其上级主管部门责令改正，对相关责任人员依法给予处分；相关责任人员构成犯罪的，依法追究刑事责任："},{"i":50,"n":"第五十条","txt":"接收安置退役士兵的单位违反本条例的规定，有下列情形之一的，由当地人民政府退役士兵安置工作主管部门责令限期改正；逾期不改的，对国家机关、社会团体、事业单位主要负责人和直接责任人员依法给予处分，对企业按照涉及退役士兵人数乘以当地上年度城镇职工平均工资10倍的金额处以罚款，并对接收单位及其主要负责人予以通报批评："},{"i":51,"n":"第五十一条","txt":"退役士兵弄虚作假骗取安置待遇的，由安置地人民政府退役士兵安置工作主管部门取消相关安置待遇。"},{"i":52,"n":"第五十二条","txt":"本条例适用于中国人民武装警察部队。"},{"i":53,"n":"第五十三条","txt":"本条例自2011年11月1日起施行。"}],"waiguogongsichuanboyunshushouruzhengshuibanfa":[{"i":1,"n":"第一条","txt":"为了加强对外国公司以船舶从事国际海运业务从中国取得运输收入的税收管理，根据《中华人民共和国税收征收管理法》、《中华人民共和国营业税暂行条例》以及企业所得税相关法律的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"外国公司以船舶从中国港口运载旅客、货物或者邮件出境的，所取得的运输收入、所得，依照本办法缴纳营业税、企业所得税。"},{"i":3,"n":"第三条","txt":"外国公司以船舶从中国港口运载旅客、货物或者邮件出境的，取得运输收入的承运人为纳税人。纳税人包括："},{"i":4,"n":"第四条","txt":"纳税人的应纳税额，按照每次从中国港口运载旅客、货物或者邮件出境取得的收入总额，依照4.65%的综合计征率计征，其中营业税为3%，企业所得税为1.65%。"},{"i":5,"n":"第五条","txt":"本办法第四条所称收入总额，是指纳税人经营的船舶每次运载从中国港口始发旅客、货物或者邮件到达目的地的客运收入和货运收入的总和，不得扣除任何费用或者支出。客运收入包括船票收入以及逾重行李运费、餐费、保险费、服务费和娱乐费等。货运收入包括基本运费以及各项附加费等收入。"},{"i":6,"n":"第六条","txt":"外国公司以船舶到中国港口运载旅客、货物或者邮件出境的，在将承运人的地址、船舶悬挂的国旗、客运情况、运货种类、运量以及到港日期通知外轮代理人的同时，应当将运费率等通知外轮代理人。"},{"i":7,"n":"第七条","txt":"外国公司以船舶到中国港口运载旅客、货物或者邮件出境，委托外轮代理人计算并代收运费的，外轮代理人应当在收取运费后，按照本办法第四条规定的综合计征率，直接从纳税人的收入总额中代扣应纳税款。"},{"i":8,"n":"第八条","txt":"外国公司以船舶到中国港口运载旅客、货物或者邮件出境，不通过外轮代理人代收运费的，外轮代理人应当根据本办法第四条规定的综合计征率计算预计税款，并通知纳税人在船舶抵港前将预计税款与港口使用费备用金一并汇达，由外轮代理人代收税款。"},{"i":9,"n":"第九条","txt":"外轮代理人应当将按照本办法第七条、第八条规定代扣、代收的税款，自代扣代收之日起10日内，将实收税款缴入国库，并在次月15日前向港口所在地税务机关报送上月外轮代理业务情况一览表、运费结算情况统计报表、《代扣代缴、代收代缴外轮运输收入税收报告表》等资料。"},{"i":10,"n":"第十条","txt":"纳税人不能完整、准确地提供本办法第六条、第八条规定的资料，不能正确计算收入总额的，外轮代理人应当及时报告港口所在地税务机关。港口所在地税务机关可以会同外轮代理人，参照国际间相同或者类似情况下运载旅客或者货物的通常价格，或者根据我国有关部门制订的运费率表，核定纳税人的收入总额，并据以征税。"},{"i":11,"n":"第十一条","txt":"外国公司以同一艘船舶在中国几个港口运载旅客、货物或者邮件出境的，应当按照其在各港口运载旅客、货物或者邮件的运输收入，分别在各起运港征税。但是，同一艘程租船连续在中国几个港口运载货物或者邮件出境，其运费收入采取净包干方法的，全部运输收入应当在运载货物或者邮件的第一港口征税；采取包干运费并加收增港附加费方法的，其包干运费收入应当在运载货物或者邮件的第一港口征税，增港附加费收入应当分别在货物或者邮件起运港征税。"},{"i":12,"n":"第十二条","txt":"在中国港口运载旅客、货物或者邮件出境，经由另一国或者地区转运到目的地的，营业税按照纳税人全程运费减去付给后续运输企业运费后的余额计征，企业所得税按照提单全程运输收入总额计征。"},{"i":13,"n":"第十三条","txt":"外轮代理人按照本办法代扣、代收税款时，税务机关应当按照有关规定付给扣缴义务人代扣、代收手续费。"},{"i":14,"n":"第十四条","txt":"纳税人、扣缴义务人未按照本办法履行义务的，依照《中华人民共和国税收征收管理法》及其实施细则的有关规定处罚。"},{"i":15,"n":"第十五条","txt":"外轮代理人填报的《代扣代缴、代收代缴外轮运输收入税收报告表》由国家税务总局统一印制。"},{"i":16,"n":"第十六条","txt":"香港、澳门、台湾的公司以船舶从境内港口运载旅客、货物或者邮件出境的，所取得的运输收入、所得，除另有规定外，比照本办法征税。"},{"i":17,"n":"第十七条","txt":"中华人民共和国同外国缔结的有关协定规定减税或者免税的，按照协定规定执行。"},{"i":18,"n":"第十八条","txt":"外国公司以船舶到中国港口运载旅客、货物或者邮件出境，所取得的运输收入、所得，按照本办法第十七条规定的协定可以享受减税或者免税的，应当按照本办法第六条的规定提供有关情况，税务机关分别情况查验下列证明文件："},{"i":19,"n":"第十九条","txt":"本办法自发布之日起施行。经国务院批准、财政部1974年6月发布的《关于对外国籍轮船运输收入的征税规定》同时废止。"}],"waiguoqiyehuozhegerenzaizhongguojingneishelihehuoqa6fa5e":[{"i":1,"n":"第一条","txt":"为了规范外国企业或者个人在中国境内设立合伙企业的行为，便于外国企业或者个人以设立合伙企业的方式在中国境内投资，扩大对外经济合作和技术交流，根据《中华人民共和国合伙企业法》（以下称《合伙企业法》），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外国企业或者个人在中国境内设立合伙企业，是指2个以上外国企业或者个人在中国境内设立合伙企业，以及外国企业或者个人与中国的自然人、法人和其他组织在中国境内设立合伙企业。"},{"i":3,"n":"第三条","txt":"外国企业或者个人在中国境内设立合伙企业，应当遵守《合伙企业法》以及其他有关法律、行政法规、规章的规定，符合有关外商投资的产业政策。"},{"i":4,"n":"第四条","txt":"外国企业或者个人用于出资的货币应当是可自由兑换的外币，也可以是依法获得的人民币。"},{"i":5,"n":"第五条","txt":"外国企业或者个人在中国境内设立合伙企业，应当由全体合伙人指定的代表或者共同委托的代理人向国务院工商行政管理部门授权的地方工商行政管理部门（以下称企业登记机关）申请设立登记。"},{"i":6,"n":"第六条","txt":"外国企业或者个人在中国境内设立的合伙企业（以下称外商投资合伙企业）的登记事项发生变更的，应当依法向企业登记机关申请变更登记。"},{"i":7,"n":"第七条","txt":"外商投资合伙企业解散的，应当依照《合伙企业法》的规定进行清算。清算人应当自清算结束之日起15日内，依法向企业登记机关办理注销登记。"},{"i":8,"n":"第八条","txt":"外商投资合伙企业的外国合伙人全部退伙，该合伙企业继续存续的，应当依法向企业登记机关申请变更登记。"},{"i":9,"n":"第九条","txt":"外商投资合伙企业变更登记或者注销登记的，企业登记机关应当同时将有关变更登记或者注销登记的信息向同级商务主管部门通报。"},{"i":10,"n":"第十条","txt":"外商投资合伙企业的登记管理事宜，本办法未作规定的，依照《中华人民共和国合伙企业登记管理办法》和国家有关规定执行。"},{"i":11,"n":"第十一条","txt":"外国企业或者个人在中国境内设立合伙企业涉及的财务会计、税务、外汇以及海关、人员出入境等事宜，依照有关法律、行政法规和国家有关规定办理。"},{"i":12,"n":"第十二条","txt":"中国的自然人、法人和其他组织在中国境内设立的合伙企业，外国企业或者个人入伙的，应当符合本办法的有关规定，并依法向企业登记机关申请变更登记。"},{"i":13,"n":"第十三条","txt":"外国企业或者个人在中国境内设立合伙企业涉及须经政府核准的投资项目的，依照国家有关规定办理投资项目核准手续。"},{"i":14,"n":"第十四条","txt":"国家对外国企业或者个人在中国境内设立以投资为主要业务的合伙企业另有规定的，依照其规定。"},{"i":15,"n":"第十五条","txt":"香港特别行政区、澳门特别行政区和台湾地区的企业或者个人在内地设立合伙企业，参照本办法的规定执行。"},{"i":16,"n":"第十六条","txt":"本办法自2010年3月1日起施行。"}],"waiziqiyefashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国外资企业法》的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"外资企业受中国法律的管辖和保护。"},{"i":3,"n":"第三条","txt":"设立外资企业，必须有利于中国国民经济的发展，能够取得显著的经济效益。国家鼓励外资企业采用先进技术和设备，从事新产品开发，实现产品升级换代，节约能源和原材料，并鼓励举办产品出口的外资企业。"},{"i":4,"n":"第四条","txt":"禁止或者限制设立外资企业的行业，按照国家指导外商投资方向的规定及外商投资产业指导目录执行。"},{"i":5,"n":"第五条","txt":"申请设立外资企业，有下列情况之一的，不予批准："},{"i":6,"n":"第六条","txt":"外资企业在批准的经营范围内，自主经营管理，不受干涉。"},{"i":7,"n":"第七条","txt":"设立外资企业的申请，由中华人民共和国对外贸易经济合作部（以下简称对外贸易经济合作部）审查批准后，发给批准证书。"},{"i":8,"n":"第八条","txt":"申请设立的外资企业，其产品涉及出口许可证、出口配额、进口许可证或者属于国家限制进口的，应当依照有关管理权限事先征得对外经济贸易主管部门的同意。"},{"i":9,"n":"第九条","txt":"外国投资者在提出设立外资企业的申请前，应当就下列事项向拟设立外资企业所在地的县级或者县级以上地方人民政府提交报告。报告内容包括：设立外资企业的宗旨；经营范围、规模；生产产品；使用的技术设备；用地面积及要求；需要用水、电、煤、煤气或者其他能源的条件及数量；对公共设施的要求等。"},{"i":10,"n":"第十条","txt":"外国投资者设立外资企业，应当通过拟设立外资企业所在地的县级或者县级以上地方人民政府向审批机关提出申请，并报送下列文件："},{"i":11,"n":"第十一条","txt":"审批机关应当在收到申请设立外资企业的全部文件之日起90天内决定批准或者不批准。审批机关如果发现上述文件不齐备或者有不当之处，可以要求限期补报或者修改。"},{"i":12,"n":"第十二条","txt":"设立外资企业的申请经审批机关批准后，外国投资者应当在收到批准证书之日起30天内向工商行政管理机关申请登记，领取营业执照。外资企业的营业执照签发日期，为该企业成立日期。"},{"i":13,"n":"第十三条","txt":"外国投资者可以委托中国的外商投资企业服务机构或者其他经济组织代为办理本实施细则第八条、第九条第一款和第十条规定事宜，但须签订委托合同。"},{"i":14,"n":"第十四条","txt":"设立外资企业的申请书应当包括下列内容："},{"i":15,"n":"第十五条","txt":"外资企业的章程应当包括下列内容："},{"i":16,"n":"第十六条","txt":"外资企业的章程经审批机关批准后生效，修改时同。"},{"i":17,"n":"第十七条","txt":"外资企业的分立、合并或者由于其他原因导致资本发生重大变动，须经审批机关批准，并应当聘请中国的注册会计师验证和出具验资报告；经审批机关批准后，向工商行政管理机关办理变更登记手续。"},{"i":18,"n":"第十八条","txt":"外资企业的组织形式为有限责任公司。经批准也可以为其他责任形式。"},{"i":19,"n":"第十九条","txt":"外资企业的投资总额，是指开办外资企业所需资金总额，即按其生产规模需要投入的基本建设资金和生产流动资金的总和。"},{"i":20,"n":"第二十条","txt":"外资企业的注册资本，是指为设立外资企业在工商行政管理机关登记的资本总额，即外国投资者认缴的全部出资额。"},{"i":21,"n":"第二十一条","txt":"外资企业在经营期内不得减少其注册资本。但是，因投资总额和生产经营规模等发生变化，确需减少的，须经审批机关批准。"},{"i":22,"n":"第二十二条","txt":"外资企业注册资本的增加、转让，须经审批机关批准，并向工商行政管理机关办理变更登记手续。"},{"i":23,"n":"第二十三条","txt":"外资企业将其财产或者权益对外抵押、转让，须经审批机关批准并向工商行政管理机关备案。"},{"i":24,"n":"第二十四条","txt":"外资企业的法定代表人是依照其章程规定，代表外资企业行使职权的负责人。"},{"i":25,"n":"第二十五条","txt":"外国投资者可以用可自由兑换的外币出资，也可以用机器设备、工业产权、专有技术等作价出资。"},{"i":26,"n":"第二十六条","txt":"外国投资者以机器设备作价出资的，该机器设备应当是外资企业生产所必需的设备。"},{"i":27,"n":"第二十七条","txt":"外国投资者以工业产权、专有技术作价出资的，该工业产权、专有技术应当为外国投资者所有。"},{"i":28,"n":"第二十八条","txt":"作价出资的机器设备运抵中国口岸时，外资企业应当报请中国的商检机构进行检验，由该商检机构出具检验报告。"},{"i":29,"n":"第二十九条","txt":"作价出资的工业产权、专有技术实施后，审批机关有权进行检查。该工业产权、专有技术与外国投资者原提供的资料不符的，审批机关有权要求外国投资者限期改正。"},{"i":30,"n":"第三十条","txt":"外国投资者缴付出资的期限应当在设立外资企业申请书和外资企业章程中载明。"},{"i":31,"n":"第三十一条","txt":"外资企业的用地，由外资企业所在地的县级或者县级以上地方人民政府根据本地区的情况审核后，予以安排。"},{"i":32,"n":"第三十二条","txt":"外资企业应当在营业执照签发之日起30天内，持批准证书和营业执照到外资企业所在地县级或者县级以上地方人民政府的土地管理部门办理土地使用手续，领取土地证书。"},{"i":33,"n":"第三十三条","txt":"土地证书为外资企业使用土地的法律凭证。外资企业在经营期限内未经批准，其土地使用权不得转让。"},{"i":34,"n":"第三十四条","txt":"外资企业在领取土地证书时，应当向其所在地土地管理部门缴纳土地使用费。"},{"i":35,"n":"第三十五条","txt":"外资企业使用经过开发的土地，应当缴付土地开发费。"},{"i":36,"n":"第三十六条","txt":"外资企业使用未经开发的土地，可以自行开发或者委托中国有关单位开发。基础设施的建设，应当由外资企业所在地县级或者县级以上地方人民政府统一安排。"},{"i":37,"n":"第三十七条","txt":"外资企业的土地使用费和土地开发费的计收标准，依照中国有关规定办理。"},{"i":38,"n":"第三十八条","txt":"外资企业的土地使用年限，与经批准的该外资企业的经营期限相同。"},{"i":39,"n":"第三十九条","txt":"外资企业除依照本章规定取得土地使用权外，还可以依照中国其他法规的规定取得土地使用权。"},{"i":40,"n":"第四十条","txt":"外资企业有权自行决定购买本企业自用的机器设备、原材料、燃料、零部件、配套件、元器件、运输工具和办公用品等（以下统称“物资”）。"},{"i":41,"n":"第四十一条","txt":"外资企业可以在中国市场销售其产品。国家鼓励外资企业出口其生产的产品。"},{"i":42,"n":"第四十二条","txt":"外资企业有权自行出口本企业生产的产品，也可以委托中国的外贸公司代销或者委托中国境外的公司代销。"},{"i":43,"n":"第四十三条","txt":"外国投资者作为出资的机器设备，依照中国规定需要领取进口许可证的，外资企业凭批准的该企业进口设备和物资清单直接或者委托代理机构向发证机关申领进口许可证。"},{"i":44,"n":"第四十四条","txt":"外资企业进口的物资以及技术劳务的价格不得高于当时的国际市场同类物资以及技术劳务的正常价格。外资企业的出口产品价格，由外资企业参照当时的国际市场价格自行确定，但不得低于合理的出口价格。用高价进口、低价出口等方式逃避税收的，税务机关有权根据税法规定，追究其法律责任。"},{"i":45,"n":"第四十五条","txt":"外资企业应当依照《中华人民共和国统计法》及中国利用外资统计制度的规定，提供统计资料，报送统计报表。"},{"i":46,"n":"第四十六条","txt":"外资企业应当依照中国法律、法规的规定，缴纳税款。"},{"i":47,"n":"第四十七条","txt":"外资企业的职工应当依照中国法律、法规的规定，缴纳个人所得税。"},{"i":48,"n":"第四十八条","txt":"外资企业进口下列物资，依照中国税法的有关规定减税、免税："},{"i":49,"n":"第四十九条","txt":"外资企业生产的出口产品，除中国限制出口的以外，依照中国税法的有关规定减税、免税或者退税。"},{"i":50,"n":"第五十条","txt":"外资企业的外汇事宜，应当依照中国有关外汇管理的法规办理。"},{"i":51,"n":"第五十一条","txt":"外资企业凭工商行政管理机关发给的营业执照，在中国境内可以经营外汇业务的银行开立账户，由开户银行监督收付。"},{"i":52,"n":"第五十二条","txt":"外资企业因生产和经营需要在中国境外的银行开立外汇账户，须经中国外汇管理机关批准，并依照中国外汇管理机关的规定定期报告外汇收付情况和提供银行对账单。"},{"i":53,"n":"第五十三条","txt":"外资企业中的外籍职工和港澳台职工的工资和其他正当的外汇收益，依照中国税法纳税后，可以自由汇出。"},{"i":54,"n":"第五十四条","txt":"外资企业应当依照中国法律、法规和财政机关的规定，建立财务会计制度并报其所在地财政、税务机关备案。"},{"i":55,"n":"第五十五条","txt":"外资企业的会计年度自公历年的1月1日起至12月31日止。"},{"i":56,"n":"第五十六条","txt":"外资企业依照中国税法规定缴纳所得税后的利润，应当提取储备基金和职工奖励及福利基金。储备基金的提取比例不得低于税后利润的10%，当累计提取金额达到注册资本的50%时，可以不再提取。职工奖励及福利基金的提取比例由外资企业自行确定。"},{"i":57,"n":"第五十七条","txt":"外资企业的自制会计凭证、会计账簿和会计报表，应当用中文书写；用外文书写的，应当加注中文。"},{"i":58,"n":"第五十八条","txt":"外资企业应当独立核算。"},{"i":59,"n":"第五十九条","txt":"外国投资者可以聘请中国或者外国的会计人员查阅外资企业账簿，费用由外国投资者承担。"},{"i":60,"n":"第六十条","txt":"外资企业应当向财政、税务机关报送年度资产负债表和损益表，并报审批机关和工商行政管理机关备案。"},{"i":61,"n":"第六十一条","txt":"外资企业应当在企业所在地设置会计账簿，并接受财政、税务机关的监督。"},{"i":62,"n":"第六十二条","txt":"外资企业在中国境内雇用职工，企业和职工双方应当依照中国的法律、法规签订劳动合同。合同中应当订明雇用、辞退、报酬、福利、劳动保护、劳动保险等事项。"},{"i":63,"n":"第六十三条","txt":"外资企业应当负责职工的业务、技术培训，建立考核制度，使职工在生产、管理技能方面能够适应企业的生产与发展需要。"},{"i":64,"n":"第六十四条","txt":"外资企业的职工有权依照《中华人民共和国工会法》的规定，建立基层工会组织，开展工会活动。"},{"i":65,"n":"第六十五条","txt":"外资企业工会是职工利益的代表，有权代表职工同本企业签订劳动合同，并监督劳动合同的执行。"},{"i":66,"n":"第六十六条","txt":"外资企业工会的基本任务是：依照中国法律、法规的规定维护职工的合法权益，协助企业合理安排和使用职工福利、奖励基金；组织职工学习政治、科学技术和业务知识，开展文艺、体育活动；教育职工遵守劳动纪律，努力完成企业的各项经济任务。"},{"i":67,"n":"第六十七条","txt":"外资企业应当积极支持本企业工会的工作，依照《中华人民共和国工会法》的规定，为工会组织提供必要的房屋和设备，用于办公、会议、举办职工集体福利、文化、体育事业。外资企业每月按照企业职工实发工资总额的2%拨交工会经费，由本企业工会依照中华全国总工会制定的有关工会经费管理办法使用。"},{"i":68,"n":"第六十八条","txt":"外资企业的经营期限，根据不同行业和企业的具体情况，由外国投资者在设立外资企业的申请书中拟订，经审批机关批准。"},{"i":69,"n":"第六十九条","txt":"外资企业的经营期限，从其营业执照签发之日起计算。"},{"i":70,"n":"第七十条","txt":"外资企业有下列情形之一的，应予终止："},{"i":71,"n":"第七十一条","txt":"外资企业依照本实施细则第七十条第（一）、（二）、（三）、（六）项的规定终止的，应当在终止之日起15天内对外公告并通知债权人，并在终止公告发出之日起15天内，提出清算程序、原则和清算委员会人选，报审批机关审核后进行清算。"},{"i":72,"n":"第七十二条","txt":"清算委员会应当由外资企业的法定代表人、债权人代表以及有关主管机关的代表组成，并聘请中国的注册会计师、律师等参加。"},{"i":73,"n":"第七十三条","txt":"清算委员会行使下列职权："},{"i":74,"n":"第七十四条","txt":"外资企业在清算结束之前，外国投资者不得将该企业的资金汇出或者携出中国境外，不得自行处理企业的财产。"},{"i":75,"n":"第七十五条","txt":"外资企业清算结束，应当向工商行政管理机关办理注销登记手续，缴销营业执照。"},{"i":76,"n":"第七十六条","txt":"外资企业清算处理财产时，在同等条件下，中国的企业或者其他经济组织有优先购买权。"},{"i":77,"n":"第七十七条","txt":"外资企业依照本实施细则第七十条第（四）项的规定终止的，参照中国有关法律、法规进行清算。"},{"i":78,"n":"第七十八条","txt":"外资企业的各项保险，应当向中国境内的保险公司投保。"},{"i":79,"n":"第七十九条","txt":"外资企业与其他公司、企业或者经济组织以及个人签订合同，适用《中华人民共和国合同法》。"},{"i":80,"n":"第八十条","txt":"香港、澳门、台湾地区的公司、企业和其他经济组织或者个人以及在国外居住的中国公民在大陆设立全部资本为其所有的企业，参照本实施细则办理。"},{"i":81,"n":"第八十一条","txt":"外资企业中的外籍职工和港澳台职工可带进合理自用的交通工具和生活物品，并依照中国规定办理进口手续。"},{"i":82,"n":"第八十二条","txt":"本实施细则自公布之日起施行。"}],"xiangzhenmeikuangguanlitiaoli":[{"i":1,"n":"第一条","txt":"为了加强乡镇煤矿的行业管理，促进乡镇煤矿的健康发展，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称乡镇煤矿，是指在乡（镇）、村开办的集体煤矿企业、私营煤矿企业以及除国有煤矿企业和外商投资煤矿企业以外的其他煤矿企业。"},{"i":3,"n":"第三条","txt":"煤炭资源属于国家所有。地表或者地下的煤炭资源的国家所有权，不因其所依附的土地的所有权或者使用权的不同而改变。"},{"i":4,"n":"第四条","txt":"乡镇煤矿开采煤炭资源，必须依照有关法律、法规的规定，申请领取采矿许可证和安全生产许可证。"},{"i":5,"n":"第五条","txt":"国家扶持、指导和帮助乡镇煤矿的发展。"},{"i":6,"n":"第六条","txt":"乡镇煤矿开采煤炭资源，应当遵循开发与保护并重的原则，依法办矿，安全生产，文明生产。"},{"i":7,"n":"第七条","txt":"国务院煤炭工业主管部门和县级以上地方人民政府负责管理煤炭工业的部门是乡镇煤矿的行业管理部门（以下统称煤炭工业主管部门）。"},{"i":8,"n":"第八条","txt":"国务院煤炭工业主管部门和省、自治区、直辖市人民政府根据全国矿产资源规划编制行业开发规划和地区开发规划时，应当合理划定乡镇煤矿开采的煤炭资源范围。"},{"i":9,"n":"第九条","txt":"未经国务院煤炭工业主管部门批准，乡镇煤矿不得开采下列煤炭资源："},{"i":10,"n":"第十条","txt":"乡镇煤矿在国有煤矿企业矿区范围内开采边缘零星资源，必须征得该国有煤矿企业同意，并经其上级主管部门批准。"},{"i":11,"n":"第十一条","txt":"国家重点建设工程需要占用乡镇煤矿的生产井田时，占用单位应当按照国家有关规定给予合理补偿；但是，对违法开办的乡镇煤矿，不予补偿。"},{"i":12,"n":"第十二条","txt":"开办乡镇煤矿，必须具备下列条件："},{"i":13,"n":"第十三条","txt":"申请开办乡镇煤矿，由资源所在地的县级人民政府负责管理煤炭工业的部门审查申请人的办矿条件。"},{"i":14,"n":"第十四条","txt":"乡镇煤矿建成投产前，应当按照国务院关于安全生产许可证管理的规定，申请领取安全生产许可证。"},{"i":15,"n":"第十五条","txt":"乡镇煤矿开采煤炭资源，应当采用合理的开采顺序和科学的采矿方法，提高资源回采率和综合利用率，防止资源的浪费。"},{"i":16,"n":"第十六条","txt":"乡镇煤矿应当按照矿井当年的实际产量提取维简费。维简费的提取标准和使用范围按照国家有关规定执行。"},{"i":17,"n":"第十七条","txt":"乡镇煤矿应当按照国家有关矿山安全的法律、法规和煤炭行业安全规程、技术规范的要求，建立、健全各级安全生产责任制和安全规章制度。"},{"i":18,"n":"第十八条","txt":"县级、乡级人民政府应当加强对乡镇煤矿安全生产工作的监督管理，保证煤矿生产的安全。"},{"i":19,"n":"第十九条","txt":"国务院煤炭工业主管部门和县级以上地方人民政府负责管理煤炭工业的部门，应当有计划地对乡镇煤矿的职工进行安全教育和技术培训。"},{"i":20,"n":"第二十条","txt":"乡镇煤矿发生伤亡事故，应当按照有关法律、行政法规的规定，及时如实地向上一级人民政府、煤炭工业主管部门及其他有关主管部门报告，并立即采取有效措施，做好救护工作。"},{"i":21,"n":"第二十一条","txt":"乡镇煤矿应当及时测绘井上下工程对照图、采掘工程平面图和通风系统图，并定期向原审查办矿条件的煤炭工业主管部门报送图纸，接受其监督、检查。"},{"i":22,"n":"第二十二条","txt":"乡镇煤矿进行采矿作业，不得采用可能危及相邻煤矿生产安全的决水、爆破、贯通巷道等危险方法。"},{"i":23,"n":"第二十三条","txt":"乡镇煤矿依照有关法律、法规的规定办理关闭矿山手续时，应当向原审查办矿条件的煤炭工业主管部门提交有关采掘工程、不安全隐患等资料。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府劳动行政主管部门负责对乡镇煤矿安全工作的监督，并有权对取得矿长资格证书的矿长进行抽查。"},{"i":25,"n":"第二十五条","txt":"违反法律、法规关于矿山安全的规定，造成人身伤亡或者财产损失的，依照有关法律、法规的规定给予处罚。"},{"i":26,"n":"第二十六条","txt":"违反本条例规定，有下列情形之一的，由原审查办矿条件的煤炭工业主管部门，根据情节轻重，给予警告、5万元以下的罚款、没收违法所得或者责令停产整顿："},{"i":27,"n":"第二十七条","txt":"违反本条例规定，有下列情形之一的，由国务院煤炭工业主管部门或者由其授权的省、自治区、直辖市人民政府煤炭工业主管部门，根据情节轻重，分别给予警告、5万元以下的罚款、没收违法所得或者责令停止开采："},{"i":28,"n":"第二十八条","txt":"县级以上人民政府劳动行政主管部门经抽查发现取得矿长资格证书的矿长不合格的，应当责令限期达到规定条件；逾期仍不合格的，提请本级人民政府决定责令其所在煤矿停产。"},{"i":29,"n":"第二十九条","txt":"煤炭工业主管部门违反本条例规定，有下列情形之一的，对负有直接责任的主管人员和其他直接责任人员给予行政处分："},{"i":30,"n":"第三十条","txt":"依照本条例第二十六条、第二十七条规定取得的罚没收入，应当全部上缴国库。"},{"i":31,"n":"第三十一条","txt":"国务院煤炭工业主管部门可以根据本条例制定实施办法。"},{"i":32,"n":"第三十二条","txt":"本条例自发布之日起施行。"}],"xianjinguanlizanxingtiaoli":[{"i":1,"n":"第一条","txt":"为改善现金管理，促进商品生产和流通，加强对社会经济活动的监督，制定本条例。"},{"i":2,"n":"第二条","txt":"凡在银行和其他金融机构（以下简称开户银行）开立账户的机关、团体、部队、企业、事业单位和其他单位（以下简称开户单位），必须依照本条例的规定收支和使用现金，接受开户银行的监督。"},{"i":3,"n":"第三条","txt":"开户单位之间的经济往来，除按本条例规定的范围可以使用现金外，应当通过开户银行进行转账结算。"},{"i":4,"n":"第四条","txt":"各级人民银行应当严格履行金融主管机关的职责，负责对开户银行的现金管理进行监督和稽核。"},{"i":5,"n":"第五条","txt":"开户单位可以在下列范围内使用现金："},{"i":6,"n":"第六条","txt":"除本条例第五条第（五）、（六）项外，开户单位支付给个人的款项，超过使用现金限额的部分，应当以支票或者银行本票支付；确需全额支付现金的，经开户银行审核后，予以支付现金。"},{"i":7,"n":"第七条","txt":"转账结算凭证在经济往来中，具有同现金相同的支付能力。"},{"i":8,"n":"第八条","txt":"机关、团体、部队、全民所有制和集体所有制企业事业单位购置国家规定的专项控制商品，必须采取转账结算方式，不得使用现金。"},{"i":9,"n":"第九条","txt":"开户银行应当根据实际需要，核定开户单位3天至5天的日常零星开支所需的库存现金限额。"},{"i":10,"n":"第十条","txt":"经核定的库存现金限额，开户单位必须严格遵守。需要增加或者减少库存现金限额的，应当向开户银行提出申请，由开户银行核定。"},{"i":11,"n":"第十一条","txt":"开户单位现金收支应当依照下列规定办理："},{"i":12,"n":"第十二条","txt":"开户单位应当建立健全现金账目，逐笔记载现金支付。账目应当日清月结，账款相符。"},{"i":13,"n":"第十三条","txt":"对个体工商户、农村承包经营户发放的贷款，应当以转账方式支付。对确需在集市使用现金购买物资的，经开户银行审核后，可以在贷款金额内支付现金。"},{"i":14,"n":"第十四条","txt":"在开户银行开户的个体工商户、农村承包经营户异地采购所需货款，应当通过银行汇兑方式支付。因采购地点不固定，交通不便必须携带现金的，由开户银行根据实际需要，予以支付现金。"},{"i":15,"n":"第十五条","txt":"具备条件的银行应当接受开户单位的委托，开展代发工资、转存储蓄业务。"},{"i":16,"n":"第十六条","txt":"为保证开户单位的现金收入及时送存银行，开户银行必须按照规定做好现金收款工作，不得随意缩短收款时间。大中城市和商业比较集中的地区，应当建立非营业时间收款制度。"},{"i":17,"n":"第十七条","txt":"开户银行应当加强柜台审查，定期和不定期地对开户单位现金收支情况进行检查，并按规定向当地人民银行报告现金管理情况。"},{"i":18,"n":"第十八条","txt":"一个单位在几家银行开户的，由一家开户银行负责现金管理工作，核定开户单位库存现金限额。"},{"i":19,"n":"第十九条","txt":"开户银行应当建立健全现金管理制度，配备专职人员，改进工作作风，改善服务设施。现金管理工作所需经费应当在开户银行业务费中解决。"},{"i":20,"n":"第二十条","txt":"开户单位有下列情形之一的，开户银行应当依照中国人民银行的规定，责令其停止违法活动，并可根据情节轻重处以罚款："},{"i":21,"n":"第二十一条","txt":"开户单位有下列情形之一的，开户银行应当依照中国人民银行的规定，予以警告或者罚款；情节严重的，可在一定期限内停止对该单位的贷款或者停止对该单位的现金支付："},{"i":22,"n":"第二十二条","txt":"开户单位对开户银行作出的处罚决定不服的，必须首先按照处罚决定执行，然后可在10日内向开户银行的同级人民银行申请复议。同级人民银行应当在收到复议申请之日起30日内作出复议决定。开户单位对复议决定不服的，可以在收到复议决定之日起30日内向人民法院起诉。（2011年1月8日删除）"},{"i":23,"n":"第二十三条","txt":"银行工作人员违反本条例规定，徇私舞弊、贪污受贿、玩忽职守纵容违法行为的，应当根据情节轻重，给予行政处分和经济处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本条例由中国人民银行负责解释；施行细则由中国人民银行制定。"},{"i":25,"n":"第二十五条","txt":"本条例自1988年10月1日起施行。1977年11月28日发布的《国务院关于实行现金管理的决定》同时废止。"}],"xinfangtiaoli":[{"i":1,"n":"第一条","txt":"为了保持各级人民政府同人民群众的密切联系，保护信访人的合法权益，维护信访秩序，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称信访，是指公民、法人或者其他组织采用书信、电子邮件、传真、电话、走访等形式，向各级人民政府、县级以上人民政府工作部门反映情况，提出建议、意见或者投诉请求，依法由有关行政机关处理的活动。"},{"i":3,"n":"第三条","txt":"各级人民政府、县级以上人民政府工作部门应当做好信访工作，认真处理来信、接待来访，倾听人民群众的意见、建议和要求，接受人民群众的监督，努力为人民群众服务。"},{"i":4,"n":"第四条","txt":"信访工作应当在各级人民政府领导下，坚持属地管理、分级负责，谁主管、谁负责，依法、及时、就地解决问题与疏导教育相结合的原则。"},{"i":5,"n":"第五条","txt":"各级人民政府、县级以上人民政府工作部门应当科学、民主决策，依法履行职责，从源头上预防导致信访事项的矛盾和纠纷。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当设立信访工作机构；县级以上人民政府工作部门及乡、镇人民政府应当按照有利工作、方便信访人的原则，确定负责信访工作的机构（以下简称信访工作机构）或者人员，具体负责信访工作。"},{"i":7,"n":"第七条","txt":"各级人民政府应当建立健全信访工作责任制，对信访工作中的失职、渎职行为，严格依照有关法律、行政法规和本条例的规定，追究有关责任人员的责任，并在一定范围内予以通报。"},{"i":8,"n":"第八条","txt":"信访人反映的情况，提出的建议、意见，对国民经济和社会发展或者对改进国家机关工作以及保护社会公共利益有贡献的，由有关行政机关或者单位给予奖励。"},{"i":9,"n":"第九条","txt":"各级人民政府、县级以上人民政府工作部门应当向社会公布信访工作机构的通信地址、电子信箱、投诉电话、信访接待的时间和地点、查询信访事项处理进展及结果的方式等相关事项。"},{"i":10,"n":"第十条","txt":"设区的市级、县级人民政府及其工作部门，乡、镇人民政府应当建立行政机关负责人信访接待日制度，由行政机关负责人协调处理信访事项。信访人可以在公布的接待日和接待地点向有关行政机关负责人当面反映信访事项。"},{"i":11,"n":"第十一条","txt":"国家信访工作机构充分利用现有政务信息网络资源，建立全国信访信息系统，为信访人在当地提出信访事项、查询信访事项办理情况提供便利。"},{"i":12,"n":"第十二条","txt":"县级以上各级人民政府的信访工作机构或者有关工作部门应当及时将信访人的投诉请求输入信访信息系统，信访人可以持行政机关出具的投诉请求受理凭证到当地人民政府的信访工作机构或者有关工作部门的接待场所查询其所提出的投诉请求的办理情况。具体实施办法和步骤由省、自治区、直辖市人民政府规定。"},{"i":13,"n":"第十三条","txt":"设区的市、县两级人民政府可以根据信访工作的实际需要，建立政府主导、社会参与、有利于迅速解决纠纷的工作机制。"},{"i":14,"n":"第十四条","txt":"信访人对下列组织、人员的职务行为反映情况，提出建议、意见，或者不服下列组织、人员的职务行为，可以向有关行政机关提出信访事项："},{"i":15,"n":"第十五条","txt":"信访人对各级人民代表大会以及县级以上各级人民代表大会常务委员会、人民法院、人民检察院职权范围内的信访事项，应当分别向有关的人民代表大会及其常务委员会、人民法院、人民检察院提出，并遵守本条例第十六条、第十七条、第十八条、第十九条、第二十条的规定。"},{"i":16,"n":"第十六条","txt":"信访人采用走访形式提出信访事项，应当向依法有权处理的本级或者上一级机关提出；信访事项已经受理或者正在办理的，信访人在规定期限内向受理、办理机关的上级机关再提出同一信访事项的，该上级机关不予受理。"},{"i":17,"n":"第十七条","txt":"信访人提出信访事项，一般应当采用书信、电子邮件、传真等书面形式；信访人提出投诉请求的，还应当载明信访人的姓名（名称）、住址和请求、事实、理由。"},{"i":18,"n":"第十八条","txt":"信访人采用走访形式提出信访事项的，应当到有关机关设立或者指定的接待场所提出。"},{"i":19,"n":"第十九条","txt":"信访人提出信访事项，应当客观真实，对其所提供材料内容的真实性负责，不得捏造、歪曲事实，不得诬告、陷害他人。"},{"i":20,"n":"第二十条","txt":"信访人在信访过程中应当遵守法律、法规，不得损害国家、社会、集体的利益和其他公民的合法权利，自觉维护社会公共秩序和信访秩序，不得有下列行为："},{"i":21,"n":"第二十一条","txt":"县级以上人民政府信访工作机构收到信访事项，应当予以登记，并区分情况，在15日内分别按下列方式处理："},{"i":22,"n":"第二十二条","txt":"信访人按照本条例规定直接向各级人民政府信访工作机构以外的行政机关提出的信访事项，有关行政机关应当予以登记；对符合本条例第十四条第一款规定并属于本机关法定职权范围的信访事项，应当受理，不得推诿、敷衍、拖延；对不属于本机关职权范围的信访事项，应当告知信访人向有权的机关提出。"},{"i":23,"n":"第二十三条","txt":"行政机关及其工作人员不得将信访人的检举、揭发材料及有关情况透露或者转给被检举、揭发的人员或者单位。"},{"i":24,"n":"第二十四条","txt":"涉及两个或者两个以上行政机关的信访事项，由所涉及的行政机关协商受理；受理有争议的，由其共同的上一级行政机关决定受理机关。"},{"i":25,"n":"第二十五条","txt":"应当对信访事项作出处理的行政机关分立、合并、撤销的，由继续行使其职权的行政机关受理；职责不清的，由本级人民政府或者其指定的机关受理。"},{"i":26,"n":"第二十六条","txt":"公民、法人或者其他组织发现可能造成社会影响的重大、紧急信访事项和信访信息时，可以就近向有关行政机关报告。地方各级人民政府接到报告后，应当立即报告上一级人民政府；必要时，通报有关主管部门。县级以上地方人民政府有关部门接到报告后，应当立即报告本级人民政府和上一级主管部门；必要时，通报有关主管部门。国务院有关部门接到报告后，应当立即报告国务院；必要时，通报有关主管部门。"},{"i":27,"n":"第二十七条","txt":"对于可能造成社会影响的重大、紧急信访事项和信访信息，有关行政机关应当在职责范围内依法及时采取措施，防止不良影响的产生、扩大。"},{"i":28,"n":"第二十八条","txt":"行政机关及其工作人员办理信访事项，应当恪尽职守、秉公办事，查明事实、分清责任，宣传法制、教育疏导，及时妥善处理，不得推诿、敷衍、拖延。"},{"i":29,"n":"第二十九条","txt":"信访人反映的情况，提出的建议、意见，有利于行政机关改进工作、促进国民经济和社会发展的，有关行政机关应当认真研究论证并积极采纳。"},{"i":30,"n":"第三十条","txt":"行政机关工作人员与信访事项或者信访人有直接利害关系的，应当回避。"},{"i":31,"n":"第三十一条","txt":"对信访事项有权处理的行政机关办理信访事项，应当听取信访人陈述事实和理由；必要时可以要求信访人、有关组织和人员说明情况；需要进一步核实有关情况的，可以向其他组织和人员调查。"},{"i":32,"n":"第三十二条","txt":"对信访事项有权处理的行政机关经调查核实，应当依照有关法律、法规、规章及其他有关规定，分别作出以下处理，并书面答复信访人："},{"i":33,"n":"第三十三条","txt":"信访事项应当自受理之日起60日内办结；情况复杂的，经本行政机关负责人批准，可以适当延长办理期限，但延长期限不得超过30日，并告知信访人延期理由。法律、行政法规另有规定的，从其规定。"},{"i":34,"n":"第三十四条","txt":"信访人对行政机关作出的信访事项处理意见不服的，可以自收到书面答复之日起30日内请求原办理行政机关的上一级行政机关复查。收到复查请求的行政机关应当自收到复查请求之日起30日内提出复查意见，并予以书面答复。"},{"i":35,"n":"第三十五条","txt":"信访人对复查意见不服的，可以自收到书面答复之日起30日内向复查机关的上一级行政机关请求复核。收到复核请求的行政机关应当自收到复核请求之日起30日内提出复核意见。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府信访工作机构发现有关行政机关有下列情形之一的，应当及时督办，并提出改进建议："},{"i":37,"n":"第三十七条","txt":"县级以上人民政府信访工作机构对于信访人反映的有关政策性问题，应当及时向本级人民政府报告，并提出完善政策、解决问题的建议。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府信访工作机构对在信访工作中推诿、敷衍、拖延、弄虚作假造成严重后果的行政机关工作人员，可以向有关行政机关提出给予行政处分的建议。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府信访工作机构应当就以下事项向本级人民政府定期提交信访情况分析报告："},{"i":40,"n":"第四十条","txt":"因下列情形之一导致信访事项发生，造成严重后果的，对直接负责的主管人员和其他直接责任人员，依照有关法律、行政法规的规定给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":41,"n":"第四十一条","txt":"县级以上人民政府信访工作机构对收到的信访事项应当登记、转送、交办而未按规定登记、转送、交办，或者应当履行督办职责而未履行的，由其上级行政机关责令改正；造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":42,"n":"第四十二条","txt":"负有受理信访事项职责的行政机关在受理信访事项过程中违反本条例的规定，有下列情形之一的，由其上级行政机关责令改正；造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":43,"n":"第四十三条","txt":"对信访事项有权处理的行政机关在办理信访事项过程中，有下列行为之一的，由其上级行政机关责令改正；造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":44,"n":"第四十四条","txt":"行政机关工作人员违反本条例规定，将信访人的检举、揭发材料或者有关情况透露、转给被检举、揭发的人员或者单位的，依法给予行政处分。"},{"i":45,"n":"第四十五条","txt":"行政机关及其工作人员违反本条例第二十六条规定，对可能造成社会影响的重大、紧急信访事项和信访信息，隐瞒、谎报、缓报，或者授意他人隐瞒、谎报、缓报，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"打击报复信访人，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分或者纪律处分。"},{"i":47,"n":"第四十七条","txt":"违反本条例第十八条、第二十条规定的，有关国家机关工作人员应当对信访人进行劝阻、批评或者教育。"},{"i":48,"n":"第四十八条","txt":"信访人捏造歪曲事实、诬告陷害他人，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关依法给予治安管理处罚。"},{"i":49,"n":"第四十九条","txt":"社会团体、企业事业单位的信访工作参照本条例执行。"},{"i":50,"n":"第五十条","txt":"对外国人、无国籍人、外国组织信访事项的处理，参照本条例执行。"},{"i":51,"n":"第五十一条","txt":"本条例自2005年5月1日起施行。1995年10月28日国务院发布的《信访条例》同时废止。"}],"xingzhengjiguangongwuyuanchufentiaoli":[{"i":1,"n":"第一条","txt":"为了严肃行政机关纪律，规范行政机关公务员的行为，保证行政机关及其公务员依法履行职责，根据《中华人民共和国公务员法》和《中华人民共和国行政监察法》，制定本条例。"},{"i":2,"n":"第二条","txt":"行政机关公务员违反法律、法规、规章以及行政机关的决定和命令，应当承担纪律责任的，依照本条例给予处分。"},{"i":3,"n":"第三条","txt":"行政机关公务员依法履行职务的行为受法律保护，非因法定事由，非经法定程序，不受处分。"},{"i":4,"n":"第四条","txt":"给予行政机关公务员处分，应当坚持公正、公平和教育与惩处相结合的原则。"},{"i":5,"n":"第五条","txt":"行政机关公务员违法违纪涉嫌犯罪的，应当移送司法机关依法追究刑事责任。"},{"i":6,"n":"第六条","txt":"行政机关公务员处分的种类为："},{"i":7,"n":"第七条","txt":"行政机关公务员受处分的期间为："},{"i":8,"n":"第八条","txt":"行政机关公务员在受处分期间不得晋升职务和级别，其中，受记过、记大过、降级、撤职处分的，不得晋升工资档次；受撤职处分的，应当按照规定降低级别。"},{"i":9,"n":"第九条","txt":"行政机关公务员受开除处分的，自处分决定生效之日起，解除其与单位的人事关系，不得再担任公务员职务。"},{"i":10,"n":"第十条","txt":"行政机关公务员同时有两种以上需要给予处分的行为的，应当分别确定其处分。应当给予的处分种类不同的，执行其中最重的处分；应当给予撤职以下多个相同种类处分的，执行该处分，并在一个处分期以上、多个处分期之和以下，决定处分期。"},{"i":11,"n":"第十一条","txt":"行政机关公务员2人以上共同违法违纪，需要给予处分的，根据各自应当承担的纪律责任，分别给予处分。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，应当从重处分："},{"i":13,"n":"第十三条","txt":"有下列情形之一的，应当从轻处分："},{"i":14,"n":"第十四条","txt":"行政机关公务员主动交代违法违纪行为，并主动采取措施有效避免或者挽回损失的，应当减轻处分。"},{"i":15,"n":"第十五条","txt":"行政机关公务员有本条例第十二条、第十三条规定情形之一的，应当在本条例第三章规定的处分幅度以内从重或者从轻给予处分。"},{"i":16,"n":"第十六条","txt":"行政机关经人民法院、监察机关、行政复议机关或者上级行政机关依法认定有行政违法行为或者其他违法违纪行为，需要追究纪律责任的，对负有责任的领导人员和直接责任人员给予处分。"},{"i":17,"n":"第十七条","txt":"违法违纪的行政机关公务员在行政机关对其作出处分决定前，已经依法被判处刑罚、罢免、免职或者已经辞去领导职务，依法应当给予处分的，由行政机关根据其违法违纪事实，给予处分。"},{"i":18,"n":"第十八条","txt":"有下列行为之一的，给予记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":19,"n":"第十九条","txt":"有下列行为之一的，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":20,"n":"第二十条","txt":"有下列行为之一的，给予记过、记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":21,"n":"第二十一条","txt":"有下列行为之一的，给予警告或者记过处分；情节较重的，给予记大过或者降级处分；情节严重的，给予撤职处分："},{"i":22,"n":"第二十二条","txt":"弄虚作假，误导、欺骗领导和公众，造成不良后果的，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分。"},{"i":23,"n":"第二十三条","txt":"有贪污、索贿、受贿、行贿、介绍贿赂、挪用公款、利用职务之便为自己或者他人谋取私利、巨额财产来源不明等违反廉政纪律行为的，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分。"},{"i":24,"n":"第二十四条","txt":"违反财经纪律，挥霍浪费国家资财的，给予警告处分；情节较重的，给予记过或者记大过处分；情节严重的，给予降级或者撤职处分。"},{"i":25,"n":"第二十五条","txt":"有下列行为之一的，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":26,"n":"第二十六条","txt":"泄露国家秘密、工作秘密，或者泄露因履行职责掌握的商业秘密、个人隐私，造成不良后果的，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分。"},{"i":27,"n":"第二十七条","txt":"从事或者参与营利性活动，在企业或者其他营利性组织中兼任职务的，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分。"},{"i":28,"n":"第二十八条","txt":"严重违反公务员职业道德，工作作风懈怠、工作态度恶劣，造成不良影响的，给予警告、记过或者记大过处分。"},{"i":29,"n":"第二十九条","txt":"有下列行为之一的，给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":30,"n":"第三十条","txt":"参与迷信活动，造成不良影响的，给予警告、记过或者记大过处分；组织迷信活动的，给予降级或者撤职处分，情节严重的，给予开除处分。"},{"i":31,"n":"第三十一条","txt":"吸食、注射毒品或者组织、支持、参与卖淫、嫖娼、色情淫乱活动的，给予撤职或者开除处分。"},{"i":32,"n":"第三十二条","txt":"参与赌博的，给予警告或者记过处分；情节较重的，给予记大过或者降级处分；情节严重的，给予撤职或者开除处分。"},{"i":33,"n":"第三十三条","txt":"违反规定超计划生育的，给予降级或者撤职处分；情节严重的，给予开除处分。"},{"i":34,"n":"第三十四条","txt":"对行政机关公务员给予处分，由任免机关或者监察机关（以下统称处分决定机关）按照管理权限决定。"},{"i":35,"n":"第三十五条","txt":"对经全国人民代表大会及其常务委员会决定任命的国务院组成人员给予处分，由国务院决定。其中，拟给予撤职、开除处分的，由国务院向全国人民代表大会提出罢免建议，或者向全国人民代表大会常务委员会提出免职建议。罢免或者免职前，国务院可以决定暂停其履行职务。"},{"i":36,"n":"第三十六条","txt":"对经地方各级人民代表大会及其常务委员会选举或者决定任命的地方各级人民政府领导人员给予处分，由上一级人民政府决定。"},{"i":37,"n":"第三十七条","txt":"对地方各级人民政府工作部门正职领导人员给予处分，由本级人民政府决定。其中，拟给予撤职、开除处分的，由本级人民政府向同级人民代表大会常务委员会提出免职建议。免去职务前，本级人民政府或者上级人民政府可以决定暂停其履行职务。"},{"i":38,"n":"第三十八条","txt":"行政机关公务员违法违纪，已经被立案调查，不宜继续履行职责的，任免机关可以决定暂停其履行职务。"},{"i":39,"n":"第三十九条","txt":"任免机关对涉嫌违法违纪的行政机关公务员的调查、处理，按照下列程序办理："},{"i":40,"n":"第四十条","txt":"监察机关对违法违纪的行政机关公务员的调查、处理，依照《中华人民共和国行政监察法》规定的程序办理。"},{"i":41,"n":"第四十一条","txt":"对行政机关公务员违法违纪案件进行调查，应当由2名以上办案人员进行；接受调查的单位和个人应当如实提供情况。"},{"i":42,"n":"第四十二条","txt":"参与行政机关公务员违法违纪案件调查、处理的人员有下列情形之一的，应当提出回避申请；被调查的公务员以及与案件有利害关系的公民、法人或者其他组织有权要求其回避："},{"i":43,"n":"第四十三条","txt":"处分决定机关负责人的回避，由处分决定机关的上一级行政机关负责人决定；其他违法违纪案件调查、处理人员的回避，由处分决定机关负责人决定。"},{"i":44,"n":"第四十四条","txt":"给予行政机关公务员处分，应当自批准立案之日起6个月内作出决定；案情复杂或者遇有其他特殊情形的，办案期限可以延长，但是最长不得超过12个月。"},{"i":45,"n":"第四十五条","txt":"处分决定应当包括下列内容："},{"i":46,"n":"第四十六条","txt":"处分决定、解除处分决定自作出之日起生效。"},{"i":47,"n":"第四十七条","txt":"行政机关公务员受到开除处分后，有新工作单位的，其本人档案转由新工作单位管理；没有新工作单位的，其本人档案转由其户籍所在地人事部门所属的人才服务机构管理。"},{"i":48,"n":"第四十八条","txt":"受到处分的行政机关公务员对处分决定不服的，依照《中华人民共和国公务员法》和《中华人民共和国行政监察法》的有关规定，可以申请复核或者申诉。"},{"i":49,"n":"第四十九条","txt":"有下列情形之一的，受理公务员复核、申诉的机关应当撤销处分决定，重新作出决定或者责令原处分决定机关重新作出决定："},{"i":50,"n":"第五十条","txt":"有下列情形之一的，受理公务员复核、申诉的机关应当变更处分决定，或者责令原处分决定机关变更处分决定："},{"i":51,"n":"第五十一条","txt":"行政机关公务员的处分决定被变更，需要调整该公务员的职务、级别或者工资档次的，应当按照规定予以调整；行政机关公务员的处分决定被撤销的，应当恢复该公务员的级别、工资档次，按照原职务安排相应的职务，并在适当范围内为其恢复名誉。"},{"i":52,"n":"第五十二条","txt":"有违法违纪行为应当受到处分的行政机关公务员，在处分决定机关作出处分决定前已经退休的，不再给予处分；但是，依法应当给予降级、撤职、开除处分的，应当按照规定相应降低或者取消其享受的待遇。"},{"i":53,"n":"第五十三条","txt":"行政机关公务员违法违纪取得的财物和用于违法违纪的财物，除依法应当由其他机关没收、追缴或者责令退赔的，由处分决定机关没收、追缴或者责令退赔。违法违纪取得的财物应当退还原所有人或者原持有人的，退还原所有人或者原持有人；属于国家财产以及不应当退还或者无法退还原所有人或者原持有人的，上缴国库。"},{"i":54,"n":"第五十四条","txt":"对法律、法规授权的具有公共事务管理职能的事业单位中经批准参照《中华人民共和国公务员法》管理的工作人员给予处分，参照本条例的有关规定办理。"},{"i":55,"n":"第五十五条","txt":"本条例自2007年6月1日起施行。1988年9月13日国务院发布的《国家行政机关工作人员贪污贿赂行政处分暂行规定》同时废止。"}],"xingzhengxueyuangongzuotiaoli":[{"i":1,"n":"第一条","txt":"为了加强行政学院工作，推进行政学院工作的科学化、规范化、制度化，根据《中华人民共和国公务员法》，制定本条例。"},{"i":2,"n":"第二条","txt":"行政学院是培训公务员、培养公共管理人员和政策研究人员、开展社会科学研究和决策咨询的机构，是政府直属单位。"},{"i":3,"n":"第三条","txt":"行政学院工作坚持以马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想为指导，深入贯彻落实科学发展观，坚持中国特色社会主义的方向，紧紧围绕党和政府的中心任务，以增强公务员素质和行政能力、提高公共行政管理水平为目标，开展教学培训、科学研究、决策咨询，为建设高素质的公务员队伍服务，为繁荣哲学社会科学服务，为党和国家事业发展服务。"},{"i":4,"n":"第四条","txt":"行政学院工作应当遵循下列方针："},{"i":5,"n":"第五条","txt":"行政学院的主要职责是："},{"i":6,"n":"第六条","txt":"行政学院应当着重提高学员的下列能力："},{"i":7,"n":"第七条","txt":"行政学院包括国务院设立的国家行政学院，省、自治区、直辖市人民政府设立的行政学院，设区的市级人民政府设立的行政学院，新疆生产建设兵团设立的行政学院。"},{"i":8,"n":"第八条","txt":"行政学院院长由本级人民政府领导人员兼任。行政学院设置常务副院长主持日常工作，常务副院长按本级人民政府工作部门正职领导人员配备。"},{"i":9,"n":"第九条","txt":"上级人民政府设立的行政学院应当对下级人民政府设立的行政学院进行业务指导，主要包括："},{"i":10,"n":"第十条","txt":"教学培训是行政学院的中心工作，行政学院各项工作应当为完成教学培训任务、提高教学培训水平服务。"},{"i":11,"n":"第十一条","txt":"行政学院应当根据时代和形势发展要求，不断充实和更新教学培训内容，以提高公务员素质和行政能力为核心，以公仆意识、政府管理、依法行政作为教学培训的重点，构建具有行政学院特色的教学培训布局。"},{"i":12,"n":"第十二条","txt":"行政学院应当立足于政府工作需要，着重建设行政管理学、经济管理学、行政法学、领导科学、社会管理学以及应急管理等学科体系。"},{"i":13,"n":"第十三条","txt":"行政学院应当根据公务员主管部门的培训规划和年度培训计划举办各类公务员培训。"},{"i":14,"n":"第十四条","txt":"行政学院根据公务员培训分级负责的要求和公务员培训规划举办进修班，完成各级人民政府公务员的培训任务。"},{"i":15,"n":"第十五条","txt":"设区的市级以上人民政府可以在行政学院举办各类专题研讨班，研讨经济社会发展中的重大问题。"},{"i":16,"n":"第十六条","txt":"设区的市级以上人民政府设立的行政学院举办提高公务员履行职责能力的任职培训班。"},{"i":17,"n":"第十七条","txt":"设区的市级以上地方人民政府设立的行政学院可以承担本级人民政府公务员的初任培训。"},{"i":18,"n":"第十八条","txt":"国家行政学院和省、自治区、直辖市人民政府设立的行政学院可以举办以行政学院教师为主要对象的师资培训班。"},{"i":19,"n":"第十九条","txt":"行政学院应当坚持理论联系实际，学用一致，不断创新教学方式方法，推行研究式教学，综合运用讲授式、研究式、互动式、案例式、体验式、模拟式等教学方法，调动教师和学员两个方面的积极性，实现教学相长、学学相长。"},{"i":20,"n":"第二十条","txt":"行政学院应当根据教学需要，完善通用教材、学位教育教材、专题教材、案例教材和电子音像教材，重视案例库建设，建立特色鲜明、针对性和实用性强的教材体系。"},{"i":21,"n":"第二十一条","txt":"行政学院应当建立健全管理制度，形成职责明确、分工协作、程序规范的教学运行机制，建立和完善教学效果考核评估体系。"},{"i":22,"n":"第二十二条","txt":"行政学院可以根据教学培训、科学研究、决策咨询工作的需要，与有关部门和单位合作建设教学科研基地，制定教学科研基地建设和使用的评估标准。"},{"i":23,"n":"第二十三条","txt":"国家行政学院依法申请取得与本院主要学科有关的硕士、博士学位授予权，并经国务院教育行政部门同意后，招收攻读硕士、博士学位的研究生，纳入国家学位管理体系。"},{"i":24,"n":"第二十四条","txt":"行政学院开展科学研究应当紧密围绕党委、政府工作和教学培训的需要，在进行基础性研究的同时，注重开展应用性研究，为理论创新服务，为提高培训质量服务，为党委、政府决策服务，为社会主义经济建设、政治建设、文化建设、社会建设以及生态文明建设服务。"},{"i":25,"n":"第二十五条","txt":"行政学院开展科学研究应当建立健全科学研究体制和项目管理机制，正确贯彻百花齐放、百家争鸣的方针，坚持实事求是的科学精神和严谨的学术规范。"},{"i":26,"n":"第二十六条","txt":"行政学院的报刊和出版工作应当坚持正确的政治方向，宣传党和国家的路线方针政策和法律法规，交流推广优秀教学培训、科学研究、决策咨询成果，推进理论和实践创新。"},{"i":27,"n":"第二十七条","txt":"行政学院应当重视科研成果的考核、评价和推介，鼓励科研创新，按照国家有关规定对做出突出贡献的人员给予表彰。"},{"i":28,"n":"第二十八条","txt":"行政学院应当围绕党委和政府工作部署，跟踪国际国内形势变化，开展决策咨询研究工作。"},{"i":29,"n":"第二十九条","txt":"行政学院应当履行决策咨询的职责，提高决策咨询的质量和水平。"},{"i":30,"n":"第三十条","txt":"行政学院应当组织教师和学员，针对经济社会发展中的重大问题进行前瞻性、对策性研究，主动为党委、政府提供决策咨询。"},{"i":31,"n":"第三十一条","txt":"行政学院应当加强对决策咨询成果的考核和评价，对做出突出贡献的人员给予表彰。"},{"i":32,"n":"第三十二条","txt":"国家行政学院和具备条件的地方行政学院应当坚持开放办学，积极利用境内外各种教学科研资源，拓展与境内外组织以及政府机构、行政院校、高等院校、学术机构、社会组织的合作和交流。"},{"i":33,"n":"第三十三条","txt":"开展对外合作和交流应当遵循以我为主、为我所用、相互学习、取长补短的原则。"},{"i":34,"n":"第三十四条","txt":"开展对外合作和交流可以采取以下形式："},{"i":35,"n":"第三十五条","txt":"行政学院应当加强学员管理，按照以人为本、严格管理、完善制度、注重实效的要求，健全科学、规范的学员管理办法，提高科学管理水平。"},{"i":36,"n":"第三十六条","txt":"行政学院应当充分调动学员的积极性，增强教学效果，开展各种有益活动，丰富学员生活。"},{"i":37,"n":"第三十七条","txt":"行政学院应当健全班委会制度、学籍制度、学员档案管理制度、学习制度和考勤制度，严格院规院纪。"},{"i":38,"n":"第三十八条","txt":"行政学院的学员管理实行班主任制度。"},{"i":39,"n":"第三十九条","txt":"行政学院应当加强对学员的考核，把学员的思想、学习、遵守院规院纪等情况提交给学员派出单位的组织人事部门，作为学员考核的内容和任职、晋升的依据之一。"},{"i":40,"n":"第四十条","txt":"学员应当遵守法律、法规和学院管理制度，努力提高政治素质和业务能力，掌握相关专业理论知识，完成规定的学习培训任务。"},{"i":41,"n":"第四十一条","txt":"行政学院学业证书是学员在行政学院学绩的凭证。行政学院学员按照教学培训计划完成学习任务，经考核合格的，取得行政学院学业证书。"},{"i":42,"n":"第四十二条","txt":"行政学院应当加强教学培训、科学研究、决策咨询、行政管理和后勤服务队伍建设，建立一支素质优良、规模适当、结构合理的工作人员队伍。"},{"i":43,"n":"第四十三条","txt":"行政学院应当加强教师队伍建设，培养、引进高层次的学科带头人，重视青年人才的培养。"},{"i":44,"n":"第四十四条","txt":"行政学院应当采取有效措施，有计划地安排教师脱产培训和挂职锻炼，提高教师队伍的素质和能力，各级人民政府及其有关部门应当给予支持。"},{"i":45,"n":"第四十五条","txt":"各级人民政府应当支持和帮助行政学院做好优秀人才选调工作，建立行政学院干部内外交流制度。"},{"i":46,"n":"第四十六条","txt":"行政学院按照专职与兼职相结合的原则，根据需要选聘理论水平较高、实践经验丰富的党政机关公务员、专家学者、企业事业单位管理人员担任兼职教师。"},{"i":47,"n":"第四十七条","txt":"列入参照《中华人民共和国公务员法》管理范围的行政学院工作人员，其人事管理按照公务员管理的相关法律法规和政策执行；未列入参照《中华人民共和国公务员法》管理范围的行政学院工作人员，按照事业单位的人事管理制度执行。"},{"i":48,"n":"第四十八条","txt":"行政学院应当建立学院工作人员考试录（聘）用、学习进修、实践锻炼、职级晋升、职称评定、绩效评估和考核制度。"},{"i":49,"n":"第四十九条","txt":"行政学院工作所需经费列入本级政府年度财政预算，保障行政学院教学科研咨询、学科建设和行政后勤等方面的工作需要。"},{"i":50,"n":"第五十条","txt":"行政学院应当加快信息化建设，实现管理高效、流程科学、资源共享。"},{"i":51,"n":"第五十一条","txt":"行政学院应当重视学院文化生活，形成有利于学员勤奋学习、教职工积极进取的文化氛围。"},{"i":52,"n":"第五十二条","txt":"设区的市级以上地方人民政府及其有关部门、行政学院、学员所在单位和学员本人，应当严格执行本条例，自觉接受组织监督、群众监督和社会监督。"},{"i":53,"n":"第五十三条","txt":"设区的市级以上人民政府及其有关部门应当依据职责对执行本条例的情况进行监督检查，对违反本条例的单位和个人，责令改正，并给予通报批评。"},{"i":54,"n":"第五十四条","txt":"本条例自2010年1月1日起施行。"}],"xueweitiaolizanxingshishibanfa":[{"i":1,"n":"第一条","txt":"根据中华人民共和国学位条例，制定本暂行实施办法。"},{"i":2,"n":"第二条","txt":"学位按下列学科的门类授予：哲学、经济学、法学、教育学、文学、历史学、理学、工学、农学、医学。"},{"i":3,"n":"第三条","txt":"学士学位由国务院授权的高等学校授予。"},{"i":4,"n":"第四条","txt":"授予学士学位的高等学校，应当由系逐个审核本科毕业生的成绩和毕业鉴定等材料，对符合本暂行办法第三条及有关规定的，可向学校学位评定委员会提名，列入学士学位获得者的名单。"},{"i":5,"n":"第五条","txt":"学士学位获得者的名单，经授予学士学位的高等学校学位评定委员会审查通过，由授予学士学位的高等学校授予学士学位。"},{"i":6,"n":"第六条","txt":"硕士学位由国务院授权的高等学校和科学研究机构授予。"},{"i":7,"n":"第七条","txt":"硕士学位的考试课程和要求：1.马克思主义理论课。要求掌握马克思主义的基本理论。2.基础理论课和专业课，一般为三至四门。要求掌握坚实的基础理论和系统的专门知识。3.一门外国语。要求比较熟练地阅读本专业的外文资料。"},{"i":8,"n":"第八条","txt":"硕士学位论文对所研究的课题应当有新的见解，表明作者具有从事科学研究工作或独立担负专门技术工作的能力。"},{"i":9,"n":"第九条","txt":"硕士学位论文答辩委员会多数成员如认为申请人的论文已相当于博士学位的学术水平，除作出授予硕士学位的决议外，可向授予博士学位的单位提出建议，由授予博士学位的单位按本暂行办法博士学位部分中有关规定办理。"},{"i":10,"n":"第十条","txt":"博士学位由国务院授权的高等学校和科学研究机构授予。"},{"i":11,"n":"第十一条","txt":"博士学位的考试课程和要求："},{"i":12,"n":"第十二条","txt":"申请博士学位人员必须通过博士学位的课程考试，成绩合格，方可参加博士学位论文答辩。"},{"i":13,"n":"第十三条","txt":"博士学位论文应当表明作者具有独立从事科学研究工作的能力，并在科学或专门技术上做出创造性的成果。博士学位论文或摘要，应当在答辩前三个月印送有关单位，并经同行评议。"},{"i":14,"n":"第十四条","txt":"博士学位论文答辩委员会由五至七人组成。成员的半数以上应当是教授或相当职称的专家。成员中必须包括二至三位外单位的专家。论文答辩委员会主席一般应当由教授或相当职称的专家担任。"},{"i":15,"n":"第十五条","txt":"博士学位论文答辩委员会认为申请人的论文虽未达到博士学位的学术水平，但已达到硕士学位的学术水平，而且申请人又尚未获得过该学科硕士学位的，可作出授予硕士学位的决议，报送学位评定委员会。"},{"i":16,"n":"第十六条","txt":"名誉博士学位由国务院授权授予博士学位的单位授予。"},{"i":17,"n":"第十七条","txt":"授予名誉博士学位须经学位授予单位的学位评定委员会讨论通过，由学位授予单位报国务院学位委员会批准后授予。"},{"i":18,"n":"第十八条","txt":"学位授予单位的学位评定委员会根据国务院批准的授予学位的权限，分别履行以下职责："},{"i":19,"n":"第十九条","txt":"学位授予单位的学位评定委员会由九至二十五人组成，任期二至三年。成员应当包括学位授予单位主要负责人和教学、研究人员。"},{"i":20,"n":"第二十条","txt":"学位授予单位每年应当将授予学士学位的人数、授予硕士学位和博士学位的名单及有关材料，分别报主管部门和国务院学位委员会备案。"},{"i":21,"n":"第二十一条","txt":"在我国学习的外国留学生申请学士学位，参照本暂行办法第三条及有关规定办理。"},{"i":22,"n":"第二十二条","txt":"学士学位的证书格式，由教育部制定。硕士学位和博士学位的证书格式，由国务院学位委员会制定。学位获得者的学位证书，由学位授予单位发给。"},{"i":23,"n":"第二十三条","txt":"已经通过的硕士学位和博士学位的论文，应当交存学位授予单位图书馆一份；已经通过的博士学位论文，还应当交存北京图书馆和有关的专业图书馆各一份。"},{"i":24,"n":"第二十四条","txt":"在职人员申请硕士学位或博士学位，经学位授予单位审核同意参加课程考试和论文答辩后，准备参加考试答辩，可享有不超过两个月的假期。"},{"i":25,"n":"第二十五条","txt":"学位授予单位可根据本暂行实施办法，制定本单位授予学位的工作细则。"}],"xuzhihongquyunyongbuchangzanxingbanfa":[{"i":1,"n":"第一条","txt":"为了保障蓄滞洪区的正常运用，确保受洪水威胁的重点地区的防洪安全，合理补偿蓄滞洪区内居民因蓄滞洪遭受的损失，根据《中华人民共和国防洪法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于附录所列国家蓄滞洪区。"},{"i":3,"n":"第三条","txt":"蓄滞洪区运用补偿，遵循下列原则："},{"i":4,"n":"第四条","txt":"蓄滞洪区所在地的各级地方人民政府应当按照国家有关规定，加强蓄滞洪区的安全建设和管理，调整产业结构，控制人口增长，有计划地组织人口外迁。"},{"i":5,"n":"第五条","txt":"蓄滞洪区运用前，蓄滞洪区所在地的各级地方人民政府应当组织有关部门和单位做好蓄滞洪区内人员、财产的转移和保护工作，尽量减少蓄滞洪造成的损失。"},{"i":6,"n":"第六条","txt":"国务院财政主管部门和国务院水行政主管部门依照本办法的规定，负责全国蓄滞洪区运用补偿工作的组织实施和监督管理。"},{"i":7,"n":"第七条","txt":"任何组织和个人不得骗取、侵吞和挪用蓄滞洪区运用补偿资金。"},{"i":8,"n":"第八条","txt":"审计机关应当加强对蓄滞洪区运用补偿资金的管理和使用情况的审计监督。"},{"i":9,"n":"第九条","txt":"蓄滞洪区内具有常住户口的居民（以下简称区内居民），在蓄滞洪区运用后，依照本办法的规定获得补偿。"},{"i":10,"n":"第十条","txt":"蓄滞洪区运用后，对区内居民遭受的下列损失给予补偿："},{"i":11,"n":"第十一条","txt":"蓄滞洪区运用后造成的下列损失，不予补偿："},{"i":12,"n":"第十二条","txt":"蓄滞洪区运用后，按照下列标准给予补偿："},{"i":13,"n":"第十三条","txt":"已下达蓄滞洪转移命令，因情况变化未实施蓄滞洪造成损失的，给予适当补偿。"},{"i":14,"n":"第十四条","txt":"蓄滞洪区所在地的县级人民政府应当组织有关部门和乡（镇）人民政府（含街道办事处，下同）对区内居民的承包土地、住房、家庭农业生产机械和役畜以及家庭主要耐用消费品逐户进行登记，并由村（居）民委员会张榜公布；在规定时间内村（居）民无异议的，由县、乡、村分级建档立卡。"},{"i":15,"n":"第十五条","txt":"已登记公布的区内居民的承包土地、住房或者其他财产发生变更时，村（居）民委员会应当于每年汛前汇总，并向乡（镇）人民政府提出财产变更登记申请，由乡（镇）人民政府核实登记后，报蓄滞洪区所在地的县级人民政府指定的部门备案。"},{"i":16,"n":"第十六条","txt":"蓄滞洪区所在地的县级人民政府应当及时将区内居民的承包土地、住房、家庭农业生产机械和役畜以及家庭主要耐用消费品的登记情况及变更登记情况汇总后抄报所在流域管理机构备案。流域管理机构应当根据每年汛期预报，对财产登记及变更登记情况进行必要的抽查。"},{"i":17,"n":"第十七条","txt":"蓄滞洪区运用后，蓄滞洪区所在地的县级人民政府应当及时组织有关部门和乡（镇）人民政府核查区内居民损失情况，按照规定的补偿标准，提出补偿方案，经省级人民政府或者其授权的主管部门核实后，由省级人民政府上报国务院。"},{"i":18,"n":"第十八条","txt":"蓄滞洪区运用补偿资金由中央财政和蓄滞洪区所在地的省级财政共同承担；具体承担比例由国务院财政主管部门根据蓄滞洪后的实际损失情况和省级财政收入水平拟定，报国务院批准。"},{"i":19,"n":"第十九条","txt":"蓄滞洪区所在地的县级人民政府在补偿资金拨付到位后，应当及时制定具体补偿方案，由乡（镇）人民政府逐户确定具体补偿金额，并由村（居）民委员会张榜公布。"},{"i":20,"n":"第二十条","txt":"流域管理机构应当加强对所辖区域内补偿资金发放情况的监督，必要时应当会同省级人民政府或者其授权的主管部门进行调查，并及时将补偿资金总的发放情况上报国务院财政主管部门和国务院水行政主管部门，同时抄送省级人民政府。"},{"i":21,"n":"第二十一条","txt":"有下列行为之一的，由蓄滞洪区所在地的县级以上地方人民政府责令立即改正，并对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":22,"n":"第二十二条","txt":"骗取、侵吞或者挪用补偿资金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":23,"n":"第二十三条","txt":"本办法规定的财产登记、财产变更登记等有关文书格式，由国务院水行政主管部门统一制订，蓄滞洪区所在地的省级人民政府水行政主管部门负责印制。"},{"i":24,"n":"第二十四条","txt":"财产登记、财产变更登记不得向区内居民收取任何费用，所需费用由蓄滞洪区所在地县级人民政府统筹解决。"},{"i":25,"n":"第二十五条","txt":"省级人民政府批准的防洪规划或者防御洪水方案中确定的蓄滞洪区的运用补偿办法，由有关省级人民政府制定。"},{"i":26,"n":"第二十六条","txt":"本办法自发布之日起施行。"}],"yaopinxingzhengbaohutiaoli":[{"i":1,"n":"第一条","txt":"为了扩大对外经济技术合作与交流，对外国药品独占权人的合法权益给予行政保护，制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称药品，是指人用药品。"},{"i":3,"n":"第三条","txt":"凡与中华人民共和国缔结有关药品行政保护双边条约或者协定的国家、地区的企业和其他组织以及个人，都可以依照本条例申请药品行政保护。"},{"i":4,"n":"第四条","txt":"国务院药品生产经营行政主管部门受理和审查药品行政保护的申请，对符合本条例规定的药品给予行政保护，对申请人颁发药品行政保护证书。"},{"i":5,"n":"第五条","txt":"申请行政保护的药品应当具备下列条件："},{"i":6,"n":"第六条","txt":"药品行政保护的申请权属于该药品独占权人。"},{"i":7,"n":"第七条","txt":"外国药品独占权人申请行政保护，应当委托国务院药品生产经营行政主管部门指定的代理机构办理。"},{"i":8,"n":"第八条","txt":"申请人应当报送下列文件的中文、外文对照本："},{"i":9,"n":"第九条","txt":"外国药品独占权人在申请药品行政保护之前或者之后，应当依照《中华人民共和国药品管理法》的规定，向国务院卫生行政部门申请办理该药品在中国境内制造或者销售许可的手续。"},{"i":10,"n":"第十条","txt":"国务院药品生产经营行政主管部门自收到行政保护申请文件之日起十五日内，进行初步审查，并分别情况作出以下处理："},{"i":11,"n":"第十一条","txt":"国务院药品生产经营行政主管部门应当自收到申请文件之日起，或者依照本条例第十条第（二）项的规定，自收到补正文件之日起，六个月内审查完毕。因特殊情况不能在六个月内审查完毕的，国务院药品生产经营行政主管部门应当及时通知申请人，并告之理由，适当延长审查时间。"},{"i":12,"n":"第十二条","txt":"国务院药品生产经营行政主管部门批准给予药品行政保护的，颁发药品行政保护证书，并予以公告。"},{"i":13,"n":"第十三条","txt":"药品行政保护期为七年零六个月，自药品行政保护证书颁发之日起计算。"},{"i":14,"n":"第十四条","txt":"外国药品独占权人应当自药品行政保护证书颁发的当年，开始缴纳年费。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，行政保护在期限届满前终止："},{"i":16,"n":"第十六条","txt":"药品行政保护证书颁发后，任何组织或者个人认为给予该药品行政保护不符合本条例规定的，都可以请求国务院药品生产经营行政主管部门撤销对该药品的行政保护；药品独占权人对国务院药品生产经营行政主管部门的撤销决定不服的，可以向人民法院提起诉讼。"},{"i":17,"n":"第十七条","txt":"药品行政保护的终止或者撤销，由国务院药品生产经营行政主管部门予以公告。"},{"i":18,"n":"第十八条","txt":"对获得行政保护的药品，未经药品独占权人许可，国务院卫生行政部门和省、自治区、直辖市的卫生行政部门不得批准他人制造或者销售。"},{"i":19,"n":"第十九条","txt":"未经获得药品行政保护的独占权人的许可，制造或者销售该药品的，药品独占权人可以请求国务院药品生产经营行政主管部门制止侵权行为；药品独占权人要求经济赔偿的，可以向人民法院提起诉讼。"},{"i":20,"n":"第二十条","txt":"国务院药品生产经营行政主管部门对申请人提供的需要保密的资料，应当采取保密措施。"},{"i":21,"n":"第二十一条","txt":"向国务院药品生产经营行政主管部门申请药品行政保护和办理有关手续，应当按照规定缴纳费用。"},{"i":22,"n":"第二十二条","txt":"本条例的实施细则由国务院药品生产经营行政主管部门制定。"},{"i":23,"n":"第二十三条","txt":"本条例由国务院药品生产经营行政主管部门负责解释。"},{"i":24,"n":"第二十四条","txt":"本条例自1993年1月1日起施行。"}],"yimiaoliutongheyufangjiezhongguanlitiaoli":[{"i":1,"n":"第一条","txt":"为了加强对疫苗流通和预防接种的管理，预防、控制传染病的发生、流行，保障人体健康和公共卫生，根据《中华人民共和国药品管理法》（以下简称药品管理法）和《中华人民共和国传染病防治法》（以下简称传染病防治法），制定本条例。"},{"i":2,"n":"第二条","txt":"本条例所称疫苗，是指为了预防、控制传染病的发生、流行，用于人体预防接种的疫苗类预防性生物制品。"},{"i":3,"n":"第三条","txt":"接种第一类疫苗由政府承担费用。接种第二类疫苗由受种者或者其监护人承担费用。"},{"i":4,"n":"第四条","txt":"疫苗的流通、预防接种及其监督管理适用本条例。"},{"i":5,"n":"第五条","txt":"国务院卫生主管部门根据全国范围内的传染病流行情况、人群免疫状况等因素，制定国家免疫规划；会同国务院财政部门拟订纳入国家免疫规划的疫苗种类，报国务院批准后公布。"},{"i":6,"n":"第六条","txt":"国家实行有计划的预防接种制度，推行扩大免疫规划。"},{"i":7,"n":"第七条","txt":"国务院卫生主管部门负责全国预防接种的监督管理工作。县级以上地方人民政府卫生主管部门负责本行政区域内预防接种的监督管理工作。"},{"i":8,"n":"第八条","txt":"经县级人民政府卫生主管部门依照本条例规定指定的医疗卫生机构（以下称接种单位），承担预防接种工作。县级人民政府卫生主管部门指定接种单位时，应当明确其责任区域。"},{"i":9,"n":"第九条","txt":"国家支持、鼓励单位和个人参与预防接种工作。各级人民政府应当完善有关制度，方便单位和个人参与预防接种工作的宣传、教育和捐赠等活动。"},{"i":10,"n":"第十条","txt":"采购疫苗，应当通过省级公共资源交易平台进行。"},{"i":11,"n":"第十一条","txt":"省级疾病预防控制机构应当根据国家免疫规划和本地区预防、控制传染病的发生、流行的需要，制定本地区第一类疫苗的使用计划（以下称使用计划），并向依照国家有关规定负责采购第一类疫苗的部门报告，同时报同级人民政府卫生主管部门备案。使用计划应当包括疫苗的品种、数量、供应渠道与供应方式等内容。"},{"i":12,"n":"第十二条","txt":"依照国家有关规定负责采购第一类疫苗的部门应当依法与疫苗生产企业签订政府采购合同，约定疫苗的品种、数量、价格等内容。"},{"i":13,"n":"第十三条","txt":"疫苗生产企业应当按照政府采购合同的约定，向省级疾病预防控制机构或者其指定的其他疾病预防控制机构供应第一类疫苗，不得向其他单位或者个人供应。"},{"i":14,"n":"第十四条","txt":"省级疾病预防控制机构应当做好分发第一类疫苗的组织工作，并按照使用计划将第一类疫苗组织分发到设区的市级疾病预防控制机构或者县级疾病预防控制机构。县级疾病预防控制机构应当按照使用计划将第一类疫苗分发到接种单位和乡级医疗卫生机构。乡级医疗卫生机构应当将第一类疫苗分发到承担预防接种工作的村医疗卫生机构。医疗卫生机构不得向其他单位或者个人分发第一类疫苗；分发第一类疫苗，不得收取任何费用。"},{"i":15,"n":"第十五条","txt":"第二类疫苗由省级疾病预防控制机构组织在省级公共资源交易平台集中采购，由县级疾病预防控制机构向疫苗生产企业采购后供应给本行政区域的接种单位。"},{"i":16,"n":"第十六条","txt":"疾病预防控制机构、接种单位、疫苗生产企业、接受委托配送疫苗的企业应当遵守疫苗储存、运输管理规范，保证疫苗质量。疫苗储存、运输的全过程应当始终处于规定的温度环境，不得脱离冷链，并定时监测、记录温度。对于冷链运输时间长、需要配送至偏远地区的疫苗，省级疾病预防控制机构应当提出加贴温度控制标签的要求。"},{"i":17,"n":"第十七条","txt":"疫苗生产企业在销售疫苗时，应当提供由药品检验机构依法签发的生物制品每批检验合格或者审核批准证明复印件，并加盖企业印章；销售进口疫苗的，还应当提供进口药品通关单复印件，并加盖企业印章。"},{"i":18,"n":"第十八条","txt":"疫苗生产企业应当依照药品管理法和国务院药品监督管理部门的规定，建立真实、完整的销售记录，并保存至超过疫苗有效期2年备查。"},{"i":19,"n":"第十九条","txt":"国务院卫生主管部门应当制定、公布预防接种工作规范，并根据疫苗的国家标准，结合传染病流行病学调查信息，制定、公布纳入国家免疫规划疫苗的免疫程序和其他疫苗的免疫程序或者使用指导原则。"},{"i":20,"n":"第二十条","txt":"各级疾病预防控制机构依照各自职责，根据国家免疫规划或者接种方案，开展与预防接种相关的宣传、培训、技术指导、监测、评价、流行病学调查、应急处置等工作，并依照国务院卫生主管部门的规定作好记录。"},{"i":21,"n":"第二十一条","txt":"接种单位应当具备下列条件："},{"i":22,"n":"第二十二条","txt":"接种单位应当承担责任区域内的预防接种工作，并接受所在地的县级疾病预防控制机构的技术指导。"},{"i":23,"n":"第二十三条","txt":"接种单位接收第一类疫苗或者购进第二类疫苗，应当索要疫苗储存、运输全过程的温度监测记录，建立并保存真实、完整的接收、购进记录，做到票、账、货、款一致。对不能提供全过程温度监测记录或者温度控制不符合要求的，接种单位不得接收或者购进，并应当立即向所在地县级人民政府药品监督管理部门、卫生主管部门报告。"},{"i":24,"n":"第二十四条","txt":"接种单位接种疫苗，应当遵守预防接种工作规范、免疫程序、疫苗使用指导原则和接种方案，并在其接种场所的显著位置公示第一类疫苗的品种和接种方法。"},{"i":25,"n":"第二十五条","txt":"医疗卫生人员在实施接种前，应当告知受种者或者其监护人所接种疫苗的品种、作用、禁忌、不良反应以及注意事项，询问受种者的健康状况以及是否有接种禁忌等情况，并如实记录告知和询问情况。受种者或者其监护人应当了解预防接种的相关知识，并如实提供受种者的健康状况和接种禁忌等情况。"},{"i":26,"n":"第二十六条","txt":"国家对儿童实行预防接种证制度。在儿童出生后1个月内，其监护人应当到儿童居住地承担预防接种工作的接种单位为其办理预防接种证。接种单位对儿童实施接种时，应当查验预防接种证，并作好记录。"},{"i":27,"n":"第二十七条","txt":"儿童入托、入学时，托幼机构、学校应当查验预防接种证，发现未依照国家免疫规划受种的儿童，应当向所在地的县级疾病预防控制机构或者儿童居住地承担预防接种工作的接种单位报告，并配合疾病预防控制机构或者接种单位督促其监护人在儿童入托、入学后及时到接种单位补种。"},{"i":28,"n":"第二十八条","txt":"接种单位应当按照国家免疫规划对居住在其责任区域内需要接种第一类疫苗的受种者接种，并达到国家免疫规划所要求的接种率。"},{"i":29,"n":"第二十九条","txt":"接种单位应当依照国务院卫生主管部门的规定对接种情况进行登记，并向所在地的县级人民政府卫生主管部门和县级疾病预防控制机构报告。接种单位在完成国家免疫规划后剩余第一类疫苗的，应当向原疫苗分发单位报告，并说明理由。"},{"i":30,"n":"第三十条","txt":"接种单位接种第一类疫苗不得收取任何费用。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府卫生主管部门根据传染病监测和预警信息，为了预防、控制传染病的暴发、流行，需要在本行政区域内部分地区进行群体性预防接种的，应当报经本级人民政府决定，并向省、自治区、直辖市人民政府卫生主管部门备案；需要在省、自治区、直辖市行政区域全部范围内进行群体性预防接种的，应当由省、自治区、直辖市人民政府卫生主管部门报经本级人民政府决定，并向国务院卫生主管部门备案。需要在全国范围或者跨省、自治区、直辖市范围内进行群体性预防接种的，应当由国务院卫生主管部门决定。作出批准决定的人民政府或者国务院卫生主管部门应当组织有关部门做好人员培训、宣传教育、物资调用等工作。"},{"i":32,"n":"第三十二条","txt":"传染病暴发、流行时，县级以上地方人民政府或者其卫生主管部门需要采取应急接种措施的，依照传染病防治法和《突发公共卫生事件应急条例》的规定执行。"},{"i":33,"n":"第三十三条","txt":"国务院卫生主管部门或者省、自治区、直辖市人民政府卫生主管部门可以根据传染病监测和预警信息发布接种第二类疫苗的建议信息，其他任何单位和个人不得发布。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府应当将与国家免疫规划有关的预防接种工作纳入本行政区域的国民经济和社会发展计划，对预防接种工作所需经费予以保障，保证达到国家免疫规划所要求的接种率，确保国家免疫规划的实施。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市人民政府根据本行政区域传染病流行趋势，在国务院卫生主管部门确定的传染病预防、控制项目范围内，确定本行政区域与预防接种相关的项目，并保证项目的实施。"},{"i":36,"n":"第三十六条","txt":"省、自治区、直辖市人民政府应当对购买、运输第一类疫苗所需经费予以保障，并保证本行政区域内疾病预防控制机构和接种单位冷链系统的建设、运转。"},{"i":37,"n":"第三十七条","txt":"县级人民政府应当保证实施国家免疫规划的预防接种所需经费，并依照国家有关规定对从事预防接种工作的乡村医生和其他基层预防保健人员给予适当补助。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府负责疫苗和有关物资的储备，以备调用。"},{"i":39,"n":"第三十九条","txt":"各级财政安排用于预防接种的经费应当专款专用，任何单位和个人不得挪用、挤占。有关单位和个人使用用于预防接种的经费应当依法接受审计机关的审计监督。"},{"i":40,"n":"第四十条","txt":"预防接种异常反应，是指合格的疫苗在实施规范接种过程中或者实施规范接种后造成受种者机体组织器官、功能损害，相关各方均无过错的药品不良反应。"},{"i":41,"n":"第四十一条","txt":"下列情形不属于预防接种异常反应："},{"i":42,"n":"第四十二条","txt":"疾病预防控制机构和接种单位及其医疗卫生人员发现预防接种异常反应、疑似预防接种异常反应或者接到相关报告的，应当依照预防接种工作规范及时处理，并立即报告所在地的县级人民政府卫生主管部门、药品监督管理部门。接到报告的卫生主管部门、药品监督管理部门应当立即组织调查处理。"},{"i":43,"n":"第四十三条","txt":"县级以上地方人民政府卫生主管部门、药品监督管理部门应当将在本行政区域内发生的预防接种异常反应及其处理的情况，分别逐级上报至国务院卫生主管部门和药品监督管理部门。"},{"i":44,"n":"第四十四条","txt":"预防接种异常反应争议发生后，接种单位或者受种方可以请求接种单位所在地的县级人民政府卫生主管部门处理。"},{"i":45,"n":"第四十五条","txt":"预防接种异常反应的鉴定参照《医疗事故处理条例》执行，具体办法由国务院卫生主管部门会同国务院药品监督管理部门制定。"},{"i":46,"n":"第四十六条","txt":"因预防接种异常反应造成受种者死亡、严重残疾或者器官组织损伤的，应当给予一次性补偿。"},{"i":47,"n":"第四十七条","txt":"因疫苗质量不合格给受种者造成损害的，依照药品管理法的有关规定处理；因接种单位违反预防接种工作规范、免疫程序、疫苗使用指导原则、接种方案给受种者造成损害的，依照《医疗事故处理条例》的有关规定处理。"},{"i":48,"n":"第四十八条","txt":"药品监督管理部门依照药品管理法及其实施条例的有关规定，对疫苗在储存、运输、供应、销售、分发和使用等环节中的质量进行监督检查，并将检查结果及时向同级卫生主管部门通报。药品监督管理部门根据监督检查需要对疫苗进行抽查检验的，有关单位和个人应当予以配合，不得拒绝。"},{"i":49,"n":"第四十九条","txt":"药品监督管理部门在监督检查中，对有证据证明可能危害人体健康的疫苗及其有关材料可以采取查封、扣押的措施，并在7日内作出处理决定；疫苗需要检验的，应当自检验报告书发出之日起15日内作出处理决定。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府卫生主管部门在各自职责范围内履行下列监督检查职责："},{"i":51,"n":"第五十一条","txt":"卫生主管部门、药品监督管理部门的工作人员依法履行监督检查职责时，不得少于2人，并出示证明文件；对被检查人的商业秘密应当保密。"},{"i":52,"n":"第五十二条","txt":"卫生主管部门、药品监督管理部门发现疫苗质量问题和预防接种异常反应以及其他情况时，应当及时互相通报，实现信息共享。"},{"i":53,"n":"第五十三条","txt":"任何单位和个人有权向卫生主管部门、药品监督管理部门举报违反本条例规定的行为，有权向本级人民政府、上级人民政府有关部门举报卫生主管部门、药品监督管理部门未依法履行监督管理职责的情况。接到举报的有关人民政府、卫生主管部门、药品监督管理部门对有关举报应当及时核实、处理。"},{"i":54,"n":"第五十四条","txt":"国家建立疫苗全程追溯制度。国务院药品监督管理部门会同国务院卫生主管部门制定统一的疫苗追溯体系技术规范。"},{"i":55,"n":"第五十五条","txt":"疾病预防控制机构、接种单位对包装无法识别、超过有效期、脱离冷链、经检验不符合标准、来源不明的疫苗，应当如实登记，向所在地县级人民政府药品监督管理部门报告，由县级人民政府药品监督管理部门会同同级卫生主管部门按照规定监督销毁。疾病预防控制机构、接种单位应当如实记录销毁情况，销毁记录保存时间不得少于5年。"},{"i":56,"n":"第五十六条","txt":"县级以上人民政府卫生主管部门、药品监督管理部门违反本条例规定，有下列情形之一的，由本级人民政府、上级人民政府卫生主管部门或者药品监督管理部门责令改正，通报批评；造成受种者人身损害，传染病传播、流行或者其他严重后果的，对直接负责的主管人员和其他直接责任人员依法给予处分；造成特别严重后果的，其主要负责人还应当引咎辞职；构成犯罪的，依法追究刑事责任："},{"i":57,"n":"第五十七条","txt":"县级以上人民政府未依照本条例规定履行预防接种保障职责的，由上级人民政府责令改正，通报批评；造成传染病传播、流行或者其他严重后果的，对直接负责的主管人员和其他直接责任人员依法给予处分；发生特别严重的疫苗质量安全事件或者连续发生严重的疫苗质量安全事件的地区，其人民政府主要负责人还应当引咎辞职；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"疾病预防控制机构有下列情形之一的，由县级以上人民政府卫生主管部门责令改正，通报批评，给予警告；有违法所得的，没收违法所得；拒不改正的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告至降级的处分："},{"i":59,"n":"第五十九条","txt":"接种单位有下列情形之一的，由所在地的县级人民政府卫生主管部门责令改正，给予警告；拒不改正的，对主要负责人、直接负责的主管人员依法给予警告至降级的处分，对负有责任的医疗卫生人员责令暂停3个月以上6个月以下的执业活动："},{"i":60,"n":"第六十条","txt":"疾病预防控制机构、接种单位有下列情形之一的，由县级以上地方人民政府卫生主管部门责令改正，给予警告；有违法所得的，没收违法所得；拒不改正的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告至撤职的处分；造成受种者人身损害或者其他严重后果的，对主要负责人、直接负责的主管人员依法给予开除的处分，并由原发证部门吊销负有责任的医疗卫生人员的执业证书；构成犯罪的，依法追究刑事责任："},{"i":61,"n":"第六十一条","txt":"疾病预防控制机构、接种单位在疫苗分发、供应和接种过程中违反本条例规定收取费用的，由所在地的县级人民政府卫生主管部门监督其将违法收取的费用退还给原缴费的单位或者个人，并由县级以上人民政府价格主管部门依法给予处罚。"},{"i":62,"n":"第六十二条","txt":"药品检验机构出具虚假的疫苗检验报告的，依照药品管理法第八十六条的规定处罚。"},{"i":63,"n":"第六十三条","txt":"疫苗生产企业未依照规定建立并保存疫苗销售记录的，依照药品管理法第七十八条的规定处罚。"},{"i":64,"n":"第六十四条","txt":"疫苗生产企业未依照规定在纳入国家免疫规划疫苗的最小外包装上标明“免费”字样以及“免疫规划”专用标识的，由药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上2万元以下的罚款，并封存相关的疫苗。"},{"i":65,"n":"第六十五条","txt":"疫苗生产企业向县级疾病预防控制机构以外的单位或者个人销售第二类疫苗的，由药品监督管理部门没收违法销售的疫苗，并处违法销售的疫苗货值金额2倍以上5倍以下的罚款；有违法所得的，没收违法所得；其直接负责的主管人员和其他直接责任人员5年内不得从事药品生产经营活动；情节严重的，依法吊销疫苗生产资格或者撤销疫苗进口批准证明文件，其直接负责的主管人员和其他直接责任人员10年内不得从事药品生产经营活动；构成犯罪的，依法追究刑事责任。"},{"i":66,"n":"第六十六条","txt":"疾病预防控制机构、接种单位、疫苗生产企业、接受委托配送疫苗的企业未在规定的冷藏条件下储存、运输疫苗的，由药品监督管理部门责令改正，给予警告，对所储存、运输的疫苗予以销毁；由卫生主管部门对疾病预防控制机构、接种单位的主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告至撤职的处分，造成严重后果的，依法给予开除的处分，并吊销接种单位的接种资格；由药品监督管理部门依法责令疫苗生产企业、接受委托配送疫苗的企业停产、停业整顿，并处违反规定储存、运输的疫苗货值金额2倍以上5倍以下的罚款，造成严重后果的，依法吊销疫苗生产资格或者撤销疫苗进口批准证明文件，其直接负责的主管人员和其他直接责任人员10年内不得从事药品生产经营活动；构成犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"违反本条例规定发布接种第二类疫苗的建议信息的，由所在地或者行为发生地的县级人民政府卫生主管部门责令通过大众媒体消除影响，给予警告；有违法所得的，没收违法所得，并处违法所得1倍以上3倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"未经卫生主管部门依法指定擅自从事接种工作的，由所在地或者行为发生地的县级人民政府卫生主管部门责令改正，给予警告；有违法持有的疫苗的，没收违法持有的疫苗；有违法所得的，没收违法所得；拒不改正的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告、降级的处分。"},{"i":69,"n":"第六十九条","txt":"儿童入托、入学时，托幼机构、学校未依照规定查验预防接种证，或者发现未依照规定受种的儿童后未向疾病预防控制机构或者接种单位报告的，由县级以上地方人民政府教育主管部门责令改正，给予警告；拒不改正的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":70,"n":"第七十条","txt":"违反本条例规定，疫苗生产企业、县级疾病预防控制机构以外的单位或者个人经营疫苗的，由药品监督管理部门依照药品管理法第七十二条的规定处罚。"},{"i":71,"n":"第七十一条","txt":"卫生主管部门、疾病预防控制机构、接种单位以外的单位或者个人违反本条例规定进行群体性预防接种的，由县级以上人民政府卫生主管部门责令立即改正，没收违法持有的疫苗，并处违法持有的疫苗货值金额2倍以上5倍以下的罚款；有违法所得的，没收违法所得。"},{"i":72,"n":"第七十二条","txt":"单位和个人违反本条例规定，给受种者人身、财产造成损害的，依法承担民事责任。"},{"i":73,"n":"第七十三条","txt":"以发生预防接种异常反应为由，寻衅滋事，扰乱接种单位的正常医疗秩序和预防接种异常反应鉴定工作的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"本条例中下列用语的含义："},{"i":75,"n":"第七十五条","txt":"出入境预防接种管理办法由国家出入境检验检疫部门另行制定。"},{"i":76,"n":"第七十六条","txt":"本条例自2005年6月1日起施行。"}],"yinhuashuizanxingtiaoli":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内书立、领受本条例所列举凭证的单位和个人，都是印花税的纳税义务人（以下简称纳税人），应当按照本条例规定缴纳印花税。"},{"i":2,"n":"第二条","txt":"下列凭证为应纳税凭证："},{"i":3,"n":"第三条","txt":"纳税人根据应纳税凭证的性质，分别按比例税率或者按件定额计算应纳税额。具体税率、税额的确定，依照本条例所附《印花税税目税率表》执行。"},{"i":4,"n":"第四条","txt":"下列凭证免纳印花税："},{"i":5,"n":"第五条","txt":"印花税实行由纳税人根据规定自行计算应纳税额，购买并一次贴足印花税票（以下简称贴花）的缴纳办法。"},{"i":6,"n":"第六条","txt":"印花税票应当粘贴在应纳税凭证上，并由纳税人在每枚税票的骑缝处盖戳注销或者画销。"},{"i":7,"n":"第七条","txt":"应纳税凭证应当于书立或者领受时贴花。"},{"i":8,"n":"第八条","txt":"同一凭证，由两方或者两方以上当事人签订并各执一份的，应当由各方就所执的一份各自全额贴花。"},{"i":9,"n":"第九条","txt":"已贴花的凭证，修改后所载金额增加的，其增加部分应当补贴印花税票。"},{"i":10,"n":"第十条","txt":"印花税由税务机关负责征收管理。"},{"i":11,"n":"第十一条","txt":"印花税票由国家税务局监制。票面金额以人民币为单位。"},{"i":12,"n":"第十二条","txt":"发放或者办理应纳税凭证的单位，负有监督纳税人依法纳税的义务。"},{"i":13,"n":"第十三条","txt":"纳税人有下列行为之一的，由税务机关根据情节轻重，予以处罚："},{"i":14,"n":"第十四条","txt":"印花税的征收管理，除本条例规定者外，依照《中华人民共和国税收征收管理法》的有关规定执行。"},{"i":15,"n":"第十五条","txt":"本条例由财政部负责解释；施行细则由财政部制定。"},{"i":16,"n":"第十六条","txt":"本条例自1988年10月1日起施行。"}],"zengzhishuizanxingtiaoli":[{"i":1,"n":"第一条","txt":"在中华人民共和国境内销售货物或者加工、修理修配劳务（以下简称劳务），销售服务、无形资产、不动产以及进口货物的单位和个人，为增值税的纳税人，应当依照本条例缴纳增值税。"},{"i":2,"n":"第二条","txt":"增值税税率："},{"i":3,"n":"第三条","txt":"纳税人兼营不同税率的项目，应当分别核算不同税率项目的销售额；未分别核算销售额的，从高适用税率。"},{"i":4,"n":"第四条","txt":"除本条例第十一条规定外，纳税人销售货物、劳务、服务、无形资产、不动产（以下统称应税销售行为），应纳税额为当期销项税额抵扣当期进项税额后的余额。应纳税额计算公式："},{"i":5,"n":"第五条","txt":"纳税人发生应税销售行为，按照销售额和本条例第二条规定的税率计算收取的增值税额，为销项税额。销项税额计算公式："},{"i":6,"n":"第六条","txt":"销售额为纳税人发生应税销售行为收取的全部价款和价外费用，但是不包括收取的销项税额。"},{"i":7,"n":"第七条","txt":"纳税人发生应税销售行为的价格明显偏低并无正当理由的，由主管税务机关核定其销售额。"},{"i":8,"n":"第八条","txt":"纳税人购进货物、劳务、服务、无形资产、不动产支付或者负担的增值税额，为进项税额。"},{"i":9,"n":"第九条","txt":"纳税人购进货物、劳务、服务、无形资产、不动产，取得的增值税扣税凭证不符合法律、行政法规或者国务院税务主管部门有关规定的，其进项税额不得从销项税额中抵扣。"},{"i":10,"n":"第十条","txt":"下列项目的进项税额不得从销项税额中抵扣："},{"i":11,"n":"第十一条","txt":"小规模纳税人发生应税销售行为，实行按照销售额和征收率计算应纳税额的简易办法，并不得抵扣进项税额。应纳税额计算公式："},{"i":12,"n":"第十二条","txt":"小规模纳税人增值税征收率为3%，国务院另有规定的除外。"},{"i":13,"n":"第十三条","txt":"小规模纳税人以外的纳税人应当向主管税务机关办理登记。具体登记办法由国务院税务主管部门制定。"},{"i":14,"n":"第十四条","txt":"纳税人进口货物，按照组成计税价格和本条例第二条规定的税率计算应纳税额。组成计税价格和应纳税额计算公式："},{"i":15,"n":"第十五条","txt":"下列项目免征增值税："},{"i":16,"n":"第十六条","txt":"纳税人兼营免税、减税项目的，应当分别核算免税、减税项目的销售额；未分别核算销售额的，不得免税、减税。"},{"i":17,"n":"第十七条","txt":"纳税人销售额未达到国务院财政、税务主管部门规定的增值税起征点的，免征增值税；达到起征点的，依照本条例规定全额计算缴纳增值税。"},{"i":18,"n":"第十八条","txt":"中华人民共和国境外的单位或者个人在境内销售劳务，在境内未设有经营机构的，以其境内代理人为扣缴义务人；在境内没有代理人的，以购买方为扣缴义务人。"},{"i":19,"n":"第十九条","txt":"增值税纳税义务发生时间："},{"i":20,"n":"第二十条","txt":"增值税由税务机关征收，进口货物的增值税由海关代征。"},{"i":21,"n":"第二十一条","txt":"纳税人发生应税销售行为，应当向索取增值税专用发票的购买方开具增值税专用发票，并在增值税专用发票上分别注明销售额和销项税额。"},{"i":22,"n":"第二十二条","txt":"增值税纳税地点："},{"i":23,"n":"第二十三条","txt":"增值税的纳税期限分别为1日、3日、5日、10日、15日、1个月或者1个季度。纳税人的具体纳税期限，由主管税务机关根据纳税人应纳税额的大小分别核定；不能按照固定期限纳税的，可以按次纳税。"},{"i":24,"n":"第二十四条","txt":"纳税人进口货物，应当自海关填发海关进口增值税专用缴款书之日起15日内缴纳税款。"},{"i":25,"n":"第二十五条","txt":"纳税人出口货物适用退（免）税规定的，应当向海关办理出口手续，凭出口报关单等有关凭证，在规定的出口退（免）税申报期内按月向主管税务机关申报办理该项出口货物的退（免）税；境内单位和个人跨境销售服务和无形资产适用退（免）税规定的，应当按期向主管税务机关申报办理退（免）税。具体办法由国务院财政、税务主管部门制定。"},{"i":26,"n":"第二十六条","txt":"增值税的征收管理，依照《中华人民共和国税收征收管理法》及本条例有关规定执行。"},{"i":27,"n":"第二十七条","txt":"纳税人缴纳增值税的有关事项，国务院或者国务院财政、税务主管部门经国务院同意另有规定的，依照其规定。"},{"i":28,"n":"第二十八条","txt":"本条例自2009年1月1日起施行。"}],"zhongwaihezijingyingqiyefashishitiaoli":[{"i":1,"n":"第一条","txt":"为了便于《中华人民共和国中外合资经营企业法》（以下简称《中外合资经营企业法》）的顺利实施，制定本条例。"},{"i":2,"n":"第二条","txt":"依照《中外合资经营企业法》批准在中国境内设立的中外合资经营企业（以下简称合营企业）是中国的法人，受中国法律的管辖和保护。"},{"i":3,"n":"第三条","txt":"在中国境内设立的合营企业，应当能够促进中国经济的发展和科学技术水平的提高，有利于社会主义现代化建设。"},{"i":4,"n":"第四条","txt":"申请设立合营企业有下列情况之一的，不予批准："},{"i":5,"n":"第五条","txt":"在中国法律、法规和合营企业协议、合同、章程规定的范围内，合营企业有权自主地进行经营管理。各有关部门应当给予支持和帮助。"},{"i":6,"n":"第六条","txt":"在中国境内设立合营企业，必须经中华人民共和国对外贸易经济合作部（以下简称对外贸易经济合作部）审查批准。批准后，由对外贸易经济合作部发给批准证书。"},{"i":7,"n":"第七条","txt":"申请设立合营企业，由中外合营者共同向审批机构报送下列文件："},{"i":8,"n":"第八条","txt":"审批机构自接到本条例第七条规定的全部文件之日起，3个月内决定批准或者不批准。"},{"i":9,"n":"第九条","txt":"申请者应当自收到批准证书之日起1个月内，按照国家有关规定，向工商行政管理机关（以下简称登记管理机构）办理登记手续。合营企业的营业执照签发日期，即为该合营企业的成立日期。"},{"i":10,"n":"第十条","txt":"本条例所称合营企业协议，是指合营各方对设立合营企业的某些要点和原则达成一致意见而订立的文件；所称合营企业合同，是指合营各方为设立合营企业就相互权利、义务关系达成一致意见而订立的文件；所称合营企业章程，是指按照合营企业合同规定的原则，经合营各方一致同意，规定合营企业的宗旨、组织原则和经营管理方法等事项的文件。"},{"i":11,"n":"第十一条","txt":"合营企业合同应当包括下列主要内容："},{"i":12,"n":"第十二条","txt":"合营企业合同的订立、效力、解释、执行及其争议的解决，均应当适用中国的法律。"},{"i":13,"n":"第十三条","txt":"合营企业章程应当包括下列主要内容："},{"i":14,"n":"第十四条","txt":"合营企业协议、合同和章程经审批机构批准后生效，其修改时同。"},{"i":15,"n":"第十五条","txt":"审批机构和登记管理机构对合营企业合同、章程的执行负有监督检查的责任。"},{"i":16,"n":"第十六条","txt":"合营企业为有限责任公司。"},{"i":17,"n":"第十七条","txt":"合营企业的投资总额（含企业借款），是指按照合营企业合同、章程规定的生产规模需要投入的基本建设资金和生产流动资金的总和。"},{"i":18,"n":"第十八条","txt":"合营企业的注册资本，是指为设立合营企业在登记管理机构登记的资本总额，应为合营各方认缴的出资额之和。"},{"i":19,"n":"第十九条","txt":"合营企业在合营期内不得减少其注册资本。因投资总额和生产经营规模等发生变化，确需减少的，须经审批机构批准。"},{"i":20,"n":"第二十条","txt":"合营一方向第三者转让其全部或者部分股权的，须经合营他方同意，并报审批机构批准，向登记管理机构办理变更登记手续。"},{"i":21,"n":"第二十一条","txt":"合营企业注册资本的增加、减少，应当由董事会会议通过，并报审批机构批准，向登记管理机构办理变更登记手续。"},{"i":22,"n":"第二十二条","txt":"合营者可以用货币出资，也可以用建筑物、厂房、机器设备或者其他物料、工业产权、专有技术、场地使用权等作价出资。以建筑物、厂房、机器设备或者其他物料、工业产权、专有技术作为出资的，其作价由合营各方按照公平合理的原则协商确定，或者聘请合营各方同意的第三者评定。"},{"i":23,"n":"第二十三条","txt":"外国合营者出资的外币，按缴款当日中国人民银行公布的基准汇率折算成人民币或者套算成约定的外币。"},{"i":24,"n":"第二十四条","txt":"作为外国合营者出资的机器设备或者其他物料，应当是合营企业生产所必需的。"},{"i":25,"n":"第二十五条","txt":"作为外国合营者出资的工业产权或者专有技术，必须符合下列条件之一："},{"i":26,"n":"第二十六条","txt":"外国合营者以工业产权或者专有技术作为出资，应当提交该工业产权或者专有技术的有关资料，包括专利证书或者商标注册证书的复制件、有效状况及其技术特性、实用价值、作价的计算根据、与中国合营者签订的作价协议等有关文件，作为合营合同的附件。"},{"i":27,"n":"第二十七条","txt":"外国合营者作为出资的机器设备或者其他物料、工业产权或者专有技术，应当报审批机构批准。"},{"i":28,"n":"第二十八条","txt":"合营各方应当按照合同规定的期限缴清各自的出资额。逾期未缴或者未缴清的，应当按合同规定支付迟延利息或者赔偿损失。"},{"i":29,"n":"第二十九条","txt":"合营各方缴付出资额后，应当由中国的注册会计师验证，出具验资报告后，由合营企业据以发给出资证明书。出资证明书载明下列事项：合营企业名称；合营企业成立的年、月、日；合营者名称（或者姓名）及其出资额、出资的年、月、日；发给出资证明书的年、月、日。"},{"i":30,"n":"第三十条","txt":"董事会是合营企业的最高权力机构，决定合营企业的一切重大问题。"},{"i":31,"n":"第三十一条","txt":"董事会成员不得少于3人。董事名额的分配由合营各方参照出资比例协商确定。"},{"i":32,"n":"第三十二条","txt":"董事会会议每年至少召开1次，由董事长负责召集并主持。董事长不能召集时，由董事长委托副董事长或者其他董事负责召集并主持董事会会议。经1/3以上董事提议，可以由董事长召开董事会临时会议。"},{"i":33,"n":"第三十三条","txt":"下列事项由出席董事会会议的董事一致通过方可作出决议："},{"i":34,"n":"第三十四条","txt":"董事长是合营企业的法定代表人。董事长不能履行职责时，应当授权副董事长或者其他董事代表合营企业。"},{"i":35,"n":"第三十五条","txt":"合营企业设经营管理机构，负责企业的日常经营管理工作。经营管理机构设总经理1人，副总经理若干人。副总经理协助总经理工作。"},{"i":36,"n":"第三十六条","txt":"总经理执行董事会会议的各项决议，组织领导合营企业的日常经营管理工作。在董事会授权范围内，总经理对外代表合营企业，对内任免下属人员，行使董事会授予的其他职权。"},{"i":37,"n":"第三十七条","txt":"总经理、副总经理由合营企业董事会聘请，可以由中国公民担任，也可以由外国公民担任。"},{"i":38,"n":"第三十八条","txt":"总经理、副总经理及其他高级管理人员有营私舞弊或者严重失职行为的，经董事会决议可以随时解聘。"},{"i":39,"n":"第三十九条","txt":"合营企业需要在国外和港澳地区设立分支机构（含销售机构）时，应当报对外贸易经济合作部批准。"},{"i":40,"n":"第四十条","txt":"本条例所称引进技术，是指合营企业通过技术转让的方式，从第三者或者合营者获得所需要的技术。"},{"i":41,"n":"第四十一条","txt":"合营企业引进的技术应当是适用的、先进的，使其产品在国内具有显著的社会经济效益或者在国际市场上具有竞争能力。"},{"i":42,"n":"第四十二条","txt":"在订立技术转让协议时，必须维护合营企业独立进行经营管理的权利，并参照本条例第二十六条的规定，要求技术输出方提供有关的资料。"},{"i":43,"n":"第四十三条","txt":"合营企业订立的技术转让协议，应当报审批机构批准。"},{"i":44,"n":"第四十四条","txt":"合营企业使用场地，必须贯彻执行节约用地的原则。所需场地，应当由合营企业向所在地的市（县）级土地主管部门提出申请，经审查批准后，通过签订合同取得场地使用权。合同应当订明场地面积、地点、用途、合同期限、场地使用权的费用（以下简称场地使用费）、双方的权利与义务、违反合同的罚则等。"},{"i":45,"n":"第四十五条","txt":"合营企业所需场地的使用权，已为中国合营者所拥有的，中国合营者可以将其作为对合营企业的出资，其作价金额应当与取得同类场地使用权所应缴纳的使用费相同。"},{"i":46,"n":"第四十六条","txt":"场地使用费标准应当根据该场地的用途、地理环境条件、征地拆迁安置费用和合营企业对基础设施的要求等因素，由所在地的省、自治区、直辖市人民政府规定，并向对外贸易经济合作部和国家土地主管部门备案。"},{"i":47,"n":"第四十七条","txt":"从事农业、畜牧业的合营企业，经所在地的省、自治区、直辖市人民政府同意，可以按合营企业营业收入的百分比向所在地的土地主管部门缴纳场地使用费。"},{"i":48,"n":"第四十八条","txt":"场地使用费在开始用地的5年内不调整。以后随着经济的发展、供需情况的变化和地理环境条件的变化需要调整时，调整的间隔期应当不少于3年。"},{"i":49,"n":"第四十九条","txt":"合营企业按本条例第四十四条取得的场地使用权，其场地使用费应当按合同规定的用地时间从开始时起按年缴纳，第一日历年用地时间超过半年的按半年计算；不足半年的免缴。在合同期内，场地使用费如有调整，应当自调整的年度起按新的费用标准缴纳。"},{"i":50,"n":"第五十条","txt":"合营企业除依照本章规定取得场地使用权外，还可以按照国家有关规定取得场地使用权。"},{"i":51,"n":"第五十一条","txt":"合营企业所需的机器设备、原材料、燃料、配套件、运输工具和办公用品等（以下简称物资），有权自行决定在中国购买或者向国外购买。"},{"i":52,"n":"第五十二条","txt":"合营企业需要在中国购置的办公、生活用品，按需要量购买，不受限制。"},{"i":53,"n":"第五十三条","txt":"中国政府鼓励合营企业向国际市场销售其产品。"},{"i":54,"n":"第五十四条","txt":"合营企业有权自行出口其产品，也可以委托外国合营者的销售机构或者中国的外贸公司代销或者经销。"},{"i":55,"n":"第五十五条","txt":"合营企业在合营合同规定的经营范围内，进口本企业生产所需的机器设备、零配件、原材料、燃料，凡属国家规定需要领取进口许可证的，每年编制一次计划，每半年申领一次。外国合营者作为出资的机器设备或者其他物料，可以凭审批机构的批准文件直接办理进口许可证进口。超出合营合同规定范围进口的物资，凡国家规定需要领取进口许可证的，应当另行申领。"},{"i":56,"n":"第五十六条","txt":"合营企业在国内购买物资的价格以及支付水、电、气、热、货物运输、劳务、工程设计、咨询、广告等服务的费用，享受与国内其他企业同等的待遇。"},{"i":57,"n":"第五十七条","txt":"合营企业与中国其他经济组织之间的经济往来，按照有关的法律规定和双方订立的合同承担经济责任，解决合同争议。"},{"i":58,"n":"第五十八条","txt":"合营企业应当依照《中华人民共和国统计法》及中国利用外资统计制度的规定，提供统计资料，报送统计报表。"},{"i":59,"n":"第五十九条","txt":"合营企业应当按照中华人民共和国有关法律的规定，缴纳各种税款。"},{"i":60,"n":"第六十条","txt":"合营企业的职工应当按照《中华人民共和国个人所得税法》缴纳个人所得税。"},{"i":61,"n":"第六十一条","txt":"合营企业进口下列物资，依照中国税法的有关规定减税、免税："},{"i":62,"n":"第六十二条","txt":"合营企业生产的出口产品，除中国限制出口的以外，依照中国税法的有关规定减税、免税或者退税。"},{"i":63,"n":"第六十三条","txt":"合营企业的一切外汇事宜，按照《中华人民共和国外汇管理条例》和有关管理办法的规定办理。"},{"i":64,"n":"第六十四条","txt":"合营企业凭营业执照，在境内银行开立外汇账户和人民币账户，由开户银行监督收付。"},{"i":65,"n":"第六十五条","txt":"合营企业在国外或者港澳地区的银行开立外汇账户，应当经国家外汇管理局或者其分局批准，并向国家外汇管理局或者其分局报告收付情况和提供银行对账单。"},{"i":66,"n":"第六十六条","txt":"合营企业在国外或者港澳地区设立的分支机构，其年度资产负债表和年度利润表，应当通过合营企业报送国家外汇管理局或者其分局。"},{"i":67,"n":"第六十七条","txt":"合营企业根据经营业务的需要，可以向境内的金融机构申请外汇贷款和人民币贷款，也可以按照国家有关规定从国外或者港澳地区的银行借入外汇资金，并向国家外汇管理局或者其分局办理登记或者备案手续。"},{"i":68,"n":"第六十八条","txt":"合营企业的外籍职工和港澳职工的工资和其他正当收益，依法纳税后，减去在中国境内的花费，其剩余部分可以按照国家有关规定购汇汇出。"},{"i":69,"n":"第六十九条","txt":"合营企业的财务与会计制度，应当按照中国有关法律和财务会计制度的规定，结合合营企业的情况加以制定，并报当地财政部门、税务机关备案。"},{"i":70,"n":"第七十条","txt":"合营企业设总会计师，协助总经理负责企业的财务会计工作。必要时，可以设副总会计师。"},{"i":71,"n":"第七十一条","txt":"合营企业设审计师（小的企业可以不设），负责审查、稽核合营企业的财务收支和会计账目，向董事会、总经理提出报告。"},{"i":72,"n":"第七十二条","txt":"合营企业会计年度采用日历年制，自公历每年1月1日起至12月31日止为一个会计年度。"},{"i":73,"n":"第七十三条","txt":"合营企业会计采用国际通用的权责发生制和借贷记账法记账。一切自制凭证、账簿、报表必须用中文书写，也可以同时用合营各方商定的一种外文书写。"},{"i":74,"n":"第七十四条","txt":"合营企业原则上采用人民币作为记账本位币，经合营各方商定，也可以采用某一种外国货币作为记账本位币。"},{"i":75,"n":"第七十五条","txt":"合营企业的账目，除按记账本位币记录外，对于现金、银行存款、其他货币款项以及债权债务、收益和费用等，与记账本位币不一致时，还应当按实际收付的货币记账。"},{"i":76,"n":"第七十六条","txt":"合营企业按照《中华人民共和国企业所得税法》缴纳所得税后的利润分配原则如下："},{"i":77,"n":"第七十七条","txt":"以前年度的亏损未弥补前不得分配利润。以前年度未分配的利润，可以并入本年度利润分配。"},{"i":78,"n":"第七十八条","txt":"合营企业应当向合营各方、当地税务机关和财政部门报送季度和年度会计报表。"},{"i":79,"n":"第七十九条","txt":"合营企业的下列文件、证件、报表，应当经中国的注册会计师验证和出具证明，方为有效："},{"i":80,"n":"第八十条","txt":"合营企业职工的招收、招聘、辞退、辞职、工资、福利、劳动保险、劳动保护、劳动纪律等事宜，按照国家有关劳动和社会保障的规定办理。"},{"i":81,"n":"第八十一条","txt":"合营企业应当加强对职工的业务、技术培训，建立严格的考核制度，使他们在生产、管理技能方面能够适应现代化企业的要求。"},{"i":82,"n":"第八十二条","txt":"合营企业的工资、奖励制度必须符合按劳分配、多劳多得的原则。"},{"i":83,"n":"第八十三条","txt":"正副总经理、正副总工程师、正副总会计师、审计师等高级管理人员的工资待遇，由董事会决定。"},{"i":84,"n":"第八十四条","txt":"合营企业职工有权按照《中华人民共和国工会法》和《中国工会章程》的规定，建立基层工会组织，开展工会活动。"},{"i":85,"n":"第八十五条","txt":"合营企业工会是职工利益的代表，有权代表职工同合营企业签订劳动合同，并监督合同的执行。"},{"i":86,"n":"第八十六条","txt":"合营企业工会的基本任务是：依法维护职工的民主权利和物质利益；协助合营企业安排和合理使用福利、奖励基金；组织职工学习政治、科学、技术和业务知识，开展文艺、体育活动；教育职工遵守劳动纪律，努力完成企业的各项经济任务。"},{"i":87,"n":"第八十七条","txt":"合营企业董事会会议讨论合营企业的发展规划、生产经营活动等重大事项时，工会的代表有权列席会议，反映职工的意见和要求。"},{"i":88,"n":"第八十八条","txt":"合营企业应当积极支持本企业工会的工作。合营企业应当按照《中华人民共和国工会法》的规定为工会组织提供必要的房屋和设备，用于办公、会议、举办职工集体福利、文化、体育事业。合营企业每月按企业职工实际工资总额的2%拨交工会经费，由本企业工会按照中华全国总工会制定的有关工会经费管理办法使用。"},{"i":89,"n":"第八十九条","txt":"合营企业的合营期限，按照《中外合资经营企业合营期限暂行规定》执行。"},{"i":90,"n":"第九十条","txt":"合营企业在下列情况下解散："},{"i":91,"n":"第九十一条","txt":"合营企业宣告解散时，应当进行清算。合营企业应当依法成立清算委员会，由清算委员会负责清算事宜。"},{"i":92,"n":"第九十二条","txt":"清算委员会的成员一般应当在合营企业的董事中选任。董事不能担任或者不适合担任清算委员会成员时，合营企业可以聘请中国的注册会计师、律师担任。审批机构认为必要时，可以派人进行监督。"},{"i":93,"n":"第九十三条","txt":"清算委员会的任务是对合营企业的财产、债权、债务进行全面清查，编制资产负债表和财产目录，提出财产作价和计算依据，制定清算方案，提请董事会会议通过后执行。"},{"i":94,"n":"第九十四条","txt":"合营企业以其全部资产对其债务承担责任。合营企业清偿债务后的剩余财产按照合营各方的出资比例进行分配，但合营企业协议、合同、章程另有规定的除外。"},{"i":95,"n":"第九十五条","txt":"合营企业的清算工作结束后，由清算委员会提出清算结束报告，提请董事会会议通过后，报告审批机构，并向登记管理机构办理注销登记手续，缴销营业执照。"},{"i":96,"n":"第九十六条","txt":"合营企业解散后，各项账册及文件应当由原中国合营者保存。"},{"i":97,"n":"第九十七条","txt":"合营各方在解释或者履行合营企业协议、合同、章程时发生争议的，应当尽量通过友好协商或者调解解决。经过协商或者调解无效的，提请仲裁或者司法解决。"},{"i":98,"n":"第九十八条","txt":"合营各方根据有关仲裁的书面协议，可以在中国的仲裁机构进行仲裁，也可以在其他仲裁机构仲裁。"},{"i":99,"n":"第九十九条","txt":"合营各方之间没有有关仲裁的书面协议的，发生争议的任何一方都可以依法向人民法院起诉。"},{"i":100,"n":"第一百条","txt":"在解决争议期间，除争议事项外，合营各方应当继续履行合营企业协议、合同、章程所规定的其他各项条款。"},{"i":101,"n":"第一百零一条","txt":"合营企业的外籍职工和港澳职工（包括其家属），需要经常入、出中国国境的，中国主管签证机关可以简化手续，予以方便。"},{"i":102,"n":"第一百零二条","txt":"合营企业的中国职工，因工作需要出国（境）考察、洽谈业务、学习或者接受培训，按照国家有关规定办理出国（境）手续。"},{"i":103,"n":"第一百零三条","txt":"合营企业的外籍职工和港澳职工，可以带进必需的交通工具和办公用品，按照中国税法的有关规定纳税。"},{"i":104,"n":"第一百零四条","txt":"在经济特区设立的合营企业，法律、行政法规另有规定的，从其规定。"},{"i":105,"n":"第一百零五条","txt":"本条例自公布之日起施行。"}],"zhongwaihezijingyingqiyeheyingqixianzanxingguiding":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国中外合资经营企业法》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"举办中外合资经营企业（以下简称合营企业），属于国家规定鼓励和允许投资项目的，除本规定第三条另有规定外，合营各方可以在合同中约定合营期限，也可以不约定合营期限。"},{"i":3,"n":"第三条","txt":"举办合营企业，属于下列行业或者情况的，合营各方应当依照国家有关法律、法规的规定，在合营合同中约定合营期限："},{"i":4,"n":"第四条","txt":"合营各方在合营合同中不约定合营期限的合营企业，按照国家规定的审批权限和程序审批。除对外经济贸易部直接审批的外，其他审批机关应当在批准后30天内报对外经济贸易部备案。"},{"i":5,"n":"第五条","txt":"合营各方在合营合同中不约定合营期限的合营企业，经税务机关批准，可以按照国家有关税收的规定享受减税、免税优惠待遇。如实际经营期未达到国家有关税收优惠规定的年限，应当依法补缴已经减免的税款。"},{"i":6,"n":"第六条","txt":"在本规定施行之前已经批准设立的合营企业，按照批准的合营合同约定的期限执行，但属本规定第三条规定以外的合营企业，合营各方一致同意将合营合同中合营期限条款修改为不约定合营期限的，合营各方应当申报理由，签订修改合营合同的协议，并提出申请，报原审批机关审查。"},{"i":7,"n":"第七条","txt":"本规定自发布之日起施行。"}],"zhongwaihezuojingyingqiyefashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国中外合作经营企业法》，制定本实施细则。"},{"i":2,"n":"第二条","txt":"在中国境内举办中外合作经营企业（以下简称合作企业），应当符合国家的发展政策和产业政策，遵守国家关于指导外商投资方向的规定。"},{"i":3,"n":"第三条","txt":"合作企业在批准的合作企业协议、合同、章程范围内，依法自主地开展业务、进行经营管理活动，不受任何组织或者个人的干涉。"},{"i":4,"n":"第四条","txt":"合作企业包括依法取得中国法人资格的合作企业和不具有法人资格的合作企业。"},{"i":5,"n":"第五条","txt":"合作企业的主管部门为中国合作者的主管部门。合作企业有2个以上中国合作者的，由审查批准机关会同有关部门协商确定一个主管部门。但是，法律、行政法规另有规定的除外。"},{"i":6,"n":"第六条","txt":"设立合作企业由对外贸易经济合作部或者国务院授权的部门和地方人民政府审查批准。"},{"i":7,"n":"第七条","txt":"设立合作企业，应当由中国合作者向审查批准机关报送下列文件："},{"i":8,"n":"第八条","txt":"对外贸易经济合作部和国务院授权的部门批准设立的合作企业，由对外贸易经济合作部颁发批准证书。"},{"i":9,"n":"第九条","txt":"申请设立合作企业，有下列情形之一的，不予批准："},{"i":10,"n":"第十条","txt":"本实施细则所称合作企业协议，是指合作各方对设立合作企业的原则和主要事项达成一致意见后形成的书面文件。"},{"i":11,"n":"第十一条","txt":"合作企业协议、合同、章程自审查批准机关颁发批准证书之日起生效。在合作期限内，合作企业协议、合同、章程有重大变更的，须经审查批准机关批准。"},{"i":12,"n":"第十二条","txt":"合作企业合同应当载明下列事项："},{"i":13,"n":"第十三条","txt":"合作企业章程应当载明下列事项："},{"i":14,"n":"第十四条","txt":"合作企业依法取得中国法人资格的，为有限责任公司。除合作企业合同另有约定外，合作各方以其投资或者提供的合作条件为限对合作企业承担责任。"},{"i":15,"n":"第十五条","txt":"合作企业的投资总额，是指按照合作企业合同、章程规定的生产经营规模，需要投入的资金总和。"},{"i":16,"n":"第十六条","txt":"合作企业的注册资本，是指为设立合作企业，在工商行政管理机关登记的合作各方认缴的出资额之和。注册资本以人民币表示，也可以用合作各方约定的一种可自由兑换的外币表示。"},{"i":17,"n":"第十七条","txt":"合作各方应当依照有关法律、行政法规的规定和合作企业合同的约定，向合作企业投资或者提供合作条件。"},{"i":18,"n":"第十八条","txt":"合作各方向合作企业的投资或者提供的合作条件可以是货币，也可以是实物或者工业产权、专有技术、土地使用权等财产权利。"},{"i":19,"n":"第十九条","txt":"合作各方应当以其自有的财产或者财产权利作为投资或者合作条件，对该投资或者合作条件不得设置抵押权或者其他形式的担保。"},{"i":20,"n":"第二十条","txt":"合作各方应当根据合作企业的生产经营需要，依照有关法律、行政法规的规定，在合作企业合同中约定合作各方向合作企业投资或者提供合作条件的期限。"},{"i":21,"n":"第二十一条","txt":"未按照合作企业合同约定缴纳投资或者提供合作条件的一方，应当向已按照合作企业合同约定缴纳投资或者提供合作条件的他方承担违约责任。"},{"i":22,"n":"第二十二条","txt":"合作各方缴纳投资或者提供合作条件后，应当由中国注册会计师验证并出具验资报告，由合作企业据以发给合作各方出资证明书。出资证明书应当载明下列事项："},{"i":23,"n":"第二十三条","txt":"合作各方之间相互转让或者合作一方向合作他方以外的他人转让属于其在合作企业合同中全部或者部分权利的，须经合作他方书面同意，并报审查批准机关批准。"},{"i":24,"n":"第二十四条","txt":"合作企业设董事会或者联合管理委员会。董事会或者联合管理委员会是合作企业的权力机构，按照合作企业章程的规定，决定合作企业的重大问题。"},{"i":25,"n":"第二十五条","txt":"董事会或者联合管理委员会成员不得少于3人，其名额的分配由中外合作者参照其投资或者提供的合作条件协商确定。"},{"i":26,"n":"第二十六条","txt":"董事会董事或者联合管理委员会委员由合作各方自行委派或者撤换。董事会董事长、副董事长或者联合管理委员会主任、副主任的产生办法由合作企业章程规定；中外合作者的一方担任董事长、主任的，副董事长、副主任由他方担任。"},{"i":27,"n":"第二十七条","txt":"董事或者委员的任期由合作企业章程规定；但是，每届任期不得超过3年。董事或者委员任期届满，委派方继续委派的，可以连任。"},{"i":28,"n":"第二十八条","txt":"董事会会议或者联合管理委员会会议每年至少召开1次，由董事长或者主任召集并主持。董事长或者主任因特殊原因不能履行职务时，由董事长或者主任指定副董事长、副主任或者其他董事、委员召集并主持。1/3以上董事或者委员可以提议召开董事会会议或者联合管理委员会会议。"},{"i":29,"n":"第二十九条","txt":"下列事项由出席董事会会议或者联合管理委员会会议的董事或者委员一致通过，方可作出决议："},{"i":30,"n":"第三十条","txt":"董事会或者联合管理委员会的议事方式和表决程序，除本实施细则规定的外，由合作企业章程规定。"},{"i":31,"n":"第三十一条","txt":"董事长或者主任是合作企业的法定代表人。董事长或者主任因特殊原因不能履行职务时，应当授权副董事长、副主任或者其他董事、委员对外代表合作企业。"},{"i":32,"n":"第三十二条","txt":"合作企业设总经理1人，负责合作企业的日常经营管理工作，对董事会或者联合管理委员会负责。"},{"i":33,"n":"第三十三条","txt":"总经理及其他高级管理人员可以由中国公民担任，也可以由外国公民担任。"},{"i":34,"n":"第三十四条","txt":"总经理及其他高级管理人员不胜任工作任务的，或者有营私舞弊或者严重失职行为的，经董事会或者联合管理委员会决议，可以解聘；给合作企业造成损失的，应当依法承担责任。"},{"i":35,"n":"第三十五条","txt":"合作企业成立后委托合作各方以外的他人经营管理的，必须经董事会或者联合管理委员会一致同意，并应当与被委托人签订委托经营管理合同。"},{"i":36,"n":"第三十六条","txt":"合作企业按照经批准的经营范围和生产经营规模，自行制定生产经营计划。"},{"i":37,"n":"第三十七条","txt":"合作企业可以自行决定在中国境内或者境外购买本企业自用的机器设备、原材料、燃料、零部件、配套件、元器件、运输工具和办公用品等（以下简称“物资”）。"},{"i":38,"n":"第三十八条","txt":"国家鼓励合作企业向国际市场销售其产品。合作企业可以自行向国际市场销售其产品，也可以委托国外的销售机构或者中国的外贸公司代销或者经销其产品。"},{"i":39,"n":"第三十九条","txt":"外国合作者作为投资进口的机器设备、零部件和其他物料以及合作企业用投资总额内的资金进口生产、经营所需的机器设备、零部件和其他物料，免征进口关税和进口环节的流转税。上述免税进口物资经批准在中国境内转卖或者转用于国内销售的，应当依法纳税或者补税。"},{"i":40,"n":"第四十条","txt":"合作企业不得以明显低于合理的国际市场同类产品的价格出口产品，不得以高于国际市场同类产品的价格进口物资。"},{"i":41,"n":"第四十一条","txt":"合作企业销售产品，应当按照经批准的合作企业合同的约定销售。"},{"i":42,"n":"第四十二条","txt":"合作企业进口或者出口属于进出口许可证、配额管理的商品，应当按照国家有关规定办理申领手续。"},{"i":43,"n":"第四十三条","txt":"中外合作者可以采用分配利润、分配产品或者合作各方共同商定的其他方式分配收益。"},{"i":44,"n":"第四十四条","txt":"中外合作者在合作企业合同中约定合作期限届满时，合作企业的全部固定资产无偿归中国合作者所有的，外国合作者在合作期限内，可以在按照投资或者提供合作条件进行分配的基础上，在合作企业合同中约定扩大外国合作者的收益分配比例，先行回收其投资。"},{"i":45,"n":"第四十五条","txt":"合作企业的亏损未弥补前，外国合作者不得先行回收投资。"},{"i":46,"n":"第四十六条","txt":"合作企业应当按照国家有关规定聘请中国注册会计师进行查账验证。合作各方可以共同或者单方自行委托中国注册会计师查账，所需费用由委托查账方负担。"},{"i":47,"n":"第四十七条","txt":"合作企业的期限由中外合作者协商确定，并在合作企业合同中订明。"},{"i":48,"n":"第四十八条","txt":"合作企业因下列情形之一出现时解散："},{"i":49,"n":"第四十九条","txt":"合作企业的清算事宜依照国家有关法律、行政法规及合作企业合同、章程的规定办理。"},{"i":50,"n":"第五十条","txt":"不具有法人资格的合作企业及其合作各方，依照中国民事法律的有关规定，承担民事责任。"},{"i":51,"n":"第五十一条","txt":"不具有法人资格的合作企业应当向工商行政管理机关登记合作各方的投资或者提供的合作条件。"},{"i":52,"n":"第五十二条","txt":"不具有法人资格的合作企业的合作各方的投资或者提供的合作条件，为合作各方分别所有。经合作各方约定，也可以共有，或者部分分别所有、部分共有。合作企业经营积累的财产，归合作各方共有。"},{"i":53,"n":"第五十三条","txt":"不具有法人资格的合作企业设立联合管理机构。联合管理机构由合作各方委派的代表组成，代表合作各方共同管理合作企业。"},{"i":54,"n":"第五十四条","txt":"不具有法人资格的合作企业应当在合作企业所在地设置统一的会计账簿；合作各方还应当设置各自的会计账簿。"},{"i":55,"n":"第五十五条","txt":"合作企业合同的订立、效力、解释、履行及其争议的解决，适用中国法律。"},{"i":56,"n":"第五十六条","txt":"本实施细则未规定的事项，包括合作企业的财务、会计、审计、外汇、税务、劳动管理、工会等，适用有关法律、行政法规的规定。"},{"i":57,"n":"第五十七条","txt":"香港、澳门、台湾地区的公司、企业和其他经济组织或者个人以及在国外居住的中国公民举办合作企业，参照本实施细则办理。"},{"i":58,"n":"第五十八条","txt":"本实施细则自发布之日起施行。"}],"zhongyangyusuanzhixingqingkuangshenjijianduzanxinge2b361":[{"i":1,"n":"第一条","txt":"为了做好对中央预算执行和其他财政收支的审计监督工作，根据《中华人民共和国审计法》（以下简称《审计法》），制定本办法。"},{"i":2,"n":"第二条","txt":"审计署在国务院总理领导下，对中央预算执行情况进行审计监督，维护中央预算的法律严肃性，促进中央各部门（含直属单位，下同）严格执行预算法，发挥中央预算在国家宏观调控中的作用，保障经济和社会的健康发展。"},{"i":3,"n":"第三条","txt":"对中央预算执行情况进行审计，应当有利于国务院对中央财政收支的管理和全国人民代表大会常务委员会对中央预算执行和其他财政收支的监督；有利于促进国务院财政税务部门和中央其他部门依法有效地行使预算管理职权；有利于实现中央预算执行和其他财政收支审计监督工作的法制化。"},{"i":4,"n":"第四条","txt":"审计署依法对中央预算执行情况，省级预算执行情况和决算，以及中央级其他财政收支的真实、合法和效益，进行审计监督。"},{"i":5,"n":"第五条","txt":"对中央预算执行情况进行审计监督的主要内容："},{"i":6,"n":"第六条","txt":"对中央级其他财政收支进行审计监督的主要内容："},{"i":7,"n":"第七条","txt":"为了做好中央预算执行情况审计监督工作，对省级政府预算执行和决算中，执行预算和税收法律、行政法规，分配使用中央财政补助地方支出资金和省级预算外资金管理和使用情况等关系国家财政工作全局的问题，进行审计或者审计调查。"},{"i":8,"n":"第八条","txt":"根据《审计法》有关审计工作报告制度的规定，审计署应当在每年第一季度对上一年度国家税务总局、海关总署所属机构和中央有关部门实施中央预算情况和其他财政收支，进行就地审计；第二季度对上一年度中央预算执行情况进行审计。审计署对预算执行中的特定事项，应当及时组织专项审计调查。"},{"i":9,"n":"第九条","txt":"国务院财政税务部门和中央其他部门应当向审计署报送以下资料："},{"i":10,"n":"第十条","txt":"对国务院财政税务部门和中央其他部门在组织中央预算执行和其他财政收支中，违反预算的行为或者其他违反国家规定的财政收支行为，审计署在法定职权范围内，依照有关法律、行政法规的规定，出具审计意见书或者作出审计决定，重大问题向国务院提出处理建议。"},{"i":11,"n":"第十一条","txt":"国务院财政税务部门和中央其他部门发布的财政规章、制度和办法有同有关法律、行政法规相抵触或者有不适当之处，应当纠正或者完善的，审计署可以提出处理建议，报国务院审查决定。"},{"i":12,"n":"第十二条","txt":"违反《审计法》的规定，拒绝或者阻碍审计检查的，由审计署责令改正，可以通报批评，给予警告；拒不改正的，依法追究责任。"},{"i":13,"n":"第十三条","txt":"中国人民解放军审计署对中国人民解放军预算执行和其他财政收支的审计结果报告，报中央军事委员会的同时，并报审计署。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市审计机关，可以参照本办法，结合本地方的实际情况，制定地方预算执行情况审计监督实施办法，报同级人民政府批准，并报审计署备案。"},{"i":15,"n":"第十五条","txt":"本办法自发布之日起施行。"}],"zhongyiyaotiaoli":[{"i":1,"n":"第一条","txt":"为了继承和发展中医药学，保障和促进中医药事业的发展，保护人体健康，制定本条例。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事中医医疗、预防、保健、康复服务和中医药教育、科研、对外交流以及中医药事业管理活动的单位或者个人，应当遵守本条例。"},{"i":3,"n":"第三条","txt":"国家保护、扶持、发展中医药事业，实行中西医并重的方针，鼓励中西医相互学习、相互补充、共同提高，推动中医、西医两种医学体系的有机结合，全面发展我国中医药事业。"},{"i":4,"n":"第四条","txt":"发展中医药事业应当遵循继承与创新相结合的原则，保持和发扬中医药特色和优势，积极利用现代科学技术，促进中医药理论和实践的发展，推进中医药现代化。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府应当将中医药事业纳入国民经济和社会发展计划，使中医药事业与经济、社会协调发展。"},{"i":6,"n":"第六条","txt":"国务院中医药管理部门负责全国中医药管理工作。国务院有关部门在各自的职责范围内负责与中医药有关的工作。"},{"i":7,"n":"第七条","txt":"对在继承和发展中医药事业中做出显著贡献和在边远地区从事中医药工作做出突出成绩的单位和个人，县级以上各级人民政府应当给予奖励。"},{"i":8,"n":"第八条","txt":"开办中医医疗机构，应当符合国务院卫生行政部门制定的中医医疗机构设置标准和当地区域卫生规划，并按照《医疗机构管理条例》的规定办理审批手续，取得医疗机构执业许可证后，方可从事中医医疗活动。"},{"i":9,"n":"第九条","txt":"中医医疗机构从事医疗服务活动，应当充分发挥中医药特色和优势，遵循中医药自身发展规律，运用传统理论和方法，结合现代科学技术手段，发挥中医药在防治疾病、保健、康复中的作用，为群众提供价格合理、质量优良的中医药服务。"},{"i":10,"n":"第十条","txt":"依法设立的社区卫生服务中心（站）、乡镇卫生院等城乡基层卫生服务机构，应当能够提供中医医疗服务。"},{"i":11,"n":"第十一条","txt":"中医从业人员，应当依照有关卫生管理的法律、行政法规、部门规章的规定通过资格考试，并经注册取得执业证书后，方可从事中医服务活动。"},{"i":12,"n":"第十二条","txt":"中医从业人员应当遵守相应的中医诊断治疗原则、医疗技术标准和技术操作规范。"},{"i":13,"n":"第十三条","txt":"发布中医医疗广告，医疗机构应当按照规定向所在地省、自治区、直辖市人民政府负责中医药管理的部门申请并报送有关材料。省、自治区、直辖市人民政府负责中医药管理的部门应当自收到有关材料之日起10个工作日内进行审查，并作出是否核发中医医疗广告批准文号的决定。对符合规定要求的，发给中医医疗广告批准文号。未取得中医医疗广告批准文号的，不得发布中医医疗广告。"},{"i":14,"n":"第十四条","txt":"国家采取措施发展中医药教育事业。"},{"i":15,"n":"第十五条","txt":"设立各类中医药教育机构，应当符合国家规定的设置标准，并建立符合国家规定标准的临床教学基地。"},{"i":16,"n":"第十六条","txt":"国家鼓励开展中医药专家学术经验和技术专长继承工作，培养高层次的中医临床人才和中药技术人才。"},{"i":17,"n":"第十七条","txt":"承担中医药专家学术经验和技术专长继承工作的指导老师应当具备下列条件："},{"i":18,"n":"第十八条","txt":"中医药专家学术经验和技术专长继承工作的继承人应当具备下列条件："},{"i":19,"n":"第十九条","txt":"中医药专家学术经验和技术专长继承工作的指导老师以及继承人的管理办法，由国务院中医药管理部门会同有关部门制定。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市人民政府负责中医药管理的部门应当依据国家有关规定，完善本地区中医药人员继续教育制度，制定中医药人员培训规划。"},{"i":21,"n":"第二十一条","txt":"国家发展中医药科学技术，将其纳入科学技术发展规划，加强重点中医药科研机构建设。"},{"i":22,"n":"第二十二条","txt":"中医药科学研究应当注重运用传统方法和现代方法开展中医药基础理论研究和临床研究，运用中医药理论和现代科学技术开展对常见病、多发病和疑难病的防治研究。"},{"i":23,"n":"第二十三条","txt":"捐献对中医药科学技术发展有重大意义的中医诊疗方法和中医药文献、秘方、验方的，参照《国家科学技术奖励条例》的规定给予奖励。"},{"i":24,"n":"第二十四条","txt":"国家支持中医药的对外交流与合作，推进中医药的国际传播。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府应当根据中医药事业发展的需要以及本地区国民经济和社会发展状况，逐步增加对中医药事业的投入，扶持中医药事业的发展。"},{"i":26,"n":"第二十六条","txt":"非营利性中医医疗机构，依照国家有关规定享受财政补贴、税收减免等优惠政策。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府劳动保障行政部门确定的城镇职工基本医疗保险定点医疗机构，应当包括符合条件的中医医疗机构。"},{"i":28,"n":"第二十八条","txt":"县级以上各级人民政府应当采取措施加强对中医药文献的收集、整理、研究和保护工作。"},{"i":29,"n":"第二十九条","txt":"国家保护野生中药材资源，扶持濒危动植物中药材人工代用品的研究和开发利用。"},{"i":30,"n":"第三十条","txt":"与中医药有关的评审或者鉴定活动，应当体现中医药特色，遵循中医药自身的发展规律。"},{"i":31,"n":"第三十一条","txt":"负责中医药管理的部门的工作人员在中医药管理工作中违反本条例的规定，利用职务上的便利收受他人财物或者获取其他利益，滥用职权，玩忽职守，或者发现违法行为不予查处，造成严重后果，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，依法给予降级或者撤职的行政处分。"},{"i":32,"n":"第三十二条","txt":"中医医疗机构违反本条例的规定，有下列情形之一的，由县级以上地方人民政府负责中医药管理的部门责令限期改正；逾期不改正的，责令停业整顿，直至由原审批机关吊销其医疗机构执业许可证、取消其城镇职工基本医疗保险定点医疗机构资格，并对负有责任的主管人员和其他直接责任人员依法给予纪律处分："},{"i":33,"n":"第三十三条","txt":"未经批准擅自开办中医医疗机构或者未按照规定通过执业医师或者执业助理医师资格考试取得执业许可，从事中医医疗活动的，依照《中华人民共和国执业医师法》和《医疗机构管理条例》的有关规定给予处罚。"},{"i":34,"n":"第三十四条","txt":"中医药教育机构违反本条例的规定，有下列情形之一的，由县级以上地方人民政府负责中医药管理的部门责令限期改正；逾期不改正的，由原审批机关予以撤销："},{"i":35,"n":"第三十五条","txt":"违反本条例规定，造成重大中医药资源流失和国家科学技术秘密泄露，情节严重，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由县级以上地方人民政府负责中医药管理的部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予纪律处分。"},{"i":36,"n":"第三十六条","txt":"违反本条例规定，损毁或者破坏中医药文献的，由县级以上地方人民政府负责中医药管理的部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予纪律处分；损毁或者破坏属于国家保护文物的中医药文献，情节严重，构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"篡改经批准的中医医疗广告内容的，由原审批部门撤销广告批准文号，1年内不受理该中医医疗机构的广告审批申请。"},{"i":38,"n":"第三十八条","txt":"本条例所称中医医疗机构，是指依法取得医疗机构执业许可证的中医、中西医结合的医院、门诊部和诊所。"},{"i":39,"n":"第三十九条","txt":"本条例自2003年10月1日起施行。"}],"ziyuanshuizanxingtiaoli":[{"i":1,"n":"第一条","txt":"在中华人民共和国领域及管辖海域开采本条例规定的矿产品或者生产盐（以下称开采或者生产应税产品）的单位和个人，为资源税的纳税人，应当依照本条例缴纳资源税。"},{"i":2,"n":"第二条","txt":"资源税的税目、税率，依照本条例所附《资源税税目税率表》及财政部的有关规定执行。"},{"i":3,"n":"第三条","txt":"纳税人具体适用的税率，在本条例所附《资源税税目税率表》规定的税率幅度内，根据纳税人所开采或者生产应税产品的资源品位、开采条件等情况，由财政部商国务院有关部门确定；财政部未列举名称且未确定具体适用税率的其他非金属矿原矿和有色金属矿原矿，由省、自治区、直辖市人民政府根据实际情况确定，报财政部和国家税务总局备案。"},{"i":4,"n":"第四条","txt":"资源税的应纳税额，按照从价定率或者从量定额的办法，分别以应税产品的销售额乘以纳税人具体适用的比例税率或者以应税产品的销售数量乘以纳税人具体适用的定额税率计算。"},{"i":5,"n":"第五条","txt":"纳税人开采或者生产不同税目应税产品的，应当分别核算不同税目应税产品的销售额或者销售数量；未分别核算或者不能准确提供不同税目应税产品的销售额或者销售数量的，从高适用税率。"},{"i":6,"n":"第六条","txt":"纳税人开采或者生产应税产品，自用于连续生产应税产品的，不缴纳资源税；自用于其他方面的，视同销售，依照本条例缴纳资源税。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，减征或者免征资源税："},{"i":8,"n":"第八条","txt":"纳税人的减税、免税项目，应当单独核算销售额或者销售数量；未单独核算或者不能准确提供销售额或者销售数量的，不予减税或者免税。"},{"i":9,"n":"第九条","txt":"纳税人销售应税产品，纳税义务发生时间为收讫销售款或者取得索取销售款凭据的当天；自产自用应税产品，纳税义务发生时间为移送使用的当天。"},{"i":10,"n":"第十条","txt":"资源税由税务机关征收。"},{"i":11,"n":"第十一条","txt":"收购未税矿产品的单位为资源税的扣缴义务人。"},{"i":12,"n":"第十二条","txt":"纳税人应纳的资源税，应当向应税产品的开采或者生产所在地主管税务机关缴纳。纳税人在本省、自治区、直辖市范围内开采或者生产应税产品，其纳税地点需要调整的，由省、自治区、直辖市税务机关决定。"},{"i":13,"n":"第十三条","txt":"纳税人的纳税期限为1日、3日、5日、10日、15日或者1个月，由主管税务机关根据实际情况具体核定。不能按固定期限计算纳税的，可以按次计算纳税。"},{"i":14,"n":"第十四条","txt":"资源税的征收管理，依照《中华人民共和国税收征收管理法》及本条例有关规定执行。"},{"i":15,"n":"第十五条","txt":"本条例实施办法由财政部和国家税务总局制定。"},{"i":16,"n":"第十六条","txt":"本条例自1994年1月1日起施行。1984年9月18日国务院发布的《中华人民共和国资源税条例（草案）》、《中华人民共和国盐税条例（草案）》同时废止。"}]};
